  def solve(): Unit = {
    val N, M = ni()
    val (from, to) = na2(N - 1 + M ,-1)

    val g = packDGraph(N, from, to)

    val o = topologicalSort(g)
//    debug(o)
    val p = Array.ofDim[Int](N)
    REP(N) { i =>
      val v = o(i)
      REP(g(v).length) { j =>
        val u = g(v)(j)
        p(u) = v
      }
    }
//    debug(p)

    REP(N) { i =>
      if (i == o(0)) out.println(0)
      else out.println(p(i) + 1)
    }
  }

  def packDGraph(n: Int, from: Array[Int], to: Array[Int]): Array[Array[Int]] = {
    val t = new Array[Array[Int]](n)
    val p = new Array[Int](n)
    val m = from.length
    REP(m)(i => p(from(i)) += 1)
    REP(n)(i => t(i) = new Array(p(i)))
    REP_r(m) { i => // 順序維持する
      p(from(i)) -= 1
      t(from(i))(p(from(i))) = to(i)
    }
    t
  }

  /**
    * @return 閉路の場合はnull
    */
  def topologicalSort(g: Array[Array[Int]]): Array[Int] = {
    val n = g.length
    val L = Array.ofDim[Int](n)
    var ptr = 0
    val S = Array.ofDim[Int](n)
    var last, cur = 0
    val deg = Array.ofDim[Int](n)
    REP(n) { i =>
      REP(g(i).length) { j =>
        deg(g(i)(j)) += 1
      }
    }

    REP(n) { i =>
      if (deg(i) == 0) {
        S(last) = i
        last += 1
      }
    }

    while(cur < last) {
      val v = S(cur)
      cur += 1
      L(ptr) = v
      ptr += 1

      REP(g(v).length) { i =>
        val u = g(v)(i)
        deg(u) -= 1
        if (deg(u) == 0) {
          S(last) = u
          last += 1
        }
      }
    }

    // 閉路チェック
    REP(n) { i =>
      if (deg(i) > 0) return null
    }
    L
  }

