    inEdgeCount(b) += 1
    edges(a) ::= b
  }
  var current = List(inEdgeCount.indexWhere(_ == 0))
  val prev = Array.tabulate(n){_ ⇒ 0}
  while (current.nonEmpty){
    var next = Nil: List[Int]
    for (c ← current; e ← edges(c)) {
      inEdgeCount(e) -= 1
      if (inEdgeCount(e) == 0) {
        next ::= e
        prev(e) = c + 1
      }
    }
    current = next
