template <typename T>
vector<T> toposort(const set<T> group, const set<pair<T,T>>& arcs) {
    map<T, set<T>> from, to;
    for (pair<T,T> arc: arcs) {
        T u = arc.first, v = arc.second;
        from[u].insert(v);
        to[v].insert(u);
    }
    int E = arcs.size();

    set<T> S;
    for (T i : group) {
        if (!found(to, i)) S.insert(i);
    }

    vector<T> L;
    while (!S.empty()) {
        T u = *S.begin();
        S.erase(u);
        L.push_back(u);
        for (T v: from[u]) {
            to[v].erase(u);
            --E;
            if (to[v].empty()) {
                S.insert(v);
            }
        }
    }

    if (E != 0) {
        return vector<T> {};
    }

    return L;
}

void solve(int N,int M,vi& a,vi& b) {
    int L=a.size(); // N-1+M
    vvi nxt(L), into(L);
    rep(i,L){
        nxt[a[i]].pb(b[i]);
        into[b[i]].pb(a[i]);
    }
    int root=-1;
    vi leaf;
    rep(i,L){
        if (into[i].size()==0) root=i;
        if (nxt[i].size()==0) leaf.pb(i);
    }

    set<int> group;
    rep(i,N) group.insert(i);
    set<ii> arcs;
    rep(i,L) arcs.insert(ii(a[i],b[i]));
    vi ord = toposort(group, arcs);
#ifdef DEBUG
    cerr << ord << endl;
#endif
    vi ordn(N);
    rep(i,N) ordn[ ord[i] ] = i;

    vi previ(N, -1);
    for (int u: ord){
        // visited[u] = true;
        int omax=-1;
        for (int f: into[u]) {
            if (ordn[f] > omax) {
                previ[u] = f;
                omax = ordn[f];
            }
        }
    }
#ifdef DEBUG
    cerr << previ << endl;
#endif
    rep(i,N){
        printf("%d\n", previ[i]+1);
    }
}

int main() {
