void DFS(vector<vector<int> > &adj, vector<int> &parent, int root){
  stack<pair<int, int> > st;
  st.push({root, 1});

  vector<int> visited(parent.size(), 0);
  visited[root] = 1;

  while(!st.empty()){
    int here = st.top().first;
    int cnt = st.top().second + 1;

    st.pop();

    for(auto &desc : adj[here]){
    	if(visited[desc] < cnt){
          visited[desc] = cnt;
          if(parent[desc] != here)
            st.push({desc, cnt});
          parent[desc] = here;
        }
    }
  }
}

