using namespace std;

class TopologicalSort
{
    using Graph = vector<vector<int>>;
    // 頂点数
    int n;
    vector<vector<int>> g;
    void dfs(int v, const Graph &G, vector<int> &res, vector<int> &used)
    {
        used[v] = 1;
        for (auto to : G[v])
            if (used[to] == 0)
            {
                dfs(to, G, res, used);
            }
        res.push_back(v);
    }

  public:
    TopologicalSort(int _n) : n(_n), g.resize(_n) {}
    void addEdge(int a, int b)
    {
        g[a].push_back(b);
    }
    vector<int> topoSort(const Graph &G)
    {
        int V = G.size();
        vector<int> ide(V);
        for (int i = 0; i < V; i++)
        {
            for (auto to : G[i])
            {
                ide[to]++;
            }
        }
        vector<int> res;
        vector<int> used(V);
        for (int i = V - 1; i >= 0; i--)
        {
            if (ide[i] == 0)
            {
                dfs(i, G, res, used);
            }
        }
        if (res.size() == 0)
            res = {-1};
        reverse(res.begin(), res.end());
        return res;
    }
};

