void bfs(ll x) {
	std::deque<pair<ll, ll> > que;
	pair<ll, ll> p = make_pair(x, 0);
	que.push_back(p);
	while (que.size()>0)
	{
		pair<ll, ll> l = que.back();
		que.pop_back();
		ll y, d;
		y = l.first;
