int countps(int i){
    if(pcnt[i]>=0) return pcnt[i];
    if(canRoot[i]){
        parent[i]=0;
        pcnt[i]=0;
        return 0;
    }
    int cnt=-1;
    int pind=i;
    for(auto x : invedge[i]){
        if(cnt<countps(x)+1){
            cnt=countps(x)+1;
            pind=x;
        }
    }
    parent[i]=pind;
    pcnt[i]=cnt;
    return cnt;
}


