void dfs(int u){
    if(used[u]) return;
    used[u] = true;
    for(auto& i: g[u]) dfs(i);
    ans.push_back(u);
}

void tsort(){
    for(int i = 0; i < N; i++){
        dfs(i);
    }
    reverse(ans.begin(), ans.end());
}

int dfs2(int u){
    int ma = -1, ma_index = -1;
    for(int i = 0; i < g2[u].size(); i++){
        int nex = g2[u][i];
        if(index_list[nex] > ma){
            ma_index = g2[u][i];
            ma = index_list[nex];
        }
    }
    return ma_index;
}

