signed main(int argc, char *argv[]) {
  int n = in(), m = in();
  vector<int> deg(n, 0), w(n, 0);
  vector<vector<int>> G(n);
  vector<int> a(n + m), b(n + m);

  vector<int> ans(n);

  for (int i = 0; i < n - 1 + m; ++i) {
    a[i] = in() - 1;
    b[i] = in() - 1;

    G[a[i]].pb(b[i]);
    deg[b[i]]++;
