  int p = -1;
  for (int i = 0; i < n; ++i) {
    if (!deg[i]) p = i;
  }

  queue<pair<int, int>> v;
  v.push({p, 0});

  while (!v.empty()) {
    pair<int, int> p = v.front();
    int from = p.first;
    v.pop();

    if (p.second != w[from]) continue;

    for (auto &to : G[from]) {
      if (chmax(w[to], w[from] + 1)) {
        v.push({to, w[to]});
        ans[to] = from + 1;
      }
    }
  }

