    if(r[i]==0)q.push({i,0});
  }
  vector<pint> dp(n, {-1,0});
  while(!q.empty()){
    pint p = q.front();q.pop();
    int u = p.first ;
    int c = p.second;
    if(dp[u].second > c)continue;
    for(int v : G[u]){
      --r[v];
      if(dp[v].second < c+1){
        dp[v]= {u,c+1};
      }
      if(r[v]==0)
        q.push({v, dp[v].second});
      }
    }
  }
  for(int i = 0; i < n; ++i){
    cout << dp[i].first + 1 << endl;
  }
}

