const int MAX_V = (int)1e5 + 5;
const int MAX_E = (int)1e5 + 5;

vector<int> G[MAX_V];
bool used[MAX_V];
int parent[MAX_V];

void dfs(int curr, int prev){
	parent[curr] = prev;
	used[curr] |= true;
	int cnt = 0;
	rep (i, (int)G[curr].size()){
		int next = G[curr][i];
		if (prev != -1){
			if (!used[next] && cnt == 0){
				dfs(next, curr);
				++cnt;
			} // end if
		}else{
			if (!used[next]){
				dfs(next, curr);
			} // end if
		} // end if
	} // end rep
}

