	vector<int> A(N - 1 + M, 0), B(N - 1 + M, 0);
	rep (i, N - 1 + M){
		cin >> A[i] >> B[i];
		--A[i], --B[i];
		G[A[i]].push_back(B[i]);
		G[B[i]].push_back(A[i]);
	} // end rep

	memset(parent, -1, sizeof(parent));
	rep (i, N){
		if (!used[i]){
			dfs(i, -1);
		} // end if
	} // end rep

	rep (i, N){
		cout << parent[i] + 1 << endl;
	} // end rep

