int Used[maxN], inD[maxN];

void DFS_topo(int u) {
    Used[u]++;
    L[u] = ++order;
    for (int v : Adj[u]) {
        if (Used[v] == 1) {
            //if (Used[u] != 1) continue;
            if (L[parent[v]] <= L[u] && L[u] <= R[parent[v]]) {
                parent[v] = u;
            }
            continue;
            //parent[v] = u;
        }
        //D[v] = D[u] + 1;
        parent[v] = u;
        DFS_topo(v);
    }
    R[u] = order;
}

void solveD_RestoreTheTree() { ///https://atcoder.jp/contests/nikkei2019-qual/tasks/nikkei2019_qual_d
    cin >> n >> m;
    for (int i = 1; i < n + m; i++) {
