        inD[v]++;
    }
    int root = 0;
    for (int i = 1; i <= n; i++) {
        if (inD[i] == 0) {
            root = i;
            break;
        }
    }
    for (int i = 1; i <= n; i++) R[i] = 1e9;
    DFS_topo(root);
    for (int i = 1; i <= n; i++) cout << parent[i] << "\n";
}

