vector<int> topo_sort(const vector<vector<int> > &G){
	vector<int> ans;
	int n = G.size();
	vector<int> num(n);
	for(int i = 0; i < n; i++){
		for(int to : G[i]) num[to]++;
	}
	queue<int> que;
	for(int i = 0; i < n; i++){
		if(num[i] == 0) que.push(i);
	}
	while(que.size()){
		int now = que.front(); que.pop();
		ans.push_back(now);
		for(auto to : G[now]){
			num[to]--;
			if(num[to] == 0) que.push(to);
		}
	}
	return ans;
}

