vector<int> topolSort(vector< vector<int> > e) {
    vector<int> indeg(e.size()), ans;
    ans.reserve(e.size());
    queue<int> q;
    for (int i = 0; i < e.size(); ++i) for (int j = 0; j < e.at(i).size(); ++j) ++indeg.at(e.at(i).at(j));
    for (int i = 0; i < e.size(); ++i) if (indeg.at(i) == 0) q.push(i);
    while (!q.empty()) {
        ans.push_back(q.front());
        q.pop();
        for (int i : e.at(ans.back())) if (--indeg.at(i) == 0) q.push(i);
    }
    return ans;
}

