vector<li> parents;
vector<li> parent_dist;

li dfs(li pos) {
    if (parent_dist[pos] >= 0) {
        return parent_dist[pos];
    }

    li dist = 0;
    for (int i = 0; i < rev[pos].size(); ++i) {
        const li next = rev[pos][i];
        li subdist = dfs(next) + 1;
        if (subdist > dist) {
            parents[pos] = next;
            dist = subdist;
        }
    }

    return parent_dist[pos] = dist;
}

