vector<int> solve(const vec<int, 2>& G) {
  int N = G.size();
  vector<int> indeg(N, 0);
  for (int v = 0; v < N; v++) {
    for (int u : G[v]) ++indeg[u];
  }
  queue<int> que;
  for (int i = 0; i < N; i++)
    if (indeg[i] == 0) que.push(i);
  vector<int> dp(N, 0);
  while (!que.empty()) {
    int v = que.front();
    que.pop();
    for (int u : G[v]) {
      dp[u] = max(dp[u], dp[v] + 1);
      --indeg[u];
      if (indeg[u] == 0) {
        que.push(u);
      }
    }
  }
  return dp;
}

