using namespace std;

class TopologicalSort
{
    using Graph = vector<vector<int>>;
    // 頂点数
    int V;
    vector<vector<int>> G;
    void dfs(int v, vector<int> &res, vector<int> &used)
    {
        used[v] = 1;
        for (auto to : G[v])
            if (used[to] == 0)
            {
                dfs(to, res, used);
            }
        res.push_back(v);
    }

  public:
    TopologicalSort(int _v) : V(_v), G(_v) {}
    void addEdge(int a, int b)
    {
        assert(0 <= a && a < V);
        assert(0 <= b && b < V);
        G[a].push_back(b);
    }
    vector<int> topologicalSort()
    {
        vector<int> ide(V);
        for (int i = 0; i < V; i++)
        {
            for (auto to : G[i])
            {
                ide[to]++;
            }
        }
        vector<int> res;
        vector<int> used(V);
        for (int i = V - 1; i >= 0; i--)
        {
            if (ide[i] == 0)
            {
                dfs(i, res, used);
            }
        }
        if (res.size() == 0)
            res = {-1};
        reverse(res.begin(), res.end());
        return res;
    }
};

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n, m;
    cin >> n >> m;
    TopologicalSort g(n);
    vector<vector<int>> rev(n);
    for (int i = 0; i < n - 1 + m; i++)
    {
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        g.addEdge(a, b);
        rev[b].push_back(a);
    }
    vector<int> ts = g.topologicalSort();
    vector<int> res(n, -1), pri(n);
    for (int i = 0; i < n; i++)
        pri[ts[i]] = i;
    res[ts[0]] = 0;
    for (int i = n - 1; i > 0; i--)
    {
        int v = ts[i];
        int ma = -1, idx = -1;
        for (auto u : rev[v])
        {
            if (pri[u] > ma)
            {
                ma = pri[u];
                idx = u;
            }
        }
        res[v] = idx + 1;
    }
    for (int i = 0; i < n; i++)
    {
        cout << res[i] << endl;
    }
}

