bool __rec_topo(vector<int> &topo, int pos) {
	if (used_topo[pos] == -1) return false;
	if (used_topo[pos] == 1) return true;
	used_topo[pos] = -1;
	for (int i : edg[pos]) {
		if (!__rec_topo(topo, i)) return false;
	}
	used_topo[pos] = 1;
	topo.push_back(pos);
	return true;
}

// Perform topological sort of the graph defined by edg.
// n: The number of vertices.
// The sorting result will be stored in the first argument topo.
// Returning false means the graph is not DAG.
bool topo_sort(vector<int> &topo, int n) {
	bool flag = true;
	for (int i = 1; i <= n; i++) {
		if (used_topo[i] == 0) flag &= __rec_topo(topo, i);
	}
	reverse(topo.begin(), topo.end());
	return flag;
}


