		int a, b;
		cin >> a >> b;
		--a; --b;
		to[a].push_back(b);
		from[b].push_back(a);
	}

	vector<int> res(N, -1);
	int root = -1;
	for (int i = 0; i < N; ++i) {
		if (from[i].size() == 0) {
			res[i] = 0;
			root = i;
			break;
		}
	}

	vector<int> rank(N, -1);
	rank[root] = 0;
	func(to, rank, root);

	for (int i = 0; i < N; ++i) {
		if (i == root) { continue; }
		for (int j = 0; j < from[i].size(); ++j) {
			if (rank[i] == rank[from[i][j]] + 1) {
				res[i] = from[i][j] + 1;
				break;
			}
		}
	}

