void dfs(const vector<vector<int>> &RG, int v, vector<int> &visit, vector<int> &vs) {
  visit[v] = true;
  for (int w: RG[v]) {
    if (!visit[w]) {
      dfs(RG, w, visit, vs);
    }
  }
  vs.push_back(v);
}

int main(int argc, char *argv[])
{
  int N, M;
  cin >> N >> M;
  vector<int> A(N + M - 1), B(N + M - 1);
  vector<vector<int>> RG(N + M);

  vector<int> visit(N + M);
  REP(i, N + M - 1) {
    cin >> A[i] >> B[i];
    RG[B[i]].push_back(A[i]);
  }
  vector<int> vs;
  REP2(v, 1, N + 1) {
    if (!visit[v]) {
      dfs(RG, v, visit, vs);
    }
  }

  vector<int> res(N);
  vector<int> d(N, -1);

  REP2(i, 1, N + 1) {
    int v = vs[i - 1];
    // cout << i - 1 << " " << v << " :"<< endl;
    for (int w: RG[v]) {
      // cout << v << " " << w << endl;
      assert(d[w] >= 0);
      d[v] = max(d[w] + 1, d[v]);
    }
    if (RG[v].size() == 0) {
      res[v - 1] = 0;
      d[v] = 0;
      continue;
    }

    for (int w: RG[v]) {
      if (d[w] == d[v] - 1) {
        res[v - 1] = w;
      }
    }
  }
  REP(i, N) {
    cout << res[i] << endl;
  }
  return 0;
}

