int main() {
  int n, m;
  scanf("%d%d", &n, &m);
  int k = n - 1 + m;

  for (int i = 0; i < k; i++) {
    int a, b;
    scanf("%d%d", &a, &b);
    a--, b--;

    nbrs[a].push_back(b);
    pns[b]++;
  }

  int rt = -1;
  for (int i = 0; rt < 0 && i < n; i++)
    if (pns[i] == 0) rt = i;
  //printf("rt=%d\n", rt);

  prts[rt] = -1;
  qi q;
  q.push(rt);

  while (! q.empty()) {
    int u = q.front(); q.pop();
    int &ud = ds[u], vd = ud + 1;
    vi &nbru = nbrs[u];
    for (vi::iterator vit = nbru.begin(); vit != nbru.end(); vit++) {
      int &v = *vit;
      if (ds[v] < vd) {
	ds[v] = vd;
	prts[v] = u;
      }
      if (--pns[v] == 0) q.push(v);
    }
  }

  for (int i = 0; i < n; i++) printf("%d\n", prts[i] + 1);

  return 0;
}

