namespace
{
	struct Node
	{
		vector<int> nexts;
		int arrowedCount = 0;
	};
	vector<int> answer;

	vector<Node> nodes;

	void Process(int target, int beforeTarget)
	{
		answer[target] = beforeTarget;

		deque<int> que;
		for (int i = 0; i < nodes[target].nexts.size(); i++)
		{
			int nextNode = nodes[target].nexts[i];
			nodes[nextNode].arrowedCount--;
			if (nodes[nextNode].arrowedCount == 0)
			{
				que.push_back(nextNode);
			}
		}

		while (!que.empty())
		{
			int t = que.front();
			que.pop_front();

			Process(t, target);
		}
	}
}

