void read(T &res) {
	res = 0;T f = 1;char c = getchar();
	while(c < '0' || c > '9') {
		if(c == '-') f = -1;
		c = getchar();
	}
	while(c >= '0' && c <= '9') {
		res = res * 10 + c - '0';
		c = getchar();
	}
	res *= f;
}
template<class T>
void out(T x) {
	if(x < 0) {x = -x;putchar('-');}
	if(x >= 10) {
		out(x / 10);
	}
	putchar('0' + x % 10);
}
vector<int> to[MAXN],pre[MAXN];
int N,M,deg[MAXN],p[MAXN],fa[MAXN];
queue<int> Q;
void Solve() {
	read(N);read(M);
	int u,v;
	for(int i = 1 ; i <= N - 1 + M ; ++i) {
		read(u);read(v);
		deg[v]++;
		to[u].pb(v);
		pre[v].pb(u);
	}
	for(int i = 1 ; i <= N ; ++i) {
		if(!deg[i]) Q.push(i);
	}
	while(!Q.empty()) {
		int u = Q.front();Q.pop();
		for(auto v : to[u]) {
			p[v] = max(p[v],p[u] + 1);
			if(!(--deg[v])) Q.push(v);
		}
		for(auto t : pre[u]) {
			if(p[t] + 1 == p[u]) fa[u] = t;
		}
	}
	for(int i = 1 ; i <= N ; ++i) {
		out(fa[i]);enter;
	}
