vector<int> g[maxn], r[maxn];
int tour[maxn], scc[maxn], deg[maxn], fa[maxn];
bool v[maxn];

void dfs(int x) {
    static int sz = 0;
    v[x] = true;
    for (int i = 0; i < (int)g[x].size(); ++i) {
        int u = g[x][i];
        if (v[u]) continue;
        dfs(u);
    }
    tour[sz++] = x;
}

void rdfs(int x, int z) {
    scc[x] = z;
    for (int i = 0; i < (int)r[x].size(); ++i) {
        int u = r[x][i];
        if (scc[u] == -1)
            rdfs(u, z);
    }
}

void dfs2(int x) {
    v[x] = true;
    for (int i = 0; i < (int)g[x].size(); ++i) {
        int u = g[x][i];
        if (v[u]) continue;
        fa[u] = x;
        dfs2(u);
    }
}

int main() {
    int n, m; scanf("%d%d", &n, &m);
    for (int i = 0; i < n - 1 + m; ++i) {
        int x, y; scanf("%d%d", &x, &y);
        --x, --y;
        g[x].push_back(y);
        r[y].push_back(x);
    }
    for (int i = 0; i < n; ++i) {
        if (v[i]) continue;
        dfs(i);
    }
    memset(scc, -1, sizeof(scc));
    int p = 0;
    for (int i = n - 1; i >= 0; --i) {
        if (scc[tour[i]] >= 0) continue;
        rdfs(tour[i], p);
        p++;
    }
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < (int)g[i].size(); ++j) {
            int u = g[i][j];
            if (scc[u] == scc[i]) continue;
            ++deg[scc[u]];
        }
    }
    int z = -1;
    for (int i = 0; i < p; ++i) {
        if (deg[i] == 0)
            z = i;
    }
    assert(z >= 0);
    int r = -1;
    for (int i = 0; i < n; ++i) {
        if (scc[i] == z)
            r = i;
    }
    assert(r >= 0);
    memset(v, false, sizeof(v));
    memset(fa, -1, sizeof(fa));
    dfs2(r);
    for (int i = 0; i < n; ++i) printf("%d\n", fa[i] + 1);
}

