class Node {
public:
	int parentsCount = 0;
	list<int> children;

	int setParents = 0;
	int trueParent = 0;
	int trueDepth = 0;

	void setDepth(int parent, int depth) {
		if (trueDepth < depth) {
			trueDepth = depth;
			trueParent = parent;
		}
		setParents++;
	}

	int getDepth() {
		if (parentsCount > setParents) {
			return -1;
		}
		return trueDepth;
	}
};

int getRoot(Node* nodes, int size) {
	for (int i=1; i<size; i++) {
		if (nodes[i].parentsCount == 0) {
			return i;
		}
	}
	return -1;
}

