class Timer {
 public:
  double GetElapsedTime() {
    return static_cast<double>(GetCycle() - start_) /
           static_cast<double>(clock_frequency_);
  }
  void Start() { start_ = GetCycle(); }

 private:
  int64_t start_;
  static constexpr int64_t clock_frequency_ = 2800000000;
  int64_t GetCycle() {
    uint32_t low, high;
    __asm__ volatile("rdtsc" : "=a"(low), "=d"(high));
    return (static_cast<int64_t>(low)) | (static_cast<int64_t>(high) << 32);
  }
};

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  Timer time;
  time.Start();

  int n, m; cin >> n >> m;
  vector<vector<int>> graph(n);
  vector<int> cnt(n, 0);

  for (int i = 0; i < n + m - 1; ++i) {
    int a, b; cin >> a >> b;
    --a; --b;
    graph[a].emplace_back(b);
    ++cnt[b];
  }

  int source = 0;

  for (int i = 0; i < n; ++i) {
    if (cnt[i] == 0) {
      source = i;
      break;
    }
  }

  vector<int> ans(n, -1);
  vector<int> depth(n, -1);
  ans[source] = 0;
  depth[source] = 0;

  auto dfs = [&](const auto& dfs, int cur, int prev) -> void {
    if (time.GetElapsedTime() >= 1.9) {
      return ;
    }
    for (int next : graph[cur]) {
      if (next == prev) continue;
      // do something
      if (depth[next] <= depth[cur]) {
        ans[next] = cur + 1;
        depth[next] = depth[cur] + 1;
      }
      dfs(dfs, next, cur);
    }
  };

  dfs(dfs, source, -1);

  for (int i = 0; i < n; ++i) {
    cout << ans[i] << '\n';
  }

  debug(depth);

  return 0;
}

