using ll = long long;

const ll INF = static_cast<ll>(1e9) + 7ll;
const ll LINF = INF * INF;
const int MAXN = static_cast<int>(1e6) + 17;

int n, m;
set<int> g[MAXN], gr[MAXN];
bool used[MAXN];
int ans[MAXN], D[MAXN];

bool read() {
    if (!(cin >> n >> m))
        return false;

    forn (i, n - 1 + m) {
        int u, v;
        cin >> u >> v;
        g[u - 1].insert(v - 1);
        gr[v - 1].insert(u - 1);
    }

    return true;
}

void solve() {
    queue<int> Q;
    fill(D, D + n, INF);

    forn (i, n) {
        if (g[i].empty()) {
            used[i] = true;
            Q.push(i);
            D[i] = 0;
        }
    }

    fill(ans, ans + n, 0);

    while (!Q.empty()) {
        int v = Q.front();
        Q.pop();

        for (auto i : gr[v]) {
            g[i].erase(v);

            if (g[i].empty()) {
                if (!used[i]) {
                    used[i] = true;
                    D[i] = D[v] + 1;
                    Q.push(i);
                }
            }
        }
    }

    forn (i, n)
        for (auto p : gr[i])
            if (ans[i] == 0 || D[p] < D[ans[i] - 1])
                ans[i] = p + 1;

    forn (i, n)
        cout << ans[i] << endl;
}

int main() {
    cin.tie(nullptr);
    std::ios_base::sync_with_stdio(false);

    while (read())
        solve();

    return 0;
}

