using namespace std;
int main() {
	int N, M;
	cin >> N >> M;
	vector<vector<int> > G(N), RG(N);
	vector<int> indeg(N);
	for (int i = 0; i < (N - 1) + M; ++i) {
		int a, b;
		cin >> a >> b; --a, --b;
		G[a].push_back(b);
		RG[b].push_back(a);
		++indeg[b];
	}
	queue<int> que;
	for (int i = 0; i < N; ++i) {
		if (indeg[i] == 0) {
			que.push(i);
		}
	}
	vector<int> topos; // topological sort order
	while (!que.empty()) {
		int u = que.front(); que.pop();
		topos.push_back(u);
		for (int i : G[u]) {
			--indeg[i];
			if (indeg[i] == 0) {
				que.push(i);
			}
		}
	}
	vector<int> topos_inv(N); // inversion of "topos" permutation
	for (int i = 0; i < N; ++i) {
		topos_inv[topos[i]] = i;
	}
	for (int i = 0; i < N; ++i) {
		int mx = -1;
		for (int j : RG[i]) {
			if (topos_inv[j] > mx) {
				mx = topos_inv[j];
			}
		}
		cout << (mx == -1 ? -1 : topos[mx]) + 1 << endl;
	}
	return 0;
}

