//ここから編集する
class Solve {
public:
    int N, M;
    vector<vector<int>> G;
    vector<vector<int>> rG;
    int root = -1;

    void input() {
        cin >> N >> M;
        G.resize(N);
        rG.resize(N);
        rep(i, 0, N + M - 1) {
            int a, b;
            cin >> a >> b;
            a--, b--;
            G[a].push_back(b);
            rG[b].push_back(a);
        }
        for (int i = 0; i < N; ++i) {
            if (rG[i].size() == 0) root = i;
        }
    }


    void solve() {
        input();
        vector<int> tree(N, -1);
        set<int> searched;

        queue<int> que;

        que.push(root);
        while (!que.empty()) {
            int top = que.front();
            que.pop();

            int v = top;
            if (!searched.count(v)) {
                for (auto nv : G[v]) {
                    que.push(nv);
                    tree[nv] = v;
                }
            }
            searched.insert(v);
        }

        for (int i = 0; i < N; ++i) {
            cout << tree[i] + 1 << endl;
        }

    }
};


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);

    Solve().solve();


    return 0;
}

