#include <bits/stdc++.h>
using namespace std;
using ll = int64_t;

int main() {
    ll N, M;
    cin >> N >> M;
    vector<vector<ll>> connect(N);
    vector<bool> in(N, false);
    for (ll i = 0; i < N - 1 + M; i++) {
        ll A, B;
        cin >> A >> B;
        connect[A - 1].push_back(B - 1);
        in[B - 1] = true;
    }

    ll root = -1;
    for (ll i = 0; i < N; i++) {
        if (!in[i]) {
            root = i;
            break;
        }
    }

    ll s = root;
    vector<ll> par(N, -1);
    vector<ll> cost(N, 0);
    par[s] = -1;
    priority_queue<pair<ll, ll>> qu;
    qu.push({ 0, s });
    while (!qu.empty()) {
        auto t = qu.top();
        qu.pop();
        if (t.first < cost[t.second]) {
            continue;
        }

        for (ll n : connect[t.second]) {
            if (t.first + 1 > cost[n]) {
                par[n] = t.second;
                cost[n] = t.first + 1;
                qu.push( { t.first + 1, n} );
            }
        }
    }

    for (ll i = 0; i < N; i++) {
        cout << par[i] + 1 << endl;
    }
}

