// dijkstra
typedef pair<int ,int> P;
struct edge{int to, cost;};
vector<edge> G[100000];
int d_dijkstra[100000];
int ans[100000];

void dijkstra(int s){
    priority_queue<P, vector<P>, greater<P>>que;
    Fill(d_dijkstra,-1);
    d_dijkstra[s]=0;
    ans[s]=0;
    que.push(P(0,s));

    while(!que.empty()){
        P p=que.top(); que.pop();
        int v = p.second;
        if(d_dijkstra[v]>p.first) continue;
        for(int i=0; i<G[v].size(); i++){
            edge e=G[v][i];
            if(d_dijkstra[e.to] < d_dijkstra[v]+e.cost){
                d_dijkstra[e.to]=d_dijkstra[v]+e.cost;
                que.push(P(d_dijkstra[e.to], e.to));
                ans[e.to]=v;
            }
        }
    }
}

int main() {
    int N, M; cin >> N >> M;
    vector<int>A,B;
    rep(i,N+M-1){
        int a,b; cin >> a >> b;
        parents[b].push_back(a);
        G[a].push_back(edge{b,1});
    }

    // 根を求める
    int root=0;
    for(int i=1; i<=N; i++){
        if(parents[i].empty()){
            root=i;
        }
    }
    dijkstra(root);
    for(int i=1; i<=N; i++){
        cout << ans[i] << endl;
    }
    return 0;
}

