int N, M, R;
vector<int> G[200000];
int P[200000];
bool vis[200000];
bool deg[200000];

void rec(int from, int prev) {
	vis[from] = true;
	if (P[from] != -1) {
		int p = P[from];
		if (vis[p]) {
			P[from] = prev;
		}
		vis[from] = false;
		return;
	}

	P[from] = prev;
	for (int to : G[from]) {
		rec(to, from);
	}
	vis[from] = false;
}

int main() {
	cin >> N >> M;
	REP(j, 0, N + M - 1) {
		int a, b;
		cin >> a >> b;
		--a; --b;
		G[a].push_back(b);
		deg[b] = true;
	}

	REP(i, 0, N) {
		if (!deg[i]) {
			R = i;
			break;
		}
	}

	Fill(P, -1);
	rec(R, -1);

	REP(i, 0, N) {
		cout << P[i] + 1 << endl;
	}
	return 0;
}

