using namespace std;
using ll = long long;

ll N, M;
vector<vector<ll>> paths;
vector<vector<ll>> rpaths;

void input() {
    cin >> N >> M;
    paths.resize(N + 1);
    rpaths.resize(N + 1);
    for (ll i = 0; i < N - 1 + M; i++) {
        ll a, b;
        cin >> a >> b;
        paths[a].push_back(b);
        rpaths[b].push_back(a);
    }
}

void solve() {
    vector<ll> pars(N + 1, 0);

    vector<bool> visited(N + 1);
    for (auto& targets : paths) {
        for (auto target : targets) {
            visited[target] = true;
        }
    }
    queue<ll> qs;
    for (ll i = 1; i < N + 1; i++) {
        if (not visited[i])
            qs.push(i);
    }

    while(not qs.empty()) {
        auto q = qs.front(); qs.pop();
        auto& targets = paths[q];
        for (auto target : targets) {
            pars[target] = q;
            if (rpaths[target].size() == 1)
                qs.push(target);
            else {
                for (ll i = 0; i < rpaths[target].size(); i++) {
                    if (rpaths[target][i] == q)
                        rpaths[target].erase(rpaths[target].begin() + 1);
                }
            }
        }
    }
    for (ll i = 1; i < N + 1; i++) {
        cout << pars[i] << endl;
    }
}


int main() {
    input();
    //    cout << solve() << endl;
    solve();

    return 0;
}

