int N, M;
vector<int> pa[100001];
list<int> ch[100001];
int tps[100001], res[100001];
bool used[100001];
stack<int> st;

void topo_sort() {
	int root;
	for (int i = 1;i <= N;i++) {
		if (pa[i].empty()) {
			root = i;
			break;
		}
	}
	st.push(root);
	used[root] = true;
	int num = N;
	while (!st.empty()) {
		int r = st.top();
		while (!ch[r].empty() && used[*ch[r].begin()]) {
			ch[r].pop_front();
		}
		if (ch[r].empty()) {
			tps[r] = num--;
			st.pop();
		}
		else {
			st.push(*ch[r].begin());
			used[*ch[r].begin()] = true;
			ch[r].pop_front();
		}
	}
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	cin >> N >> M;
	REP(i, N - 1 + M) {
		int A, B;
		cin >> A >> B;
		ch[A].push_back(B);
		pa[B].push_back(A);
	}
	topo_sort();
	for (int i = 1;i <= N;i++) {
		int n = pa[i].size();
		int tmp = 0;
		for (int j = 0;j < n;j++) {
			if (tmp < tps[pa[i][j]]) {
				tmp = tps[pa[i][j]];
				res[i] = pa[i][j];
			}
		}
	}
	for (int i = 1;i <= N;i++) cout << res[i] << "\n";

	return 0;
}

