vector<int> edge[100001];
P par[100001]={};

void rec(int tar, int parent, int depth){
  par[tar] = P(parent, depth);
  for(int i=0;i<edge[tar].size();i++){
    P next = par[edge[tar][i]];
    if(next.first == 0)
      rec(edge[tar][i], tar, depth+1);
    if(depth >= next.second) 
      rec(edge[tar][i], tar, depth+1);
  }
}

