  int root;
  for(int i=1;i<=n;i++){
    if(!rev[i]) root = i;
  }
  for(int i=0;i<edge[root].size();i++){
    P next = par[edge[root][i]];
    if(next.first == 0)
      rec(edge[root][i], root, 1);
    if(1 >= next.second) 
      rec(edge[root][i], root, 1);
  }
  par[root] = P(0,0);
  for(int i=1;i<=n;i++){
    cout << par[i].first << endl;
  }
}

