using Graph = VVI;
bool topo_sort(const Graph& G, VI& order){
  order.clear();
  int N = G.size();
  VI color(N, 0);

  function<bool(int)> visit = [&](int v)->bool{
	color[v] = 1;
	for(const auto& e: G[v]){
	  if(color[e] == 2) continue;
	  if(color[e] == 1) return false;
	  if(!visit(e)) return false;
	}
	order.push_back(v);
	color[v] = 2;
	return true;
  };

  for(int u=0;u<N;++u)
	if(!color[u] && !visit(u))
	  return false;
