int DFS(int x)
{
	if(deep[x]!=-1)
	{
		return deep[x];
	}
	deep[x]=0;
	EACH(E[x],it)
	{
		int y=*it;
		deep[x]=max(deep[x],DFS(y)+1);
	}
	return deep[x];
}

void solve(int x,int p)
{
	if(par[x]!=-1)
	{
		return ;
	}
	par[x]=p;
	vii ch;
	EACH(E[x],it)
	{
		int y=*it;
		ch.push_back(pii(deep[y],y));
	}
	sort(ALL(ch));
	reverse(ALL(ch));
	EACH(ch,it)
	{
		solve(it->second,x);
	}
}

