using P = pair<int, int>;

int main() {
	int N, M;
	cin >> N >> M;
	vector<vector<int>> to(N);
	vector<int> in_cnt(N, 0);
	for (int i = 0; i < N - 1 + M; ++i) {
		int a, b;
		cin >> a >> b;
		--a; --b;
		to[a].push_back(b);
		++in_cnt[b];
	}

	int root = -1;
	for (int i = 0; i < N; ++i) {
		if (in_cnt[i] == 0) {
			root = i;
			break;
		}
	}

	vector<int> order(N, -1);
	priority_queue<P, vector<P>, greater<P>> que;
	que.push(P(0, root));
	int num = 0;
	while (!que.empty()) {
		P p = que.top(); que.pop();
		int v = p.second;
		if (in_cnt[v] < p.first) { continue; }

		if (in_cnt[v] == 0) { order[num++] = v; }
		for (int i = 0; i < to[v].size(); ++i) {
			--in_cnt[to[v][i]];
			que.push(P(in_cnt[to[v][i]], to[v][i]));
		}
	}

	vector<int> par(N, -1);
	par[root] = 0;
	for (int i = 0; i < N; ++i) {
		int v = order[i];
		for (int j = 0; j < to[v].size(); ++j) {
			par[to[v][j]] = v + 1;
		}
	}

	for (int i = 0; i < N; ++i) {
		cout << par[i] << endl;
	}

	return 0;
}

