// トポロジカルソートされた数列
vector<int> ans;

void dfs(int u) {
    if(used[u]) return;
    used[u] = true;
    for(auto& i: g[u]) dfs(i);
    // 帰りがけ順で追加
    ans.push_back(u);
}

void tsort() {
    for(int i=0; i<v; ++i) dfs(i);
    reverse(ans.begin(), ans.end());
}


int main() {
    ll N, M;
    cin >> N >> M;
    v = N, e = M;
    vector<vector<ll>> connect(N);
    vector<bool> in(N, false);
    vector<ll> out(N, 0);
    for (ll i = 0; i < N - 1 + M; i++) {
        ll A, B;
        cin >> A >> B;
        A--; B--;
        connect[A].push_back(B);
        out[A]++;
        in[B] = true;
        g[A].push_back(B);
    }

    tsort();

    vector<ll> tnum(N, -1);
    for (ll i = 0; i < N; i++) {
        tnum[ans[i]] = i;
    }

    ll root = -1;
    for (ll i = 0; i < N; i++) {
        if (!in[i]) {
            root = i;
            break;
        }
    }

    ll s = root;
    vector<ll> par(N, -1);
    vector<ll> cost(N, 0);
    par[s] = -1;
    priority_queue<pair<ll, pair<ll, ll>>> qu;
    qu.push({ 0, { 0, s }});
    while (!qu.empty()) {
        auto t = qu.top();
        qu.pop();
        if (t.first < cost[t.second.second]) {
            continue;
        }

        for (ll n : connect[t.second.second]) {
            if (t.first + 1 > cost[n]) {
                qu.push( { t.first + 1, {N - tnum[n], n} } );
                par[n] = t.second.second;
                cost[n] = t.first + 1;
            }
        }
    }

    for (ll i = 0; i < N; i++) {
        cout << par[i] + 1 << endl;
    }
}

