const int MAX_V = (int)1e5 + 5;
const int MAX_E = (int)2e5 + 5;

class UNION_FIND{
public:
	vector<int> a;
	UNION_FIND(int n){
		a.clear();
		a.resize(n, -1);
	}

	~UNION_FIND(){
		a.clear();
	}

	int find(int x){
		if (a[x] < 0){
			return x;
		}else{
			return (a[x] = find(a[x]));
		} // end if
	}

	void unite(int x, int y){
		x = find(x);
		y = find(y);
		if (x != y){
			a[x] += a[y];
			a[y] = x;
		} // end if
	}

	bool same(int x, int y){
		return find(x) == find(y);
	}

	int size(int x){
		return -a[find(x)];
	} // end if
};

struct edge{
	int u, v, cost;
};

bool cmp(const edge & e1, const edge & e2){
	return e1.cost < e2.cost;
}

edge es[MAX_E];
int V, E;			// 頂点数と辺数
bool used[MAX_E];

void kruskal(void){
	memset(used, false, sizeof(used));
	sort (es, es+E, cmp);	// edge.cost が小さい順にソートする
	UNION_FIND uf(V);	// Union-Find の初期化
	int res = 0;
	for (int i = 0; i < E; ++i){
		edge e = es[i];
		if (!uf.same (e.u, e.v)){
			uf.unite (e.u, e.v);
			res += e.cost;
//			cerr << "egde:(" << e.u << ',' << e.v << ") is used." << endl;
			used[i] |= true;
		} // end if
	} // end rep
}

vector<int> G[MAX_V];

int parent[MAX_V];

void dfs(int curr, int prev){
	parent[curr] = prev;
	rep (i, (int)G[curr].size()){
		int next = G[curr][i];
		if (next != prev){
			dfs(next, curr);
		} // end if
	} // end rep
}

int main()
{
	ios_base::sync_with_stdio(0);
	cin.tie(0);
	int N, M; cin >> N >> M;
	V = N, E = N - 1 + M;
	vector<int> A(N - 1 + M, 0), B(N - 1 + M, 0);
	rep (i, N - 1 + M){
		cin >> A[i] >> B[i];
		--A[i], --B[i];
		es[i] = (edge){A[i],B[i],1};
	} // end rep

	kruskal();

	rep (i, V) G[i].clear();
	rep (i, E){
		if (used[i]){
			edge e = es[i];
			int u = e.u;
			int v = e.v;
			G[u].push_back(v);
			G[v].push_back(u);
		} // end if
	} // end rep

	memset(parent, -1, sizeof(parent));
	rep (i, E){
		if (used[i]){
			dfs(i, -1);
		} // end if
	} // end rep

	rep (i, N){
		cout << parent[i] + 1 << endl;
	} // end rep

	return 0;
}

