void bfs(int root) {
    rep(i, 100100) {
        dis[i] = INF;
    }
    par[root] = 0;
    queue<pii> que;
    que.push(pii(root, 0));
    while (!que.empty()) {
        pii p2 = que.front();
        que.pop();
        int p = p2.first;
        int cost = p2.second;
        if (cost >= dis[p])continue;
        dis[p] = cost;
        for (auto q:G[p]) {
            if (dis[q] > cost + 1) {
                que.push(pii(q, cost + 1));
            }
        }
    }
}

bool update_sub(int i) {
    int maxval = 0;
    for (auto p:G2[i]) {
        maxval = max(maxval, dis[p]);
    }
    if (dis[i] != maxval + 1) {
        dis[i] = maxval + 1;
        return true;
    }
    return false;
}

void update() {
    bool updated = false;
    while (true) {
        for (int i = 1; i <= N; ++i) {
            updated |= update_sub(i);
        }
        if (!updated) {
            return;
        }
        updated = false;
    }
}

int ansi(int i) {
    int maxidx = -1;
    int maxval = -1;
    for (auto p:G2[i]) {
        if (dis[p] > maxval) {
            maxval = dis[p];
            maxidx = p;
        }
    }
    if (maxidx == -1)return 0;
    return maxidx;
}

