struct edge_t {
  int from;
  int to;
};

using namespace std;

static int n, m;
static std::vector<edge_t> es{};
static std::vector<std::vector<int>> sources{};
static std::vector<std::vector<int>> dests{};
static std::forward_list<int> topologicals{};
static std::vector<bool> visited{};

void visit(int from) {
  if (visited[from]) {
    return;
  }
  visited[from] = true;
  for (auto const fromIdx : sources[from]) {
    auto& e = es[fromIdx];
    visit(e.to);
  }
  topologicals.push_front(from);
}

std::vector<int> solve(int root) {
  visit(root);
  std::vector<int> topologicalOrders(n);
  int i = 0;
  for (auto const idx : topologicals) {
    topologicalOrders[idx] = i++;
  }

  std::vector<int> ret(n);
  for (int i = 0; i < n; ++i) {
    int from = -1;
    int topologicalOrder = -1;
    for (auto const toIdx : dests[i]) {
      auto& e = es[toIdx];
      if (topologicalOrders[e.from] <= topologicalOrder) {
        continue;
      }
      topologicalOrder = topologicalOrders[e.from];
      from = e.from;
    }
    ret[i] = from + 1;
  }
  return ret;
}

int main() {
  std::cin.tie(nullptr);
  std::ios::sync_with_stdio(false);
  std::cin >> n >> m;
  es.resize(n - 1 + m);
  dests.resize(n, std::vector<int>(0));
  sources.resize(n, std::vector<int>(0));
