    e.from--;
    e.to--;
    sources[e.from].push_back(i);
    dests[e.to].push_back(i);
    rootish[e.to] = false;
  }
  int root;
  for (root = 0; root < n; ++root) {
    if (rootish[root]) {
      break;
    }
  }
  auto ret = solve(root);
  for (auto node : ret) {
    std::cout << node << std::endl;
  }
  return 0;
}

