struct Graph
{
    Graph(const std::size_t v) : V{v}, edge(v), rev_edge(v) {}
    void addEdge(const std::size_t from, const std::size_t to) { edge[from].push_back(to), rev_edge[to].push_back(from); }
    const std::size_t V;
    std::vector<std::vector<std::size_t>> edge, rev_edge;
};
std::pair<bool, std::vector<std::size_t>> TopSort(const Graph& g)
{
    std::vector<std::size_t> srt, used(g.V, 0);
    auto dfs = [&](auto&& self, const std::size_t s) -> bool {
        if (used[s] == 1) {
            return false;
        } else if (used[s] == 0) {
            used[s] = 1;
            for (const std::size_t to : g.edge[s]) {
                if (not self(self, to)) { return false; }
            }
            used[s] = 2, srt.push_back(s);
        }
        return true;
    };
    for (std::size_t i = 0; i < g.V; i++) {
        if (not dfs(dfs, i)) { return {false, srt}; }
    }
    std::reverse(srt.begin(), srt.end());
    return {true, srt};
}
int main()
{
    int N, M;
    std::cin >> N >> M;
    Graph g(N);
    for (int i = 0; i < N + M - 1; i++) {
        int u, v;
        std::cin >> u >> v, u--, v--;
        g.addEdge(u, v);
    }
    const auto top = TopSort(g).second;
    std::vector<int> dp(N, 0);
    for (int i = 0; i < N; i++) {
        for (const int to : g.edge[top[i]]) { dp[to] = std::max(dp[to], dp[top[i]] + 1); }
    }
    std::vector<int> ans(N, 0);
    for (int i = 0; i < N; i++) {
        for (const int to : g.edge[top[i]]) {
            if (dp[to] == dp[top[i]] + 1) {
                ans[to] = top[i] + 1;
            }
        }
    }
    for (int i = 0; i < N; i++) { std::cout << ans[i] << std::endl; }
    return 0;
}

