int dmax[101010];

int visit(int p)
{
	if (dmax[p] != -1) return dmax[p];

	dmax[p] = 0;
	for (int q : graph[p]) {
		dmax[p] = max(dmax[p], visit(q) + 1);
	}

	return dmax[p];
}

int ans[101010];

void visit2(int p, int rt)
{
	if (ans[p] != -1) return;
	ans[p] = rt + 1;

	vector<pair<int, int>> ch;
	for (int q : graph[p]) ch.push_back({dmax[q], q});
	sort(ch.begin(), ch.end());
	reverse(ch.begin(), ch.end());

	for (auto a : ch) visit2(a.second, p);
}

