    vector<bool> in(N, false);
    for (ll i = 0; i < N - 1 + M; i++) {
        ll A, B;
        cin >> A >> B;
        connect[A - 1].push_back(B - 1);
        in[B - 1] = true;
    }

    ll root = -1;
    for (ll i = 0; i < N; i++) {
        if (!in[i]) {
            root = i;
            break;
        }
    }

    ll s = root;
    vector<ll> par(N, -1);
    vector<ll> cost(N, 0);
    par[s] = -1;
    priority_queue<pair<ll, ll>> qu;
    qu.push({ 0, s });
    while (!qu.empty()) {
        auto t = qu.top();
        qu.pop();
        for (ll n : connect[t.second]) {
            if (t.first + 1 > cost[n]) {
                par[n] = t.second;
                qu.push( { t.first + 1, n} );
            }
        }
    }

    for (ll i = 0; i < N; i++) {
        cout << par[i] + 1 << endl;
    }
}

