int n, m;
int a[100000 + 5], b[100000 + 5];
vector<vector<int>> g(100000 + 5);
vector<int> ans(100000 + 5, -1);
vector<int> indeg(100000 + 5), outdeg(100000 + 5);
vector<bool> visited(100000 + 5);

void dfs(int now, int par) {
  visited[now] = true;
  if (par != -1 && ans[now] == -1) {
    ans[now] = par + 1;
  }
  for (auto nx : g[now]) {
    if (nx == par || visited[nx]) continue;
    if (indeg[nx] == 1) {
      for (auto nx2 : g[now]) {
        indeg[nx2]--;
      }
      dfs(nx, now);
      for (auto nx2 : g[now]) {
        indeg[nx2]++;
      }
    }
  }
  return;
}

void bfs(int r, int par) {
  queue<pii> q;
  q.push({r, par});
  while (!q.empty()) {
    pii p = q.front();q.pop();
    int now = p.fi;
    int pa = p.se;
    visited[now] = true;
    if (now != r) ans[now] = pa + 1;
    for (auto nx : g[now]) {
      if (indeg[nx] == 1 && !visited[nx]) {
        visited[nx] = true;
        q.push({nx, now});
      }
    }
    for (auto nx : g[now]) {
      indeg[nx]--;
    }
  }
}

