struct node{
	int x,d;
	node() {}
	node(int x,int d) : x(x),d(d) {} 
	bool operator < (const node &rhs) const {
		return d<rhs.d;
	}
};
priority_queue<node> q;
void dijkstra(int rt) {
	dis[rt]=1;
	q.push(node(rt,1));
	while (!q.empty()) {
		node u=q.top(); q.pop();
		if (u.d!=dis[u.x]) continue;
		for (int i=0;i<G[u.x].size();i++) {
			int y=G[u.x][i];
			if (dis[y]<dis[u.x]+1) {
				dis[y]=dis[u.x]+1;
				fa[y]=u.x;
				q.push(node(y,dis[y]));
			}
		}
	}
}

