    int root = -1;
    for(int i=0; i<N; ++i) {
        if(indeg[i] == 0) {
            root = i;
            break;
        }
    }

    auto par = solve(G, root, N);
    for(int i=0; i<N; ++i) cout << par[i] + 1 << endl;
}

