vector<vector<int>> chi;
vector<int> nPar;
vector<int> dist;
vector<int> ans;

void dfs(int n){
    // 葉に達したら探索を終える
    if(chi[n].size()==0) return;

    int nChi = chi[n].size();
    // 頂点 n の子の、根からの距離を求める
    for(int i=0; i<nChi; i++){
        int nxt = chi[n][i];
        nPar[nxt]--;
        if(dist[nxt] < dist[n] + 1){
            // 距離が更新される時に、親を更新する
            dist[nxt] = dist[n] + 1;
            ans[nxt] = n;
        }
        // 頂点 nxt への nPar[nxt] 回目の参照のとき、以降の探索を行う。
        if(nPar[nxt]==0) dfs(nxt);
    }
}

int main(){
    int N, M;
    cin >> N >> M;
    // chi[i][j] は頂点 i の j 番目の子
    chi = vector<vector<int>>(N+1, vector<int>());
    // 各頂点の親の数を数えておく
    nPar = vector<int>(N+1,0);
    for(int i=0; i<N+M-1; i++){
        int A, B;  cin >> A >> B;
        chi[A].push_back(B);
        nPar[B]++;
    }

    // 根を求める
    vector<bool> rootCand(N+1, true);
    for(int i=1; i<=N; i++){
        int nChi = chi[i].size();
        for(int j=0; j<nChi; j++) rootCand[chi[i][j]]=false;
    }
    int root;
    for(int i=1; i<=N; i++) if(rootCand[i]) root = i;

    // dist[i] は根から頂点 i への距離
    dist = vector<int>(N+1, 0);
    // ans[i] は頂点 i の親
    ans = vector<int>(N+1, 0);
    ans[root] = 0;
    // 根から深さ優先探索を行う
    dfs(root);
    for(int i=1; i<=N; i++){
        cout << ans[i] << endl;
    }
}

