    vector<vector<ll>> Gr;
    vector<ll> indegree; //各ノードの入次数
    queue<ll> noindegree; //入次数0のノード
    vector<ll> topo; //topoligical sorted

    graph(ll n): N(n), G(N), Gr(N), indegree(N){}

    void add_edge(ll s, ll t){
        G[s].emplace_back((edge){t});
        Gr[t].emplace_back(s);
        ++indegree[t];
    }

    void go(){
        rep(i,N) if(indegree[i]==0) noindegree.emplace(i);
        while(!noindegree.empty()){
            ll v=noindegree.front();
            noindegree.pop();
            topo.emplace_back(v);
            for(auto E: G[v]){
                if(--indegree[E.to]==0) noindegree.push(E.to);
            }
        }
    }

};


//--MAIN-----------------------------------
void Main() {
    ll N,M; cin>>N>>M;
    graph g(N);
    vector<ll> A(N-1+M);
    vector<ll> B(N-1+M);
    rep(i,N-1+M){
        cin>>A[i]>>B[i]; --A[i],--B[i];
        g.add_edge(A[i],B[i]);
    }
    g.go();
    vector<ll> parent(N,-1);
    rep(i,N){
        ll v=g.topo[i];
        for(auto E: g.G[v]){
            parent[E.to]=v;
        }
    }
    rep(i,N){
        cout<< parent[i]+1 <<"\n";
    }

}
