void visit(int now)
{
	used[now]=true;
	for(int i=0;i<g[now].size();i++)
	{
		if(!used[g[now][i].to])
			visit(g[now][i].to);
	}
	tres.push_back(now);
	return;
}
void tsort(int n)
{
	tres.clear();
	fill(used,used+n,false);
	for(int i=0;i<n;i++)
	{
		if(!used[i])
			visit(i);
	}
	reverse(tres.begin(),tres.end());
}
