int main(){
  int N,M;
  cin>>N>>M;
  int a,b;
  vector<vector<int>> gh;
  int gh_n[N][N]={};
  gh.resize(N);
  //入次数の管理
  int h[N]={};
  //トポロジカルソート の実装
  for(int i=0;i<N+M-1;i++){
    cin>>a>>b;
    //aからbへの有向グラフ
    gh[a-1].push_back(b-1);
    gh_n[a-1][b-1]=1;
    h[b-1]+=1;
  }
  //入次数0の要素をキューとして管理
  queue<int> q;
  for(int i=0;i<N;i++){
    if(h[i]==0){
      q.push(i);
    }
  }

  vector<int> ans;
  int tmp,tmp_2;
  while(q.size()){
    int i=q.front();
    q.pop();
    ans.push_back(i);
    //隣接する頂点の入次数を-1する
    for(int j=0;j<gh[i].size();j++){
      tmp=gh[i][j];
      h[tmp]-=1;
      if(h[tmp]==0){
        q.push(tmp);
      }
    }
  }

  int result[N]={};
  result[ans[0]]=(-1);

  //順番に親を出力していく。親は入次してくる者のうち、もっともトポロジカルソートで下位の者
  for(int i=1;i<N;i++){
    tmp=ans[i];
    //tmpについて親を調べる
    for(int k=i-1;k>=0;k--){
      tmp_2=ans[k];
      //tmp2が親たりうるかしらベル
      if(gh_n[tmp_2][tmp]==1){
        result[tmp]=tmp_2;
        break;
      }
  }
  }

  for(int i=0;i<N;i++){
    cout<<result[i]+1<<"\n";
  }
return 0;
}

