struct node {
    int id = -1;
    int depth = -1;
    int parent = -1;
    VI children;
};

vector<struct node> nodes;

void f(int root)
{
    deque<int> dq;
    dq.push_back(root);

    while (!dq.empty()) {
        int id = dq.front();
        dq.pop_front();
        struct node p = nodes[id];

        REPALL(i,p.children) {
            if (nodes[p.children[i]].depth  == -1 || nodes[p.children[i]].depth >= p.depth) {
                nodes[p.children[i]].depth = p.depth + 1;
                nodes[p.children[i]].parent = p.id;
                dq.push_back(p.children[i]);
            }
        }
    }
}

