//BELOW
void DFS(int V,int P,vector<vector<int> > &GRAPH, vector<int> & Parent,vector<int>& DIST,vector<int> & used)
{
  if(Parent[V] != P)return;
  if(P != -1)
  if(DIST[P] + 1 != DIST[V])return;
  for (auto &&nV : GRAPH[V])
  {
    if(DIST[V] +1 >= DIST[nV])
    {
      Parent[nV] = V;
      DIST[nV] = DIST[V]+1;
      DFS(nV,V,GRAPH,Parent,DIST,used);
    }

  }
  return;
}
void solve(void)
{ 
  int N,M;
  cin>>N>>M;
  vector<vector<int> > GRAPH (N);
  vector<int> CNT(N,0);
  vector<int> UsedE(N,-1);
  for (int i = 0; i < N + M -1 ; i++)
  {
    int A,B;
    cin>>A>>B;
    A--;B--;
    GRAPH[A].push_back(B);
    CNT[B]++;
  }
  int S = -1;
  for (int i = 0; i < N; i++)
  {
    if(CNT[i] == 0)S = i;
  }
  vector<int> P (N,-1);
  vector<int> DIST(N,0);
  DIST[S] = 0;
  DFS(S,-1,GRAPH,P,DIST,UsedE);
  for (int i = 0; i < N; i++)
  {
    cout<<P[i]+1<<endl;
  }


  return;
}
