int dfs(int node,int p=0,int d=0)
{
    vis[node]=1;
    par[node]=p;
    dist[node]=d;
    for(int to:g[node]){
        if(vis[to]){
            if(dist[to]<dist[node]+1){
                dist[to]=dist[node]+1;
                par[to]=node;
            }
        }
        else
            dfs(to,node,d+1);
    }
}
