void dfs(ll u, ll p, ll count) {
	// printf("dfs %d %d %d\n", u + 1, p + 1, count);
	memo[u].insert(make_pair(-count, p));
	if (G[u].size() == 0) return;

	for (auto v : G[u]) {
		if (rec[u].count(v)) continue;
		rec[u].insert(v);
		dfs(v, u, count + 1);
	}
}

