#include <bits/stdc++.h>
using namespace std;
using vi = vector<int>;
using vvi = vector<vi>;
#define repex(i, a, b, c) for(int i = a; i < b; i += c)
#define repx(i, a, b) repex(i, a, b, 1)
#define rep(i, n) repx(i, 0, n)
#define repr(i, a, b) for(int i = a; i >= b; i--)
#define pb push_back
const int MAX = 101010;
int iDegree[MAX]; // 各頂点における入次数.
int ans[MAX];     // 各頂点における親頂点.

// グラフをトポロジカルソートする.
// https://ja.wikipedia.org/wiki/トポロジカルソート
// ※トポロジカルソートの動作確認用.
// @param G: グラフ.
// @param N: 頂点数.
// @param s: グラフの探索開始頂点(※入力辺を持たない頂点(根)).
// @return: 特に無し.
void tSort(vvi &G, int N, int s){
    // 1. 変数準備.
    vi L;         // トポロジカルソートした結果を蓄積する空リスト.
    queue<int> q; // 入力辺を持たないすべての頂点の集合(空のキュー).

    // 2. 探索開始頂点 s をキュー q に追加.
    q.push(s);
    while(!q.empty()){
        // 3. キューから取り出す.
        int n = q.front();
        q.pop();

        // 4. L に n を 追加.
        L.pb(n);

        // 5. 取り出した要素を処理.
        for(auto &m : G[n]){
            // 6. n の 出力辺 e を グラフから削除.
            iDegree[m]--;

            // 7. m がその他の入力辺を持っていなければ, q に 追加.
            if(!iDegree[m]) q.push(m), ans[m] = n + 1;
        }
    }

    // 8. グラフに辺が残っている場合は, 閉路があり, 
    // DAG(Directed Acyclic Graph)でないので中断.
    bool isDAG = true;
    rep(i, N){
        if(iDegree[i]){
            isDAG = false;
            break;
        }
    }
    assert(isDAG != false); // DAGでない場合.
    return;
}

int main(){

    // 1. 入力情報.
    int N, M, a, b;
    scanf("%d %d", &N, &M);
    vvi G(N);
    rep(i, N + M - 1){
        scanf("%d %d", &a, &b);
        a--, b--;
        G[a].pb(b);
        iDegree[b]++;
    }

    // 2. 入次数ゼロの頂点(根)は？
    int root = -1;
    rep(i, N){
        if(!iDegree[i]){
            root = i;
            break;
        }
    }
    assert(root != -1); // 根が見つからなかった場合.

    // 3. Topological Sort.
    tSort(G, N, root);

    // 4. 出力.
    rep(i, N) printf("%d\n", ans[i]);
    return 0;

}

