#include <bits/stdc++.h>

using namespace std;

typedef long long ll;
typedef vector<ll> vi;
typedef vector<vi> vvi;
typedef pair<ll, ll> pii;
typedef vector<pii> vpii;

int main() {
  ll N, M;
  cin >> N >> M;

  vi A(N + M - 1), B(N + M - 1);
  for (ll i = 0; i < N + M - 1; i++) {
    cin >> A[i] >> B[i];
    A[i] -= 1;
    B[i] -= 1;
  }

  ll r;
  {
    vi v(N);
    for (ll i = 0; i < N + M - 1; i++) {
      v[B[i]] += 1;
    }
    for (ll i = 0; i < N; i++) {
      if (v[i] == 0) {
        r = i;
      }
    }
  }

  vvi G(N);
  for (ll i = 0; i < N + M - 1; i++) {
    G[A[i]].push_back(B[i]);
  }

  vector<unordered_set<ll>> G2(N);
  for (ll i = 0; i < N + M - 1; i++) {
    G2[A[i]].insert(B[i]);
  }

  vi v1;
  {
    list<ll> q;
    unordered_set<ll> visited;
    q.push_back(r);
    while (!q.empty()) {
      ll n = -1;
      vi v;
      for (ll i: G2[q.back()]) {
        v.push_back(i);
        if (visited.find(i) == visited.end()) {
          n = i;
          for (ll j: v) {
            G2[q.back()].erase(j);
          }
          break;
        }
      }
      if (n == -1) {
        v1.push_back(q.back());
        q.pop_back();
      } else {
        visited.insert(n);
        q.push_back(n);
      }
    }
  }

  vi v2(N, -1);
  {
    unordered_set<ll> s;
    for (ll i = 0; i < N; i++) {
      for (ll j: G[v1[i]]) {
        if (s.find(j) != s.end()) {
          v2[j] = v1[i];
          s.erase(j);
        }
      }
      s.insert(v1[i]);
    }
  }

  for (ll i = 0; i < N; i++) {
    cout << v2[i] + 1 << endl;
  }
}

