typedef long long ll;

vector<long long> topological_sort(vector<vector<ll>> &graph,vector<ll> &in_degrees){
    stack<ll> st;
    for (ll i=1;i<graph.size();i++){
        if (in_degrees[i] == 0) st.push(i);
    }
    vector<ll> ans;
    while(st.size()>0){
        auto i = st.top();st.pop();
        ans.push_back(i);
        for (auto &j:graph[i]){
            in_degrees[j] --;
            if (in_degrees[j] == 0) st.push(j);
        }
    }
    return ans;
}


void solve(long long N, long long M, std::vector<long long> A, std::vector<long long> B){
    //隣接リストを構築
    vector<vector<ll>> graph(N+1);    //グラフの頂点はN個    
    vector<vector<ll>> in_graph(N+1);
    vector<ll> in_degrees(N+1,0);
    for (ll i=0;i<A.size();i++){
        graph[A[i]].push_back(B[i]);
        in_graph[B[i]].push_back(A[i]);
        in_degrees[B[i]]+=1;
    }
    vector<ll> sorted_graph = topological_sort(graph,in_degrees);
    vector<ll> node_score(N+1);
    for (ll i=0;i<sorted_graph.size();i++){
        node_score[sorted_graph[i]] = i;
    }
