void dfs(int curr, int prev, int depth){
	used[curr] |= true;
	int cnt = 0;

	if (depth > maxDepth){
		candV = curr;
		maxDepth = depth;
	} // end if

	rep (i, (int)G[curr].size()){
		int next = G[curr][i];
		if (prev != -1){
			if (!used[next] && cnt == 0){
				dfs(next, curr, depth + 1);
				g[curr].push_back(next);
				g[next].push_back(curr);
				++cnt;
			} // end if
		}else{
			if (!used[next] && cnt <= 1){
				dfs(next, curr, depth + 1);
				g[curr].push_back(next);
				g[next].push_back(curr);
				++cnt;
			} // end if
		} // end if
	} // end rep
