int getRoot(const int n, const vector<Edge>& edges) {
  set<int> rootie;
  for (int i = 0; i < n; ++i)
    rootie.insert(i);
  for (auto& e : edges)
    rootie.erase(e.second);
  return *rootie.begin();
}

