void dfs(int now,int depth){
    d[now]=max(d[now],depth);
    for(int child:children[now]){
        if(d[child]==depth+1) continue;
        dfs(child,depth+1);
    }
}

vector<int> ans;
void solve(int now,int parent){
    ans[now]=parent;
    for(int child:children[now]){
        if(d[child]==d[now]+1){
            solve(child,now);
        }
    }
}

