void dijkstra(const vector< vector<int> >& G, vector<int>& d, vector<int>& prev, int s)
{
   priority_queue<P> que;
   fill(d.begin(), d.end(), 0);
   prev[s] = -1;
   que.push(P(0, s));
   while(!que.empty()) {
      int temp_cost = que.top().first;
      int from = que.top().second;
      que.pop();
      if (d[from] > temp_cost) continue;
      for (int i = 0; i < G[from].size(); i++) {
         int to = G[from][i];
         if (d[to] < d[from] + 1) {
            d[to] = d[from] + 1;
            que.push(P(d[to], to));
            prev[to] = from;
         }
      }
   }
}

