      A[i]--; B[i]--;
   }

   vec<vec<int>> G(N);
   REP(i, 0, N-1+M) {
      G[A[i]].PB(B[i]);
   }
   vec<int> d(N);
   vec<int> prev(N);
   int s = -1;
   set<int> st;
   REP(i, 0, N-1+M) {
      st.insert(B[i]);
   }
   REP(i, 0, N) {
      if (!EXIST(st, i)) {
         s = i;
         break;
      }
   }

   dijkstra(G, d, prev, s);
   DUMP(d)
   DUMP(prev)
   REP(i, 0, N) {
      cout << prev[i]+1 << endl;
   }

   return 0;
}

