using namespace std;

void dfs(vector<vector<int>> &vec, vector<vector<int>> &road, int node, int dp){

    for(int i=0; i<road[node].size(); i++){
        int next = road[node][i];
        if(vec[next][0]==node)continue;
        else if(vec[next][1]<dp+1){
            vec[next][0]=node;
            vec[next][1]=dp+1;
        }
        dfs(vec, road, next,dp+1);
    }
}

int rootSearch(vector<vector<int>> &inv_road, int node){
    if(inv_road[node].size()==0){
        return node;
    }else{
        return rootSearch(inv_road, inv_road[node][0]);
    }
}

int main(){
    int N,M;
    cin >> N >> M;
    vector<vector<int>> road(N,vector<int>({}));
    vector<vector<int>> inv_road(N,vector<int>({}));
    vector<vector<int>> tree(N,vector<int>(2,-1));

    for(int i=0; i<N+M-1; i++){
        int A,B;
        cin >> A >> B;
        A--;B--;
        road[A].push_back(B);
        inv_road[B].push_back(A);
    }
    int root = rootSearch(inv_road, 0);
    tree[root]={-1,0};
    dfs(tree,road,root,0);

    for(int i=0; i<N; i++){
        cout << tree[i][0]+1 << endl;
    }

}

