		scanf("%d %d", &input1, &input2);

		graph[input1].push_back(input2);

		indeg[input2]++;
	}

	for (i = 1; i <= n; i++)
	{
		if (!indeg[i])
		{
			parent[i] = 0;

			q.push(i);

			break;
		}
	}

	while (!q.empty())
	{
		cur = q.front();

		q.pop();

		for (i = 0; i < graph[cur].size(); i++)
		{
			if (!(--indeg[graph[cur][i]]))
			{
				parent[graph[cur][i]] = cur;

				q.push(graph[cur][i]);
			}
		}
	}

	for (i = 1; i <= n; i++)
	{
		printf("%d\n", parent[i]);
	}

	return 0;
}

