    read(N, M);
    fill(inDeg, inDeg + N, 0);
    FOR(i, N - 1 + M) {
        int a, b;
        read(a, b);
        dfs.addEdge(--a, --b);
        inDeg[b]++;
    }
    int root = -1;
    FOR(i, N) if (inDeg[i] == 0) root = i;
    assert(root != -1);
    FOR(i, N) if (inDeg[i] == 0) assert(root == i);
    dfs.run(N, root);
    FOR(i, N) {
        sort(all(dfs.adj[i]), [&] (const int &i, const int &j) {
            return dfs.revPostInd[i] < dfs.revPostInd[j];
        });
    }
    fill(par, par + N, -1);
    makeTree(root, -1);
    FOR(i, N) writeln(par[i] + 1);
    return 0;
}

