void dijkstra(int v) {
    D[v] = {0, -1};

    using pi = pair<int, int>;
    priority_queue<pi> pq;
    pq.push({0, v});

    while (!pq.empty()) {
        auto q = pq.top(); pq.pop();
        // cout << "# v : " << q.second << ", dist : " << q.first << " , D : " << D[q.second].first << endl;
