struct Object {
    // 任意の構造体
    ll x;
    ll depth;
};

queue<Object> q;
vector<vec> v;
int N, M;
vec p;
void bfs() {
    while (!q.empty()) {
        // キューの先頭の要素を取り出す dequeue(pop)
        Object now = q.front(); q.pop();

        // 停止条件
        // if (now.hoge == target) return ~;  // 探索対象
        // if (now.x == gx && now.y == gy) return now.depth;

        // BFS
        rep(i, v[now.x].size()){
            ll next_x = v[now.x][i];
            Object next = {next_x, now.depth+1};  // 深さ（ステップ数）を一つ足す
            p[next_x] = now.x+1;
            q.push(next);
        }
    }
}

