vector<int> TopologicalSort(vector<vector<int>> &G) {
    int N = G.size();
    vector<int> cnt(N);
    for(int i = 0; i < N; i++) {
        for(int j = 0; j < G[i].size(); j++) {
            cnt[G[i][j]]++;
        }
    }
    vector<int> S;
    for (int i = 0; i < N; i++) {
        if (!cnt[i]) S.push_back(i);
    }
    if (!S.size()) return vector<int>();

    vector<int> L;
    while(!S.empty()) {
        int n = S.back(); S.pop_back();
        L.push_back(n);
        for(int i = 0; i < G[n].size(); i++) {
            cnt[G[n][i]]--;
            if (!cnt[G[n][i]]) {
                S.push_back(G[n][i]);
            }
        }
    }
    if (L.size() == N) return L;
    return vector<int>();
}


void solve() {
    int N, M;
    cin >> N >> M;
    vector<int> D(N);
    vector<vector<int>> G(N);
    for (int i = 0; i < N - 1 + M; i++) {
        int a, b;
        cin >> a >> b;
        a--, b--;
        D[b]++;
        G[a].push_back(b);
    }

    vector<int> T = TopologicalSort(G);

    vector<int> P(N);

    for(int i = 0; i < N; i++) {
        if (D[i] == 0) {
            P[i] = -1;
            break;
        }
    }

    for (int i = 0; i < N; i++) {
        int v = T[i];
        for(int j = 0; j < G[v].size(); j++) {
            P[G[v][j]] = v;
        }
    }

    for (int i = 0; i < N; i++) {
        cout << P[i] + 1 << endl;
    }
}

