int main(void){
    // 入力
    int n, m; scanf("%d%d", &n, &m);
    edge.resize(n);
    In.resize(n, 0);
    REP(i, n+m-1){
        int a, b; scanf("%d%d", &a, &b); a--; b--;
        edge[b].push_back(a);
        In[a]++;
    }

    // Topological Sort - ic
    std::queue<int> Q;
    Dist.resize(n); 
    Par.resize(n, -1);

    REP(i, n) if(In[i] == 0){ Q.push(i); Dist[i] = 0;}
    while(not Q.empty()){
        int v = Q.front(); Q.pop();
        for(int nv : edge[v]){
            In[nv]--;
            if(In[nv] == 0){
                Dist[nv] = Dist[v] + 1;
                Q.push(nv);
            }
        }
    }

    // 親の取得
    REP(i, n){
        int par = -1, depth = INT32_MAX;
        for(int v : edge[i]){
            if(depth > Dist[v]){ // 根からもっとも近い部分
                depth = Dist[v];
                par = v;
            }
        }
        // 出力
        printf("%d\n", par+1);
    }

    return 0;
}

