    nodes.resize(n);

    set<int> candidate;
    REP(i,n) {
        nodes[i].id = i;
        candidate.insert(i);
    }

    REP(i,n-1+m) {
        int a, b;
        cin>>a>>b;
        a--; b--;
        nodes[a].children.push_back(b);

        if (candidate.find(b) != candidate.end()) {
            candidate.erase(b);
        }
    }

    int root = *candidate.begin();
    nodes[root].parent = -1;
    nodes[root].depth = 0;
    f(root);

    REP(i,n) {
        cout<<nodes[i].parent + 1<<endl;
    }

    return 0;
}

