struct edge {
    int from, to; ll cost;
    edge(int s, int t, ll w = 0) : from(s), to(t), cost(w) {}
};

bool tpz(vector<vector<edge>> g, vector<pair<int,int>>& ans) {
    int v = g.size(); ans.clear();
    VI in(v, 0);
    for (auto es : g)for (edge e : es)in[e.to]++;
    set<int> set;
    FOR(i, 0, v)if (in[i] == 0) {
        set.insert(i);
        ans.push_back({ i, -1 });
    }

    while (!set.empty()) {
        int now = *set.begin(); set.erase(now);
        for (edge next : g[now]) {
            if (--in[next.to] == 0) {
                set.insert(next.to);
                ans.push_back({ next.to,now });
            }
        }
    }
    return v == ans.size();
}

