vll topological_sort(vvll &G, vll &indeg, ll V) {
    vll ret;
    queue<ll> que;
    // for(ll in:indeg) {
    rep(i,V){
        if(indeg[i]==0) que.push(i);
    }
    while(!que.empty()){
        ll u = que.front();
        que.pop();
        for(auto v:G[u]){
            indeg[v]--;
            if(indeg[v]==0) que.push(v);
        }
        ret.pb(u);
    }
    return ret;
}

