/// template


class DirectedGraph {
    struct edge {
        int from;
        int to;
        int cost;
    };

    int edge_num = 0;

public:
    int V;
    int E;
    vector<edge> edges;

    DirectedGraph(int v, int e) : V(v), edges(e), E(e) {};

    void add_edge(int from, int to, int cost) {
        edge e = {from,to,cost};
        edges[edge_num++] = e;
    }

    // O(E * V)
    vector<int> bellman_ford(int s) {
        vector<int> d(V, 0);
        d[s] = 0;
        while (true) {
            bool update = false;
            for (int i = 0; i < E; i++) {
                edge e = edges[i];
                if (d[e.from] != INF && d[e.to] < d[e.from] + e.cost) {
                    d[e.to] = d[e.from] + e.cost;
                    update = true;
                }
            }

            if (!update) break;
        }
        return move(d);
    }

    bool find_negative_loop() {
        vector<int> d(V, 0);

        for (int i = 0; i < V; i++) {
            for (int j = 0; j < E; j++) {
                edge e = edges[j];
                if (d[e.from] != INF && d[e.to] > d[e.from] + e.cost) {
                    d[e.to] = d[e.from] + e.cost;
                    if (i == V - 1) return true;
                }
            }
        }

        return false;
    }
};

