void dfs2(vector<vll> &G, vb &checked, vll &ts, ll u){
    checked[u] = true;
    for(auto v: G[u]){
        if(!checked[v])
            dfs2(G, checked, ts, v);
    }
    ts.push_back(u);
}

vll dfs_toposort(vector<vll> &G, vb &checked){
    ll N = G.size();
    fill(ALL(checked), false);
    vll ts;
    REP(i, N){
        if(!checked[i]){
            dfs2(G, checked, ts, i);
        }
    }
    reverse(ALL(ts));
    return ts;
}

void solve(long long N, long long M, std::vector<long long> A, std::vector<long long> B){
    vector<vll> G(N), Ginv(N);
    M += N-1;
    REP(i, M){
        G[A[i]].push_back(B[i]);
        Ginv[B[i]].push_back(A[i]);
    }
    //* topological sort
    vb checked(N, false);
    vll ts = dfs_toposort(G, checked);
    //* 
    vll tsinv(N);
    REP(i, N){
        //* vectex ts[i] --> position i
        tsinv[ts[i]] = i;
    }
    //* find parent
    REP(v, N){
        if(Ginv[v].empty())
            cout << 0 << endl;
        else{
            ll res = -1;
            for(auto x: Ginv[v]){
                res = max(res, tsinv[x]);
            }
            cout << ts[res]+1 << endl;
        }
    }

}

