void topological_sort(){
  rep(i,N){     // 初期化
    indeg[i]=0;
    parent[i]=0;
  }
  rep(i,N){
    rep(j,E[i].size()){    //  入次数を持たせる
      indeg[E[i][j]]++;
    }
  }

  rep(i,N){
    if(indeg[i]==0 && !B[i]){
      parent[i]=-1;
      bfs(i);
    }
  }
}

