int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> N >> M;
    vector<ll> iri(N, 0);
    REP(i, N-1+M){
    	ll A, B;
    	cin >> A >> B;
    	A--, B--;
    	G[A].push_back(B);
    	iri[B]++;
    }

    ll root;
    REP(i, N) if(iri[i] == 0) root = i;

    queue<pll> qu;
    qu.push({root, -1});

    ll d = -1;
    while(!qu.empty()){
    	d++;
    	ll qu_len = qu.size();
    	vector<bool> visited(N, false);
    	REP(i, qu_len){
    		pll tmp = qu.front();qu.pop();
    		ll now = tmp.first;
    		ll parent = tmp.second;
    		dist[now] = d;
    		par[now] = parent;
    		REP(j, G[now].size()){
    			ll next = G[now][j];
    			if(visited[next]) continue;
    			qu.push({next, now});
    			visited[next] = true;
    		}
    	}
    }
    REP(i, N){
    	cout << par[i]+1 << endl;
    }
