int find(int x){
	return par[x]=x?par[x]:find(par[x]);
}
void unite(int a,int b){
	a=find(a);
	b=find(b);
	if(a==b) return ;
	if(ran[a]<ran[b]){
		par[a]=b;
	}
	else{
		par[b]=a;
		if(ran[a]==ran[b]) ran[a]++;
	}
}
bool same(int a,int b){
	return find(a)==find(b);
}
