struct node {
	vector<int> child;
	vector<int> parent;
	int flag;
	int indeg;
};
int main() {
	int N, M;
	cin >> N >> M;
	node*T = new node[N];
	int A, B;
	for (int i = 0; i < N - 1 + M; i++) {
		cin >> A >> B;
		T[A-1].child.push_back(B-1);
		T[B-1].parent.push_back(A-1);
	}
	for (int i = 0; i < N; i++) {
		T[i].flag = 0;
		T[i].indeg = T[i].parent.size();
	}
	vector<int>ts;
	queue<int>q;
	for (int i = 0; i < N ; i++) {
		if (T[i].indeg == 0 && T[i].flag == 0) {
			q.push(i);
			T[i].flag = 1;
			while (!q.empty()) {
				int now = q.front();
				q.pop();
				ts.push_back(now);
				for (int tmp : T[now].child) {
					T[tmp].indeg--;
					if (T[tmp].indeg == 0 && T[tmp].flag == 0) {
						q.push(tmp);
						T[tmp].flag = 1;
					}
				}
			}
		}
	}
	vector<int>out(N);
	for (int i = 0; i < N; i++) {
		out[ts[i]] = i+1;
	}
	for (int i = 0; i < N; i++) {
		if (T[i].parent.size() == 0) {
			cout << 0 << endl;
			continue;
		}
		int ans = 0;
		int max = 0;
		for (int tmp : T[i].parent) {
			if (max < out[tmp]) {
				max = out[tmp];
				ans = tmp;
			}
		}
		cout << ans+1 << endl;
	}
}

