class SCC {
	vector<char> used;
	vector<vector<int>> e, re;

	void dfs(int v, vector<int>& vs) {
		used[v] = true;
		for (auto to : e[v]) if (!used[to]) dfs(to, vs);
		vs.push_back(v);
	}
	void rdfs(int v, vector<int> & group) {
		used[v] = true;
		for (auto to : re[v]) if (!used[to]) rdfs(to, group);
		group.push_back(v);
	}

public:
	SCC(const vector<vector<int>>& G) : used(sz(G)), e(sz(G)), re(sz(G)) {
		FOR(i, sz(G)) for (auto to : G[i]) {
			e[i].push_back(to);
			re[to].push_back(i);
		}
	}

	vector<vector<int>> run() {
		vector<int> vs;
		fill(used.begin(), used.end(), 0);
		FOR(v, sz(e)) if (!used[v]) dfs(v, vs);
		fill(used.begin(), used.end(), 0);
		vector<vector<int>> ret;
		for (int i = sz(vs) - 1; i >= 0; i--) {
			if (!used[vs[i]]) {
				ret.emplace_back();
				rdfs(vs[i], ret.back());
			}
		}
		return ret;
	}
};


int main() {
	int n, m; reader(n, m);
	vector<vector<int>> e(n);
	FOR(i, n + m - 1) {
		int a, b; reader(a, b);
		a--; b--;
		e[a].push_back(b);
	}

	SCC scc(e);
	auto dp = scc.run();
	vector<int> ans(n, -1);
	for (auto& x : dp) {
		int a = x[0];
		for (auto to : e[a]) ans[to] = a;
	}
	FOR(i, n) writerLn(ans[i] + 1);


	return 0;
}

