void dfs(int n, ll v) {
  used_v[n] = true;
  for (auto x: adj[n]) {
    if (x.v<=v) {
      used_e[x.i] = true;
      if (used_v[x.to]) continue;
      dfs(x.to,v);
    }
  }
}

