// ShortPath.h start----------------------------------------

bool topologicalSort(const Graph &g, vector<int> &id_ordered);

//----------------------------------------------------------

bool visit(const Graph &g, int id, vector<int> &id_ordered, vector<int> &color) {
	if (color[id] == 2)
		return true;
	if (color[id] == 1)
		return false;
	color[id] = 1; //temporary
	for (const auto &e : g.vertices[id]->edges)
		if (!visit(g, e->p_dst->id, id_ordered, color))
			return false;
	color[id] = 2; //permanent
	id_ordered.push_back(id);
	return true;
}

bool topologicalSort(const Graph &g, vector<int> &id_ordered) {
	const size_t n = g.vertices.size();
	vector<int> color(n, 0);
	for (int id = 0; id < n; id++)
		if (color[id] == 0)
			if(!visit(g, id, id_ordered, color))
				return false;
	reverse(id_ordered.begin(), id_ordered.end());
	return true;
}

// ShortPath.h end----------------------------------------------

