#define REP(i, a, n) for (ll i = ((ll) a); i < ((ll) n); i++)
using namespace std;
typedef long long ll;

ll N, M;
vector<ll> E[200000], R[200000];

ll parent[200000];
set<ll> st;

void dfs(ll v, ll p) {
  bool ok = true;
  for (ll u : R[v]) {
    if (!st.count(u)) {
      ok = false;
    }
  }
  if (!ok) return;

  parent[v] = p;
  st.insert(v);

  for (ll u : E[v]) {
    dfs(u, v);
  }

  st.erase(v);
}

int main(void) {
  cin >> N >> M;
  REP(i, 0, N + M - 1) {
    ll A, B;
    cin >> A >> B, A--, B--;
    E[A].push_back(B);
    R[B].push_back(A);
  }

  ll root;
  REP(i, 0, N) if (R[i].size() == 0) root = i;

  dfs(root, -1);

  REP(i, 0, N) {
    cout << parent[i] + 1 << endl;
  }
}

