using namespace std;
int n,m,a[100001],b[100001],d[100001],num[100001],ans[100001],ori=-1;
vector<int> g[100001];
int visit(int p)
{
	if(d[p]!=-1) return d[p];
	d[p]=0;
	for(int i=0;i<g[p].size();i++)
	 d[p]=max(d[p],visit(g[p][i])+1);
	return d[p];
}
void visit2(int p,int rt)
{
	if(ans[p]!=-1) return;
	ans[p]=rt+1;
	vector<pair<int,int> > ch;
	for(int i=0;i<g[p].size();i++)
	 ch.push_back({d[g[p][i]],g[p][i]});
	sort(ch.begin(),ch.end());
	reverse(ch.begin(),ch.end());
	for(int i=0;i<ch.size();i++)
	 visit2(ch[i].second,p);
}
int main()
{
	cin>>n>>m;
	for(int i=0;i<n-1+m;i++)
	{
		cin>>a[i]>>b[i];
		a[i]--; b[i]--;
	}
	for(int i=0;i<n-1+m;i++)
	{
		g[a[i]].push_back(b[i]);
		num[b[i]]++;
	}
	for(int i=0;i<n;i++)
	 if(num[i]==0) ori=i;
	for(int i=0;i<n;i++)
	d[i]=ans[i]=-1;
	visit(ori);
	visit2(ori,-1);
	for(int i=0;i<n;i++)
	 cout<<ans[i]<<endl;
	return 0;
}

