using namespace std;
int InDegree[100005] , OutDegree[100005];
int Count[100005] , Parents[100005];
set<int> S[100005] , Leaves[2];
set<int>::iterator it , Fit;
map<int,int> M;
map<int,int>::iterator Mit;

int main(){
    int N , m , u , v , i;
    scanf( "%d%d" , &N , &m );

    for( i = 1 ; i <= N - 1 + m ; ++i ){
        scanf( "%d%d" , &u , &v );
        S[v].insert( u );
        ++InDegree[v];
        ++OutDegree[u];
    }

    int root;

    for( i = 1 ; i <= N ; ++i ){
        if( OutDegree[i] == 0 ){
            Leaves[0].insert( i );
            Count[i] = 0;

            for( it = S[i].begin() ; it != S[i].end() ; ++it ){
                Mit = M.find( *it );
                if( Mit == M.end() ) M[*it] = 1;
                else ++Mit->second;
            }
        }
        if( InDegree[i] == 0 ) root = i;
    }

    int Cur , Pre;
    i = 1;

    while( true ){
        Cur = (i&1);
        Pre = (i - 1)&1;

        for( Mit = M.begin() ; Mit != M.end() ; ++Mit ){
            OutDegree[Mit->first] -= Mit->second;

            if( OutDegree[Mit->first] == 0 ){ 
                Leaves[Cur].insert( Mit->first );
                Count[Mit->first] = i;
            }
        }

        if( *( Leaves[Cur].begin() ) == root ){
            Parents[root] = 0;
            break;
        }

        Leaves[Pre].clear();
        M.clear();

        for( it = Leaves[Cur].begin() ; it != Leaves[Cur].end() ; ++it ){
            u = *it;

            for( Fit = S[u].begin() ; Fit != S[u].end() ; ++Fit ){
                Mit = M.find( *Fit );
                if( Mit == M.end() ) M[*Fit] = 1;
                else ++Mit->second;
            }
        }

        ++i;
    }

    int Min , index;

    for( i = 1 ; i <= N ; ++i ){
        Min = 10000000;
        index = 0;

        for( it = S[i].begin() ; it != S[i].end() ; ++it ){
            if( Count[*it] < Min ){
                Min = Count[*it];
                index = *it;
            }
        }

        Parents[i] = index;
    }

    for( i = 1 ; i <= N ; ++i )
        printf( "%d\n" , Parents[i] );
    return 0;
}

