	TOPO tp(n);
	rep(i,n+m-1){
		int a,b;
		cin>>a>>b;
		a--;b--;
		tp.add_edge(a,b);
	}
	vi out=tp.tsort();
	rep(i,n)cout<<out[i]<<endl;
}

