using namespace std;

int depth[100005];

int get_depth(vector<set<int>>& VS, int i) {
  if (0 <= depth[i]) return depth[i];
  else {
    int ret = 0;
    for (auto x : VS[i]) {
      ret = max(ret, get_depth(VS, x) + 1);
    }
    depth[i] = ret;
    return ret;
  }
}

int get_p(vector<set<int>>& VS, int i) {
  int p, maxdepth = -1;
  for (auto x : VS[i]) {
    int d = get_depth(VS, x);
    if (maxdepth < d) {
      p = x;
      maxdepth = d;
    }
  }
  return p;
}

int main() {
  int N, M;
  cin >> N >> M;
  for (int i = 0; i < N; i++) depth[i] = -1;
  int NE = N - 1 + M;
  int a, b;
  vector<set<int>> VS(N);
  for (int i = 0; i < NE; i++) {
    cin >> a >> b;
    a--; b--;
    VS[b].insert(a);
  }
  for (int i = 0; i < N; i++) {
    auto S = VS[i];
    if (S.size() == 0) {
      depth[i] = 0;
      cout << 0 << endl;
    } else if (S.size() == 1) {
      int p = *(S.begin());
      depth[i] = get_depth(VS, p) + 1;
      cout << p + 1 << endl;
    } else {
      int p = get_p(VS, i);
      depth[i] = get_depth(VS, p) + 1;
      cout << p + 1 << endl;
    }
  }
}

