using Graph = vector<vector<T>>;

constexpr int lim = 1e5;
Graph<int> g, ng;
vector<bool> vis;
vector<int> parent;

void dfs(int n){
  if(!vis[n]){
    vis[n] = true;

    for(int i=0; i<g[n].size(); i++){
      bool skip = false;
      for(int j=0; j<ng[g[n][i]].size(); j++){
        if(!vis[ng[g[n][i]][j]]){
          skip = true;
          break;
        }
      }

      if(skip) continue;
      if(parent[g[n][i]] == 0)
        parent[g[n][i]] = n+1;

      dfs(g[n][i]);
    }
  }
}

int main(){
  int n, m; cin >> n >> m;
  g.resize(n); ng.resize(n);
  vis.resize(n, false);
  parent.resize(n, 0);

  vector<bool> isRoot(n, true);
  REP(i, n+m-1){
    int a, b; cin >> a >> b;
    a--; b--;

    g[a].emplace_back(b);
    ng[b].emplace_back(a);
    isRoot[b] = false;
  }

  int root = -1;
  REP(i, n){
    if(isRoot[i]) root = i;
  }
  assert (root != -1);

  dfs(root);

  REP(i, n){
    cout << parent[i] << endl;
  }

  return 0;
}

