class SCC {
public:
  int N;
  vector< vector<int> > G, R;
  vector<int> vs, used, ord;

  SCC(int N) : N(N) {
    G.resize(N);
    R.resize(N);
    used.resize(N);
    ord.resize(N);
  }

  void add_edge(int x, int y) {
    G[x].pb(y);
    R[y].pb(x);
  }

  void dfs(int x) {
    if (used[x]) return;
    used[x] = true;
    for (int t : G[x]) dfs(t);
    vs.pb(x);
  }
  void rdfs(int x, int k) {
    if (used[x]) return;
    used[x] = true;
    ord[x] = k;
    for (int t : R[x]) rdfs(t, k);
  }

  int scc() {
    rep(i, N) used[i] = false;
    rep(i, N) dfs(i);
    rep(i, N) used[i] = false;
    int k = 0;
    for (int i=vs.size()-1; i>=0; i--) {
      if (!used[vs[i]]) rdfs(vs[i], k++);
    }
    return k;
  }
};

