  while(!q.empty()) {
    LL p = q.front();
    q.pop();
    for(LL c:child[p]) {
      parent[c].erase(p);
      if(parent[c].size()==0) {
        q.push(c);
        answer[c]=p;
      }
    }
  }
  FOR(i,1,n+1) cout << answer[i] << endl;
  return 0;
}

