	queue<int> q; q.push(tt);
	while (!q.empty()) {
		int t = q.front(); q.pop();
		for (int i = 0; i < v[t].size(); i++) {
			int u = v[t][i];
			if (par[u] == 0) {
				par[u] = t;
				l[u] = l[t] + 1;
				q.push(u);
			} else if (l[u] < l[t] + 1) {
				par[u] = t;
				l[u] = l[t] + 1;
			}
		}
	}
}

void dfs2(int t) {
	if (l[t] < l[par[t]]) return;
	for (int i = 0; i < v[t].size(); i++) {
		int u = v[t][i];
		if (l[u] < l[t])  {
			l[u] = l[t] + 1;
			par[u] = t;
			dfs2(u);
		}
	}
}

