void rec(int v, vector<vector<int>> const &G, vector<bool> &seen, vector<int> &order, vector<int> &parent) {
  seen[v] = true;
  for (auto next : G[v]) {
    if (seen[next]) {
      if (parent[next] == -1) parent[next] = v;
      continue; // 既に訪問済みなら探索しない
    }
    parent[next] = v+1;
    rec(next, G, seen, order, parent);
  }
  order.push_back(v);
}
