void dfs_2(vector<vector<ll>>& mat, ll current, vector<ll>& parents)
{
    visited.insert(current);
    for (auto e : mat[current])
    {
        if (!visited.count(e))
        {
            parents[e] = current;
            dfs_2(mat, e, parents);
        }
    }
}

