    // Sorting ...
    while(q.size() != 0) {
        int u = q.front();
        q.pop();

        for(int v : adj[u]) {
            if(--inorder[v] == 0) {
                q.push(v);
                parent[v] = u; // Next Vertex in DFS..
            }
        }
    }

