vector<int> solve(vector<vector<int>> G, vector<int> indeg, int root, int N) {
    vector<int> par(N, -1);
    vector<int> dist(N, -1);
    dist[root] = 0;

    queue<int> Q;
    Q.push(root);

    while(!Q.empty()) {
        int v = Q.front(); Q.pop();
        for(int to : G[v]) {
            if(dist[to] < dist[v] + 1) {
                dist[to] = dist[v] + 1;
                par[to] = v;
            }
            indeg[to] -= 1;
            if(indeg[to] == 0) Q.push(to);
        }
    }

    return par;
}

