using ll = long long;

using Graph = vector< vector<int> >;

bool dfs(int cur, vector<int>& memo, Graph& g, vector<int>& order) {
    memo[cur] = 1;
    for (int nex : g[cur]) {
        if (memo[nex] == 2) continue;
        if (memo[nex] == 1) return false;
        if (!dfs(nex, memo, g, order)) return false;
    }
    memo[cur] = 2;
    order.push_back(cur);
    return true;
}

bool tsort(Graph& g, vector<int>& order) {
    vector<int> memo(g.size(), 0);
    for (int i = 0; i < g.size(); i++) {
        if (memo[i] != 0) continue;
        if (!dfs(i, memo, g, order)) return false;
    }
    reverse(order.begin(), order.end());
    return true;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n, m;
    cin >> n >> m;
    Graph g(n), rg(n);
    for (int i = 0; i < n + m - 1; i++) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        g[a].push_back(b);
        rg[b].push_back(a);
    }

    vector<int> order;
    tsort(g, order);

    //for (int i = 0; i < n; i++) cout << order[i] << endl;

    map<int, int> zip;
    for (int i = 0; i < order.size(); i++) {
        zip[order[i]] = i;
    }

    int root = order[0];
    vector<int> par(n, -1);
    par[root] = 0;
    for (int i = 1; i < order.size(); i++) {
        int p = -1, hoge = -1;
        for (int nex : rg[order[i]]) {
            if (par[nex] == -1) continue;
            if (hoge < zip[nex]) {
                hoge = zip[nex];
                p = nex;
            }
        }
        par[order[i]] = p + 1;
    }

    for (int i = 0; i < n; i++) {
        cout << par[i] << endl;
    }
    return 0;
}

