ll root_search(const ll N, const vvll& edge){
  vll root_test(N, -1);
  vector<bool> flag(N, false);
  ll ans = 0;
  rep(i, 0, N){
    if(flag[i]) continue;
    ans = i;
    flag[i] = true;
    root_test[i] = i;
    queue<ll> que;
    que.push(i);
    while(!que.empty()){
      ll next = que.front();
      flag[next] = true;
      rep(j, 0, edge[next].size()){
        root_test[edge[next][j]] = i;
        if(flag[edge[next][j]]) continue;
        que.push(edge[next][j]);
      }
      que.pop();
    }
  }
  return ans;
}

void ans_search(const ll pos, const vvll& edge, vector<bool>& flag, vll& dp, int depth, vll& depth_vec){
  if(flag[pos]){
    return;
  }
  flag[pos] = true;
  for(ll i=0; i<edge[pos].size(); ++i){
    if(depth_vec[edge[pos][i]] > depth+1) continue;
    depth_vec[edge[pos][i]] = depth+1;
    dp[edge[pos][i]] = pos+1;
    ans_search(edge[pos][i], edge, flag, dp, depth+1, depth_vec);
  }
  return;
}

