int Log[100000 + 100];

void bfs(int s) {
	d[s] = 0;
	stack<pair<int, int>> q;
	q.push(make_pair(0, s));
	while (q.size()) {
		auto now = q.top(); q.pop();
		int pos = now.second;
		if (d[pos] > now.first)continue;

		for (int i = 0; i < E[pos].size(); i++) {
			int nxt = E[pos][i];
			if (d[nxt] < d[pos] + 1) {
				d[nxt] = d[pos] + 1;
				q.push(make_pair(d[nxt], nxt));
				Log[nxt] = pos;
			}
		}
	}
}

