int dfs(int idx)
{
	if(depth[idx]!=0)return depth[idx];
	if(G[idx].empty())return depth[idx] = 1;
	for(auto &i:G[idx])
	{
		depth[idx] = max(depth[idx],dfs(i)+1);
	}
