bool mark[N];
vector<int> gr[N], rg[N];
void bfs(int st) {
	queue<int> q;
	q.push(st);
	while (!q.empty()) {
		int v = q.front();
		q.pop();
		for (auto u : gr[v])
			if (!mark[u])
				q.push(u), dis[u] = dis[v] + 1, mark[u] = 1;
	}
	return;
}
void getPar() {
	memset(mark, 0, sizeof(mark));
	queue<int> q;
	for (int i = 0; i < n; i++) 
		if (!(int) gr[i].size())
			q.push(i);
	while (!q.empty()) {
		int v = q.front();
		q.pop();
		pair<int, int> mx = {-1, -1};
		for (auto u : rg[v])
			mx = max(mx, {dis[u], u});
		par[v] = mx.second;;
		if (mx.second > -1 && !mark[mx.second])
			q.push(mx.second);
	}
	return;
}
