using namespace std;
const int N=100005;
int dep[N],fa[N][18],root[N];
vector<int>e[N];
void dfs(int v,int f)
{
	dep[v]=dep[f]+1;
	fa[v][0]=f;
	for(int i=0;i<e[v].size();i++)
		if(e[v][i]!=f)
			dfs(e[v][i],v);
}
int lca(int a,int b)
{
	if(dep[a]<dep[b])
		swap(a,b);
	int t=dep[a]-dep[b];
	for(int i=17;i>=0;i--)
		if(t&(1<<i))
			a=fa[a][i];
	for(int i=17;i>=0;i--)
	{
		if(fa[a][i]^fa[b][i])
		{
			a=fa[a][i];
			b=fa[b][i];
		}
	}
	if(a==b)
		return a;
	else
		return fa[a][0];
}
int main()
{
	int n,m;
	scanf("%d%d",&n,&m);
	for(int i=1;i<=n+m-1;i++)
	{
		int x,y;
		scanf("%d%d",&x,&y);
		e[x].push_back(y);
		root[y]=1;
	}
	for(int i=1;i<=n;i++)
	{
		if(!root[i])
		{
			dep[i]=0;
			dfs(i,0);
		}
	}
	for(int j=1;j<=17;j++)
	{
		for(int i=1;i<=n;i++)
		{
			if(1<<j>dep[i])
				continue;
			fa[i][j]=fa[fa[i][j-1]][j-1];
		}
	}
	for(int i=1;i<=n;i++)
	{
		for(int j=0;j<e[i].size();j++)
		{
			int u=e[i][j];
			if(lca(i,u)!=i)
			{
				fa[u][0]=i;
				for(int j=1;j<=17;j++)
				{
					for(int k=1;k<=n;k++)
					{
						if(1<<j>dep[k])
							continue;
						fa[k][j]=fa[fa[k][j-1]][j-1];
					}
				}
			}
		}
	}
	for(int i=1;i<=n;i++)
		printf("%d\n",fa[i][0]);
	return 0;
}

