struct topological_sort{
    const int V;
    vector<vector<int>> board;
    vector<int> into,list;
    vector<bool> visited;
    topological_sort(int v)
        :V(v)
        ,into(v,0)
        ,visited(v,false)
        {
            board.assign(v,vector<int>());
        }
    // 入力
    void add(int from,int to){
        board[from].push_back(to);
        into[to]++;
    }
    // トポロジカルソート
    void build(){
        for(int i=0;i<V;i++){
            if(into[i]==0&&!visited[i]){
                queue<int> q;
                q.push(i);
                while(q.size()){
                    int from=q.front(); q.pop();
                    list.push_back(from);
                    visited[from]=true;
                    for(int to:board[from]){
                        into[to]--;
                        if(into[to]==0&&!visited[to]){
                            q.push(to);
                        }
                    }
                }
            }
        }
    }
    // 取得
    vector<int> get(){
        return list;
    }
};
int main(){
    int V,E; cin>>V>>E; E+=V-1;
    topological_sort graph(V);
    vector<vector<int>> bboard(V);
    while(E--){
        int s,t; cin>>s>>t;
        graph.add(--s,--t);
        bboard[t].push_back(s);
    }
    graph.build();
    vector<int> l=graph.get();
    int used[V]={};
    int ans[V];
    rep(i,V){
        if(i==0){
            ans[l[i]]=-1;
            used[l[i]]=1;
        }else{
            int depth=0;
            for(int from:bboard[l[i]]){
                if(used[from]){
                    if(depth<used[from]){
                        depth=used[from];
                        ans[l[i]]=from;
                    }
                }
            }
            used[l[i]]=depth+1;
        }
    }
    rep(i,V){
        cout<<ans[i]+1<<endl;
    }
    return 0;
}

