#include <bits/stdc++.h>
using namespace std;

struct edge {
    int from, to;
};

struct graph {
    int n;
    vector<vector<edge>> ev;
    graph(int _n) {
        n = _n;
        ev.assign(n+1, vector<edge>());
    }
    void push_edge(int i, int j) {
        ev[i].push_back({i, j});
    }
};

void tp_dfs(int v, graph &g, vector<bool> &visited, deque<int> &tps) {
    visited[v] = true;
    for (int i = 0; i < g.ev[v].size(); i++) {
        int nextv = g.ev[v][i].to;
        if (visited[nextv]) continue;
        tp_dfs(nextv, g, visited, tps);
    }
    tps.push_front(v);
}

deque<int> TopologicalSort(graph &g) {
    deque<int> tps;
    vector<bool> visited(g.n+1, false);
    for (int i = 1; i <= g.n; i++) {
        if (!visited[i]) {
            tp_dfs(i, g, visited, tps);
        }
    }
    return tps;
}

int main() {
    int n, m; cin >> n >> m;
    graph g(n);
    for (int i = 0; i < m+n-1; i++) {
        int p, q; cin >> p >> q;
        g.push_edge(p, q);
    }
    deque<int> tps = TopologicalSort(g);
    vector<int> parent(n+1, 0);
    for (int i = 0; i < n; i++) {
        int v = tps[i];
        for (int j = 0; j < g.ev[v].size(); j++) {
            int vv = g.ev[v][j].to;
            parent[vv] = v;
        }
    }
    for (int i = 1; i <= n; i++) {
        cout << parent[i] << endl;
    }
    return 0;
}

