int N, M;
vector<int> length, parent;

int calcLength(const vector<vector<int>> &edges, int current)
{
  if (length[current] != -1)
    return length[current];
  int longest = -1;
  for (const int &fr : edges[current])
  {
    int len = calcLength(edges, fr) + 1;
    if (longest < len)
    {
      longest = len;
      parent[current] = fr;
      length[current] = longest;
    }
  }
  return longest;
}

int main(int argc, char const *argv[])
{
  cin >> N >> M;
  parent.resize(N + 1, -1);
  length.resize(N + 1, -1);
  vector<vector<int>> edges(N + 1); // [to, fr]
  for (int i = 0, l = N + M - 1; i < l; ++i)
  {
    int fr, to;
    cin >> fr >> to;
    edges[to].push_back(fr);
  }

  int root;
  for (int to = 1; to <= N; ++to)
  {
    auto &fr = edges[to];
    if (fr.size() == 0)
    {
      root = to;
      break;
    }
  }

  parent[root] = 0;
  length[root] = 0;
  for (int i = 1; i <= N; ++i)
  {
    calcLength(edges, i);
  }

  for (int i = 1; i <= N; ++i)
  {
    cout << parent[i] << '\n';
  }
  cout.flush();
}

