void topological_sort(const vector<vector<int>>& G, vector<int>& idx)
{
   vec<int> num(G.size(),0);
   REP(i, 0, G.size()) {
      REP(j, 0, G[i].size()) {
         num[G[i][j]]++;
      }
   }
   stack<int> st;
   for(int i = 0; i < num.size(); i++) {
      if (num[i] == 0) {
         st.push(i);
      }
   }
   int k = 0;
   while (!st.empty()) {
      int i = st.top(); st.pop();
      idx[i] = k;
      for(int j = 0; j < G[i].size(); j++) {
         num[G[i][j]]--;
         if (num[G[i][j]] == 0) {
            st.push(G[i][j]);
         }
      }
      k++;
   }
}

