void detectDepth(int v, int d = 0) {
    if (depth[v] > d) return;
    depth[v] = d;
    for (const int child : G[v]) {
        detectDepth(child, d + 1);
    }
}

void detectParent(int v) {
    for (const int child : G[v]) {
        if (depth[child] == depth[v] + 1) {
            parent[child] = v;
            detectParent(child);
        }
    }
}

