int scc(const VV<>& g, V<>& comp) {
  int n = g.size();
  VV<> rg(n);
  for (int v = 0; v < n; v++) {
    for (int w : g[v]) {
      rg[w].push_back(v);
    }
  }
  V<> vs;
  V<bool> vis(n);
  comp.resize(n);

  auto dfs = [&](const auto& dfs, int v) -> void {
    vis[v] = true;
    for (int w : g[v]) if (!vis[w]) {
      dfs(dfs, w);
    }
    vs.push_back(v);
  };

  auto rdfs = [&](const auto& rdfs, int v, int k) -> void {
    vis[v] = true;
    comp[v] = k;
    for (int w: rg[v]) if (!vis[w]) {
      rdfs(rdfs, w, k);
    }
  };

  for (int v = 0; v < n; v++) if (!vis[v]) {
    dfs(dfs, v);
  }
  vis.assign(n, false);
  int k = 0;
  reverse(vs.begin(), vs.end());
  for (int v : vs) if (!vis[v]) {
    rdfs(rdfs, v, k++);
  }
  return k;
}

int main() {
  cin.tie(nullptr); ios_base::sync_with_stdio(false);
  int n, m; cin >> n >> m;
  VV<> g(n);
  for (int i = 0; i < n - 1 + m; ++i) {
    int a, b; cin >> a >> b, --a, --b;
    g[a].push_back(b);
  }
  V<> comp;
  int k = scc(g, comp);
  assert(k == n);
  V<> vs(n);
  iota(begin(vs), end(vs), 0);
  sort(begin(vs), end(vs), [&](int u, int v) { return comp[u] < comp[v]; });
  for (int v = 0; v < n; ++v) {
    sort(begin(g[v]), end(g[v]), [&](int ul, int ur) { return comp[ul] < comp[ur]; });
  }
  V<> par(n, -2);
  auto dfs = [&](const auto& dfs, int v, int p) -> void {
    if (par[v] != -2) return;
    for (int w : g[v]) if (w != p) {
      dfs(dfs, w, v);
    }
    par[v] = p;
  };
  dfs(dfs, vs[0], -1);
  for (int v = 0; v < n; ++v) {
    cout << par[v] + 1 << '\n';
  }
}

