void solveTS(ll i,graph &G,ll N,vector<bool> &seen,vector<ll> &res){
    seen[i] = true;
    for (int j = 0; j < G[i].size(); ++j) {
        ll next = G[i][j];
        if(seen[next]){
            continue;
        }
        solveTS(next,G,N,seen,res);
    }
    res.push_back(i);
}

vector<ll> topologicalSort(graph &G, ll N){
    vector<ll> res;
    vector<bool> seen(N);
    for (int i = 0; i < N; ++i) {
        if(!seen[i]){
            solveTS(i,G,N,seen,res);
        }
    }
    reverse(res.begin(),res.end());
    return res;

}

