    {
        pint pa = pq.top();
        pq.pop();
        if (pa.first <= times[pa.second]) continue;
        times[pa.second] = pa.first;
        for (auto nxt : chi[pa.second])
        {
            ans[nxt] = pa.second;
            pq.push(pint(pa.first + 1, nxt));
        }
    }

    FOR(i, 1, N + 1) printf("%d\n", ans[i]);
}

