class topological_sort{
public:
    int V;
    vector<int> vis, indeg, sorted;
    vector<vector<int>> edge;
    topological_sort(int v){
        V = v;
        vis.resize(v, 0);
        indeg.resize(v, 0);
        edge.resize(v);
    }

    void add(int from, int to){
        edge[from].push_back(to);
        indeg[to]++;
    }

    void bfs(int s){
        queue<int> q;
        q.push(s);
        vis[s] = 1;
        while (!q.empty()) {
            int f = q.front();
            q.pop();
            sorted.push_back(f);
            rep(i, edge[f].size()){
                int e = edge[f][i];
                indeg[e]--;
                if (indeg[e] == 0 && !vis[e]) {
                    vis[e] = 1;
                    q.push(e);
                }
            }
        }
    }

    void sort(){
        rep(i, V){
            if (indeg[i] == 0 && !vis[i]) {
                bfs(i);
            }
        }
    }
};



