using namespace std;

template <class T>
struct Edge {
    int to;
    T cost;
    Edge(int to, T cost) : to(to), cost(cost){};
};

template <class T>
class Graph {
public:
    explicit Graph(int N = 0) : size(N) { path.resize(size); }
    void span(int u, int v, T cost = 1) { path[u].push_back(Edge<T>(v, cost)); }
    vector<Edge<T>> operator[](int v) const { return path[v]; }

    int size;
    vector<vector<Edge<T>>> path;
};

template <class T>
class TopologicalSort {
public:
    int size;
    Graph<T> graph;
    vector<bool> visited;
    vector<int> order, id;
    // トポロジカルソート後において、頂点vはid[v]番目

    void dfs(int v) {
        if (visited[v]) return;
        visited[v] = true;
        for (const auto& e : graph[v]) dfs(e.to);
        order.push_back(v);
    }

    explicit TopologicalSort(const Graph<T>& g) : size(g.size), graph(g) {
        visited.assign(size, false);
        for (int v = 0; v < size; ++v) dfs(v);
        reverse(order.begin(), order.end());

        id.resize(size);
        for (int i = 0; i < size; ++i) id[order[i]] = i;
    }
};

int main() {
    int N, M;
    cin >> N >> M;
    Graph<int> graph(N);
    vector<vector<int>> par(N);

    for (int i = 0; i < N + M - 1; ++i) {
        int u, v;
        cin >> u >> v;
        --u, --v;
        graph.span(u, v);
        par[v].push_back(u);
    }

    TopologicalSort<int> ts(graph);
    for (int v = 0; v < N; ++v) {
        int p;
        if (par[v].empty()) {  // 根
            p = -1;
        } else {
            // トポロジカルソートで一番大きいのが直接の親
            p = *max_element(par[v].begin(), par[v].end(),
                             [&](int i, int j) { return ts.id[i] < ts.id[j]; });
        }
        cout << p + 1 << endl;
    }
    return 0;
}

