int n, m, root;
int deg[N], ans[N], dp[N];
bool check[N];
vector<ii> child[N];
ii edge[N];

void solve()    {
    priority_queue<ii> pq;
    FOR(i, 1, n) dp[i] = -1;
    dp[root] = 0; pq.push({0, root});

    while(!pq.empty())  {
        auto cur = pq.top(); pq.pop();
        if(dp[cur.se] != cur.fi) continue;

        for(auto it: child[cur.se]) if(dp[it.fi] < dp[cur.se] + 1){
            dp[it.fi] = cur.fi + 1;
            pq.push({cur.fi + 1, it.fi});
        }
    }
    FOR(i, 1, n)    {
        for(auto it: child[i]) if(dp[it.fi] - dp[i] > 1)
            check[it.se] = 1;
    }
    FOR(i, 1, n - 1 + m) if(!check[i])
        ans[edge[i].se] = edge[i].fi;
    FOR(i, 1, n) cout << ans[i] << '\n';
}

