typedef long long ll;
#define FOR(i, a, n) for (ll i=(ll)a;i<(ll)n;i++)
#define REP(i, n) FOR(i, 0, n)

typedef struct Graph_{
    int n, m;
    vector<vector<int>> matrix;
}Graph;

typedef stack<int> List;


void visit(List &l, Graph &g, vector<int> &flag, int u){
    if (flag[u]==-1){
        exit(0);
    }
    else if (flag[u]!=1){
        REP(v, g.n){
            if (g.matrix[u][v]==1){
                visit(l, g, flag, v);
            }
        }
        flag[u] = 1;
        l.push(u); 
    }
}

vector<int> topological_sort(Graph &g){
    vector<int> flag; flag.resize(g.n);
    REP(i, g.n){
        flag[i] = 0;
    }

    List l;
    vector<int> L(g.n, 0);

    REP(u, g.n){
        if (flag[u]==0){
            visit(l, g, flag, u);
        }
    }

    REP(i, g.n){
        L[i] = l.top();
        l.pop();
    }

    return L;
}

int main(){
    int n,m; cin >> n >> m;
    Graph g;
    g.n = n;
    g.m = n+m-1;
    g.matrix.resize(g.n);
    REP(i, g.n){
        g.matrix[i].resize(g.n);
    }

    REP(i, g.m){
        int a, b;
        cin >> a >> b;
        g.matrix[a-1][b-1] = 1;
    }

    vector<int> L = topological_sort(g);
    vector<int> num(g.n, 0);

    REP(i, g.n){
        // cout << L[i]+1 << endl;
        num[L[i]] = i;
    }

    REP(i, g.n){
        int ans = 0;
        REP(j, num[i]+1){
            if (g.matrix[L[num[i]-j]][i]){
                ans = L[num[i]-j]+1;
                break;
            }
        }
        cout << ans << endl;
    }

}

