        set<int> searched;

        priority_queue<pair<int, int>> que;
        vector<int> dist(N);
        que.push({0, root});



//        que.push(root);
        while (!que.empty()) {
            pair<int, int> top = que.top();
            que.pop();

            int v = top.second;
            int d = top.first;

            if (dist[v] > d) {
                continue;
            }

            for (auto nv : G[v]) {
                if (dist[nv] < d + 1) {
                    que.push({d + 1, nv});
                    tree[nv] = v;
                    dist[nv] = d + 1;
                }
            }
            searched.insert(v);
        }

        for (int i = 0; i < N; ++i) {
            cout << tree[i] + 1 << endl;
        }

    }
};


