  vector<vector<int>> gh_n;
  gh.resize(N);
  gh_n.resize(N);
  //入次数の管理
  int h[N]={};
  //トポロジカルソート の実装
  for(int i=0;i<N+M-1;i++){
    cin>>a>>b;
    //aからbへの有向グラフ
    gh[a-1].push_back(b-1);
    gh_n[b-1].push_back(a-1);
    h[b-1]+=1;
  }
  //入次数0の要素をキューとして管理
  queue<int> q;
  for(int i=0;i<N;i++){
    if(h[i]==0){
      q.push(i);
    }
  }

  vector<int> ans;
  int tmp,tmp_2;
  while(q.size()){
    int i=q.front();
    q.pop();
    ans.push_back(i);
    //隣接する頂点の入次数を-1する
    for(int j=0;j<gh[i].size();j++){
      tmp=gh[i][j];
      h[tmp]-=1;
      if(h[tmp]==0){
        q.push(tmp);
      }
    }
  }

  int judge=0;
  int result[N]={};
  result[ans[0]]=(-1);

  //順番に親を出力していく。親は入次してくる者のうち、もっともトポロジカルソートで下位の者
  for(int i=1;i<N;i++){
