      tmp_2=ans[k];
      //tmp2が親たりうるかしらベル
      judge=0;
    for(int j=0;j<gh_n[tmp].size();j++){
      if(gh_n[tmp][j]==tmp_2){
        judge=1;
      }
    }
    if(judge==1){
      result[tmp]=tmp_2;
      break;
    }
  }
  }

  for(int i=0;i<N;i++){
    cout<<result[i]+1<<"\n";
  }
return 0;
}

