void djkstra(int s, VI &depth, VI &parent, const vector<VI> &connect)
{
    vector<int> search = {s};
    vector<int> new_search;

    while (!search.empty())
    {
        for (auto i :search)
        {
            for (auto j : connect[i])
            {
                if (depth[j] < 1 + depth[i])
                {
                    depth[j] = 1 + depth[i];
                    parent[j] = i + 1;
                    new_search.push_back(j);
                }
            }
        }
        search.clear();
        search = new_search;
        new_search.clear();
    }
}

