struct TopologicalSort{
    int n;
    vector<set<int> > G;
    vector<bool> used;
    vector<int> indeg,p;

    TopologicalSort(){}
    TopologicalSort(int sz):n(sz),G(n),used(n),indeg(n),p(0){}

    void add_edge(int s,int t){
        G[s].insert(t);
    }

    void bfs(int s){
        queue<int> q;
        q.push(s);
        used[s]=1;
        while(!q.empty()){
            int v=q.front();q.pop();
            p.push_back(v);
            for(int u:G[v]){
                indeg[u]--;
                if(indeg[u]==0&&!used[u]){
                    used[u]=1;
                    q.push(u);
                }
            }
        }
    }

    vector<int>  build(){
        fill(used.begin(),used.end(),0);
        fill(indeg.begin(),indeg.end(),0);

        for(int i=0;i<n;i++)
            for(int v:G[i]) indeg[v]++;

        for(int i=0;i<n;i++)
            if(indeg[i]==0&&!used[i]) bfs(i);

        return p;
    }
};

signed main() {
    int N, M;
    cin >> N >> M;

    vector<int> table[N];

    int parent[N];
    fill(parent, parent + N, -2);

    TopologicalSort ts(N);
    for (int i = 0; i < N - 1 + M; i++) {
        int s, t;
        cin >> s >> t;
        s--; t--;
        ts.add_edge(s, t);
        table[s].push_back(t);
    }

    auto p = ts.build();

    for (int node : p) {
        for (int next : table[node]) {
            parent[next] = node;
        }
    }

    for (int i = 0; i < N; i++) {
        if (parent[i] == -2) {
            cout << 0 << endl;
            continue;
        }

        cout << parent[i] + 1 << endl;
    }

    return 0;
}

