#include <queue>


vector<Weight> dijkstra(const Graph &g, const int id_start, const Weight INF) { // INFに気を付けよ
	using Pwi = pair<Weight, int>;

	const size_t n = g.vertices.size();
	vector<Weight> d(n, INF);
	vector<bool> is_used(n, false);
	priority_queue<Pwi, vector<Pwi>, greater<Pwi>> que;

	d[id_start] = 0;
	for (que.push(Pwi(0, id_start)); !que.empty(); ) {
		Pwi p = que.top(); que.pop();
		const int tmpid = p.second; // p.first >= d[tmpid]
		if (is_used[tmpid]) continue;
		is_used[tmpid] = true;
		//assert(p.first == d[tmpid]);
		for (const auto &p_nxte : g.vertices[tmpid]->edges) {
			const int nxtid = p_nxte->p_dst->id;
			Weight nxtd = d[tmpid] + p_nxte->weight;
			if (d[nxtid] > nxtd) {
				d[nxtid] = nxtd;
				que.push(Pwi(nxtd, nxtid));
			}
		}
	}
	return d;
}

vector<Weight> bellman_ford(const Graph &g, const int id_start, const Weight INF) {
	// INFに気を付けよ d_max < INF
	// 負の閉路からアクセスできる頂点にはd = -INF
	const size_t n = g.vertices.size();
	vector<Weight> d(n, INF);
	d[id_start] = 0;
	bool is_negative_cycle = false;
	for (size_t i = 1; i <= n; i++)
	{
		for (const auto &p_tmpe : g.edges) {
			const int id_src = p_tmpe->p_src->id;
			const int id_dst = p_tmpe->p_dst->id;
			if (d[id_src] != INF && d[id_dst] > d[id_src] + p_tmpe->weight) {
				d[id_dst] = d[id_src] + p_tmpe->weight;
				if (i == n) {
					d[id_dst] = -INF;
					is_negative_cycle = true;
				}
			}
		}
	}
	if (is_negative_cycle) {
		for (size_t i = 1; i < n; i++)
		{
			for (const auto &p_tmpe : g.edges) {
				const int id_src = p_tmpe->p_src->id;
				const int id_dst = p_tmpe->p_dst->id;
				if (d[id_src] == -INF && d[id_dst] != -INF) {
					d[id_dst] = -INF;
				}
			}
		}
	}
	return d;
}

vector<vector<Weight>> warshall_floyd(const Graph &g, const Weight INF) {
	const size_t n = g.vertices.size();
	vector<vector<Weight>> d(n, vector<Weight>(n, INF));
	for (size_t id = 0; id < n; id++)
	{
		d[id][id] = 0;
	}

	for (const auto &p_tmpe : g.edges) {
		d[p_tmpe->p_src->id][p_tmpe->p_dst->id] = p_tmpe->weight;
	}
	for (size_t id_new = 0; id_new < n; id_new++)
	{
		for (size_t id_src = 0; id_src < n; id_src++)
		{
			for (size_t id_dst = 0; id_dst < n; id_dst++)
			{
				if (d[id_src][id_dst] > d[id_src][id_new] + d[id_new][id_dst]) {
					d[id_src][id_dst] = d[id_src][id_new] + d[id_new][id_dst];
				}
			}
		}
	}
	return d;
}

