long long gcd(long long a, long long b) {
    if (a>b) swap(a,b);

    auto r = b % a;

    return (r ? gcd(r, a) : a);
}
int main() {
    int N, M;
    multimap<int, int> AB;
    set<int> ex;

    cin >> N >> M;

    REP(i,N+M){
        int a,b;
        cin>>a>>b;
        AB.emplace(a, b);
        ex.insert(b);
    }

    int root;
    for (root = 1;root <= N; root++)
        if (ex.count(root) == 0)
            break;

    set<int> bfs, used;
    vector<int> r(N, 0);
    bfs.insert(root);
    while(!bfs.empty()){
        for (auto now : bfs){
            auto it = AB.lower_bound(now), ite = AB.upper_bound(now);

            while (it != ite){
                    used.insert(it->second);
                r[it->second-1] = now;
                it++;
            }
            bfs = move(used);
            used.clear();
        }
    }
    for (int i : r)
        cout << i << endl;

    return 0;
}

