int indeg[100010];

signed main()
{
    //頂点数v、辺の数e
    int n, m;
    cin >> n >> m;
    REP(i, n+m-1) {
        int s, t;
        cin >> s >> t;
        s--;t--;
        //頂点sから頂点tへの有向辺
        G[s].push_back(t);
        indeg[t]++;
    }

    //入次数が0の頂点の集合を格納するスタック
    stack<int> st;

    //入次数が0の頂点であればstに追加
    REP(i, v) if(indeg[i] == 0) st.push(i);

    //ソートされた後のグラフの頂点の列
    vector<int> seq;
    //stがなくなるまでループ
    while(st.size()) {
        //stの集合のから一つ取り出す
        int i = st.top(); st.pop();
        seq.push_back(i);
        for(auto& j: G[i]) {
            //隣接する頂点の入次数をマイナス1
            indeg[j]--;
            //これによって入次数が0になればstに追加
            if(indeg[j] == 0) st.push(j);
        }
    }

    vector<int> ans(n);
    REP(i,n){
      if(i==0){
        ans[seq[i]] = 0;
      }else{
        ans[seq[i]] = seq[i-1]+1;
      }
    }
    REP(i,n){
      cout<<ans[i];
    }
    return 0;
}

