void calc_ind(vector<vector<int>> &graph, vector<int> &ind, vector<bool> &flag, int start)
{
  //入次数を求めるためにDFS
  stack<int> s;
  s.push(start);
  flag[start] = true;
  while(!s.empty()){
    int current = s.top();
    s.pop();
    for(int i = 0; i < graph[current].size(); i++)
    {
      int next = graph[current][i];
      ind[next]++;
      if(!flag[next])
      {
        s.push(next);
        flag[next] = true;
      }
    }
  }
}

void calc_parent(vector<vector<int>> &graph, vector<int> &parent, vector<bool> &flag, int root)
{
  //親を見つけるためにBFS
  //あとのラウンドで見つかった方を親に設定
  queue<int> q;
  q.push(root);
  flag[root] = true;
  while(!q.empty())
  {
    int current = q.front();
    q.pop();
    for(int i = 0; i < graph[current].size(); i++)
    {
      int next = graph[current][i];
      parent[next] = current;
      if(!flag[next])
      {
        q.push(next);
        flag[next] = true;
      }
    }
  }
}

int main()
{
  int n, m;
  cin >> n >> m;
  vector<vector<int>> graph(n, vector<int>());
  for(int i = 0; i < n + m - 1; i++)
  {
    int a, b;
    cin >> a >> b;
    graph[a - 1].push_back(b - 1);
  }
  vector<int> ind(n, 0);
  vector<int> parent(n , -1);
  vector<bool> flag(n, false);
  for(int i = 0; i < n; i++)
  {
    if(flag[i]) continue;
    calc_ind(graph, ind, flag, i); 
  }
  int root = 0;
  for(int i = 0; i < ind.size(); i++)
  {
    if(ind[i] == 0)
    {
      root = i;
      break;
    }
  }
  //rootからBFS
  for(int i = 0; i < n; i++){
    flag[i] = false;
  } 
  calc_parent(graph, parent, flag, root);
  for(auto e : parent){
    cout << e + 1 << endl;
  }
}

