struct TopologicalSort{//{{{
    vector<vector<int>> g;
    TopologicalSort(const int &n) : g(n){}
    inline void add_edge(const int &s, const int &t){ g[s].emplace_back(t); }
    vector<int> ord, idx;
    bool run(){//{{{
        const int n = g.size();
        ord.resize(n); idx.resize(n);
        vector<int> d(n);
        for(int u = 0; u < n; ++u) for(auto &v : g[u]) ++d[v];
        int ql = -1, qr = -1;
        for(int u = 0; u < n; ++u) if(d[u] == 0) ord[++qr] = u;
        while(ql != qr){
            int u = ord[++ql]; idx[u] = ql;
            for(auto &v : g[u]) if(!--d[v]) ord[++qr] = v;
        }
        return qr + 1 == g.size();
    }//}}}
};//}}}

struct UnionFind{ //{{{
    vector<int> par;
    int n, cnt;
    UnionFind(const int &x=0){init(x);}
    void init(const int &x){par.assign(cnt = n = x, -1);}
    inline int find(const int &x){ return par[x]<0 ? x : par[x] = find(par[x]); }
    inline bool same(const int &x, const int &y){ return find(x) == find(y); }
    inline bool unite(int x, int y){
        if((x = find(x)) == (y = find(y))) return false;
        --cnt;
        if(par[x] > par[y]) swap(x, y);
        par[x] += par[y];
        par[y] = x;
        return true;
    }
    inline int count() const { return cnt; }
    inline int count(int x){ return -par[find(x)]; }
};
//}}}

bool solve(){
    int n, m;
