int MomoneMomo(Graph &g, vi &table, int pos)
{
    if (table[pos] == -1) {
        int ret = 0;
        for (auto i : g[pos]) {
            ret = max(ret, MomoneMomo(g, table, i.d) + 1);
        }
        return table[pos] = ret;
    } else {
        return table[pos];
    }
}

void bfs(Graph &g, vi &rank, int node)
{
    queue<int> now;
    now.push(node);
    while (now.size()) {
        queue<int> nxt;
        while (now.size()) {
            int pos = now.front(); now.pop();
            //cout << "call : " << pos << endl;
            rep(i, g[pos].size()) {
                nxt.push(g[pos][i].d);
                rank[g[pos][i].d] = rank[pos]+1;
            }
        }
        now = nxt;
    }
}

vi tps(Graph &g)
{
    vi cnt(g.size(), 0);
    rep(i, g.size()) {
        rep(j, g[i].size()) {
            cnt[g[i][j].d]++;
        }
    }
    vi ret;
    queue<int> nxt;
    rep(i, g.size()) if (!cnt[i]) nxt.push(i);

    int pos = 0;
    while (nxt.size()) {
        pos = nxt.front(); nxt.pop();
        ret.pb(pos);
        rep(i, g[pos].size()) {
            cnt[g[pos][i].d]--;
            if (!cnt[g[pos][i].d]) {
                nxt.push(g[pos][i].d);
            }
        }
    }

    return ret;
}

