typedef long long ll;

using namespace std;

template <typename T1, typename T2>
void func(T1& to, T2& rank, int v ) {
	for (int i = 0; i < to[v].size(); ++i) {
		if ((rank[to[v][i]] > rank[v])) { continue; }
		rank[to[v][i]] = rank[v] + 1;
	}
	for (int i = 0; i < to[v].size(); ++i) {
		func(to, rank, to[v][i]);
	}
}

int main() {
	int N, M;
	cin >> N >> M;
	vector<vector<int>> to(N);	// a -> b
	vector<vector<int>> from(N); // b <- a
	for (int i = 0; i < N - 1 + M; ++i) {
		int a, b;
		cin >> a >> b;
		--a; --b;
		to[a].push_back(b);
		from[b].push_back(a);
	}

	vector<int> res(N, -1);
	int root = -1;
	for (int i = 0; i < N; ++i) {
		if (from[i].size() == 0) {
			res[i] = 0;
			root = i;
			break;
		}
	}

	vector<int> rank(N, -1);
	rank[root] = 0;
	func(to, rank, root);

	for (int i = 0; i < N; ++i) {
		if (i == root) { continue; }
		for (int j = 0; j < from[i].size(); ++j) {
			if (rank[i] == rank[from[i][j]] + 1) {
				res[i] = from[i][j] + 1;
				break;
			}
		}
	}

	for (int i = 0; i < N; ++i) {
		cout << res[i] << endl;
	}

	return 0;
}

