int N, M;
vector<int> G[100005];
int in[100005];
int level[100005];
int ret[100005];

bool visit(int v, vector<int> &order, vector<int> &color) {
  color[v] = 1;
  rep(i,G[v].size()){
    int e = G[v][i];
    if (color[e] == 2) continue;
    if (color[e] == 1) return false;
    if (!visit(e, order, color)) return false;
  }
  order.push_back(v); color[v] = 2;
  return true;
}
bool topologicalSort(vector<int> &order) {
  int n = N-1+M;
  vector<int> color(n+1);
  REP(u, 1, n+1) if (!color[u] && !visit(u, order, color)) return false;
  reverse(order.begin(),order.end());
  return true;
}

void dfs(int v){
  rep(i,G[v].size()){
    if(level[G[v][i]] == level[v] + 1) ret[G[v][i]] = v;
    dfs(G[v][i]);
  }  
}

int main(){
  cin >> N >> M;

  rep(i,N-1+M){
    int A, B;
    cin >> A >> B;
    G[A].push_back(B);
    in[B]++;
  }

  int root = -1;
  REP(i,1,N+1){
    if(in[i] == 0){
      root = i;
      break;
    }
  }

  vector<int> order;
  topologicalSort(order);
  level[root] = 1;
  rep(i,order.size()){
    if(order[i] > N) continue;
    int v = order[i];
    rep(j,G[v].size()){
      level[G[v][j]] = level[v] + 1;
    }
  }

  dfs(root);
  ret[root] = 0;

  REP(i,1,N+1){
    cout << ret[i] << endl;
  }
  return 0;
}

