typedef pair<int,int> pii; // (cst, to)

#define MAX 100100

vector<pii> G[MAX];
bool used[MAX];

vector<int> prim(int root) {
    priority_queue<pii, vector<pii>, greater<pii> > que;
    memset(used, 0, sizeof(used));
    que.push(pii(0,root));
    vector<int> T;
    int ret = 0;
    while(!que.empty()) {
        int cst = que.top().first, v = que.top().second;
        que.pop();
	//cout << "cur: " << v << endl;
        if(used[v]) continue;
	T.push_back(v);
        used[v] = 1;
        ret += cst;
        for(int i = 0; i < G[v].size(); i++)
            que.push(pii(G[v][i].first, G[v][i].second));
    }
    return T;
}

