void add(int u,int v)
{
	e[++edgenum].from=u;
	e[edgenum].to=v;
	e[edgenum].next=head[u];
	head[u]=edgenum;
}
int ind;
void Tarjan(int node)
{
	if(dfn[node])return;
	st[++top]=node;
	dfn[node]=low[node]=++ind;
	flag[node]=1;
	for(int hd=head[node];hd;hd=e[hd].next)
	{
		int to=e[hd].to;
		if(!dfn[to])
		{
			Tarjan(to);
			low[node]=min(low[node],low[to]);
		}
		else if(flag[to])low[node]=min(low[node],dfn[to]);
	}
	if(dfn[node]==low[node])
	{
		int v=st[top--];
		flag[v]=0;
		p[v]=++scc;
		while(v!=node)
		{
			v=st[top--];
			flag[v]=0;
			p[v]=scc;
		}
	}
}
void work(int root)
{
	ans[root]=0;
	q.push(root);
	memset(flag,0,sizeof(flag));
	flag[root]=1;
	while(!q.empty())
	{
		int node=q.front();
		q.pop();
		for(int hd=head[node];hd;hd=e[hd].next)
		{
			int to=e[hd].to;
			if(!flag[to])
			{
				flag[to]=1;
				q.push(to);
				ans[to]=node;
			}
		}
	}
}
