        if(used_reverse_edge_count[cur] < (int)reverse_edges[cur].size() - 1){
            used_reverse_edge_count[cur] ++;
            continue;
        }
        parent[cur] = prev;

        for(int i = 0; i < edges[cur].size(); i++){
