void dfs(int parent,vector<set<int>>& f,vector<int>& d,vector<int>& p) {
	for (int x : f[parent]) {
		if (d[x] == 0) {
			d[x] = d[parent] + 1;
			p[x] = parent;
		}
		else if (d[x] < d[parent] + 1) {
			d[x] = d[parent] + 1;
			p[x] = parent;
		}
		dfs(x, f, d, p);
	}
}

