  gh.resize(N);
  //入次数の管理
  int h[N]={};
  //トポロジカルソート の実装
  for(int i=0;i<N+M-1;i++){
    cin>>a>>b;
    //aからbへの有向グラフ
    gh[a-1].push_back(b-1);
    gh_n[a-1][b-1]=1;
    h[b-1]+=1;
  }
  //入次数0の要素をキューとして管理
  queue<int> q;
  for(int i=0;i<N;i++){
    if(h[i]==0){
      q.push(i);
