void topo_sort() {
	int root;
	for (int i = 1;i <= N;i++) {
		if (pa[i].empty()) {
			root = i;
			break;
		}
	}
	stack<int> st;
	st.push(root);
	int num = N;
	while (!st.empty()) {
		int r = st.top();
		int n = ch[r].size();
		for (int i = 0;i <= n;i++) {
			if (i == n) {
				tps[r] = num--;
				st.pop();
			}
			else if (!used[ch[r][i]]) {
				used[ch[r][i]] = true;
				st.push(ch[r][i]);
				break;
			}
		}
	}
}

