bool dijkstra(const vector<vector<ll>>& G, ll start, ll end, ll num_node)
{
	vector<bool> dist = vector<bool>(num_node);
	for (ll i = 0; i < num_node; ++i)
	{
		dist[i] = false;
	}


	dist[start] = true;

	queue<ll> que;
	que.push(start);

	while (!que.empty()) {
		ll v = que.front();
		que.pop();
		//ll v = p.second;
		if (dist[v])
		{
			continue;
		}
		for (int i = 0; i < G[v].size(); i++)
		{
			ll e = G[v][i];
			dist[e] = true;
			if (e == end)
			{
				goto bbb;
			}
			que.push(e);
		}
	}
	bbb:
	return dist[end];
}

