struct Vertex
{
    vector<int> next;
    ll d = INF;
    int p = 0;
    vector<int> pt;
};

Vertex V[100005];
bool isC[100005];
int pN[100005];
int Ans[100005];
bool U[100005];

int main()
{
    ll N, M;
    cin >> N >> M;
    REP(i, N - 1 + M)
    {
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        isC[b] = true;
        V[a].next.push_back(b);
        V[b].pt.push_back(a);
        pN[b]++;
    }

    int root = -1;
    REP(i, N)
    {
        if (!isC[i])
        {
            root = i;
            break;
        }
    }

    V[root].d = 0;

    queue<int> q;
    q.push(root);
    while (!q.empty())
    {
        int t = q.front();
        q.pop();
        if (U[t])
            continue;

        ll max = -1;
        int k = 0;
        REP(j, V[t].pt.size())
        {
            if (max < V[V[t].pt[j]].d)
            {
                max = V[V[t].pt[j]].d;
                k = V[t].pt[j];
            }
        }
        if (max == V[t].d - 1)
        {
            U[t] = true;
            Ans[t] = k;
        }
        REP(i, V[t].next.size())
        {
            int n = V[t].next[i];
            V[n].d = V[t].d + 1;
            q.push(n);
        }
    }
    Ans[root] = -1;
    REP(i, N)
    {
        cout << Ans[i] + 1 << endl;
    }
    return 0;
}

