struct graph{
	int n;
	vector<vector<int>>g;
	vector<bool>used;	
	vector<int>ts;	
	vector<int>pr;

	graph(int _n){
		n=_n;
		g.resize(n);
		used.resize(n,false);
		pr.resize(n,-1);
	};

	void add_edge(int a,int b){
		g[a].push_back(b);
	}

	void traverse(int i){
		if(used[i])return;
		used[i]=true;
		for(auto&& w:g[i]){
			traverse(w);
		}
		ts.push_back(i);
	}
	void tsort(){
		for(int i=0;i<n;i++){
			traverse(i);
		}
		reverse(begin(ts),end(ts));
	}



	void set_pr(){
		tsort();
		pr[ts[0]]=-1;
		for(int i=0;i<n;i++){
			for(auto&& w:g[ts[i]])pr[w]=i;
		}
	}

};


