int main(void) {
  ios::sync_with_stdio(false);
  int N, M;
  cin >> N >> M;

  vector<vector<int>> G(N);
  vector<int> inE(N, 0);
  rep(i, N + M - 1) {
    int A, B;
    cin >> A >> B;
    A--, B--;
    G[A].emplace_back(B);
    inE[B]++;
  }
  int root = -1;
  rep(i, N) {
    if (inE[i] == 0) {
      root = i;
      break;
    }
  }

  stack<pair<int, int>> dfs;
  dfs.emplace(root, -1);
  vector<int> dist(N, -1);
  dist[root] = 0;
  vector<int> answer(N);
  answer[root] = 0;
  while (!dfs.empty()) {
    int u, from;
    tie(u, from) = dfs.top();
    dfs.pop();
    for (auto v : G[u]) {
      if (v == from) continue;
      int ndist = dist[u] + 1;
      if (dist[v] == -1 || dist[v] < ndist) {
        dist[v] = ndist;
        answer[v] = u + 1;
        dfs.emplace(v, u);
      }
    }
  }

  rep(i, N) cout << answer[i] << endl;
  return 0;
}

