// トポロジカルソート DAGでない場合は空配列を返す
template<typename T>
vector<int> TopologicalSort(T &g){
  int N = g.size();
  vector<int> marked(N , 0) , temp(N , 0) , v;
  // 訪問して帰りがけ順にvに追加
  auto visit = [&](auto f, int i) -> bool{
    if(temp[i] == 1) return false;
    if(marked[i] == 0){
      temp[i] = 1;
      for(auto &e : g[i]){
        if(f(f , e) == false) return false;
      }
      marked[i] = 1;
      v.push_back(i);
      temp[i] = 0;
    }
    return true;
  };

  for(int i = 0 ; i < N ; i++){
    if(marked[i] == 0) {
      if(visit(visit , i) == false) return vector<int>();
    }
  }
  reverse( v.begin() , v.end() );
  return v;
}

void solve(){
  ini(N , M);
  auto g = graph(N , N + M - 1 , true);
  auto topo = TopologicalSort(g);
  trc(g);
  vi inv(N);
  rep(i , N) inv[topo[i]] = i;
  trc(topo);
  trc(inv);
  rep(i , N) each(x , g[i]) x = inv[x];

  //
  vvi h(N);
  rep(i , N) each(j , g[i]) h[j].pb(inv[i]);

  rep(i , N) trc(h[i]);

  vi ans(N);
  rep1(i , N - 1) ans[topo[i]] = topo[h[i].back()] + 1; 
  each(x,ans)out(x);



}

