		cin >> a >> b;
		--a; --b;
		to[a].push_back(b);
	}

	vector<int> tp = tpsort(to);
	vector<int> par(N, -1);
	par[tp[0]] = 0;
	for (int i = 0; i < tp.size(); ++i) {
		int u = tp[i];
