void dfs(int a, int b, const vvll &c, vll &p, vb &ald, vll &dist){
    ald[a] = true;
    dist[a] = b;
    for(auto x: c[a]){
        if(ald[x] == true){
            if(b+1>=dist[x]){
                p[x]=a;
                dfs(x, b+1, c, p, ald, dist);
            }else{
                return;
            }
        }else{
            p[x] = a;
            dfs(x, b+1, c, p, ald, dist);
        }
    }
    return;
}

