static inline DOUBLE inputFP(void)
{
    DOUBLE dInt = 0.0;
    DOUBLE dFrac = 0.0;
    DOUBLE dMultiplier = 1.0;
    DWORD dwFpCnt = 0;
    DOUBLE *pdCur = &dInt;
    M_BOOL bRead = M_FALSE;
    for (;;) {
        char c = getchar();
        if (!bRead) {
            if ('-' == c) {
                dMultiplier = -1;
            }
        }
        if ('.' == c) {
            pdCur = &dFrac;
        } else if (('0' <= c) && (c <= '9')) {
            (*pdCur) *= 10;
            (*pdCur) += (DOUBLE)(c - '0');
            bRead = M_TRUE;
            if (pdCur == &dFrac) {
                dwFpCnt++;
            }
        } else {
            if (bRead) {
                return dMultiplier * (dInt + dFrac / (pow((DOUBLE)10.0 , (DOUBLE)dwFpCnt)));
            }
        }
    }
}

#define MAX_EDGES   (100000 + 1)
#define MAX_POINTS  (100000 + 1)
#define DIST_MIN   (0)
int main(void)
{
    DWORD dwInput_N, dwInput_M;

    dwInput_N = inputSDWORD();
    dwInput_M = inputSDWORD();


    static vector<DWORD> avEdges[MAX_POINTS];
    static vector<DWORD> avRevEdges[MAX_POINTS];
    DWORD dwEdgeNum = dwInput_N + dwInput_M - 1;
    DWORD dwPntNum = dwInput_N + dwInput_N;

    for (DWORD dwIdx = 1; dwIdx <= dwEdgeNum; dwIdx++) {
        DWORD dwInput_A, dwInput_B;
        dwInput_A = inputSDWORD();
        dwInput_B = inputSDWORD();

        avEdges[dwInput_A].push_back(dwInput_B);
        avRevEdges[dwInput_B].push_back(dwInput_A);
    }

    /* 親を求める */
    DWORD dwCurPos = 1;
    while(1) {
        if (avRevEdges[dwCurPos].size() == 0) {
            break;
        }
        dwCurPos = avRevEdges[dwCurPos][0];
    }
    DWORD dwRoot = dwCurPos;

    queue<DWORD> que;
    DWORD adwParent[MAX_POINTS];
    DWORD adwDstEdgeNum[MAX_POINTS];

    memset(adwDstEdgeNum, 0, sizeof(adwDstEdgeNum));

    adwParent[dwRoot] = 0;
    que.push(dwRoot);

    /* 冗長辺の数を数える */
    for (DWORD dwIdx = 1; dwIdx <= dwPntNum ; dwIdx++) {
        DWORD dwEdgeDstNum = avRevEdges[dwIdx].size();
        if (0 < dwEdgeDstNum) {
            adwDstEdgeNum[dwIdx] = dwEdgeDstNum;
        }
    }

    /* bfs */
    while (0 < que.size()) {
        DWORD dwPnt = que.front();
        que.pop();

        for (DWORD dwEdgeIdx = 0; dwEdgeIdx < avEdges[dwPnt].size(); dwEdgeIdx++) {
            DWORD dwNextPnt = avEdges[dwPnt][dwEdgeIdx];
            adwParent[dwNextPnt] = dwPnt;
            adwDstEdgeNum[dwNextPnt]--;
            if (0 == adwDstEdgeNum[dwNextPnt]) {
                que.push(dwNextPnt);
            }
        }

    }
    for (DWORD dwPnt = 1; dwPnt <= dwInput_N; dwPnt++) {
        printf("%d\n", adwParent[dwPnt]);
    }

    return 0;
}

