void func(T1& to, T2& rank, int v ) {
	vector<int> x;
	for (int i = 0; i < to[v].size(); ++i) {
		if ((rank[to[v][i]] > rank[v])) { continue; }
		rank[to[v][i]] = rank[v] + 1;
		x.push_back(to[v][i]);
	}
	for (int i = 0; i < x.size(); ++i) {
		func(to, rank, x[i]);
	}
}

