#include <map>
using namespace std;

int get_depth(vector<vector<int> >& parents, int x, map<int, int>& depth) {
  if (depth.count(x)) {
    return depth[x];
  }
  int ret = 0;
  for (int i = 0; i < parents[x].size(); i++) {
    int p = parents[x][i];
    ret = max(ret, get_depth(parents, p, depth) + 1);
  }
  depth[x] = ret;
  return ret;
}

int main() {
  int n, m; cin >> n >> m;
  vector<vector<int> > parents(n+1);
  vector<vector<int> > children(n+1);
  for (int i = 0; i < n + m - 1; i++) {
    int a, b; cin >> a >> b;
    parents[b].push_back(a);
    children[a].push_back(b);
  }
  int root;
  for (int i = 1; i <= n; i++) {
    if (parents[i].size() == 0) {
      root = i;
    }
  }
  map<int, int> depth;
  for (int i = 1; i <= n; i++) get_depth(parents, i, depth);
  for (int i = 1; i <= n; i++) {
    int d = depth[i];
    int ans = 0;
    for (int j = 0; j < parents[i].size(); j++) {
      int p = parents[i][j];
      if (depth[i] == depth[p] + 1) {
        ans = p;
      }
    }
    cout << ans << endl;
  }
}

