constexpr int MAX_V = 100010;
vector<int> G[MAX_V];

int main() {

    int N, M;
    cin >> N >> M;

    vector<int> in(N, 0);

    vector<int> A(N - 1 + M), B(N - 1 + M);
    for (int i = 0; i < N - 1 + M; i++) {
        cin >> A[i] >> B[i];
        A[i]--, B[i]--;
        G[A[i]].push_back(B[i]);
        in[B[i]]++;
    }

    int parent = -1;
    for (int i = 0; i < N; i++) if (in[i] == 0) parent = i;

    vector<int> dist(N, 0);
    queue<int> Q;
    Q.push(parent);
    while (!Q.empty()) {
        int v = Q.front();
        Q.pop();
        for (int i = 0; i < G[v].size(); i++) {
            int to = G[v][i];
            in[to]--;
            dist[to] = max(dist[to], dist[v] + 1);
            if (in[to] == 0) {
                Q.push(to);
            }
        }
    }

    vector<int> par(N, -1);
    for (int i = 0; i < N - 1 + M; i++) {
        int f = A[i];
        int to = B[i];
        if (dist[to] - dist[f] == 1) {
            par[to] = f;
        }
    }
    for(int i = 0;i<N;i++) cout << par[i] + 1 << endl;

    return 0;
}

