using namespace std;

class Node {
public:
	int parentsCount = 0;
	list<int> children;

	int setParents = 0;
	int trueParent = 0;
	int trueDepth = 0;

	void setDepth(int parent, int depth) {
		if (trueDepth < depth) {
			trueDepth = depth;
			trueParent = parent;
		}
		setParents++;
	}

	int getDepth() {
		if (parentsCount > setParents) {
			return -1;
		}
		return trueDepth;
	}
};

int getRoot(Node* nodes, int size) {
	for (int i=1; i<size; i++) {
		if (nodes[i].parentsCount == 0) {
			return i;
		}
	}
	return -1;
}

int main(void) {
	Node* nodes = NULL;
	int N, M, a, b;
	scanf("%d%d", &N, &M);
	nodes = new Node[N+1];

	for (int i=0; i<N+M-1; i++) {
		scanf("%d%d", &a, &b);
		nodes[b].parentsCount++;
		nodes[a].children.push_front(b);
	}

	list<int> list;
	list.push_front(getRoot(nodes, N+1));

	while (list.size() > 0) {
		int target = list.front();
		list.pop_front();
		int depth = nodes[target].getDepth();

		for (const int x : nodes[target].children) {
			nodes[x].setDepth(target, depth+1);
			if (nodes[x].getDepth() != -1) {
				list.push_front(x);
			}
		}

	}

	for (int i=1; i<N+1; i++) {
		printf("%d\n", nodes[i].trueParent);
	}

}

