llong bfs(llong now) {
    if(depth[now] != -1) return depth[now];
    llong ret = 0;
    for(llong pr : edges[now]) {
        llong d = bfs(pr);
        if(ret < d) {
            ret = d;
            ans[now] = pr;
        }
    }
    ret++;
    depth[now] = ret;
    return ret;
};

