template <typename T>
class TopologicalSort {
  struct Edge {
    int src, dst;
    T cost;
    Edge(int dst_, T cost_ = -1) : src(-1), dst(dst_), cost(cost_) {}
    Edge(int src_, int dst_, T cost_) : src(src_), dst(dst_), cost(cost_) {}
    inline bool operator < (const Edge &rhs) { return cost < rhs.cost; }
    inline bool operator <= (const Edge &rhs) { return cost <= rhs.cost; }
    inline bool operator > (const Edge &rhs) { return cost > rhs.cost; }
    inline bool operator >= (const Edge &rhs) { return cost >= rhs.cost; }
  };

  int sz;

  bool dfs(int ver, vector<int> &state) {
    state[ver] = 1;
    for (Edge e : graph[ver]) {
      if (state[e.dst] == 1) return false;
      if (state[e.dst] == 0 && !dfs(e.dst, state)) return false;
    }
    order.emplace_back(ver);
    state[ver] = -1;
    return true;
  }

public:
  vector<vector<Edge> > graph;
  vector<int> order;

  TopologicalSort(int sz_) : sz(sz_), graph(sz) {}

  void add(int src, int dst, T cost = -1) { graph[src].emplace_back(Edge(dst, cost)); }

  bool build() {
    order.clear();
    vector<int> state(sz, 0);
    REP(i, sz) if (state[i] == 0 && !dfs(i, state)) return false;
    reverse(ALL(order));
    return true;
  }
};

int main() {
  cin.tie(0); ios::sync_with_stdio(false);
  // freopen("input.txt", "r", stdin);

  int n, m; cin >> n >> m;
  TopologicalSort<int> ts(n);
  REP(i, n-1+m) {
    int a, b; cin >> a >> b;
    --a;
    --b;
    ts.add(a, b);
  }
  ts.build();
  vector<int> toposo = ts.order, ans(n, -1);
  reverse(ALL(toposo));
  for (int i : toposo) {
    for (auto e : ts.graph[i]) if (ans[e.dst] == -1) ans[e.dst] = i;
  }
  REP(i, n) {
    if (ans[i] == -1) cout << 0 << '\n';
    else cout << ans[i]+1 << '\n';
  }
  return 0;
}

