int DFS0(const int u) {
   if (rev[u].empty())
      return u;
   return DFS0(rev[u][0]);
}//DFS0

void DFS1(const int u, const int p, const int d) {
   depths[d].push_back(u);
   for (auto& e : edges[u])
      if (e != p)
         DFS1(e, u, d + 1);
}//DFS1

