typedef pair<int, int> i2;

const int maxN = 1e5 + 1;
const int maxM = 1e6 + 1;
vector<i2> adj[maxN];
int number[maxN], low[maxN], nC[maxN], order = 0;
int n, m;
stack<int> stk;
int SLTPLTM = 0, TP[maxN];

/// Strongly connected components (SSC)
void DFS_SCC(int u) {
    number[u] = ++order;
    low[u] = number[u];
    stk.push(u);
    for (i2 x : adj[u]) {
        int v = x.first;
        //int id = x.second;
        if (TP[v] != 0) continue;
        if (number[v] == 0) {
            DFS_SCC(v);
            low[u] = min(low[u], low[v]);
        }
        else low[u] = min(low[u], number[v]);
    }
    if (number[u] == low[u]) {
        int v;
        SLTPLTM++;
        do {
            v =  stk.top();
            stk.pop();
            TP[v] = SLTPLTM;
        } while (v != u);
    }
}

