void solve(long long N, long long M, std::vector<long long> A, std::vector<long long> B){
    vector<int> d(N + 1), p(N + 1, -1);
    vector<vector<int>> e(N + 1);
    for(int i = 0; i < A.size(); ++i) {
        e[A[i]].push_back(B[i]);
        d[B[i]]++;
    }
    queue<int> Q;
    for(int i = 1; i <= N; ++i) if(d[i] == 0) {
        p[i] = 0;
        Q.push(i);
    }
    while(!Q.empty()) {
        int v = Q.front(); Q.pop();
        for(auto a: e[v]) {
            d[a]--;
//            cerr << v << "->" << a << "," << d[a] << endl;
            if(d[a] == 0) {
                Q.push(a);
                p[a] = v;
            }
        }
    }
    for(int i = 1; i <= N; ++i) {
        cout << p[i] << endl;
    }
}

