	if(ans[p]!=-1)
		return;
	ans[p]=rt+1;
	vector<pair<int,int>>c;
	for(int q:graph[p])
		c.push_back({dmax[q],q});
	sort(c.begin(),c.end());
	reverse(c.begin(),c.end());
	for(auto a:c)
		visit2(a.second,p);
}
