struct Graph{
    struct Node{
        unordered_set<int> inEdges, outEdges;
        int minDepth = M;
        int from = 0;
    };
    vector<Node> nodes;
    Graph(int num): nodes(num){ }
    int id(Node* n){ return n - &nodes[0]; }
    int id(Node& n){ return &n - &nodes[0]; }
    void print(){ for(auto& node : nodes){ prints(id(node), node.outEdges); } }
    void add1Edge(int from, int dest){
        nodes[from].outEdges.insert(dest);
        nodes[dest].inEdges.insert(from);
    }
    void dfs(int idx, int from = -1, int depth = 0){
        if(nodes[idx].minDepth == M){
        }else if(nodes[idx].minDepth < depth){
        }else{
            return;
        }
        nodes[idx].from = from;
        nodes[idx].minDepth = depth;
        for(int didx : nodes[idx].outEdges){
            if(didx == from){ continue; }
            dfs(didx, idx, depth + 1);
        }
    }
};

