typedef pair<int ,int> P;
struct edge{int to, cost;};
vector<edge> G[100000];
ll d_dijkstra[100000];
int ans[100000];

void dijkstra(ll s){
    priority_queue<P, vector<P>, greater<P>>que;
    Fill(d_dijkstra,0);
    d_dijkstra[s]=0;
    que.push(P(0,s));

    while(!que.empty()){
        P p=que.top(); que.pop();
        int v = p.second;
        if(d_dijkstra[v]>p.first) continue;
        for(int i=0; i<G[v].size(); i++){
            edge e=G[v][i];
            if(d_dijkstra[e.to] < d_dijkstra[v]+e.cost){
                d_dijkstra[e.to]=d_dijkstra[v]+e.cost;
                que.push(P(d_dijkstra[e.to], e.to));
                ans[e.to]=v;
            }
        }
    }
}

