vector<int> graph[200010];
vector<int> par(200010);

bool topologicalSort(int V, int E, vector<int> &order) {
  assert(order.size() == 0);
  // トポロジカルソートした結果をorderに格納して返す. 返り値はDAGならtrue
  vector<int> indegree(V); // 200000とかだと遅い？ 厳しそうならグローバル変数にする
  // 入次数の初期化. ほんとは読み込み時にやったほうが効率が良いけど許容する
  for (int v = 0; v < V; ++v) {
    for (int nv : graph[v]) ++indegree[nv];
  }

  stack<int> st;
  for (int v = 0; v < V; ++v) {
    // 入次数0の点をstackにいれる
    if (indegree[v] == 0) {
      par[v] = -1;
      st.push(v);
    }
  }

  while (st.size() > 0) { 
    int v = st.top(); st.pop();
    order.push_back(v);
    for (int nv : graph[v]) {
      --indegree[nv];
      if (indegree[nv] == 0) {
        st.push(nv);
        par[nv] = v;
      }
    }
  }

  return order.size() == V;
}

