    for (int i = 0; i < N + M - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        G[a].push_back(b);
        indeg[b]++;
    }
    priority_queue<pii, vector<pii>, greater<pii>> pq;
    for (int i = 1; i <= N; i++)
        pq.push(make_pair(indeg[i], i));
