  Solver2(LL n, LL m) : n(n), m(m), g(n), d(n, -1), inc(n), cnt(n){};

  void solve() {
    set<int> S;
    for (int i = 0; i < n; ++i) {
      S.insert(i);
    }
    for (int i = 0; i < n + m - 1; ++i) {
      int a, b;
