struct DAG{
    int V;
    vector<vector<int>> G;
    vector<int> in;
    DAG(int V):V(V),G(V),in(V){}
    void add_edge(int f,int t){
        G[f].push_back(t);
        in[t]++;
    }
    vector<int> topological_sort(){
        vector<int> res;
        stack<int> st;
        for(int i=0;i<V;i++){
            if(!in[i]){
                st.push(i);
            }
        }
        while(st.size()){
            int t=st.top();st.pop();
            res.push_back(t);
            for(int i=0;i<G[t].size();i++){
                if(!(--in[G[t][i]])){
                    st.push(G[t][i]);
                }
            }
        }
        return res;
    }
};
