void dfs(ll start){
  d[start] = 0;
  priority_queue<pair<ll, ll>> pque;
  pque.push({0, start});
  while(!pque.empty()){
    pair<ll, ll> p = pque.top();
    pque.pop();
    for(ll to : E[p.s]){
      if(d[to] < p.f + 1){
        d[to] = p.f + 1;
        pque.push({d[to], to});
      }
    }
  }
}

