int set_parent(int now, vector<vector<int>> &edges, vector<int> &height, vector<int> &parent) {
    if (height[now] != -1)
        return height[now];

    if (edges[now].size() == 0) {
        parent[now] = -1;
        return 0;
    }
    int maxx = -1;
    int maxto = -1;
    for (int to : edges[now]) {
        int ret = set_parent(to, edges, height, parent);
        if (ret > maxx) {
            maxx = ret;
            maxto = to;
        }
    }
    parent[now] = maxto;
    return maxx + 1;
}
