struct Comb {
    vector<vector<s64> > data;
    Comb(int n) { // O(n^2)
        data = vector<vector<s64> >(n+1,vector<s64>(n+1,1));
        UPTO(i,1,n) {
            FOR(j,i+1) {
                if (!j || j == i) data[i][j] = 1;
                else data[i][j] = data[i-1][j-1] + data[i-1][j];
            }
        }
    }

    s64 ncr(int n, int r) {
        return data[n][r];
    }
};

static inline int ri() {
  int a;
  scanf("%d", &a);
  return a;
}

int int_less(const void *a, const void *b) {
  return (*((const int*)a) - *((const int*)b));
}
int int_greater(const void *a, const void *b) {
  return (*((const int*)b) - *((const int*)a));
}

int main() {
    int n = ri();
	int m = ri();
	int a[n+m-1], b[n+m-1];
	vector<set<int> > to(n);
	vector<set<int> > rev(n);

	FOR(i,n+m-1) a[i] = ri()-1, b[i] = ri()-1, to[a[i]].insert(b[i]), rev[b[i]].insert(a[i]);

	int root = 0;
	while (rev[root].size()) {
		root = *rev[root].begin();
	}

	int dist[n];INIT(dist,INF);dist[root] = 0;
	int updated[n]; INIT(updated,-1);
	queue<int> que; que.push(root);

	set<pair<int,int> > removes;
	while (que.size()) {
		int i = que.front(); que.pop();
		for (auto j : to[i]) {
			if (dist[j] == INF) {
				dist[j] = dist[i] + 1;
				updated[j] = i;
				if (rev[j].size() == 1) {
					que.push(j);
				}
			} else {
				assert(dist[i]+1 != dist[j]);
				if (dist[j] > dist[i] + 1) while(1) { volatile int x; x = 1; }
				dist[j] = dist[i] + 1;
				removes.insert({updated[j],j});
				to[updated[j]].erase(j);
				rev[j].erase(updated[j]);
				updated[j] = i;
				if (rev[j].size() == 1) {
					que.push(j);
				}
			}
		}
	}

	assert(removes.size() == m);
	FOR(i,n) {
		cout << (i == root ? 0 : *rev[i].begin()+1) << endl;
	}

    return 0;
}

