template<class Type>
Type solve(Type res = Type()){
    int N,M; cin >> N >> M;
    vector<vector<int>> G(N+1);
    vector<vector<int>> rG(N+1);
    for(int i = 0; i < N-1+M;i++){
        int A,B; cin >> A >> B;

        A--; B--;
        G[A].push_back(B);
        rG[B].push_back(A);
    }

    // 逆辺グラフからrootを探索する
    int root = 0;
    while(!rG[root].empty()) root = rG[root].front();

    // 順辺グラフを用いて各頂点の到達優先度を数える (昇順)
    // この中で最も優先度が低い状態へ子へ入る（子の優先度が最後に更新される)親が真の親と子の関係
    vector<int> ans(N);
    vector<ll> visit_priority(N);
    visit_priority[root] = 1;

    using Item = tuple<ll,int>;
    priority_queue<Item> pq; pq.push(Item(1,root));
    while(pq.size()){
        ll priority; int n; tie(priority,n) = pq.top(); pq.pop();
        if(visit_priority[n] > priority) continue;

        for(auto next:G[n]){
            if(visit_priority[next] < visit_priority[n] + 1){
                visit_priority[next] = visit_priority[n] + 1; //親と子の関係は必ず優先度が降下 ;
                ans[next] = n + 1;
                pq.push(Item(visit_priority[next],next));
            }
        }
    }

    for(int i = 0; i < N;i++){
        cout << ans[i] << endl;
    }
    return res;
}
int main(void) {
    cin.tie(0); ios_base::sync_with_stdio(false);
    solve(0);
    // cout << fixed << setprecision(15) << solve<ll>() << endl;
    return 0;
}

