// 各頂点の親
int parent[maxN];

// #define TEST
int main() {
  #ifdef TEST
    freopen("input.txt", "r", stdin);
  #endif
  int N, M;
  cin >> N >> M;

  for (int i = 0; i < maxN; i++) {
    degree[i] = 0;
    visited[i] = false;
  }

  for (int i = 0; i < N + M - 1; i++) {
    int s, t;
    cin >> s >> t;
    G[s - 1].push_back(t - 1);
    degree[t - 1] += 1;
  }

  queue<int> q;
  for (int i = 0; i < N; i++) {
    if (degree[i] == 0) {
      q.push(i);
    }
  }
  // 根付き木なので根は1個しかない
  assert (q.size() == 1);

  // vector<int> sorted;
  // topological sort
  while (!q.empty()) {
    int u = q.front();
    q.pop();
    visited[u] = true;
    // sorted.push_back(u);

    for (auto v : G[u]) {
      degree[v]--;
      if (degree[v] == 0 && visited[v] == false) {
        q.push(v);
        parent[v] = u;
      }
    }
  }

  for (int i = 0; i < N; i++) {
    if (parent[i] == 0) {
      cout << parent[i] << endl;
    }
