// 強連結成分分解
struct SCC {
    const int n;
    vector<vector<int>> G;
    vector<vector<int>> rG;
    vector<int> vs;
    vector<bool> used;
    vector<int> cmp;

    SCC(int _n) : n(_n), G(_n), rG(_n), used(_n), cmp(_n) {}

    void addEdge(int from, int to) {
        G[from].emplace_back(to);
        rG[to].emplace_back(from);
    }

    void dfs(int v) {
        used[v] = true;
        for (auto&& nxt : G[v]) {
            if (!used[nxt]) dfs(nxt);
        }
        vs.emplace_back(v);
    }

    void rdfs(int v, int k) {
        used[v] = true;
        cmp[v] = k;
        for (auto&& nxt : rG[v]) {
            if (!used[nxt]) rdfs(nxt, k);
        }
        vs.emplace_back(v);
    }

    int scc() {
        REP(v, n)
        {
            if (!used[v]) dfs(v);
        }
        used.assign(n, false);
        int k = 0;
        for (int i = vs.size() - 1; i >= 0; i--) {
            int v = vs[i];
            if (!used[v]) rdfs(v, k++);
        }
        return k;
    }

    bool same(int a, int b) {
        return cmp[a] == cmp[b];
    }

    int get(int a) {
        return cmp[a];
    }
};

signed main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<int> in(N);
    SCC scc(N);
    REP(i, N-1 + M) {
        int from, to;
        cin >> from >> to;
        --from;
        --to;

        scc.addEdge(from, to);
        G[from].push_back(to);
        in[to]++;
    }

    int root = -1;
    REP(i, N) {
        if (in[i] == 0) {
            root = i;
            break;
        }
    }

    if (root == -1) {
        scc.scc();
        REP(i, N) {
            if (i != scc.get(i)) {
                root = i;
                break;
            }
        }
    }

    vector<int> p(N);
    REP(i, N) p[i] = -1;
    p[root] = 0;

    queue<int> q;
    q.push(root);
    while(!q.empty()) {
        int t = q.front();
        q.pop();
        REP(i, G[t].size()) {
            int child = G[t][i];
            if (p[child] >= 0) continue;
            p[child] = t + 1;
            q.push(child);
        }
    }

    REP(i, N) {
        cout << p[i] << endl;
    }

    return 0;
}

