using namespace std;

const int N = 100005;

int n, m;
vector<int> g[N];
bool visit[N];
int low[N], num[N], now;
stack<int> st;
int pos[N];
int par[N];
int ncomp;
int deg[N];
vector<int> vec[N];

void dfs(int u) {
	low[u] = num[u] = ++now;
	st.push(u);
	for (int v : g[u]) {
		if (num[v]) {
			low[u] = min(low[u], num[v]);
		} else {
			dfs(v);
			low[u] = min(low[u], low[v]); 
		}
	}
	if (low[u] == num[u]) {
		int v = 0;
		++ncomp;
		do {
			v = st.top();
			st.pop();
			low[v] = num[v] = N;
			vec[ncomp].push_back(v);
			pos[v] = ncomp;
		} while (v != u);
	}
}

void bfs(int root) {
	queue<int> q;
	visit[root] = true;
	q.push(root);
	while (!q.empty()) {
		int u = q.front(); q.pop();
		for (int v : g[u]) {
			if (visit[v] == false) {
				par[v] = u;
				visit[v] = true;
				q.push(v);
			}
		}
	}
}

