		g[u].push_back(v);
	}
	for (int u = 1; u <= n; ++u) {
		if (num[u] == 0) {
			dfs(u);
		}
	}
	for (int u = 1; u <= n; ++u) {
		for (int v : g[u]) {
			if (pos[u] != pos[v]) {
				++deg[pos[v]];
			}
		}
	}
	int root = -1;
	for (int i = 1; i <= ncomp; ++i) {
		if (deg[i] == 0) {
			root = vec[i][0];
			break;
		}
	}
	bfs(root);
	for (int i = 1; i <= n; ++i) {
		printf("%d\n", par[i]);
	}
}

