vector<ll> color;
bool dfs(const Graph &G, int v, int cur = 0)
{
	color[v] = cur;
	for (auto next_v : G[v])
	{

		//cerr << v << next_v.to << endl;
		// 隣接頂点がすでに色確定していた場合
		if (color[next_v.to] != -1)
		{
			if (color[next_v.to] == cur)
				return false; // 同じ色が隣接したらダメ
			continue;
		}

		// 隣接頂点の色を変えて、再帰的に探索 (一回でも false が返ってきたら false)
		if (!dfs(G, next_v.to, 1 - cur))
			return false;
	}
	return true;
}

