/* template */

std::vector<int> TopologicalSort(const graph &g){
    int V = g.size();
    std::vector<int> indeg(V,0);
    for(auto &in_edge: g){
        for(auto &e: in_edge){
            indeg[e]++;
        }
    }
    std::queue<int> que;
    for(int i = 0; i<V; i++){
        if(indeg[i]==0) que.push(i);
    }
    std::vector<int> t_sort;
    while(!que.empty()){
        int v = que.front(); que.pop();
        for(auto &nv: g[v]){
            indeg[nv]--;
            if(indeg[nv]==0) que.push(nv);
        }
        t_sort.emplace_back(v);
    }
    return t_sort;
}

