void djkstra(int s, VI &depth, VI &parent, const vector<VI> &connect, VI &indeg)
{
    vector<int> search = {s};
    vector<int> new_search;

    while (!search.empty())
    {
        for (auto i :search)
        {
            for (auto j : connect[i])
            {
                if (depth[j] < 1 + depth[i])
                {
                    indeg[j]--;
                    depth[j] = 1 + depth[i];
                    parent[j] = i + 1;
                    if (indeg[j] == 0)
                        new_search.push_back(j);
                }
            }
        }
        search.clear();
        search = new_search;
        new_search.clear();
    }
}

