const int MAX = 100010;

vector<int>G[MAX];
vector<int>RG[MAX];

int findRoot(int now){
  if(RG[now].size() == 0){
    return now;
  }
  return findRoot(RG[now][0]);
}

int max_cost[MAX];
int parent[MAX];

void dfs(int pre, int now, int cost){
  if(cost > max_cost[now]){
    parent[now] = pre + 1;
    max_cost[now] = cost;
  }
  for(int i = 0 ; i < G[now].size() ; i++){
    dfs(now, G[now][i], cost+1);
  }
}

