struct edge{
	int from,to,cost;
};

edge es[100010]; //辺
int d[100010]; //最短距離
int N,M; //頂点数、辺数

//ｓ番目の頂点から各頂点への最短距離を求める
void shortest_path(int s) {
	for(int i = 0;i < N;i++) {
		d[i] = Inf;
	}
	d[s] = 0;
	while(true) {
		bool update = false;
		for(int i = 0;i < M;i++) {
			edge e = es[i];
			if(d[e.from] != Inf && d[e.to] > d[e.from] + e.cost) {
				d[e.to] = d[e.from] + e.cost;
				update = true;
			}
		}
		if(update == false) {
			break;
		}
	}
}

//trueなら負の閉路が存在する
bool find_negative_roop() {
	memset(d,0,sizeof(d));
	for(int i = 0;i < N;i++) {
		for(int j = 0;j < M;j++) {
			edge e = es[j];
			if(d[e.to] > d[e.from] + e.cost) {
				d[e.to] = d[e.from] + e.cost;
				if(i == N - 1) return true;
			}
		}
	}
	return false;
}

