vector<int> depth;
vector<int> parent;

int get_depth(int node) {
    if (depth[node] >= 0)
        return depth[node];

    if (adj[node].empty())
        return depth[node] = 0;

    depth[node] = 0;
    parent[node] = -1;

    for (int p : adj[node])
        if (get_depth(p) + 1 > depth[node]) {
            depth[node] = get_depth(p) + 1;
            parent[node] = p;
        }

    return depth[node];
}

