	for (int i = 0; i < N; i++)
	{
		queue<int> q;

		arrived[i] = 1;
		ans[i] = 0;
		for (int j = 0; j < edges[i].size(); j++)
		{
			q.push(edges[i][j]);
			arrived[edges[i][j]] = 1;

			ans[j] = i + 1;
		}

		while (!q.empty())
		{
			int node = q.front(); q.pop();

			for (int k = 0; k < edges[node].size(); k++)
			{
				int next = edges[node][k];
				q.push(next);
				arrived[next] = 1;

				if (next != i)
				{
					ans[next] = node + 1;
				}
			}
		}

		if (find(arrived.begin(), arrived.end(), 0) == arrived.end())
		{
			root = i;
			break;
		}
		else
