  queue<int> que;
  que.push(root);
  parent[root] = 0;
  while (!que.empty())
  {
    int current = que.front();
    que.pop();

    for (int to : edges[current])
    {
      parent[to] = current;
      if (checked[to]++ < reversed[to].size())
        que.push(to);
    }
  }

  for (int i = 1, l = parent.size(); i < l; ++i)
    cout << parent[i] << '\n';
  cout.flush();
}

