vector<int> topological_sort(const vector<vector<int>>& g)
{
    vector<int> ideg(g.size());
    for (const auto& v : g) {
        for (const auto& u : v) {
            ideg[u]++;
        }
    }
    vector<int> sorted;
    for (int i = 0; i < g.size(); i++) {
        if (ideg[i] == 0) {
            sorted.push_back(i);
        }
    }
    int i = 0;
    while (i < sorted.size()) {
        int v = sorted[i];
        for (const auto& u : g[v]) {
            assert(ideg[u] > 0);
            if (--ideg[u] == 0) {
                sorted.push_back(u);
            }
        }
        i++;
    }
    if (i != g.size()) sorted.clear();
    return sorted;
}

int main()
{
    int N, M; cin >> N >> M;
    vector<vector<int>> g(N+1);
    for (int i = 0; i < N-1+M; i++) {
        int a, b; cin >> a >> b;
        g[a].push_back(b);
    }
    vector<int> topo = topological_sort(g);
    vector<int> ord(topo.size());
    for (int i = 0; i < topo.size(); i++) {
        ord[topo[i]] = i;
    }
    vector<int> ans(N+1);
    for (int i = 0; i < N+1; i++) {
        for (const auto& v : g[i]) {
            if (ans[v] == 0 || ord[ans[v]] < ord[i]) {
                ans[v] = i;
            }
        }
    }
    for (int i = 1; i < ans.size(); i++) {
        cout << ans[i] << endl;
    }
}

