	VL v(n);
	REP(i, n + m - 1) {
		ll f, t;
		cin >> f >> t;
		graph.emplace(f - 1, t - 1);
		++v[t - 1];
	}


	ll root;
	REP(i, n) {
		if (v[i] == 0) { root = i; break; }
	}

	vector<bool> used(n, false);
	used[root] = true;

	queue<ll> q;
	q.emplace(root);
	vector<PAIR> depth(n);
	depth[root] = PAIR(root, 0);
	vector<list<ll>> parent(n);

	while (!q.empty()) {
		ll from = q.front();
		q.pop();
		auto range = graph.equal_range(from);
		REPI2(itr, range.first, range.second) {
			ll to = itr->second;
			if (!used[to]) {
				used[to] = true;
				q.emplace(to);
			}
			parent[to].emplace_back(from);
			depth[to] = PAIR(to, depth[from].second + 1);
		}
	}

	auto depth_old = depth;
	bool flg = true;
	vector<bool> ok(n);
	while (flg) {
		flg = false;
		sort(ALL(depth), [](cauto a, cauto b) {
			return a.second < b.second;
		});
		REPI(itr, depth) {
			ll i = itr->first;
			ll dep = depth_old[i].second;
			if (ok[i]) { continue; }
			REPC(x, parent[i]) {
				ll comDep = depth_old[x].second;
				if (dep < comDep + 1) {
					depth_old[i] = PAIR(i, comDep + 1);
					dep = comDep + 1;
					flg = true;
				}
			}
			if (!flg) {
				ok[i] = true;
			}
		}
		depth = depth_old;
	}
	sort(ALL(depth), [](cauto a, cauto b) {
		return a.second > b.second;
	});

	VL ans(n);
	REPC(p, depth) {
		ll i = p.first;
		ll dep = p.second;
		if (v[i] == 0) {
			ans[i] = 0;
		} else if (v[i] == 1) {
			ans[i] = *parent[i].begin() + 1;
		} else {
			ll max = 0;
			ll tmp;
			REPC(x, parent[i]) {
				if (max < depth_old[x].second) {
					max = depth_old[x].second;
					tmp = x;
				}
			}
			ans[i] = tmp + 1;
		}
	}

