using namespace std;
typedef struct edge
{
    int out; //出力端のノード
    int in;  //入力端のノード
} edge;
typedef struct node
{
    int input;  //ノードの入力端の数
    int parent; //親ノード
    int num;    //ノード自身の番号
} node;
typedef struct nodeLists
{
    vector<node> nodeList;    //ノードを格納したベクター
    list<int> noInputNodeQue; //入力端を持たないノードのキュー
    int root;                 //根のノード
    //初期化処理
    //引数 : 要素数 int
    void nodesInitializ(int N)
    {
        this->root = -1;
        vector<node> list(N);
        for (int i = 0; i < N; i++)
        {
            list[i].num = i;
            list[i].input = 0;
            list[i].parent = -1;
        }
        this->nodeList = list;
    }
} nodes;
typedef struct edgeLists
{
    vector<edge> edgeList; //エッジのリスト
    int edgeNum;           //エッジの個数
    //エッジの入力処理
    //引数：ノード(nodes)
    void inputEdge(nodes &nodes)
    {
        vector<edge> tmp(this->edgeNum);
        this->edgeList = tmp;
        for (int i = 0; i < this->edgeNum; i++)
        {
            cin >> this->edgeList[i].out >> this->edgeList[i].in; //入力
            this->edgeList[i].out--;
            this->edgeList[i].in--;
            nodes.nodeList[this->edgeList[i].in].input++; //入力端の数を増やす
        }
    }
} edges;
//終了していれば0,終了していなければ1を返す
int main()
{
    int N, M;
    cin >> N >> M;
    //ノードの初期化
    nodeLists nodes;
    nodes.nodesInitializ(N);
    //枝の入力
    edgeLists edges;
    edges.edgeNum = N + M - 1;
    edges.inputEdge(nodes);
    /*ソート*/
    while (!edges.edgeList.empty())
    {
        nodes.noInputNodeQue.clear();
        //入力端のないノードのリストを作る
        for (int i = 0; i < N; i++)
        {
            if (nodes.nodeList[i].input == 0)
            {
                nodes.nodeList[i].input = -1;
                nodes.noInputNodeQue.push_back(i);
            }
        }
        //枝の処理
        //node:処理中の頂点
        for (auto node : nodes.noInputNodeQue)
        {
            for (vector<edge>::iterator itrEdge = edges.edgeList.begin(); itrEdge != edges.edgeList.end();)
            {
                if (itrEdge->out == node)
                {
                    nodes.nodeList[itrEdge->in].input--;
                    if (nodes.nodeList[itrEdge->in].input == 0)
                    {
                        if (nodes.root == -1)
                        {
                            nodes.root = itrEdge->out;
                        }
                        nodes.nodeList[itrEdge->in].parent = itrEdge->out;
                    }
                    itrEdge = edges.edgeList.erase(itrEdge);
