            }
        }
    }
    for (int i = 0; i < N; i++)
    {
        if (i == nodes.root)
        {
            cout << "0" << endl;
        }
        else
        {
            cout << nodes.nodeList[i].parent + 1 << endl;
        }
    }
    return 0;
}

