using namespace std;
typedef long long ll;
#define REP(i,n) for (ll i = 0; i < (n); ++i)


void solve(long long N, long long M,
           std::vector<long long> A, std::vector<long long> B){
    vector<vector<ll>> net(N);
    vector<ll> indeg(N, 0);
    REP(i, A.size()){
        ll ai = A.at(i);
        ll bi = B.at(i);
        ai--; bi--;
        net.at(ai).push_back(bi);
        indeg.at(bi)++;
    }

    ll src = 0;
    REP(i, N){
        if(indeg.at(i) == 0){
            src = i;
            break;
        }
    }

    vector<ll> dist(N, -1);
    vector<ll> par(N, -1);
    priority_queue<pair<ll, ll>> que;
    que.emplace(0, src);
    dist.at(src) = 0;
    while(!que.empty()){
        ll v = que.top().second; que.pop();
        for(ll nxt : net.at(v)){
            if(dist.at(nxt) < dist.at(v) + 1){
                dist.at(nxt) = dist.at(v) + 1;
                que.emplace(dist.at(nxt), nxt);
                par.at(nxt) = v;
            }
        }
    }

    REP(i, N){
        if(i == src){
            cout << 0 << endl;
        }else{
            cout << par.at(i) + 1 << endl;
        }
    }
}

