//グラフの隣接リスト
vector<ll> g[100010];
//頂点の入次数を管理
int h[100010];

vector<ll> topological_sort() {
  //入次数が0の頂点の集合
  stack<int> st;

  //入次数が0の頂点であればstに追加
  REP(i, v) if (h[i] == 0) st.push(i);

  //ソートされた後のグラフ
  vector<ll> ans;
  // stがなくなるまでループ
  while (st.size()) {
    // stの集合のから一つ取り出す
    int i = st.top();
    st.pop();
    ans.push_back(i);
    for (auto &j : g[i]) {
      //隣接する頂点の入次数をマイナス1
      h[j]--;
      //これによって入次数が0になればstに追加
      if (h[j] == 0)
        st.push(j);
    }
  }
  return ans;
}

map<ll, ll> node_to_order;

bool comp(const pair<ll, ll> &l, const pair<ll, ll> &r) {
  if (l.second < r.second) {
    return true;
  } else if (l.second > r.second) {
    return false;
  } else {
    return node_to_order[l.first] > node_to_order[r.first];
  }
}

void solve(long long N, long long M, std::vector<long long> A,
           std::vector<long long> B) {
  v = N;
  e = N - 1 + M;
  REP(i, A.size()) {
    g[A[i] - 1].push_back(B[i] - 1);
    h[B[i] - 1]++;
  }
  auto ans = topological_sort();
  for (int i : ans) {
    node_to_order[ans[i]] = i;
  }
  vector<pair<ll, ll>> C(A.size());
  REP(i, A.size()) {
    C[i].first = A[i] - 1;
    C[i].second = B[i] - 1;
  }
  sort(ALL(C), comp);
  vector<ll> parent(N, 0);
  ll prev = -1;
  REP(i, C.size()) {
    if (prev == C[i].second) {
      C[i].first = -1;
    } else {
      parent[C[i].second] = C[i].first + 1;
    }
    prev = C[i].second;
  }
  REP(i, N) {
    std::cout << parent[i] << std::endl;
  }
}

