ll binary_search_2(ll target, vector< pair<ll, ll> > & search_table)
{
	const ll loop_cnt = 1000;	// 要調整
	ll N = search_table.size();
	ll lb = 0;
	ll ub = N;

	for (int i = 0; i < loop_cnt; ++i) {
		ll mid = (lb + ub) / 2;

		if (target == search_table[mid].first) {
			return mid;
		}
		else if (target >= search_table[mid].first) {
			lb = mid;
		}
		else {
			ub = mid;
		}
	}

	return ub;
}

