		e_rev[i].first = e[i].second;
	}
	Rep(i, N + M - 1) {
		ll dest = e[i].second;
		jisuu[dest]++;
	}
	sort(e_rev.begin(), e_rev.end());

	Rep(i, N) {
		if (jisuu[i] == 0) {
			// root
			ans[i] = 0;
		}
		else if (jisuu[i] == 1) {
			// parent is ans[i]
			ans[i] = binary_search_2(i, e_rev) + 1;
		}
		else {
			ans[i] = binary_search_2(i, e_rev) + 1;
		}
	}


	Rep(i, N) {
		cout << ans[i] << endl;
	}

	return 0;
}

