	for (ll i = 0; i < N - 1 + M; ++i)
	{
		ll A, B;

		cin >> A >> B;
		E[i].first = A - 1;
		E[i].second = B - 1;
	}

	vector<vector<ll>> graph(N);
	vector<set<ll>> Ecome(N);

	for (ll i = 0; i < N; ++i)
	{
		graph[i] = vector<ll>();
		Ecome[i] = set<ll>();
	}

	for (ll i = 0; i < N - 1 + M; ++i)
	{
		Ecome[E[i].second].insert(E[i].first);
		graph[E[i].first].push_back(E[i].second);
	}

	//vector<pair<ll, ll>> kakutei;
	vector<ll> ans(N);

	for (ll i = 0; i < N; ++i)
	{
		if (Ecome[i].size() == 0)
		{
			ans[i] = -1;
			continue;
		}

		if (Ecome[i].size() == 1)
		{
			ans[i] = *(Ecome[i].begin());
			continue;
