int main (){
  int n,m,bufa,bufb;
  cin >> n >> m;
  map<int, int> parentNum;
  map<int, vector<int>> children;
  for(int i = 0; i < n; i++){
    parentNum[i] = 0;
    children[i] = vector<int> {};
  }
  for(int i = 0 ; i < n-1+m; i++){
    cin >> bufa >> bufb;
    parentNum[bufb-1]++;
    children[bufa-1].push_back(bufb-1);
  }

  int answer[n];
  int parent = 0;
  vector<int> isolated = {};
  for(int i=0; i < n; i++){
    if(parentNum[i] == 0){
      answer[i] = -1;
      isolated.push_back(i);
      break;
    }
  }
  while(isolated.size() > 0){
    int buf;
    parent = isolated[isolated.size() - 1];
    isolated.pop_back();
    vector<int> found={};
    vector<int> bufv = children[parent];
    for(int i=0; i < (int)bufv.size(); i++){
      buf = bufv[i];
      parentNum[buf]--;
      if(parentNum[buf] == 0){
        found.push_back(buf);
      }
    }
    for(int i=0;i < (int)found.size(); i++){
      buf = found[i];
      answer[buf] = parent;
      isolated.push_back(buf);
    }
  }
  for(int i=0;i<n;i++){
    cout << answer[i] + 1 << endl;
  }
  return 0;
}

