    } else {
      std::set<size_t> s;
      s.insert(A);
      Parents.insert(std::make_pair(B, s));
    }
  }

  Rank rank(Parents);

  for (size_t i=0; i<N; i++) {
    if (Parents.count(i) > 0) {
      auto const& ps = Parents.at(i);
      auto ans = *std::max_element(ps.begin(), ps.end(),
                                   [&](auto a, auto b){return rank(a) < rank(b);});
