using PII = pair<int, int>;

int main() {
	int n, m;
	cin >> n >> m;

	vector<int> a(n + m - 1, 0);
	auto b = a;
	vector<vector<int>> children(n + 1, vector<int>());
	vector<vector<int>> parents(n + 1, vector<int>());
	for (int i = 0; i < a.size(); i++) {
		cin >> a[i] >> b[i];
		children[a[i]].emplace_back(b[i]);
		parents[b[i]].emplace_back(a[i]);
	}

	int root = -1;
	for (int i = 1; i < parents.size(); i++) {
		if (parents[i].size() == 0) {
			root = i;
			break;
		}
	}

	// printf("root %d\n", root);

	// 距離 index
	// 最小距離からとってくる
	priority_queue<PII, vector<PII>, greater<PII>> que;

	vector<int> distance(n + 1, -1);
	distance[root] = 0;
	que.push(make_pair(0, root));

	int check_dist = 0;
	vector<bool> checked(n + 1, false);

	while (!que.empty()) {
		auto p = que.top();
		que.pop();

		int dist = p.first;
		if (dist > check_dist) {
			check_dist = dist;
			checked.assign(n + 1, false);
		}
		int idx = p.second;
		// printf("pop: idx %d, dist %d\n", idx, dist);

		if (checked[idx]) {
			continue;
		}
		checked[idx] = true;

		for (auto x: children[idx]) {
			int n_dist = dist + 1;
			if (n_dist > distance[x]) {
				distance[x] = n_dist;
				que.push(make_pair(n_dist, x));
			}
		}
	}

	vector<int> ans(n + 1, -1);
	ans[root] = 0;
	for (int i = 0; i < a.size(); i++) {
		if (distance[a[i]] + 1 == distance[b[i]]) {
			ans[b[i]] = a[i];
		}
	}

	for (int i = 1; i < ans.size(); i++) {
		cout << ans[i] << endl;
	}
	return 0;
}

