std::vector<std::vector<LL>>G;
std::vector<LL>topological_sort(LL V)
{
	std::vector<LL>h(V + 1);
	for (LL i = 1; i <= V; ++i) for (auto e : G[i]) ++h[e];

	std::stack<LL>st;
	std::vector<LL>ans;
	for (LL i = 1; i <= V; ++i) if (h[i] == 0) st.push(i);
	while (!st.empty())
	{
		LL v = st.top(); st.pop();
		ans.push_back(v);
		for (auto u : G[v])
		{
			--h[u];
			if (h[u] == 0) st.push(u);
		}
	}

	return ans;
}

