	rep(i, N - 1 + M) G[A[i]].push_back(B[i]);
	auto sortedVs = topological_sort(N);
	rep(i, N) rev[sortedVs[i]] = i;

	std::vector<LL>ans(N + 1, sortedVs[0]);
	ans[sortedVs[0]] = 0;
	rep(i, N - 1 + M) if (rev[ans[B[i]]] < rev[A[i]]) ans[B[i]] = A[i];

	for (LL i = 1; i <= N; ++i) out << ans[i] << std::endl;
}

