int N,M;
int A[100000],B[100000];
vector<int> oya[100000];

int dp[100000];
int solve(int now){
    if(dp[now] != -1) return dp[now];
    if(oya[now].size() == 0) return dp[now] = 0;
    if(oya[now].size() == 1) return dp[now] = solve(oya[now][0]) + 1;
    int tmp = -1;
    int p = -1;
    for(int i=0; i<oya[now].size(); i++){
        if(solve(oya[now][i]) > tmp){
            tmp = solve(oya[now][i]);
            p = oya[now][i];
        }
    }
    oya[now].clear();
    oya[now].push_back(p);
    return dp[now] = tmp + 1;
}

