const ll INF = 5e15;
ll N, M;
vector<vector<ll>> edges(1e5);
vector<vector<ll>> reve(1e5);

vector<ll> top_sort(const vector<vector<ll>> &edges){
	vector<ll> ret;
	vector<bool> road(N);
	vector<bool> used(N);
	function<bool(ll)> dfs = [&](ll now){
		used[now] = true;
		road[now] = true;
		for(ll nxt : edges[now]){
			if(road[nxt]) return false;
			if(used[nxt]) continue;
			if(!dfs(nxt)) return false;
		}
		ret.push_back(now);
		road[now] = false;
		return true;
	};
	for(ll i = 0; i < edges.size(); i++){
		if(used[i]) continue;
		if(!dfs(i)) return vector<ll>(0);
	}
	reverse(ret.begin(), ret.end());
	return ret;
}

int main(){
    cin >> N >> M;
    edges.resize(N);
    reve.resize(N);
    for(ll i = 0; i < N + M - 1; i++){
        ll a, b;
        cin >> a >> b;
        a--;
        b--;
        edges[a].push_back(b);
        reve[b].push_back(a);
    }
    auto ts = top_sort(edges);
    vector<ll> pos(N);
    for(ll i = 0; i < N; i++) pos[ts[i]] = i;
    vector<ll> ans(N);
    for(ll i = 0; i < N; i++){
        if(reve[i].size() == 0){
            ans[i] = 0;
            continue;
        }
        ll look = reve[i][0];
        for(ll e : reve[i]){
            if(pos[look] < pos[e]) look = e;
        }
        ans[i] = look + 1;
    }
    for(ll e : ans) cout << e << '\n';
    return 0;
}

