            break;
        for (int i = 0; i < N + M + 1; i++) {
            if (a[i] == p[j]) {
                r[b[i]] = p[j];
                a[i] = 0;
                b[i] = 0;
            };
        }
        p[j] = 0;
    }
    int x[N + 1], y[N + 1];
    for(int n = 1; n < N + 1; n++){
        x[n] = 0;
        y[n] = 0;
    }

    for(int i = 0; i < N + M - 1; i++){
        x[a[i]] = 1;
        y[b[i]] = 1;
    }

    int pointer = 0;
    for(int n = 1; n < N + 1; n++){
        if(x[n] == 1 && y[n] == 0){
            p[pointer++] = n;
        }
    }

    if(pointer != 0)
        my_func(p, a, b, r);
}

