typedef pair<int,int> P;

struct edge{
	int to,cost;
};
typedef pair<int,int> P; //firstは最短距離、secondは頂点の番号

int V; //頂点数
vector<edge> G[100010];
int d[100010]; //頂点sからの最短距離

void dijkstra(int s) {
	//greater<P>を指定することでfirstが小さい順に取り出せる
	priority_queue<P,vector<P>,greater<P>> que;
	fill(d,d + V,0);
	d[s] = 0;
	que.push(P(0,s));

	while(!que.empty()) {
		P p = que.top();
		que.pop();
		int v = p.second;
		if(d[v] < p.first) {
			continue;
		}
		for(int i = 0;i < G[v].size();i++) {
			edge e = G[v][i];
			if(d[e.to] < d[v] + e.cost) {
				d[e.to] = d[v] + e.cost;
				que.push(P(d[e.to],e.to));
			}
		}
	}
}

int main() {
    cin >> V;
    int M;
    cin >> M;
    vector<P> vec(V + M - 1);
    vector<bool> vec2(V);
    for(int i = 0;i < V + M - 1;i++) {
        int A,B;
        cin >> A >> B;
        G[A - 1].push_back(edge{B - 1,1});
        vec.at(i) = P(A - 1,B - 1);
        vec2.at(B - 1) = true;
    }
    int cnt = 0;
    for(int i = 0;i < V;i++) {
        if(vec2.at(i) == false) {
            cnt = i;
        }
    }
    dijkstra(cnt);
    vector<int> ret(V);
    for(int i = 0;i < V + M - 1;i++) {
        if(d[vec.at(i).second] - d[vec.at(i).first] == 1) {
            ret.at(vec.at(i).second) = vec.at(i).first;
        }
    }
    for(int i = 0;i < V;i++) {
        if(i == cnt) {
            cout << 0 << endl;
            continue;
        }
        cout << ret.at(i) + 1 << endl;
    }
}

