long long gcd(long long a, long long b) {
    if (a>b) swap(a,b);

    auto r = b % a;

    return (r ? gcd(r, a) : a);
}
int main() {
    int N, M;
    multimap<int, int> AB;
    set<int> ex;

    cin >> N >> M;

    REP(i,N+M){
        int a,b;
        cin>>a>>b;
        AB.emplace(a, b);
        ex.insert(b);
    }

    int root;
    for (root = 1;root <= N; root++)
        if (ex.count(root) == 0)
            break;

    queue<int> bfs;
    vector<int> r(N, 0);
    bfs.push(root);
    set<int> used;
