        auto now = bfs.front(); bfs.pop();
        if (used.count(now) == 0){
            auto it = AB.lower_bound(now), ite = AB.upper_bound(now);

            while (it != ite){
                r[it->second-1] = now;
                bfs.push(it->second);
                it++;
            }
            used.insert(now);
        }
    }
    for (int i : r)
