set<ll> visited;
ll n;

ll dfs(vector<vector<ll>>& mat, ll current, ll count)
{
    count++;
    visited.insert(current);
    for (auto e : mat[current])
    {
        if (!visited.count(e))
        {
            count = dfs(mat, e, count);
        }
    }
    return count;
}

void dfs_2(vector<vector<ll>>& mat, ll current, vector<ll>& parents)
{
    visited.insert(current);
    for (auto e : mat[current])
    {
        if (!visited.count(e))
        {
            parents[e] = current;
            dfs_2(mat, e, parents);
        }
    }
}

int main()
{
    ios_base::sync_with_stdio(false);
    //cout.tie(0);
    //cin.tie(0);

    ll m;
    cin >> n >> m;

    vector<vector<ll>> mat(n + 1);
    ll count = 0;
    for (auto i = 0; i < (n - 1 + m); i++)
    {
        ll from, to;
        cin >> from >> to;
        mat[from].push_back(to);
    }

    set<ll> root;
    for (auto i = 1; i <= n; i++)
        root.insert(i);

    bool flag = true;
    ll root_a = -1;
    while (flag)
    {
        for (auto e : root)
        {
            ll c = dfs(mat, e, 0);

            if (c == n)
            {
                flag = false;
                root_a = e;
                break;
            } else
            {
                for (auto v : visited)
                    root.erase(v);
                visited.clear();

                break;
            }
        }
    }

    vector<ll> parents(n + 1);
    parents[*(visited.begin())] = 0;

    ll tmp = root_a;
    visited.clear();

    dfs_2(mat, tmp, parents);

    for (auto i = 1; i <= n; i++)
        cout << parents[i] __;

    return 0;
}

