using namespace std;


vector<int> V[100000];

int findRoot( vector<int>& B, int N, int M ){
    vector<bool> isAppeared(N, false);  // B に現れてないのが root
    for( int i = 0; i < N-1+M; ++i ) isAppeared[B[i]] = true;
    for( int i = 0; i < N; ++i ){
        if( !isAppeared[i] ) return i;
    }
    return -1;
}


int main()
{
    int N, M;
    cin >> N >> M;
    vector<int> A(N-1+M), B(N-1+M);
    for( int i = 0; i < N-1+M; ++i ){
        cin >> A[i] >> B[i];
        --A[i], --B[i];
        V[A[i]].push_back( B[i] );
    }


    int root = findRoot(B, N, M);

    // 親からの最長経路を辿ればいい！って思って幅優先探索を実装したけど、
    // トポロジカルソートってやつと同義らしい
    vector<int> indegree(N, 0);
    for( int i = 0; i < N-1+M; ++i ) ++indegree[B[i]];

    vector<int> parent(N);
    queue<int> q;
    q.push( root );
    while( !q.empty() )
    {
        int tmp = q.front();
        q.pop();
        for( auto v: V[tmp] ){
            if( indegree[v] == 1 ){
                parent[v] = tmp+1;
                q.push( v );
            }
            --indegree[v];
        }
    }
    for( int i = 0; i < N; ++i ) cout << parent[i] << endl;

    return 0;
}

