void solve(int N,int M,vi& a,vi& b) {
    int L=a.size();
    vvi nxt(L), into(L);
    rep(i,L){
        nxt[a[i]].pb(b[i]);
        into[b[i]].pb(a[i]);
    }
    int root=-1;
    rep(i,L){
        if (into[i].size()==0) { root=i; break; }
    }
    vi d(N, INT_MAX);
    queue<pair<int,ii>> q;
    vi prev(N, -1);
    q.push(make_pair(root, ii(0,-1)));
    while (!q.empty()) {
        auto p = q.front(); q.pop();
        int u=p.first, lv=p.second.first, from=p.second.second;
        if (d[u] == INT_MAX) {
            d[u] = lv;
            prev[u] = from;
            for (int v: nxt[u]) {
                q.push(make_pair(v, ii(lv+1, u)));
            }
        } else if (d[u] >= lv) {
            continue;
        } else {
            prev[u] = from;
        }
    }
    rep(i,N){
        printf("%d\n", prev[i]+1);
    }
}

