SINT64 top;
vector<SINT64> root;
vector<vector<SINT64>> up(100005);
vector<vector<SINT64>> down(100005);

void dfs(SINT64 x) {
	if (up[x].size() == 0) {
		top = x;
	} else {
		dfs(up[x][0]);
	}
}

void dfs2(SINT64 x,SINT64 cnt) {
	root[x] = MAX(cnt,root[x]);
	cnt++;
	rep(i,0,down[x].size()) {
		dfs2(down[x][i],cnt);
	}
}

int main() {

	SINT64 N;	cin >> N;
	SINT64 M;	cin >> M;

	vector<SINT64> ans(N,0);
	vector<SINT64> ccc(N);

	root.resize(N,-1);

	rep(i,0,N-1+M) {
		SINT64 a,b;
		cin >> a >> b;
		a--;b--;
		down[a].emplace_back(b);

		up[b].emplace_back(a);
		ccc[b]++;
	}
	dfs(0);

	priority_queue<Pll, vector<Pll>>q;

	q.push(Pll(0,top));

	while(q.size() != 0) {
		Pll buf = q.top();
		q.pop();
		if (root[buf.S] < buf.F) {
			root[buf.S] = buf.F;
		}
		buf.F++;
		rep(i,0,down[buf.S].size()) {
			ccc[down[buf.S][i]]--;
			if (ccc[down[buf.S][i]] == 0){
				q.push(Pll(buf.F,down[buf.S][i]));
			}
		}
	}




	rep(i,0,N) {
		rep(j,0,up[i].size()) {
			if (root[up[i][j]]+1 == root[i]) {
				ans[i] = up[i][j];
			}
		}
	}
	ans[top] = -1;
	rep(i,0,N) {
		put(ans[i]+1);
	}
	return 0;
}


