			triplets.insert(who[i][0] + who[i][1] + who[i][2]);
		}
	}
	sort(a.rbegin(), a.rend());
	printf("-1\n");
	int64 value = 0;
	int64 last_single = -1;
	int64 last_pair = -1;
	for (int s = 2, i = 0, cur = 0; s <= n; ++s) {
		while ((i < sz(a)) && (cur + a[i].sc.sc <= s)) {
			value += a[i].fs;
			cur += a[i].sc.sc;
			int num = a[i].sc.fs;
			if (a[i].sc.sc == 1) {
				last_single = a[i].fs;
				singles.erase(singles.find(last_single));
			} else {
