			nxt = max(nxt, value - last_single + a[i].fs);
		}
		if ((last_pair != -1) && !triplets.empty()) {
			nxt = max(nxt, value - last_pair + *triplets.rbegin());
		}
		if (!singles.empty()) {
			nxt = max(nxt, value + *singles.rbegin());
		}
		printf("%lld\n", nxt);
	}
	return 0;
