bool visit(int v){
  color[v] = 1;
  rep(i,G[v].size()){
    int e = G[v][i];
    if (color[e] == 2) continue;
    if (color[e] == 1) return false;
    if (!visit(e)) return false;
  }
  order.push_back(v); color[v] = 2;
  return true;
}
bool topologicalSort() {
  REP(u, 1, N+1) if (!color[u] && !visit(u)) return false;
  reverse(order.begin(),order.end());
  return true;
}

