        G[a].push_back(b);
        oya[b].push_back(a);
    }
    int ne;
    REP(i,N){
        if(oya[i].size()==0) ne=i;
    }

    //ダイクストラ O(ElogV)
    // データ構造
    vector<int> dist(N, INF); // 全頂点を「未訪問」に初期化
    priority_queue<pair<ll,ll>,vector<pair<ll,ll>>,greater<pair<ll,ll>>> que;

    vector<int> ans(N);
    ans[ne]=0;
    // 初期条件 (頂点 0 を初期ノードとする)
    dist[ne] = 0;
    que.push(make_pair(0,ne)); // 0 を橙色頂点にする

     // 開始 (キューが空になるまで探索を行う)
    while (!que.empty()) {
        pair<ll,ll> p = que.top(); // 優先度キューから先頭頂点を取り出す
        que.pop();
        ll d=p.first;
        ll v=p.second;
        if(dist[v]<d) continue;
        // v から辿れる頂点をすべて調べる
        for (int nv : G[v]) {
            ll nd=d-1;
            // 新たな頂点 nv について距離が短いなら更新
            if(nd<dist[nv]){
                dist[nv] = nd;
                ans[nv]=v+1;
                que.push(make_pair(nd,nv));
            }
        }
    }
    REP(i,N) cout<<ans[i]<<endl;




}

