// Adjacent Array Based
class Graph
{
public:
    ll N;
    struct Vertex{
        ll dist, idx;
        bool operator<(const Vertex o) { return dist < o.dist; }
    };
    struct Edge{ll from, to;ll cost;};
    vector<vector<Edge> > adj;
    vector<vector<ll> > rev;
    vll c, v, order;
	Graph(ll siz)
	{
        N = siz;
		adj.resize(siz);
		rev.resize(siz);
        c.resize(N);
        v.resize(N);
	}
	void unite(ll from, ll to, ll cost=1LL) {
        adj[from].push_back({from, to, cost});
        rev[to].push_back(from);
    }
    bool dfs(ll v) {
        c[v] = 1;
        for(auto &e:adj[v]) {
            if(c[e.to] == 2) continue;
            if(c[e.to] == 1) return false;
            if(!dfs(e.to)) return false;
        }
        order.push_back(v);c[v] = 2;
        return true;
    }
    bool topological_sort() {
        REP(u, N) {
            if(!c[u] && !dfs(u)) {
                return false;
            }
        }
        INV(order);
        return true;
    }
};

void solve() {
    ll N, M;
    cin >> N >> M;
    Graph g(N);
    REP(i, N - 1 + M) {
        ll a, b;
        cin >> a >> b;
        a--;b--;
        g.unite(a, b);
    }
    g.topological_sort();
    vll ord = g.order;
    vec<vll> rev = g.rev;
    vll par(N);
    REP(i, N) {
        vll p = rev[i];
        ll aa = -1;
        if(p.empty()) {
            out(0);
            continue;
        }
        REP(j, p.size()){
            ll a = find(ord.begin(), ord.end(), p[j]) - ord.begin();
            aa = max(aa, a);
        }
        out(ord[aa]+1);
    }
}

