        vector<int> &dist) {
    for (int v : g[u]) {
        if (h + 1 > dist[v]) {
            if (dist[v] == 0) {
                dist[v] = h + 1;
                par[v] = u;
                dfs(v, h + 1, g, par, dist);
            } else {
                dist[v] = h + 1;
                par[v] = u;
            }
        }
    }
}
int main() {
    std::ios::sync_with_stdio(false); 
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;
    vector<vector<int>> g(N);
    vector<int> indeg(N, 0);
    for (int i = 0; i < N - 1 + M; ++i) {
        int A, B;
        cin >> A >> B;
        g[A - 1].push_back(B - 1);
        ++indeg[B - 1];
    }
    int r = -1;
    for (int i = 0; i < N; ++i) {
        if (indeg[i] == 0) {
            r = i;
        }
    }

    vector<int> dist(N, 0), par(N, -1);
    dfs(r, 0, g, par, dist);

    for (int i = 0; i < N; ++i) {
        cout << par[i] + 1 << "\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

long long M;
long long N;
vector<long long> B(100001);
vector<long long> A(100001);
stack<long long> st[100001];
vector<long long> dep(100001);
vector<long long> res(100001);

long long depth(long long n) {
	if (dep[n] != -1) return dep[n];

	if (st[n].empty()) {
		res[n] = 0;
		return dep[n] = 0;
	} else {

		while (!st[n].empty()) {
			long long ntop = st[n].top();
			if (depth(ntop) > dep[n]-1) {
				res[n] = ntop;
				dep[n] = depth(ntop)+1;
			}
			st[n].pop();
		}
		return dep[n];
	}
}

int main(){
	scanf("%lld",&N);
	scanf("%lld",&M);
	for(int i = 0 ; i <= ((N-1)+M)-1 ; i++){
		scanf("%lld",&A[i]);
		scanf("%lld",&B[i]);
	}

	for(int i = 0 ; i <= ((N-1)+M)-1 ; i++){
		st[B[i]].push(A[i]);
	}

	for (int i = 1 ; i <= N ; i++) {
		dep[i] = -1;
	}

	for (int i = 1 ; i <= N ; i++) {
		depth(i);
	}

	for (int i = 1 ; i <= N ; i++) {
		cout << res[i] << "\n";
	}

	return 0;
}

