vector <int> adj[N];

stack <int> stk;

int visit[N], P[N];

void dfs(int u) {
        if(visit[u]) return;
        visit[u] = 1;
        for(int v: adj[u]) dfs(v);
        stk.push(u);
}

void dfs(int p, int u) {
        if(visit[u]) return;
        visit[u] = 1;
        P[u] = p;
        for(int v: adj[u]) dfs(u, v);
}

