  while (q.size()) {
    u = q.back(); q.pop_back();
    for (auto v : g[u]) {
      deg[v]--;
      if (deg[v] == 0) {
        q.push_back(v);
        par[v] = u;
      }
    }
  }

  for (auto i : par) {
    cout << i + 1 << '\n';
  }

  return 0;
}

