int ganbaru(ll now, ll depth){
	for(ll i = 1; i <= edgelist[now].size(); i++){
		ll buf = edgelist[now].back(); edgelist[now].pop_back(); edgelist[now].push_front(buf);
		if(parent[buf][0] == -1){
			parent[buf][0] = now;
			ganbaru(buf, depth+1);
		}
		else{
			ll olddepth = 0;
			ll at = buf;
			while(at != root){
				at = parent[at][0];
				olddepth++;
			}
			if(olddepth < depth+1){
				parent[buf][0] = now;
				ganbaru(buf, depth+1);
			}
		}
	}
	return 0;
}

