int main() {
	ll N;
	cin >> N;
	ll M;
	cin >> M;

	//グラフ表現(Nノードのうちノードindexから別のノード番号へ接続)
	vector<vector<ll>> graph(N + 1, vector<ll>(0));
	vll inCount(N + 1, 0);

	rep(i, N - 1 + M) {
		ll a;
		cin >> a;
		ll b;
		cin >> b;

		graph[a].push_back(b);
		inCount[b]++;
	}

	//根を探す
	ll root = 0;
	reps(i, 1, N) {
		if (inCount[i] == 0) {
			root = i;
			break;
		}
	}

	//根からBFS
	queue<ll> q;
	vll dist(N + 1, -1);
	vll parent(N + 1, -1);
	dist[root] = 0;
	parent[root] = 0;
	q.push(root);

	while (q.empty() == false) {
		ll curr = q.front();
		q.pop();
		ll currDist = dist[curr];

		for (auto next : graph[curr]) {
			if (dist[next] < 0) {
				dist[next] = currDist + 1;
				parent[next] = curr;
				q.push(next);
			}
			else if (dist[next] < currDist + 1) {
				dist[next] = currDist + 1;
				parent[next] = curr;
				q.push(next);
			}
		}
	}

	reps(i, 1, N) {
		cout << parent[i] << endl;
	}

	return 0;
}

