const int INF = 1e9;

void solve() {
  int N, M;
  cin >> N >> M;
  vector<vi32> g(N + 1);
  vi32 deg(N + 1);
  rep(i, N + M - 1) {
    int u, v;
    cin >> u >> v;
    g[u].emplace_back(v);    
    deg[v]++;
  }
  int root = -1;
  reps(i, N) if (deg[i] == 0) {
    if (root != -1) {
      assert(false);
    }
    root = i;
  }
  vi32 par(N + 1);
  vi32 dep(N + 1, INF);
  dep[root] = 0;

  auto dfs = [&](auto dfs, int u, int p) -> void {
    for (auto v : g[u]) {
      if (v == p) continue;
      if (dep[v] == INF) {
        par[v] = u;
        dep[v] = dep[u] + 1;
        dfs(dfs, v, u);
      } else {
        if (dep[v] < dep[u] + 1) {
          par[v] = u;
          dep[v] = dep[u] + 1;
        }
      }
    }
  };
  dfs(dfs, root, -1);
  reps(i, N) {
    cout << par[i] << endl;
  }
}

