struct Node {
  std::vector<int> next;
  int inbound_degree{0};
  int max_depth{-1};
  int parent{-1};
};
void dfs(int root, std::vector<Node> &nodes) {
  if (nodes[root].max_depth != -1) {
    return;
  }
  nodes[root].max_depth = 0;
  for (auto to : nodes[root].next) {
    dfs(to, nodes);
    nodes[root].max_depth = std::max(nodes[root].max_depth, nodes[to].max_depth + 1);
  }
}
void dfs2(int root, int from, std::vector<Node> &nodes) {
  if (nodes[root].parent != -1) {
    return;
  }
  nodes[root].parent = from;
  std::sort(nodes[root].next.begin(), nodes[root].next.end(),
            [&](const auto &a, const auto &b) { return nodes[a].max_depth > nodes[b].max_depth; });
  for (auto to : nodes[root].next) {
    dfs2(to, root + 1, nodes);
  }
}
