int check(int now)
{
	int ji=0,rem=-1;
	for(int i=0;i<v[now].size();i++)
		if(in[v[now][i]]>0)
			ji++,rem=v[now][i];
	if(ji!=1)return -1;
	return rem;
}
void kill(int now)
{
	for(int i=0;i<v[now].size();i++)
		in[v[now][i]]--;
}
int tuopu(int now)
{
	int zero=0;
	if(in[now]==0)return 0;
	queue<int>q;
	for(int i=0;i<N;i++)
		if(in[i]==0)
			q.push(i);
	while(!q.empty())
	{
		int x=q.front();
		q.pop();
		int judge=check(now);
		if(judge>0)return judge;
		kill(x);
		for(int i=0;i<N;i++)
			if(in[i]==0)
				q.push(i);
	}
}
