		ch[A[i]].pb(B[i]);
		pa[B[i]].pb(A[i]);
		cc[A[i]]++;
		pc[B[i]]++;
	}
	ll root;
	REP(i, N) {
		if (!pc[i]) root = i;
	}
	qll Q;
