	ll now;
	vll ans(N, -1);
	while (!Q.emp) {
		now = Q.fr;
		Q.pop();
		ROR(ch[now], i) {
			pc[i]--;
			if (!pc[i]) {
				ans[i] = now;
				Q.push(i);
			}
		}
	}

	REP(i, N) sal(ans[i] + 1);


}

