	while (st.size()) {
		//stの集合のから一つ取り出す
		int i = st.top(); st.pop();
		vsort.push_back(i);
		for (auto& j : g[i]) {
			//隣接する頂点の入次数をマイナス1
			h[j]--;
			//これによって入次数が0になればstに追加
			if (h[j] == 0) st.push(j);
		}
	}


	vector<int> ans;
	ans.assign(N + 1, 0);

	for (int i = 0; i < N; i++){
		//vsort[i]に入る辺が複数あれば一番短いのだけを残す
		if (gg[vsort[i]].size() >= 2){
			// 現在の頂点の複数の親についてforして、vsortの中で後ろの方に出てくるものを残す
			int m = 0;
			for (int j = 0; j < gg[vsort[i]].size(); j++){
				auto k = find(vsort.begin(), vsort.end(), gg[vsort[i]][j]);
				int s = k - vsort.begin();
//				cout << vsort[i] << " " << *k << endl;
//				cout << m << endl;
				m = max(m, s );
			}
			ans[vsort[i]] = vsort[m];
		}
		else if (gg[vsort[i]].size() ==1){
			ans[vsort[i]] = gg[vsort[i]][0];
		}
	}

	for (int i = 1; i <= N; i++){
		cout << ans[i] << endl;
	}

	return 0;
}

