  union_find(int size){//コンストラクタ,size個のノードを作成し、自分を親につける
    par.assign(size,0);
    rank.assign(size,0);
    //for(int i = 0;i < size;++i) par[i]=i;
  }
  void ad(ll a,ll b){//a→bに辺を貼る
    if(rank[a] + 1>rank[b]){
      rank[b] = rank[a]+1;
      par[b] = a;
    }
  }
};
