int parent[maxN], L[maxN], R[maxN], child[maxN], D[maxN];
int cost[maxM];
long long res = 0;

void DFS_tree(int u) {
    L[u] = ++order;
    child[u] = 1;
    for (i2 x : adj[u]) {
        int id = x.second;
        int v = x.first;
        if (v == parent[u]) continue;
        parent[v] = u;
        D[v] = D[u] + cost[id];
        DFS_tree(v);
        child[u] += child[v];
        res += 1LL * cost[id] * child[v] * (n - child[v]);
        //cout << child[v] << " " << v << " ";
    }
    R[u] = order;
}

void NTTREE() { /// https://vn.spoj.com/problems/NTTREE/
    cin >> n;
    for (int i = 1; i < n; i++) {
        int u, v; cin >> u >> v >> cost[i];
        u++; v++;
        adj[u].push_back({v, i});
        adj[v].push_back({u, i});
    }
    DFS_tree(1);
    cout << res;
}

