void dfs(ll x, ll d) {
	for (int i = 0; i < chil[x].size(); ++i)
	{
		ll c = chil[x][i];
		if (depth[c] < d+1)
		{
			depth[c] = d+1;
			parent[c] = x;
			dfs(c, d+1);
		}
	}
	return;
}

int main() {
	cin >> n >> m;
	for (int i = 0; i < n+m-1; ++i)
	{
		ll a, b;
