		chil[a-1].push_back(b-1);
		ra[b-1] += 1;
	}
	ll par;
	for (int i = 0; i < n; ++i)
	{
		if (ra[i] == 0)
		{
			par = i;
			break;
		}
	}
	parent[par] = -1;
	dfs(par, 0);
	for (int i = 0; i < n; ++i)
	{
		cout << parent[i]+1 << "\n";
	}
	return 0;
}

