	for (int i = 0; i < v[x].size(); ++i)deep[x] = max(deep[x], deep[v[x][i]] + 1);
	return deep[x]; 
}
void dfs2(int x, int p)
{
	if (par[x] != -1)return ;
	else par[x] = p;
	vector <pair<int,int> > c;
	for (int i = 0; i < v[x].size(); ++i){
		c.push_back({deep[v[x][i]], v[x][i]});
	}
	sort(c.begin(), c.end());
	reverse(c.begin(), c.end());
	for (int i = 0; i < c.size(); ++i)dfs2(c[i].second, x);
}
