class Edge{
public:
	ll first,second;
	bool valid{true};
	Edge()=default;
	Edge(ll a,ll b):first(a),second(b){}
};

class ConnectNodeInfo{
	vector<vector<Edge>> graph;
public:
	ConnectNodeInfo(int node_num){
		graph.resize(node_num);
	}
	void AddNonDirectionalConnection(ll u,ll v,ll w){
		graph[u].emplace_back(v,w);
		graph[v].emplace_back(u,w);
	}
	void AddDirectionalConnection(ll u,ll v,ll w){
		graph[u].emplace_back(v,w);
	}
	vector<Edge>& operator[](ll index){
		return graph[index];
	}
	size_t size(){return graph.size();}
	size_t valid_size(ll index){
		size_t sum=0;
		for(auto& x:graph[index]){
			if(x.valid) sum++;
		}
		return sum;
	}
	size_t valid_index(ll index){
		size_t sum=0;
		for(auto& x:graph[index]){
			if(x.valid){
				sum=x.first;
				break;
			}
		}
		return sum;
	}
};

class Node{
public:
	ll parent{-1},depth{0};
};

void dfs(ConnectNodeInfo& connection,ll child,ll parent,ll dep,vector<Node>& node){
	if(node[child].depth<dep){
		node[child].parent = parent;
		node[child].depth = dep;
	}

	for(int i = 0;i < connection[child].size();i++){
		if(connection[child][i].first != parent){
			dfs(connection,connection[child][i].first,child,dep+1,node);
		}
	}
};

