  int src, dst, wei;
  Edge(int s = 0, int d = 0, int w = 0) : src(s), dst(d), wei(w) {}
};
using Graph = vector<vector<Edge>>;

vector<int> Toposort(Graph &g) {
  int v = g.size(), k = 0;
  vector<int> res(v, -1), in(v);
  for (int i = 0; i < v; i++) {
    for (int j = 0; j < g[i].size(); j++) {
      Edge &x = g[i][j];
      in[x.dst]++;
    }
  }
  queue<int> q;
  for (int i = 0; i < v; i++) {
    if ((in[i] == 0)) {
      q.push(i);
      res[i] = 0;
    }
  }
  while (!q.empty()) {
    int u = q.front();
    q.pop();
    for (int i = 0; i < g[u].size(); i++) {
      Edge &e = g[u][i];
      if (in[e.dst] == 1) {
        res[e.dst] = u + 1;
        q.push(e.dst);
      }
      in[e.dst]--;
    }
  }
  return res;
}

