int par[100000];
int p_rank[100000];

void init(int n) {
    for (int i = 0; i < n; ++i) {
        par[i] = i;
        p_rank[i] = 0;
    }
}

int find_root(int x) {
    if (par[x] == x) {
        return x;
    } else {
        // update parent
        return par[x] = find_root(par[x]);
    }
}

void unite(int x, int y) {
    int x_root = find_root(x);
    int y_root = find_root(y);
    if (x_root == y_root) return;

    if (p_rank[x_root] < p_rank[y_root]) {
        par[x_root] = y_root;
    } else {
        par[y_root] = x_root;
        if (p_rank[x_root] == p_rank[y_root]) p_rank[x_root]++;
    }
}

bool be_same(int x, int y) {
    return find_root(x) == find_root(y);
}

