   }
   while(!pq.empty())
   {
      int u=pq.top();
      pq.pop();
      topo.push_back(u);
      for(auto &v:g[u])
      {
         indeg[v]--;
         if(!indeg[v])
            pq.push(v);
      }
   }

   int curr = 0;
   idx.resize(n+1);
   for(auto it: topo)
      idx[it] = curr++;

   if(sz(topo)<n)
      return 0;
   return 1;
}

