void bfs(int from) {
    if(inv[from].empty()) {
        Rank[from] = 1;
        parent[from] = 0;
        return;
    }
    if(parent[from] != 0) return;
    int par = 0;
    int now = 0;
    for(int i = 0; i < inv[from].size(); i++) {
        int from_from = inv[from][i];
        bfs(from_from);
        if(now < Rank[from_from]) {
            now = Rank[from_from];
            par = from_from;
        }
    }
    parent[from] = par;
    Rank[from] = now + 1;
}

