using namespace std;

vector<vector<long> > tt;
vector<long> depth;
vector<long> par;
vector<long> child;

void dfs( long curr )
{
    long nSize=(long)tt[curr].size();
    long i;
    for(i=0; i<nSize; i++) {
        long next = tt[curr][i];
        if(depth[next] < 0) {
            depth[next] = depth[curr] + 1;
            par[next]=curr;
        }
        else if(depth[next]==depth[curr]+1) {
            ;  // do nothing
        }
        else if(depth[next]<depth[curr]+1) {
            depth[next]=depth[curr]+1;
            par[next]=curr;
        }
        else {
            ;  // do nothing
        }

        child[next]--;
        if(child[next]==0) {
            dfs( next );
        }
    }

    return;
}


int main(int argc, char* argv[])
{
    long n, m;
    scanf("%ld%ld", &n, &m);

    tt.resize(n);
    child.resize(n);

    long i;
    for(i=0; i<n+m-1; i++) {
        long a, b;
        scanf("%ld%ld", &a, &b);
        tt[a-1].push_back(b-1);
        child[b-1]++;
    }

    long root=-1;
    for(i=0; i<n; i++) {
        if(child[i]==0) {
            root=i; break;
        }
    }

    depth.resize(n);
    for(i=0; i<n; i++) {
        depth[i]=-1;
    }
    depth[root]=0;

    par.resize(n);
    for(i=0; i<n; i++) {
        par[i]=-1;
    }

    dfs( root );

    for(i=0; i<n; i++) {
        printf("%ld\n", par[i]+1);
    }

    return 0;
}

