typedef pair<int, int> pii;
const int INF = 1l << 60;
#define u_b upper_bound
#define l_b lower_bound

int N, M;
vector<int> G[100100];
vector<int> G2[100100];
bool isNotRoot[100100];
int par[100100];
int dis[100100];

void bfs(int root) {
    rep(i, 100100) {
        dis[i] = INF;
    }
    par[root] = 0;
    queue<pii> que;
    que.push(pii(root, 0));
    while (!que.empty()) {
        pii p2 = que.front();
        que.pop();
        int p = p2.first;
        int cost = p2.second;
        if (cost >= dis[p])continue;
        dis[p] = cost;
        for (auto q:G[p]) {
            if (dis[q] > cost + 1) {
                que.push(pii(q, cost + 1));
            }
        }
    }
}

bool update_sub(int i) {
    int maxval = 0;
    for (auto p:G2[i]) {
        maxval = max(maxval, dis[p]);
    }
    if (dis[i] != maxval + 1) {
        dis[i] = maxval + 1;
        return true;
    }
    return false;
}

void update() {
    bool updated = false;
    set<int> se, se2;
    for (int i = 1; i <= N; ++i) {
        if (update_sub(i)) {
            updated = true;
            se.insert(i);
        }
    }
    if (!updated)return;
    while (true) {
        for (int i :se) {
            if (update_sub(i)) {
                updated = true;
                se2.insert(i);
            }
        }
        if (!updated) {
            return;
        }
        updated = false;
        se = se2;
        se2.clear();
    }
}

int ansi(int i) {
    int maxidx = -1;
    int maxval = -1;
    for (auto p:G2[i]) {
        if (dis[p] > maxval) {
            maxval = dis[p];
            maxidx = p;
        }
    }
    if (maxidx == -1)return 0;
    return maxidx;
}

signed main() {
    cin >> N >> M;
    rep(i, N - 1 + M) {
        int a, b;
        cin >> a >> b;
        G[a].push_back(b);
        G2[b].push_back(a);
        isNotRoot[b] = true;
    }
    int root = -1;
    for (int i = 1; i <= N; ++i) {
        if (!isNotRoot[i])root = i;
    }
    bfs(root);

    update();

    for (int i = 1; i <= N; ++i) {
        cout << ansi(i) << endl;
    }
    return 0;
}

