using namespace std;

using ll = long long;

int n, m, root;
vector<vector<int>> adj;
vector<int> par, in_deg;

int main() {
    cin.tie(0); ios::sync_with_stdio(false);

    cin >> n >> m;
    adj.resize(n);
    par.resize(n, -1);
    in_deg.resize(n);

    for (int i = 0; i < n + m - 1; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u - 1].push_back(v - 1);
        ++in_deg[v - 1];
    }

    for (int v = 0; v < n; ++v) {
        if (in_deg[v] == 0) {
            root = v;
            break;
        }
    }

    queue<pair<int, int>> que;
    que.push(make_pair(-1, root));
    while (!que.empty()) {
        const auto cur = que.front(); que.pop();
        const int v = cur.second, p = cur.first;
        if (v != root) {
            par[v] = p;
            --in_deg[v];
        }
        if (in_deg[v] == 0) {
            for (auto u : adj[v])
                que.push(make_pair(v, u));
        }
    }

    for (int v = 0; v < n; ++v)
        cout << (par[v] == -1 ? 0 : par[v] + 1) << '\n';

    return 0;
}

