void make_linklist(V<ll> linklist[100003], ll &root, ll refcounts[100003],
                   const V<t2> &ablist)
{
    memset(refcounts, 0, sizeof(ll) * 100003);

    for (auto ab : ablist) {
        ll a = get<0>(ab);
        ll b = get<1>(ab);
        linklist[a].pb(b);
        refcounts[b]++;
    }

    srep (i, 1, 100003) {
        if (refcounts[i] == 0LL) {
            root = i;
            break;
        }
    }

    debug_printf("---- root=%lld\n", root);
}

int _main()
{
    ll n; llin(n);
    ll m; llin(m);
    V<t2> ablist; llinl2(ablist, n-1+m);

    static V<ll> linklist[100003];
    ll root;
    static ll refcounts[100003];
    make_linklist(linklist, root, refcounts, ablist);

    static ll anslist[100003];
    priority_queue_incr<t2> q;

    q.push(t2(0LL, root));
    anslist[root] = 0LL;

    while (!q.empty()) {
        auto dv = q.top(); q.pop();
        ll d = get<0>(dv);
        ll v = get<1>(dv);
        for (auto nv : linklist[v]) {
            if ((--refcounts[nv]) <= 0LL) {
                q.push(t2(d+1LL, nv));
                anslist[nv] = v;
            }
        }
    }

    srep (i, 1, n+1) cout << anslist[i] << endl;

    return 0;
}

