void dfs(int now, int par) {
  visited[now] = true;
  if (par != -1 && ans[now] == -1) {
    ans[now] = par + 1;
  }
  for (auto nx : g[now]) {
    if (nx == par || visited[nx]) continue;
    if (indeg[nx] == 1) {
      for (auto nx2 : g[now]) {
        indeg[nx2]--;
      }
      dfs(nx, now);
      for (auto nx2 : g[now]) {
        indeg[nx2]++;
      }
    }
  }
  return;
}

