    auto sorted = topologicalSort(G);
    vector<int> res(n, 0);
    for (int x : sorted) {
        for (int nx : G.at(x)) {
            res.at(nx) = x + 1;
        }
    }

    for (int x : res) {
        cout << x << '\n';
    }
}

