        fill_n(dist.begin(), V, INF);
        fill_n(used.begin(), V, false);
        while (!Q.empty()) {
            T d;
            ll t, p;
            tie(d, t, p) = Q.top(), Q.pop();
            res[t] = p;
            if (used[t]) continue;
            used[t] = true, dist[t] = d;
            for (ll e : G[t]) {
                Q.push(P(d + 1, e, t));
            }
        }
    }
};

