VI G[MAX], revG[MAX];
set<int> G_se[MAX], revG_se[MAX];
int ans[MAX];


int main(void) {
    cin >> N >> M;
    topological_sort ts(N);
    REP(i, N - 1 + M) {
        int a, b;
        cin >> a >> b;
        a--;b--;
        G[a].EB(b);
        G_se[a].emplace(b);
        revG[b].EB(a);
        revG_se[b].emplace(a);
        ts.add_edge(a, b);
    }
    memset(ans, -1, sizeof(ans));
    auto nodes = ts.bfs_tsort();
    int root = -1;
    set<int> not_used;
    FORE(e, nodes) {
        if (root == -1) {
            root = e;
            ans[e] = 0;
        } else {
            FORE(nxt, revG[e]) {
                if (not_used.count(nxt)) {
                    ans[e] = nxt + 1;
                    break;
                }
            }
        }
        not_used.emplace(e);
    }
    REP(i, N) {
        cout << ans[i] << endl;
    }
}

