int N, M;
DGraph graph;

vector<pair<int, int>> tourist; // <rem_indeg, max_distance>
int root = 0;


void dfs_findroot(int idx) {
    for (int fr : graph.vertex_from[idx]) {
        dfs_findroot(fr);
        return;
    }
    root = idx;
}

void dfs_tour(int idx, int dist = 0) {
    chmax(tourist[idx].second, dist);
    if (tourist[idx].first > 0) return;
    dist = tourist[idx].second;
    for (int to : graph.vertex_to[idx]) {
        tourist[to].first--;
        dfs_tour(to, dist + 1);
    }
}

int main() {

    scanner >> N >> M;
    M = N - 1 + M;
    graph.resize(N);
    tourist.resize(N);

    repeat(i, M) {
        int a, b;
        scanner >> a >> b; --a; --b;
        graph.connect(a, b);
    }
    repeat(i, N) {
        tourist[i].first = graph.vertex_from[i].size();
    }

    dfs_findroot(rand(0, N - 1));
    dfs_tour(root);

    repeat(i, N) {
        if (i == root) {
            printer << 0 << '\n';
            continue;
        }
        int d = tourist[i].second;
        for (int fr : graph.vertex_from[i]) {
            if (tourist[fr].second + 1 == d) {
                printer << (fr + 1) << '\n';
            }
        }
    }


    return 0;
}

