using namespace std;

struct Node {
    int index, depth, in;
    Node(int index, int depth, int in) : index(index), depth(depth), in(in) {}
};

bool operator<(const Node& x, const Node& y) {
    if (x.depth != y.depth) {
        return x.depth < y.depth;
    }
    return x.in > y.in;
}

int main() {
    int n, m;
    cin >> n >> m;
    int nm = n + m;
    vector<int> es[n + 1];
    int depth[n + 1], ins[n + 1], parent[n + 1];
    fill(depth + 1, depth+ n + 1, 0);
    fill(ins + 1, ins + n + 1, 0);
    fill(parent + 1, parent + n + 1, 0);

    for (int i = 1; i < nm; i++) {
        int a, b;
        cin >> a >> b;
        es[a].push_back(b);
        ins[b]++;
    }

    int root = min_element(ins + 1, ins + n + 1) - ins;

    priority_queue<Node> pque;
    pque.push(Node (root, 0, 0));
    while (!pque.empty()) {
        Node top = pque.top();
        pque.pop();
        for (int i: es[top.index]) {
            if (depth[i] <= top.depth) {
                depth[i] = top.depth + 1;
                parent[i] = top.index;
                pque.push(Node (i, depth[i], ins[i]));
            }
        }
    }
    for (int i = 1; i <= n; i++) {
        cout << parent[i] << endl;
    }
    return 0;
}

