    if(ins[i].size()==0){
      notins.insert(i);
    }
  }
  //notins構築完了
  vector<set<int>> nexts(n);//各頂点に対する辺情報
  for(auto i:edges){
    nexts[i.first].insert(i.second);
  }
  //辺入力完了
