  int root = -1;
  rep(i,0,N - 1) {
    if(res[i] == 0) {
      root = i;
      break;
    }
  }
  rep(i,0,N - 1) ans[i] = -1;
  dfs(root);
  rep(i,0,N - 1) {
    cout << ans[i] + 1 << endl;
  }
}

