struct Data  {
  int cur, dep;
  bool operator < ( const Data &data ) const {
    if( dep != data.dep ) return dep < data.dep;
    return cur < data.cur;
  }
};

const bool debug = 0;

void compute() {
  rep(i,V) depth[i] = -INT_MAX;
  memset(deg,0,sizeof deg);
  priority_queue<Data> Q;
  rep(i,V) {
    if( (int)G[i].size() == 0 ) {
      depth[i] = 0;
      Q.push((Data){i,0});
    }
  }
  while( !Q.empty() ) {
    Data d = Q.top(); Q.pop();
    rep(i,(int)rG[d.cur].size()) {
      int nex = rG[d.cur][i];
      if( depth[nex] < d.dep + 1 ) {
