VI topological_sort(VV& G){
    ll N = G.size();
    debug(N);
    debug(G);

    // 入次数
    VI IN(N, 0);
    rep(i, N){
        for(ll to : G[i]){
            IN[to]++;
        }
    }

    stack<ll> st; // 入次数0のものを入れる
    rep(i, N){
        if(IN[i]==0) st.push(i);
    }

    VI ret;
    while(!st.empty()){
        ll i = st.top();
        st.pop();
        ret.push_back(i);
        for(ll to : G[i]){
            IN[to]--;
            if(IN[to]==0){
                st.push(to);
            }
        }
    }

    // 成功したか確認
    for(ll in : IN){
        if(in!=0){
            // 失敗（DAGじゃなかった）
            VI empty_vector;
            debug("not DAG");
            return empty_vector;
        }
    }
    // 正常の戻り値
    return ret;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    // input
    ll N, M;
    cin >> N >> M;

    VV G(N);
    VV IN(N); // 親たち

    rep(i, N+M-1){
      ll a, b;
      cin >> a >> b;
      a--; b--;
      debug(a, b);
      G[a].push_back(b);
      // a -> b
      IN[b].push_back(a);
    }

    VI res = topological_sort(G);
    VI I(N); // 逆引き
    rep(i, N){
      ll a = res[i];
      I[a] = i;
    }
    debug(res);
    debug(I);

    rep(i, N){
      ll new_i = I[i];
      if(new_i==0){
        p(0);
        continue;
      }
      // そいつに刺さってくるやつら
      ll ma = 0;
      for(ll par : IN[i]){
        ll new_p = I[par];
        chmax(ma, new_p);
      }
      // 元の世界に戻す
      ll ans = res[ma];
      p(ans+1);
    }

    return 0;
}

