struct topological_sort{
    vector<vector<int>> G;
    vector<int> indegree;
    int V;

    topological_sort(int V) : V(V) {G.resize(V); indegree.resize(V);}
    void add_edge(int a, int b) {
        G[a].push_back(b);
        indegree[b]++;
    }
    vector<int> sort() {
        queue<int> q;
        vector<int> sorted;
        for (int i = 0; i < V; i++) if (indegree[i] == 0) q.push(i);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (int i = 0; i < G[v].size(); i++) {
                int u = G[v][i];
                indegree[u]--;
                if (indegree[u] == 0) q.push(u);
            }
            sorted.push_back(v);
        }
        return sorted;
    }
};

int main() {
    int n, m; cin >> n >> m;
    topological_sort ts(n);
    vvint dest(n);
    rep(i,n-1+m) {
        int a, b; cin >> a >> b;
        a--; b--;
        ts.add_edge(a,b);
        dest[b].push_back(a);
    }
    vint res = ts.sort();
    map<int,int> mp;
    rep(i,n) mp[res[i]] = i;
    rep(i,n) {
        if (dest[i].empty()) cout << 0 << endl;
        else {
            set<int> st;
            rep(j,dest[i].size()) st.insert(mp[dest[i][j]]);
            cout << res[*st.rbegin()] + 1 << endl;
        }
    }
}

