void bfs( long root )
{
    queue<long> que;
    que.push( root );

    while( !que.empty() ) {
        long curr = que.front();
        que.pop();

        long nSize=(long)tt[curr].size();
        long i;
        for(i=0; i<nSize; i++) {
            long next = tt[curr][i];
            par[next]=curr;

            child[next]--;
            if(child[next]==0) {
                que.push(next);
            }
        }
    }

    return;
}


int main(int argc, char* argv[])
{
    long n, m;
    scanf("%ld%ld", &n, &m);

    tt.resize(n);
    child.resize(n);

    long i;
    for(i=0; i<n+m-1; i++) {
        long a, b;
        scanf("%ld%ld", &a, &b);
        tt[a-1].push_back(b-1);
        child[b-1]++;
    }

    long root=-1;
    for(i=0; i<n; i++) {
        if(child[i]==0) {
            root=i; break;
        }
    }

    par.resize(n);
    for(i=0; i<n; i++) {
        par[i]=-1;
    }

    bfs( root );

    for(i=0; i<n; i++) {
        printf("%ld\n", par[i]+1);
    }

    return 0;
}

