bool used[100010];

void dfs2(int v,int depth) {
  used[v] = true;

  rep(i,(int)G[v].size() ){
    int vnext = G[v][i];
    if(used[vnext]) {
      if (dep[vnext] < depth) {
        par[vnext] = v;
        dep[vnext] = depth;
      }
    }else {
      par[vnext] = v;
      dep[vnext] = depth;
      dfs2(vnext,depth + 1);
    }
  }
}


