class TopologicalSort{
public:
	int n;
	vector<int> ans, deg;
	vector<vector<int> > G;
	void init(int N){
		n = N;
		deg.resize(n);G.resize(n);
	}
	void add_edge(int from, int to){	//DAG
		G[from].pb(to);deg[to]++;
	}
	void sort(){
		stack<int> st;
		rep(i,n)if(deg[i] == 0)st.push(i);
		while(!st.empty()){
			int v = st.top();st.pop();ans.pb(v);
			rep(i,G[v].size())if(--deg[G[v][i]] == 0)st.push(G[v][i]);
		}
	}
};

