const int MAXN = 1e5 + 7;
int N, M;
vector<int> G[MAXN], G2[MAXN];
int64_t W[MAXN];
int par[MAXN];
bool notRoot[MAXN], vis[MAXN];

void dfs(int u)
{
	W[u] = 1;
	for (int v : G[u]) {
		if (!vis[v]) {
			vis[v] = 1;
			dfs(v);
		}
		W[u] += W[v];
	}
	// cout << u << ": " << W[u] << endl;
}

int32_t main()
{
	ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);

	cin >> N >> M;
	M += N - 1;
	FOR(i, 0, M - 1) {
		int u, v;
		cin >> u >> v;
		G[u].push_back(v);
		G2[v].push_back(u);
		notRoot[v] = 1;
	}

	int root = 1;
	while (notRoot[root]) ++root;
	assert(G2[root].empty());
	assert(root <= N);

	vis[root] = 1;
	dfs(root);

	FOR(u, 1, N) {
		cout << (u == root ? 0 : *min_element(ALL(G2[u]), [&](int i, int j) { return W[i] < W[j]; })) << '\n';
	}

	return 0;
}

