vector<int> topologicalSort(vector<vector<int>> &G) {
    int n = G.size();
    vector<int> indegree(n, 0);
    REP(i, 0, n) {
        for (auto g : G[i]) {
            indegree[g]++;
        }
    }

    stack<int> st;
    REP(i, 0, n) if (indegree[i] == 0) st.push(i);

    vector<int> sorted;
    while (!st.empty()) {
        auto v = st.top(); st.pop();
        sorted.push_back(v);
        for (auto g : G[v]) {
            indegree[g]--;
            if (indegree[g] == 0) st.push(g);
        }
    }
    return sorted;
}

