    }

    auto sorted = topologicalSort(G);
    vector<int> idx(N, 0);
    REP(i, 0, sorted.size()) {
        idx[sorted[i]] = i;
    }

    vector<int> ans(N, -1);
    REP(i, 0, N) {
        for (auto g : G[i]) {
