		void bfsSub(int start, vector<bool>& check, int MAX_DEPTH) {

			queue<pair<pair<int, int>, int>> target; // id, from, dist
			target.push(pair<pair<int, int>, int>(pair<int, int>(start, -1), 0));
			while (!target.empty()) {
