{
	int n=read(), m=read();
	for (int i=1; i<=n+m-1; i++) 
	{
		int u=read(), v=read();
		add(v, u); deg[u]++;
	}
	for (int i=1; i<=n; i++) if (!deg[i]) q.push(i);
	while (!q.empty())
	{
		int u=q.front(); q.pop(); rnk[u]=++tot;
		for (int i=head[u]; i; i=edge[i].nxt)
		{
			int v=edge[i].to;
			if (!(--deg[v])) q.push(v);
		}
	}
	for (int u=1; u<=n; u++) 
	{
		int ans=0, mn=N;
		for (int i=head[u]; i; i=edge[i].nxt)
		{
