// トポロジカルソートする
void rec(int v, const Graph &G, vector<bool> &seen, vector<int> &order) {
    seen[v] = true;
    for (auto next : G[v]) {
        if (seen[next]) continue; // 既に訪問済みなら探索しない
        rec(next, G, seen, order);
    }
    order.push_back(v);
}

void dfs(const Graph& graph, int v, int p, int d) {
	if (parent[v] == -1){	//初訪問のとき
		parent[v] = p;
		depth[v] = d;
		for (auto nv : graph[v]){
			if (nv == p) continue;
			dfs(graph, nv, v, d + 1);
		}
	} else {	//初訪問でないとき
		int orgP = parent[v];
		int orgD = depth[v];
		bool cond1 = (orgP != p);
		bool cond2 = (orgD < d);

		if (cond1){
			if (cond2){
				parent[v] = p;
				depth[v] = d;
				// for (auto nv : graph[v]){
				// 	if (nv == p) continue;
				// 	dfs(graph, nv, v, d + 1);
				// }
			}
		} else {
