struct Graph{
    struct Node{
        unordered_set<int> inEdges, outEdges;
        vector<pair<int, int>> cands;
        int maxDepth = -1;
        int from = 0;
    };
    vector<Node> nodes;
    Graph(int num): nodes(num){ }
    int id(Node* n){ return n - &nodes[0]; }
    int id(Node& n){ return &n - &nodes[0]; }
    void print(){ for(auto& node : nodes){ prints(id(node), node.outEdges); } }
    void add1Edge(int from, int dest){
        nodes[from].outEdges.insert(dest);
        nodes[dest].inEdges.insert(from);
    }
    void dfs(int idx, int from = -1, int depth = 0){
        nodes[idx].cands.emplace_back(depth, from);
        printde(idx, nodes[idx].cands.size(), nodes[idx].inEdges.size());
        if(depth && nodes[idx].cands.size() != nodes[idx].inEdges.size()){ return; }
        sort(nodes[idx].cands.rbegin(), nodes[idx].cands.rend());
        from = nodes[idx].cands[0].second;
        depth = nodes[idx].cands[0].first;
        printde(idx, from, depth);
        // bool first = nodes[idx].maxDepth == -1;
        // if(nodes[idx].maxDepth >= depth){
        //     return;
        // }
        nodes[idx].from = from;
        nodes[idx].maxDepth = depth;
        // if(!first){ return; }
        for(int didx : nodes[idx].outEdges){
            dfs(didx, idx, depth + 1);
        }
    }
};

