const ll INF = 1000000;


ll dijkstra(const vector<vector<ll>>& G, ll start, ll end, ll num_node)
{
	vector<ll> dist;

	dist = vector<ll>(num_node, INF);
	dist[start] = 0;

	priority_queue<pair<ll, ll>, vector<pair<ll, ll>>, greater<pair<ll, ll>>> que;
	que.push(make_pair(0, start));

	while (!que.empty()) {
		pair<ll, ll> p = que.top();
		que.pop();
		ll v = p.second;
		if (dist[v] < p.first)
		{
			continue;
		}
		for (int i = 0; i < G[v].size(); i++)
		{
			ll e = G[v][i];
			if (dist[e] > dist[v] + 1)
			{
				dist[e] = dist[v] + 1;
				if (e == end)
				{
					goto bbb;
				}

				que.push(make_pair(dist[e], e));
			}
		}
	}
	bbb:
	return dist[end];
}

