	a %= MOD;
	a *= minv(b);
	return a%MOD;
}

class BIT {
public:
	int n;
	vector<ll> bit;
	ll sum(int i) {
		int s = 0;
		while (i > 0) {
			s += bit[i];
			i -= i&-i;
		}
		return s;
	}
	void add(int i, int x) {
		while (i <= n) {
			bit[i] += x;
			i += i&-i;
		}
	}
	BIT(int argn, vector<int> v) {
		n = argn;
		bit.push_back(0);
		ll partsum = 0;
		REP(i, n) {
			partsum += v[i];
			int k = i + 1;
			ll tosub = 0;
			for (int j = 1; j < k; j *= 2) {
				if (k&j != 0) {
					tosub = sum(k - j);
					break;
				}
			}
			bit.push_back(partsum - tosub);
		}
	}
};
struct UnionFind {
	vector<int> data;
	UnionFind(int size) : data(size, -1) { }
	bool unite(int x, int y) {
		x = root(x); y = root(y);
		if (x != y) {
			if (data[y] < data[x]) swap(x, y);
			data[x] += data[y]; data[y] = x;
		}
		return x != y;
	}
	bool same(int x, int y) {
		return root(x) == root(y);
	}
	int root(int x) {
		return data[x] < 0 ? x : data[x] = root(data[x]);
	}
	int size(int x) {
		return -data[root(x)];
	}
};

