// Kahn (1962) のアルゴリズムによるトポソ DAGでないものを入れると鼻から悪魔が出る可能性がある
vector<ll> toposo(const vector<vector<ll>> &g) {
    ll n = g.size();
    vector<ll> r; r.reserve(n);
    vector<ll> indeg(n, 0);
    for (ll i = 0; i < n; i++) {
        for (const ll &j : g[i]) {
            ++indeg[j];
        }
    }
    deque<ll> zerodeg;
    for (ll i = 0; i < n; i++) {
        if (!indeg[i]) {
            zerodeg.push_back(i);
        }
    }
    while (zerodeg.size()) {
        ll i = zerodeg.front(); zerodeg.pop_front();
        r.push_back(i);
        for (const ll &j : g[i]) {
            if (--indeg[j] == 0) {
                zerodeg.push_back(j);
            }
        }
    }
    return r;
}

