class Xorshift
{
private:
    uint32_t x, y, z, w;
public:
    Xorshift(uint32_t seed=88675123, int32_t loop=50){
        x = 123456789;
        y = 362436069;
        z = 521288629;
        w = seed;
        while(--loop >= 0){
            (*this)();
        }
    }
    uint32_t operator()(){
        uint32_t t=(x^(x<<11));
        x=y; y=z; z=w;
        return w=(w^(w>>19))^(t^(t>>8));
    }
    uint32_t operator()(uint32_t size){
        return (*this)() % size;
    }
    uint64_t get64(){
        uint64_t a = (*this)();
        uint64_t b = (*this)();
        return (a << 32) | b;
    }
    uint64_t get64(uint64_t size){
        return get64() % size;
    }
    template <class T>
    void shuffle(vector<T>& v){
        uint32_t n = v.size();
        for(uint32_t i=0; i<n-1; ++i){
            uint32_t j = (*this)(n-i) + i;
            swap(v[i], v[j]);
        }
    }
};
Xorshift xorshift;

vector<vector<int> > edges;
vector<int> parent, maxDepth;

bool solve(int curr, int depth)
{
    if(depth <= maxDepth[curr])
        return false;
    maxDepth[curr] = depth;

    vector<int> v = edges[curr];
    if(!v.empty()){
        xorshift.shuffle(v);
        for(int next : v){
            if(solve(next, depth+1))
                parent[next] = curr;
        }
    }
    return true;
}

int main()
{
    int n, m;
    cin >> n >> m;
    edges.assign(n, vector<int>());
    vector<int> cnt(n, 0);
    for(int i=0; i<n+m-1; ++i){
        int a, b;
        cin >> a >> b;
        -- a;
        -- b;
        edges[a].push_back(b);
        ++ cnt[b];
    }

    int root = find(cnt.begin(), cnt.end(), 0) - cnt.begin();
    parent.assign(n, -1);
    maxDepth.assign(n, -1);
    solve(root, 0);
    for(int i=0; i<n; ++i)
        cout << (parent[i] + 1) << endl;

    return 0;
}

