using namespace std;

void visit(const vector<vector<int>> &g, vector<int> &order, vector<int> &mark, int pos){
	for(auto& next : g[pos]){
		if(mark[next]) continue;
		visit(g, order, mark, next);
	}
	mark[pos] = 1;
	order.push_back(pos);
}

vector<int> topologicalSort(const vector<vector<int>> &g){
	vector<int> res;
	vector<int> mark(g.size(), 0);
	for(int i=0;i<g.size();i++){
		if(mark[i]) continue;
		visit(g, res, mark, i);
	}
	reverse(res.begin(), res.end());
	return res;
}

int main(){
    int N, M;
    while(cin >> N >> M){
        vector<vector<int>> g(N), h(N);
        for(int i=0;i<N+M-1;i++){
            int a, b; cin >> a >> b;
            --a; --b;
            g[a].push_back(b);
            h[b].push_back(a);
        }
        vector<int> order = topologicalSort(g);
        vector<int> rank(N);
        for(int i=0;i<order.size();i++){
            rank[order[i]] = i;
        }
        vector<int> res(N, -1);
        for(auto& t : order){
            res[t] = 0;
            int best = -1;
            for(auto dst : h[t]){
                if(best < rank[dst]){
                    res[t] = dst + 1;
                    best = rank[dst];
                }
            }
        }
        for(auto& t : res) cout << t << endl;
    }
}

