    a--,b--;
    G[a].push_back(b);
  }

  auto v = tsort(G);
  vector<int> dp(n,-1),pre(n,-1); //根からの距離,先祖
  for(int i = 0; i < n; i++){
    for(int j : G[v[i]]){
      if(dp[j] < dp[v[i]]+1)
      dp[j] = dp[v[i]]+1;
      pre[j] = v[i];
    }
  }

  for(int i = 0; i < n; i++){
    cout << pre[i]+1 << endl;
  }

  return 0;
}

