int N, M;
int root;
vector<vector<int> > G;

vector<int> dist, pre;
int rec(int v) {
    if (dist[v] != -1) return dist[v];
    int res = 0;
    for (auto nv : G[v]) {
        if (chmax(res, rec(nv) + 1)) {
            pre[v] = nv;
        }
    }

    //cout << v << ": " << res << ", " << pre[v] << endl;
    return dist[v] = res;
}

int main() {
    vector<int> deg;
    while (cin >> N >> M) {
        G.assign(N, vector<int>());
        deg.assign(N, 0);
        dist.assign(N, -1);
        pre.assign(N, -1);
        for (int i = 0; i < N + M - 1; ++i) {
            int a, b; cin >> a >> b; --a, --b;
            G[b].push_back(a);
            deg[b]++;
        }

        root = -1;
        for (int v = 0; v < N; ++v) {
            if (deg[v] == 0) root = v;
        }
        dist[root] = 0;
        for (int v = 0; v < N; ++v) {
            rec(v);
        }

        for (int v = 0; v < N; ++v) {
            cout << pre[v] + 1 << endl;
        }
    }
}

