typedef ll Node; // Node番号

class TopologicalSort {
public:
  void Init(ll size) {
    V = size;
    graph.resize(size);
    indegree.resize(size);
  }

  void AddEdge(Node from, Node to) {
    graph[from].push_back(Edge{to});
    indegree[to]++;
  }

  vector<Node> Sort() {
    stack<Node> st; //入次数が0の頂点の集合
    REP(i, V) {
      if (indegree[i] == 0) {
        st.push(i);
      }
    }
    vector<Node> ans;
    while (st.size()) {
      Node i = st.top();
      st.pop();
      ans.push_back(i);
      for (const auto &j : graph[i]) {
        indegree[j.to]--;
        if (indegree[j.to] == 0)
          st.push(j.to);
      }
    }
    return ans;
  }

private:
  ll V;
  struct Edge {
    Node to;
  };
  vector<vector<Edge>> graph;
  vector<ll> indegree;
};

map<ll, ll> node_to_order;

bool comp(const pair<ll, ll> &l, const pair<ll, ll> &r) {
  if (l.second < r.second) {
    return true;
  } else if (l.second > r.second) {
    return false;
  } else {
    return node_to_order[l.first] > node_to_order[r.first];
  }
}

void solve(long long N, long long M, std::vector<long long> A,
           std::vector<long long> B) {
  TopologicalSort t;
  t.Init(N);
  REP(i, A.size()) {
    t.AddEdge(A[i] - 1, B[i] - 1);
  }
  auto ans = t.Sort();
  for (int i : ans) {
    node_to_order[ans[i]] = i;
  }
  vector<pair<ll, ll>> C(A.size());
  REP(i, A.size()) {
    C[i].first = A[i] - 1;
    C[i].second = B[i] - 1;
  }
  sort(ALL(C), comp);
  vector<ll> parent(N, 0);
  ll prev = -1;
  REP(i, C.size()) {
    if (prev == C[i].second) {
      C[i].first = -1;
    } else {
      parent[C[i].second] = C[i].first + 1;
    }
    prev = C[i].second;
  }
  REP(i, N) { std::cout << parent[i] << std::endl; }
}

int main() {
  long long N;
  scanf("%lld", &N);
  long long M;
  scanf("%lld", &M);
  std::vector<long long> A(N - 1 + M);
  std::vector<long long> B(N - 1 + M);
  for (int i = 0; i < N - 1 + M; i++) {
    scanf("%lld", &A[i]);
    scanf("%lld", &B[i]);
  }
  solve(N, M, std::move(A), std::move(B));
  return 0;
}

