const LL mod = 1000000007ll;
const int mod_int = 1000000007;

LL N,M;
vector<vector<LL>> adj;
vector<vector<LL>> adj_back;

vector<LL> ans;

void solve(){
	LL start = 1;
	{
		vector<int> used(N+1,0);
		while(1){
			used[start] = 1;
			bool roop_flag = false;
			if(adj_back[start].size()==0) break;
			for(LL next:adj_back[start]){
				if(used[next]) continue;
				start = next;
				roop_flag = true;
			}
			if(!roop_flag) break;
		}
	}

	ans = vector<LL>(N+1,0);

	stack<LL> st;
	vector<int> used(N+1,0);
	used[start] = 1;
	st.push(start);
	while(!st.empty()){
		LL now = st.top();
		st.pop();
		for(LL next:adj[now]){
			if(used[next]) continue;
			used[next] = 1;
			st.push(next);
			ans[next] = now;
		}
	}
}

int main(){
    cin >> N >> M;
    adj = vector<vector<LL>>(N+1);
    adj_back = vector<vector<LL>>(N+1);
    for(int i=0;i<N+M-1;i++){
    	LL a,b;cin >> a >> b;
    	adj[a].push_back(b);
    	adj_back[b].push_back(a);
    }

    solve();

    for(int i=1;i<=N;i++)cout << ans[i] << endl;
    return 0;
}

