int main()
{
    int n, m;
    cin >> n >> m;
    VEC( int, n, pa, -1 );
    vector< vector<int> > edge(n);

    VEC( int, n, bb, 0 );
    REP( i, n - 1 + m )
    {
        int a, b;
        cin >> a >> b;
        edge[a-1].push_back( b-1 );
        bb[b-1]++;
    }

    stack<int> st;
    REP( i, n )
    {
        if( bb[i] > 0 ) continue;
        st.push( i );
        break;
    }

    vector<int> top;
    while( !st.empty() )
    {
        int i = st.top(); st.pop();
        top.push_back(i);
        for( const auto& v : edge[i] )
        {
            if( --bb[v] == 0 ) st.push( v );
        }
    }

    REP(i,n)
    {
        int t = top[i];
        if( i == 0 ) { pa[t] = 0; }
        for( const auto& v : edge[t] )
        {
            pa[v] = t;
        }
    }

    REP( i, n )
    {
        cout << pa[i]+ 1 << endl;
    }
    return 0;
}

