vector<int> rank;
void search(int root,int cur){
  for(int i = 0;i < child[root].size();i++){
    if(rank[child[root][i]] < cur+1){
      rank[child[root][i]] = cur+1;
      parent[child[root][i]] = root;
    }
    search(child[root][i],cur+1);
  }
}

