bool lessPair(const P& l, const P& r){return l.second < r.second;}
bool morePair(const P& l, const P& r){return l.second > r.second;}

vector<lint> TopSort(lint N, vector<P> edges) {
  vector<lint> in_degree(N);
  vector<vector<lint>> adj(N);
  vector<lint> res(N);

  REP(i, edges.size()) {
    auto edge = edges[i];
    in_degree[edge.second]++;

    adj[edge.first].push_back(edge.second);
  }
  queue<lint> Q;

  lint idx = 0;

  REP(i, N) {
    if(in_degree[i] == 0) {
      Q.push(i);
    }
  }


  while(!Q.empty()) {
    lint i = Q.front();
    Q.pop();
    res[i] = idx++;
    REP(j, adj[i].size()) {
      auto k = adj[i][j];
      in_degree[k]--;
      if(in_degree[k] == 0) {
        Q.push(k);
      }
    }
  }

  return res;
}

