        bool done = true;
        for (Edge edge : graph2[e.to]) {
          if (depth[edge.to] == -1 || depth[edge.to] >= depth[e.to]) done = false;
        }
        if (!done) continue;
        que.emplace(e.to);
        used[e.to] = true;
      }
    }
  }
  for (int i = 0; i < n; ++i) cout << p[i] + 1 << endl;
}

