template <typename T> struct DJK {
    ll V;
    using P = tuple<ll, ll, ll>;
    vector<vector<ll>> G;
    vector<T> dist;
    vector<bool> used;
    DJK(ll v) : V(v), G(v), dist(v), used(v) {}
    void set(ll a, ll b) { G[a].push_back(b); }
    void culc(ll s = 0) {
        priority_queue<P, vector<P>, greater<P>> Q;
        Q.push(P(0, s, 0));
        fill_n(dist.begin(), V, INF);
        fill_n(used.begin(), V, false);
        while (!Q.empty()) {
            T d;
            ll t, p;
            tie(d, t, p) = Q.top(), Q.pop();
            if (dist[t] == INF || dist[t] < d) res[t] = p;
            if (used[t]) continue;
            used[t] = true, dist[t] = d;
            for (ll e : G[t]) {
                Q.push(P(d + 1, e, t));
            }
        }
    }
};

