int B[MAX_MN];
bool is_root[MAX_MN];
bool is_unusedPath[MAX_MN];
int dist[MAX_MN];

vector<Pii> G[MAX_MN];

int main() {
  std::ios::sync_with_stdio(false);std::cin.tie(0);

  cin >> N >> M;
  rep(i, N+M-1) cin >> A[i] >> B[i];

  memset(is_root, true, sizeof(is_root));
  rep(i, N+M-1) {
      is_root[B[i]] = false;
  }

  int root = 0;
  for (int i = 1; i <= N; ++i) {
      if (is_root[i]) {
          root = i; break;
      }
  }

  rep(i, N+M-1) {
      G[A[i]].push_back(Pii(B[i], i));
  }


  priority_queue<Pii, vector<Pii>, greater<Pii> > que;
