  while (!que.empty()) {
      int u = que.top().sc; que.pop();
      for (int i = 0; i < G[u].size(); ++i) {
          int v = G[u][i].fi;
          if (dist[v] < dist[u]+1) {
              dist[v] = dist[u]+1;
              que.push(Pii(dist[v], v));
          }
      }
  }

  rep(i, N+M-1) {
