struct Graph {
    struct Vertex { int n, f; };
    struct Edge { int i, n; };
    Graph(int n, int m) : z(n), y(n), r(n), v(n, { -1, 0 }), e(m), n(n), m(0), l(0) {}
    void add_edge(int i, int j) {
        e[m] = { j, v[i].n };
        v[i].n = m;
        m++;
    }
    void dfs(int i) {
        v[i].f = 1;
        for (int j = v[i].n; j >= 0; j = e[j].n) {
            Edge& o = e[j];
            if (v[o.i].f) continue;
            dfs(o.i);
        }
        y[i] = l;
        z[l] = i;
        l++;
    }
    void solve(Graph f) {
        for (int i1 = 0; i1 < n; i1++) {
            int i = z[i1];
            int i0 = -1, y0 = n;
            for (int j = f.v[i].n; j >= 0; j = f.e[j].n) {
                Edge& o = f.e[j];
                if (y[o.i] < y0) {
                    y0 = y[o.i];
                    i0 = o.i;
                }
            }
            r[i] = i0;
        }
        for (int i = 0; i < n; i++) {
            cout << r[i] + 1 << '\n';
        }
        cout << flush;
    }
    int l;
    vector<int> z, y, r;
    vector<Vertex> v;
    vector<Edge> e;
    int n, m;
};

