    while (!sta.empty()) {
        int v, p; tie(v, p) = sta.top().first;
        int d = sta.top().second; sta.pop();
        for (auto u : G[v]) if (p != u) {
            if (depth[u] == -1) sta.emplace(make_pair(u, v), d+1);
            if (depth[u] <= d) { depth[u] = d + 1; par[u] = v; }
        }
    }

    for (auto ans : par) cout << ans+1 << endl;
    return 0;
}

