constexpr ll INF = 1e18;
constexpr ll MOD = 1e9 + 7;
constexpr double PI = 3.14159265358979323846;
constexpr int di[] = {0, 0, 1, -1};
constexpr int dj[] = {1, -1, 0, 0};

int r;
int rnk[112345];

//#####################
//Dijkstra
//#####################
struct edge
{
    int to, cost;
};

int dn;
vector<edge> g[112345];
int dis[112345];

void dijkstra(int s)
{
    priority_queue<P> que;
    fill(dis, dis + dn + 1, INF);
    dis[s] = 0;
    que.push(P(0, s));

    while (!que.empty())
    {
        P p = que.top();
        que.pop();
        int n_ = p.second;
        if (dis[n_] > p.first)
            continue;
        for (int i = 0; i < g[n_].size(); i++)
        {
            edge e = g[n_][i];
            if (dis[e.to] < dis[n_] + e.cost)
            {
                dis[e.to] = dis[n_] + e.cost;
                que.push(P(dis[e.to], e.to));
            }
        }
    }
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, m, a[112345], b[112345];

    int t[112345] = {0};

    cin >> n >> m;

    memset(rnk, -1, sizeof(rnk));

    REP(i, n - 1 + m)
    {
        cin >> a[i] >> b[i];

        t[b[i]]++;

        g[a[i]].push_back({b[i], 1});
    }

    REP(i, n)
    if (t[i + 1] == 0)
        r = i + 1;

    //dfs(r, 0);

    dn = n;

    dijkstra(r);

    int res[112345];

    REP(i, n - 1 + m)
    {
        if (dis[a[i]] - (dis[b[i]]) == -1)
            res[b[i]] = a[i];
    }

    for (int i = 1; i <= n; i++)
        cout << res[i] << endl;

    return 0;
}

