int main() {
    int n, m;
    in(n, m);

    vector<vector<int>> e(n);
    vector<int> in_cnt(n);

    for (int i = 0; i < n + m - 1; i++) {
        int a, b;
        in(a, b);

        e[a - 1].push_back(b - 1);
        in_cnt[b - 1]++;
    }

    using P = pair<int, int>;

    priority_queue<P, vector<P>, greater<P>> que;

    for (int i = 0; i < n; i++) {
        que.emplace(in_cnt[i], i);
    }

    vector<int> parent(n, -1);

    while(!que.empty()) {
        auto p = que.top();
        que.pop();

        if (p.first != in_cnt[p.second]) {
            continue;
        }

        for (int to : e[p.second]) {
            parent[to] = p.second;
            in_cnt[to]--;

            que.emplace(in_cnt[to], to);
        }
    }

    for (int i = 0; i < n; i++) {
        out(parent[i] + 1);
    }
}

