vi TopologicalSort(const vector<vi>& g) {
  const int v = g.size();
  vi indeg(v, 0);
  stack<int> st;

  for (auto& out_edges : g)
    for (auto& v : out_edges) indeg[v]++;

  rep(i, v) {
    if (indeg[i] == 0) st.push(i);
  }

  vi ans;
  while (st.size() > 0) {
    int u = st.top();
    st.pop();
    ans.emplace_back(u);
    for (auto& v : g[u]) {
      indeg[v]--;
      if (indeg[v] == 0) st.push(v);
    }
  }
  return ans;
}



