    u--;v--;
    G[u].push_back(v);
  }
  auto res = TopologicalSort(G);
  for(auto u:res){
    for(auto v: G[u]){
      maxs(depth[v],depth[u]+1);
    }
  }

  rep(u,n){
    for(auto v: G[u]){
      if(depth[u]+1 == depth[v]) ans[v] = u+1;
    }
  }
  rep(i,n){
    cout<<ans[i]<<endl;
  }
  return 0;
}

