const int MAX = 1e5+10;

int N, M, root;
vi childs[MAX];
vi parents[MAX];
bool isRoot[MAX];
int parent[MAX];
int R[MAX];

int dfs(int n) { // n番目のノードの深さを探索
    if (R[n] >= 0) return R[n];
    int resRank = -1, idx = -1;
    FORE (p, parents[n]) {
        int r = dfs(p);
        if (r > resRank) {
            resRank = r;
            idx = p;
        }
    }
    parent[n] = idx;
    R[n] = resRank+1;
    return resRank;
}

int main() {
    cin >> N >> M;
    REP (i, N) {
        isRoot[i] = true;
    }
    REP (i, N+M-1) {
        int a, b;
