        a--; b--;
        parent[i] = -2;
        R[i] = -1;
        childs[a].push_back(b);
        parents[b].push_back(a);
        isRoot[b] = false;
    }

    root = -1;
    REP (i, N) {
        if (isRoot[i]) {
            root = i;
            parent[i] = -1;
            R[i] = 0;
        } else {
            if (parents[i].size() == 1) {
                parent[i] = parents[i][0];
            }
        }
    }

    REP (i, N) dfs(i);

    REP (i, N) cout << parent[i]+1 << "\n";
    return 0;

}

