template<typename T>
vi topologicalSort (const WeightedGraph<T> &graph) {
    int sz = graph.size();
    vi ans;
    stack<int> st;
    vi h(sz);
    for(int i=0;i<sz;i++) {
        for(int j=0;j<graph[i].size();j++) {
            h[graph[i][j].to]++;
        }
    }

    for(int i=0;i<sz;i++) {
        if(h[i] == 0) {
            st.push(i);
            break;
        }
    }

    while(!st.empty()) {
        int i = st.top(); st.pop();
        ans.push_back(i);
        for(auto& j: graph[i]) {
            h[j]--;
            if(h[j] == 0) st.push(j);
        }
    }

    return ans;
}

