int main(){
    int n,m; cin >> n >> m;
    int e = n-1+m;

    vector<bool> vb(n);
    vector<int> s(n);
    vector<vector<int> > g(n);
    for(int i=0;i<e;i++) vb[i] = false;
    /*
    vector<pair<int,int> > ch(n);
    for(int i=0;i<n;i++){ch[i].first = 1000000; ch[i].second = -1;}
    */

    for(int i=0;i<e;i++){
        int a,b;
        cin >>  a >> b;
        g[a-1].push_back(b-1);
        vb[b-1] = true;
    }
    int root;
    for(int i=0;i<n;i++){
        if(!vb[i]){root = i; break;}
    }

    queue<int> q;
    s[root] = 0;
    q.push(root);
    while(!q.empty()){
        int idx = q.front();
        q.pop();
        for(auto x: g[idx]){
            s[x] = idx+1;
            q.push(x);
        }
    }
    for(auto x: s) cout << x << endl;
