  vector<vector<int>> adjA(n),adjB(n);
  vector<int> res(n,-1),tplg(n,-1),deg(n,0);
  for(int i=0;i<n+m-1;++i){
    cin>>a>>b;
    adjA[b-1].push_back(a-1);
    adjB[a-1].push_back(b-1);
  }

  for(int i=0;i<adjA.size();++i)deg[i]=adjA[i].size();
  for(int i=0;i<n;++i){ //topological sort
    int j=find(deg.begin(),deg.end(),0)-deg.begin();
    tplg[i]=j;
    deg[j]--;
    for(int k=0;k<n;++k)if(find(adjA[k].begin(),adjA[k].end(),tplg[i])!=adjA[k].end())deg[k]--;
  }
  cerr<<"# ";
  for(int i=0;i<n;++i)cerr<<tplg[i];
  cerr<<"\n";
  for(int i=0;i<n;++i){
    cerr<<"["<<i<<"]";
    if(!adjA[i].empty()){
      sort(adjA[i].begin(),adjA[i].end(),[=](int p,int q){return find(tplg.begin(),tplg.end(),p)>find(tplg.begin(),tplg.end(),q);});
      for(int j=0;j<adjA[i].size();++j)cerr<<adjA[i][j];
      res[i]=adjA[i][0];
    }
    cerr<<"\n";
  }

  for(int i=0;i<n;++i)cout<<res[i]+1<<"\n";
