using namespace std;
typedef long long ll;

vector <vector<ll>> node;
vector <ll> height;
vector <ll> parent;

void dfs(ll now_parent, ll now_height){
	now_height++;
	for (int z=0;z<node[now_parent].size();z++){
		ll now = node[now_parent][z];
		if (now_height > height[now]) {
			height[now] = now_height; 
			parent[now] = now_parent;
			dfs(now,now_height);
		}
		else return;
	}
}

int main(){
	ios_base::sync_with_stdio(false); 
    cin.tie(NULL); 
    ll n,m;
    cin >> n >> m;
    node.resize(n+1);
    height.resize(n+1,0);
    parent.resize(n+1,0);
    vector <bool> isroot(n+1,false);
    for (int z=0;z<n+m-1;z++){
    	ll a,b;
    	cin >> a >> b;
    	node[a].push_back(b);
    	isroot[b] = true;
    }
    ll root;
    for (int z=1;z<=n;z++){
    	if (!isroot[z]) {root = z; break;}
    }
    height[root] = 1;
    parent[root] = 0;
    dfs(root,height[root]);
    for (int z=1;z<=n;z++){
    	cout << parent[z] << endl;
    }
    cin >> n;
}

