	VVI G(N+1);
	VI indeg(N+1, 0);
	FOR(i, 0, N + M - 1) {
		int a, b; cin >> a >> b;
		G[a].push_back(b);
		indeg[b]++;
	}

	VI di(N + 1, INF);
	priority_queue<PII, vector<PII>,greater<PII>>pq;
	FOR(i, 1, N+1) {
		if (indeg[i] == 0) {
			pq.push(PII(0,i));
			di[i] = 0;
			DD(de(i));
		}
	}
	VI par(N+1, 0);
	while (!pq.empty()) {
		int d, v;
		tie(d, v) = pq.top(); pq.pop();
		if(d!= di[v])continue;
		for (auto nx : G[v]) {
			if (d - 1 < di[nx]) {
				di[nx] = d - 1;
				par[nx] = v;
				DD(de(nx, v));
				pq.push(PII(d - 1, nx));
			}
		}
	}

	FOR(i, 1, N+1) {
		cout << par[i] << endl;
	}





	return 0;
}

