		{
			eda.push_back(k);
		}
		else
		{	
			erase_node.push_back(k);
		}
	}
	for (int j = 0; j < erase_node.size(); j++)
	{
		E[i].erase(erase_node[j]);
		revE[erase_node[j]].erase(i);
	}

	for (int j = 0; j < eda.size(); j++)
	{
		int k = eda[j];
		ans[k] = i;
		solve(k);
	}
}

