typedef long long ll;

typedef struct node_{
    vector<int> pre;
    vector<int> nx;
    int nprev;
    int nnext;
    int depth;
    int parent;
    int visited;
}* node;

vector<node> g;
vector<int> l;

void visit(int n){
    if(g[n] -> visited == 0){
        g[n] -> visited = 1;
        rep(i, g[n] -> nnext){
            visit(g[n] -> nx[i]);
        }
        l.push_back(n);
    }
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);//おまじないでcin, cout早くする
    int n, m;
    cin >> n >> m;
    g.resize(n);
    rep(i, n){
        node nd = new node_;
        g[i] = nd;
        g[i] -> nprev = 0;
        g[i] -> nnext = 0;
        g[i] -> depth = -1;
        g[i] -> parent = -1;
        g[i] -> visited = 0;
    }

    rep(i, n - 1 + m){
        int a, b;
        cin >> a >> b;
        a--; b--;
        g[a] -> nx.push_back(b);
        g[b] -> pre.push_back(a);
        g[a] -> nnext++;
        g[b] -> nprev++;
    }
    rep(i, n){
        visit(i);
    }
    int root = l[n - 1];
    g[l[n - 1]] -> parent = 0;
    g[l[n - 1]] -> depth = 0;
    for(int i = n - 2; i >= 0; i--){
        node nd = g[l[i]];
        rep(j, nd->nprev){
            if(nd->depth < g[nd->pre[j]]->depth + 1){
                nd->depth = g[nd->pre[j]]->depth + 1;
                nd->parent = nd->pre[j];
            }
        }
    }

    rep(i, n){
        if(i == root) cout << 0 << "\n";
        else cout << g[i] -> parent + 1 << "\n";
    }
    return 0;
}

