};

const int N = 200010;

int n, m;
int prt[N], dep[N];
bool vis[N];
Ed* g[N];

void adde(int u, int v);
void dfs(int u);

int main() {

  scanf("%d%d", &n, &m);
  m += n - 1;
  while (m--) {
    int u, v;
    scanf("%d%d", &u, &v);
    adde(v, u);
  }
  for (int i = 1; i <= n; ++i) {
    dfs(i);
    printf("%d\n", prt[i]);
  }

  return 0;
}

void dfs(int u) {
  if (vis[u])
    return;
  vis[u] = true;
  if (!g[u])
    return;
  pair<int, int> ans = make_pair(-1, 0);
  for (Ed* p = g[u]; p; p = p->next) {
    dfs(p->v);
    ans = max(ans, make_pair(dep[p->v], p->v));
  }
  dep[u] = ans.first + 1;
  prt[u] = ans.second;
}

void adde(int u, int v) {
  static Ed pool[N];
  static Ed* p = pool;
  p->v = v;
  p->next = g[u];
  g[u] = p;
  ++p;
}

