// トポロジカルソート
void tsort_dfs(ll n, vvll& to, vector<bool>& visited, vll& result)
{
    if (!visited[n]) {
        visited[n] = true;
        for (auto t : to[n]) {
            tsort_dfs(t, to, visited, result);
        }
        result.push_back(n);
    }
}
void tsort(ll N, vvll& to, vll& result)
{
    vector<bool> visited(N, false);
    for1 (i, N) {
        tsort_dfs(i, to, visited, result);
    }
    reverse(all(result));
}
//---------------------------------------------------------
void dfs(ll cur, ll pre, vvll& to, vll& ans)
{
    if (pre != -1) {
        if (ans[cur] != -1) {
            return;
        }
    }
    ans[cur] = pre;
    for (ll t : to[cur]) {
        dfs(t, cur, to, ans);
    }
}
void solve()
{
    ll N, M;
    in(N, M);
    vvll to(N);
    vvll rto(N);
    for1 (i, N - 1 + M) {
        ll a, b;
        in(a, b);
        --a;
        --b;
        to[a].push_back(b);
        rto[b].push_back(a);
    }
    vll result;
    tsort(N, to, result);
    vll ans(N, -1);
    dfs(result[0], -1, to, ans);
    for1 (i, N) {
        print(ans[i] + 1);
    }
}
