vector<int> topologicalsort(const vector<vector<int> > &G) {
  const int V = G.size();      // V…頂点の数
  vector<int> indegree(V, 0);  // それぞれの頂点の入次数
  stack<int> S;                // 入次数0を突っ込むstack

  for (auto &edges : G)  // 全ての頂点の入次数を計算する
    for (auto &v : edges)
      indegree[v]++;

  for (int i = 0; i < V; i++)  // もし入次数0なら、Sに追加
    if (!indegree[i])
      S.push(i);

  vector<int> res;  // トポロジカル順に頂点を並べる
  while (S.size()) {
    int r = S.top();  // 根の番号をrに突っ込む
    res.push_back(r);
    S.pop();
    for (auto &v : G[r]) {  // rからの矢印を無かったことにする
      indegree[v]--;
      if (indegree[v] == 0)  // 入次数が0なら追加
        S.push(v);
    }
  }
  return res;
}

int main() {
  int N, M;
  cin >> N >> M;

  vector<vector<int> > v(N);    // 隣接リスト
  vector<vector<int> > inv(N);  // 隣接リスト(入力)

  int from, to;
  for (int i = 0; i < N - 1 + M; i++) {  // N-1+M 辺の数
    cin >> from >> to;
    v[from - 1].push_back(to - 1);  //一つずらしている
    inv[to - 1].push_back(from - 1);
  }

  vector<int> t = topologicalsort(v);  //トポ順n番目は頂点x
  vector<int> topo(N);                 // 頂点i はトポ順で何番目か
  for (int i = 0; i < N; i++)
    topo[t[i]] = i;

  for (int i = 0; i < N; i++) {
    int parent = -1;
    for (int j = 0; j < inv[i].size(); j++)
      if (parent == -1 || topo[parent] < topo[inv[i][j]])
        parent = inv[i][j];
    cout << (parent == -1 ? 0 : parent + 1) << endl;  // ずらして出力
  }
}

