int main() {
    cin.tie(nullptr);
    cout.tie(nullptr);
    ios_base::sync_with_stdio(false);

    int n, m;
    cin >> n >> m;

    vector<vector<int>> g(n + 1);
    vector<int> in(n + 1), val(n + 1);

    for (int i = 0; i < n - 1 + m; i++) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        in[v]++;
    }

    int rt;
    for (int i = 1; i <= n; i++) {
        if (!in[i]) {
            rt = i;
            break;
        }
    }

    queue<int> q;
    q.emplace(rt);

    while (q.size()) {
        int c = q.front();
        q.pop();

        int minin = 999999;

        for (int x : g[c]) {
            if (minin > in[x]) {
                minin = in[x];
            }
        }

        for (int x : g[c]) {
            if (in[x] == minin && !val[x]) {
                val[x] = c;
                q.emplace(x);
            }
            in[x]--;
        }
    }

    for (int i = 1; i <= n; i++) {
        cout << val[i] << '\n';
    }

    return 0;
}

