int main()
{
    int n, m;
    cin >> n >> m;
    VEC( int, n, pa, -1 );
    vector< vector<int> > edge(n);

    VEC( bool, n, bb, false );
    REP( i, n - 1 + m )
    {
        int a, b;
        cin >> a >> b;
        edge[a-1].push_back( b-1 );
        bb[b-1] = true;
    }

    REP( i, n )
    {
        sort( edge[i].begin(), edge[i].end() );
    }

    deque<int> que;
    REP( i,n )
    {
        if( bb[i] == false )
        {
            que.push_back( i );
            pa[i] = 0;
            break;
        }
    }

    while( !que.empty() )
    {
        int p = que.front() + 1; que.pop_front();

        fill(bb.begin(), bb.end(), false);

        deque<int> que2;
        for( const auto& v : edge[p-1] )
        {
            if( bb[v] ) { continue; }

            pa[v] = p;
            que2.push_back( v );

            for( const auto& vv : edge[v] )
            {
                bb[vv] = true;
            }
