bool use[100010];


vector<edge> te[100010];
vector<edge> fe[100010];

void rec(int p) {

	vector<int> children;
	for (size_t i = 0; i < te[p].size(); i++)
	{
		int f = te[p][i].t;
		if (fe[f].size() != 1) {
			for (size_t j = 0; j < fe[f].size(); j++)
			{
				if (fe[f][j].t == p) {
					fe[f].erase(fe[f].begin() + j);
					break;
				}
			}
		}
		else {
			children.push_back(f);
		}
	}
	for (size_t i = 0; i < children.size(); i++)
	{
		rec(children[i]);
	}
}
