using namespace std;

class TopologicalSort {
    const unsigned int N;                        // ノード数
    const std::vector<std::vector<int>> graph;   // グラフ
    std::vector<bool> used;                      // 使用済みノード
    std::vector<int> indeg;                      // 入次数


public:
    std::vector<int> result; // ソート結果

public:
    TopologicalSort(unsigned int num_node, const std::vector<std::vector<int>> &graph) : N(num_node), graph(graph) {
        this->indeg.assign(num_node, 0);
        this->used.assign(num_node, false);
    }

    // 自分から自分にエッジを張る場合に注意(graph[0] = {0}みたいなの)
    bool sort() {
        for (int u = 0; u < N; ++u) {
            for (int v : graph[u]) {
                indeg[v]++;
            }
        }

        for (int u = 0; u < N; ++u) {
            if (indeg[u] == 0 and not used[u]) {
                bfs(u);
            }
        }

        return this->result.size() == N;
    }

private:
    void bfs(int s) {
        std::queue<int> que;
        que.push(s);
        used[s] = true;
        while (not que.empty()) {
            int u = que.front();
            que.pop();
            result.emplace_back(u);

            for (int v : graph[u]) {
                indeg[v]--;
                if (indeg[v] == 0 and not used[v]) {
                    used[v] = true;
                    que.push(v);
                }
            }
        }
    }
};


