    FOR(i, 0, N - 1 + M) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        out[a].emplace_back(b);
        in[b].emplace_back(a);
    }

    TopologicalSort ts(N, out);
    ts.sort();

    V<int> node_idx(N, -1);
    FOR(i, 0, ts.result.size()) {
        node_idx[ts.result[i]] = i;
    }

    V<int> ans(N, -1);
    FOR(i, 0, N) {
        if (in[i].size() == 0) {
            ans[i] = 0; // root
        }
        else if (in[i].size() == 1) {
            ans[i] = in[i][0] + 1;
        }
        else {
            int p = in[i][0];
            FOR(j, 1, in[i].size()) {
                int idx1 = node_idx[p];
                int idx2 = node_idx[in[i][j]];

                if (idx1 < idx2) {
                    p = in[i][j];
                }
            }
            ans[i] = p + 1;
        }
    }

    FOR(i, 0, N) {
        print(ans[i]);
    }

	return 0;
}

