int ds(int n)
{
	if (v[n].size() == 0) 
		return d[n] = 0;
	if (d[n] != 0) return d[n];
	for (int i = 0; i < v[n].size(); i++)
		d[n] = max(d[n], ds(v[n][i]) + 1);
	return d[n];
}

