void dijkstra(ll s) {
  priority_queue<P, vector<P>, greater<P>> q;
  fill_n(par, N, 0); par[s] = -1;
  fill_n(d, N, 0); q.push(P(0, s));
  while (!q.empty()) {
    P p = q.top(); q.pop();
    ll v = p.second;
    for (auto e: adj[v]) {
      if (d[e] <= d[v]) {
        d[e] = d[v]+1;
        par[e] = v;
        q.push(P(d[e], e));
      }
    }
  }
}

