int main(){
	int N, M; 
	cin >> N >> M; 
	vector<int> E[100010] = {}; 
	for(int i = 0; i < N+M; i++){
		int a, b; 
		cin >> a >> b; 
		E[b].push_back(a); 
	}
	int ans[100010] = {}; 
	int depth[100010] = {}; 
	for(int i = 1; i <= N; i++){
		depth[i] = 114514; 
	}
	int root = 0; 
	for(int i = 1; i <= N; i++){
		if(E[i].size() == 0) {ans[i] = 0, depth[i] = 0;} 
		root = i; 
		break; 
	}
	for(int i = 1; i <= N; i++){
		if(E[i].size() == 1 && E[i].at(0) == root){
			ans[i] = root, depth[i] = 1; 
		}
	}
	for(int z = 0; z < 114514; z++){
		for(int p = 1; p <= N; p++){
			if(depth[p] != 114514) continue;
			int m = 0; int w = 0; 
			for(int q = 0; q < E[p].size(); q++){
				if(E[p].at(q) == -1) continue; 
				if(depth[E[p].at(q)] > m){
					m = depth[E[p].at(q)]; w = E[p].at(q); 
					if(q > 0) E[p].at(q-1) = -1; 
				}
				if(m == 114514) break; 
			}
			if(m != 114514){
				ans[p] = w; depth[p] = depth[w] + 1; 
			}	
		}
	}
	for(int i = 1; i <= N; i++){
		cout << ans[i] << endl; 
	}
}

