vector<int> TopologicalSort(){
	vector<int> va;
	queue<int> qa;
	for(int i = 1; i <= N; i++){
		if(indegree[i] == 0) qa.push(i);
	}
	while(!qa.empty()){
		int u = qa.front(); qa.pop();
		va.push_back(u);
		for(int i = 0; i < G[u].size(); i++){
			int v = G[u][i];
			indegree[v]--;
			if(indegree[v] == 0) qa.push(v);
		}
	}
	return va;
}

