        a--;
        b--;
        G[a].push_back(b);
        oya[b].push_back(a);
        indegree[b]++;
    }
    vector<int> topo=topological_sort(G,indegree,N);
    vector<int> ans(N);
    vector<int> rev(N+1);
    REP(i,N) rev[topo[i]]=i;
    rev[N]=-1;

    REP(i,N){
        if(oya[i].size()==0) ans[i]=0;
        else{
            int idx=N;
            REP(j,oya[i].size()){
                int v=oya[i][j];
                if(rev[v]>rev[idx]&&rev[v]<rev[i]){
                    idx=v;
                }
            }
            ans[i]=idx+1;
        }

    }
