int Used[maxN], inD[maxN];

void DFS_topo(int u) {
    Used[u]++;
    L[u] = ++order;
    for (int v : Adj[u]) {
        if (Used[v] == 1) {
            if (Used[u] != 1) continue;
            if (L[u] <= L[v] && L[v] <= R[u]) continue;
            //parent[v] = u;
        }
        //D[v] = D[u] + 1;
        parent[v] = u;
        DFS_topo(v);
    }
    R[u] = order;
}

void solveD_RestoreTheTree() { ///https://atcoder.jp/contests/nikkei2019-qual/tasks/nikkei2019_qual_d
    cin >> n >> m;
    for (int i = 1; i < n + m; i++) {
        int u, v; cin >> u >> v;
        Adj[u].push_back(v);
        inD[v]++;
    }
    int root = 0;
    for (int i = 1; i <= n; i++) {
        if (inD[i] == 0) {
            root = i;
            break;
        }
    }
    for (int i = 1; i <= n; i++) R[i] = 1e9;
    DFS_topo(root);
    for (int i = 1; i <= n; i++) cout << parent[i] << "\n";
}

