class toporogical_sort_fn_t {
public:
  toporogical_sort_fn_t(const std::vector<std::vector<int>>& G) :
    G_(G), N_(G_.size()), indices_(N_), visit_(N_)
  {
    assert(N_);
  };

public:
  std::vector<int> sort() {
    index_ = N_ - 1;

    std::fill(ALL(visit_), 0);

    for (int i = 0; i < N_; i ++)
      if (! visit_[i])
        if (! dfs(i))
          return {};

    return indices_;
  };

private:
  bool dfs(int i) {
    visit_[i] = 1;

    for (const auto& k : G_[i]) {
      // If self-loop is allowed, uncomment the following lines.
      //  if (k == i)
      //   continue;

      if (visit_[k] == 2)
        continue;

      if (visit_[k] == 1)
        return false;	// Self-loop is detected.

      if (! dfs(k))
        return false;
    }

    visit_[i] = 2;

    assert(0 <= index_ && index_ < N_);

    indices_[index_ --] = i;

    return true;
  };

private:
  const std::vector<std::vector<int>>& G_;

private:
  int N_;

  std::vector<int> indices_;

  int index_;

  std::vector<uint8_t> visit_;
};


int main(int argc, char** argv)
{
  std::cin.tie(0);
  std::ios_base::sync_with_stdio(0);

  std::cout << std::fixed << std::setprecision(6);
  std::cerr << std::fixed << std::setprecision(6);

  int N, M;

  std::cin >> N >> M;

  std::vector<std::vector<int>> G(N), H(N);

  for (int i = 0, u, v; i < N - 1 + M; i ++) {
    std::cin >> u >> v;

    u --;
    v --;

    G[u].push_back(v);
    H[v].push_back(u);
  }

  toporogical_sort_fn_t fn(G);

  std::vector<int> a = fn.sort();

  int d[111111], p[111111];

  memset(d, -1, sizeof(d));

  for (int i = 0; i < N; i ++) {
    int x = a[i];

    if (i == 0) {
      d[x] = 0;
      p[x] = 0;
    }
    else {
      int dp = -1, kp = -1;

      for (const auto& k : H[x]) {
        assert(d[k] >= 0);

        if (d[k] > dp) {
          dp = d[k];
          kp =   k;
        }
      }

      d[x] = dp + 1;
      p[x] = kp + 1;
    }
  }

  for (int i = 0; i < N; i ++)
    std::cout << p[i] << std::endl;

  return 0;
}

