    pre[t] = s;
    for(int i = 0; i < adj[t].size();i++){
        if(pre[adj[t][i]] == -1){
                dfs(t,adj[t][i]);
        }
        else{
            if(!in_root(adj[t][i],t)) pre[adj[t][i]] = t;
        }
    }
}

