vector<int> ans;


template <typename G>
vector<int> topological_sort(const G& g) {
  const int N = (int)g.size();
  vector<int> deg(N);
  for (int i = 0; i < N; i++) {
    for (auto& to : g[i])
      ++deg[to];
  }
  stack<int> st;
  for (int i = 0; i < N; i++) {
    if (deg[i] == 0)
      st.emplace(i);
  }
  vector<int> ord;
  while (!st.empty()) {
    auto p = st.top();
    st.pop();
    ord.emplace_back(p);
    for (auto& to : g[p]) {
      if (--deg[to] == 0) {
        st.emplace(to);
        ans[to] = p + 1;
      }
    }
  }
  return ord;
}

