ll root_search(const ll N, const vvll& edge){
  vll root_test(N, -1);
  vector<bool> flag(N, false);
  rep(i, 0, N){
    if(flag[i]) continue;
    flag[i] = true;
    root_test[i] = i;
    queue<ll> que;
    que.push(i);
    while(!que.empty()){
      ll next = que.front();
      flag[next] = true;
      rep(j, 0, edge[next].size()){
        root_test[edge[next][j]] = i;
        if(flag[edge[next][j]]) continue;
        que.push(edge[next][j]);
      }
      que.pop();
    }
  }
  ll ans = 0;
  while(ans != root_test[ans]){
    ans = root_test[ans];
  }
  return ans;
}

void ans_search(const ll pos, const vvll& edge, vector<bool>& flag, vll& dp){
  queue<ll> que;
  dp[pos] = 0;
  que.push(pos);
  while(!que.empty()){
    ll next = que.front();
    flag[next] = true;
    rep(i, 0, edge[next].size()){
      dp[edge[next][i]] = next+1;
      if(flag[edge[next][i]]) continue;
      que.push(edge[next][i]);
    }
    que.pop();
  }
  return;
}

