struct Graph{
    struct Node{
        vector<int> dests;
        int maxDepth = -1;
        int from = 0;
    };
    vector<Node> nodes;
    Graph(int num): nodes(num){ }
    int id(Node* n){ return n - &nodes[0]; }
    int id(Node& n){ return &n - &nodes[0]; }
    void print(){ for(auto& node : nodes){ prints(id(node), node.dests); } }
    void add1Edge(int from, int dest){
        nodes[from].dests.push_back(dest);
    }
    void dfs(int idx, int from = -1, int depth = 0){
        bool first = nodes[idx].maxDepth == -1;
        if(nodes[idx].maxDepth >= depth){
            return;
        }
        nodes[idx].from = from;
        nodes[idx].maxDepth = depth;
        if(!first){ return; }
        for(int didx : nodes[idx].dests){
            if(didx == from){ continue; }
            dfs(didx, idx, depth + 1);
        }
    }
};
