vector<int> G[100005];
vector<int> H[100005];
int D[100005]; // depth
int P[100005]; // parent

void dfs(int node) {
  int maxd = -1;
  for (int i=0; i<H[node].size(); i++) {
    int parent = H[node][i];
    if (maxd < D[parent]) {
      maxd = D[parent];
      P[node] = parent;
    }
  }
  D[node] = maxd + 1;
  for (int i=0; i<G[node].size(); i++) {
    dfs(G[node][i]);
  }
}

