vector<lli> d[100100];
vector<lli> f[100100];

signed main(){

	lli n,m;
	cin>>n>>m;

	lli in[100100];

	REP(i,0,n-1+m){
		lli a,b;
		cin>>a>>b;
		a--;b--;
		d[a].push_back(b);
		f[b].push_back(a);
		in[b]++;
	}

	/*適当な点から逆側に幅優先探索で最後にたどり着く箇所が根になる*/
	/*さらに根から幅優先探索を行っていき、親を更新していくことで答えとなる*/

	/*ということで、最初の点0から上にあがる。fを使う*/
	queue<lli> q;
	q.push(0);

	lli last=-1;
	REP(i,0,n){
		if(in[i]==0){
			last = i;
			break;
		}
	}
	lli ans[100100]={-1};
	ans[last]=0;
	q.push(last);

	while(q.size()){
		lli top=q.front();
		q.pop();

		for(lli i=0;i<d[top].size();i++){
			lli now = d[top].at(i);
			in[now]--;
			if(in[now]==0){
				q.push(now);
				ans[now]=top+1;
			}
		}
	}

	REP(i,0,n){
		cout<<ans[i]<<endl;
	}

	return 0;
}

