int in_deg[MAX_N], ans[MAX_N], nnew[MAX_N];

bitset<MAX_N> sibl[MAX_N];
int flag[MAX_N];
void dfs_sibl(int v) {
	flag[v] = 1;
	sibl[v].set(v, 1);
	for (int i = 0; i < (int)e[v].size(); i++)
		if (!flag[e[v][i]]) {
			dfs_sibl(e[v][i]);
			sibl[v] |= sibl[e[v][i]];
		}
}


void dfs(int v) {
	nnew[v] = 1;
	for (int i = 0; i < (int)e[v].size(); i++)
		if (!nnew[e[v][i]]) {
			int Ok = 1;
			for (int j = 0; j < (int)e_back[e[v][i]].size(); j++)
				if (sibl[v].test(e_back[e[v][i]][j])) {
					Ok = 0;
					break;
				}
			//if ((sibl[v] & bts[e[v][i]]).count() == 0) {
			if (Ok) {
				ans[e[v][i]] = v;
				dfs(e[v][i]);
			}
		}
}


int main() {
	//freopen("input.txt", "r", stdin);
	//freopen("output.txt", "w", stdout);

	int n, m;
	scanf("%d%d", &n, &m);
	for (int i = 0; i < n - 1 + m; i++) {
		int a, b;
		scanf("%d%d", &a, &b);
		a--; b--;
		e[a].push_back(b);
		in_deg[b]++;
		//bts[b].set(a, 1);
		e_back[b].push_back(a);
	}

	int root = 0;
	for (int i=0; i<n; i++)
		if (in_deg[i] <= 0) {
			root = i;
			break;
		}

	ans[root] = -1;

	dfs_sibl(root);
	for (int i = 0; i < n; i++) sibl[i].set(i, 0);

	dfs(root);

	for (int i = 0; i < n; i++) ans[i]++;
	for (int i = 0; i < n; i++) printf("%d\n", ans[i]);
	return 0;
}

