int main() {
    int N, M;
    cin >> N >> M;
    vector<int> deg(N, 0);
    vector<vector<int>> G(N);
    for (int i = 1; i < N+M; i++) {
        int a, b; cin >> a >> b; a--; b--;
        G[a].emplace_back(b); deg[b]++;
    }

    int r = -1;
    for (int i = 0; i < N; i++) if (deg[i] == 0) r = i;

    vector<int> depth(N, -1); depth[r] = 0;
    vector<int> par(N, -1);
    queue<pair<int, int>> sta;
    sta.emplace(r, r);
    while (!sta.empty()) {
        int v, p; tie(v, p) = sta.front(); sta.pop();
        for (auto u : G[v]) if (p != u) {
            if (depth[u] < depth[v]) sta.emplace(u, v);
            if (depth[u] <= depth[v]) { depth[u] = depth[v] + 1; par[u] = v; }
        }
    }

    for (auto ans : par) cout << ans+1 << endl;
    return 0;
}

