const int INF = 1e9;

void solve() {
  int N, M;
  cin >> N >> M;
  vector<vi32> sg(N + 1);
  vector<vi32> rg(N + 1);
  vi32 deg(N + 1);
  rep(i, N + M - 1) {
    int u, v;
    cin >> u >> v;
    sg[u].emplace_back(v);    
    rg[v].emplace_back(u);
    deg[v]++;
  }
  vi32 dag;
  {
    vi32 seen(N + 1);
    auto dfs = [&](auto dfs, int u) -> void {
      seen[u] = 1;
      each(v, sg[u]) if (!seen[v]) {
        dfs(dfs, v);
      }
      dag.emplace_back(u);
    };
    reps(i, N) if (!seen[i]) dfs(dfs, i);
    reverse(all(dag));
  }
  vi32 mp(N + 1);
  rep(i, N) {
    mp[dag[i]] = i;
  }
  vi32 ans(N + 1);
  rep(i, N) {
    int u = dag[i];
    pair<int, int> ma(0, 0);
    each(p, rg[u]) amax(ma, make_pair(mp[p], p));
    ans[u] = ma.second;
  }
  reps(i, N) cout << ans[i] << endl;
}

