using namespace std;

#define rep(i,n) for(int i=0;i<(n);i++)

template<typename T> struct edge {
  int to;

  edge(int to_) : to(to_) {}
};

template<typename T,template <typename ELEM> class C> struct Topological_Sort {
  vector<vector<C<T>>> G;
  vector<bool> used;
  int V;//0,...,|V|-1
  T INF;

  Topological_Sort (int V_) {
    init(V_);
  }

  void init(int V_) {
    V = V_;

    G.clear();
    G.resize(V);
  }

  void add_edge(int from,int to) {
    G[from].push_back(C<T>(to));
  }

  bool dfs (int i,set<int> pars,vector<int> &sorted) {
    pars.insert(i);
    used[i] = true;

    rep(j,(int)G[i].size()) {
      if (!used[G[i][j].to]) {
        if(dfs(G[i][j].to,pars,sorted)) {
          return true;
        }
      } else {
        if (pars.find(G[i][j].to) != pars.end())  {
          return true;
        }
      }
    }

    pars.erase(i);
    sorted.push_back(i);//dfsの帰りがけの順
    return false;
  }

  bool topological_sort (vector<int> &sorted) { // 成功ならtrue 失敗(DAG出ない)ならfalseを返す
    used.clear();
    used.resize(V,false);

    sorted.clear();

    rep (i,V) {
      if (!used[i] && dfs(i,set<int>(),sorted)) {
        return false;;
      }
    }

    reverse(sorted.begin(),sorted.end());

    return true;
  }

};

using ll = long long;


vector<ll> G[100010];
int par[100010];
int dep[100010];
bool used[100010];

void dfs2(int v,int depth) {
  used[v] = true;

  rep(i,(int)G[v].size() ){
    int vnext = G[v][i];
    if(used[vnext]) {
      if (dep[vnext] < depth) {
        par[vnext] = v;
        dep[vnext] = depth;
      }
    }else {
      par[vnext] = v;
      dep[vnext] = depth;
      dfs2(vnext,depth + 1);
    }
  }
}


int main() {
  ll n ,m;
  cin >> n >> m;
  ll V,E;
  V = n;
  E = n + m - 1;
  Topological_Sort<ll,edge> ts(V);
  rep(i,E) {
    ll s,t;
    cin >> s >> t;
    s--;t--;
    ts.add_edge(s,t);
    G[s].push_back(t);
  }
  rep(i,n)par[i]=-1;

  vector<int> ans;

  ts.topological_sort(ans);

  par[ans[0]] = -1;
  dep[ans[0]] = 0;
  dfs2(ans[0],1);

  rep(i,n)
    cout << par[i] + 1 << endl;
  return 0;
}

