int n,m;
vvi g;
vi tsort_Kahn(){
    vi indeg(n, 0);
    vi dist(n, -1);
    stack<int> S;
    rep(i,n) for(auto v : g[i]) indeg[v]++;
    rep(i,n) if(indeg[i] == 0) S.push(i), dist[i] = 0;

    vi res;
    while(S.size()>0){
        int v = S.top(); S.pop();
        res.emplace_back(v); for(auto u : g[v]){
            indeg[u]--;
            if(indeg[u] == 0) S.push(u), dist[u] = max(dist[u], dist[v] + 1);
        }
    }
    return dist;
}

int main(){
    ios_base::sync_with_stdio(0);
