    rep(i,n-1+m){
        int a,b;
        cin >> a >> b;
        g[a].push_back(b);
        cnt[b]++;
    }
    n++;
    REP(i,1,n) if(cnt[i] == 0) g[0].push_back(i);
    auto dist = tsort_Kahn();

    vi par(n, 0);
    REP(v,1,n){
        for(auto u : g[v]){
            if(dist[u] == dist[v] + 1) par[u] = v;
        }
    }
    REP(v,1,n){
        cout << par[v] << endl;
    }
    return 0;
}

