void dfs(int cur) {
	vint flags;
	for (auto to : edge[cur]) {
		if (depth[to] < depth[cur] + 1) {
			depth[to] = depth[cur] + 1;
			parent[to] = cur;
			ecnt[to]--;
			flags.push_back(to);
		}
	}
	for (auto to : flags) {
		if (ecnt[to] == 0) {
			dfs(to);
		}
	}
}

