const int MAXN = 500000 + 10;

int deg[MAXN];
int far[MAXN];
int pre[MAXN << 1], to[MAXN << 1], head[MAXN], wcnt;
int q[MAXN], ql, qr;
inline void addedge(int u, int v) {
	wcnt++;
	pre[wcnt]=head[u];
	head[u]=wcnt;
	to[wcnt]=v;
}

int main() {
	int i, n, m, u, v;

	scanf("%d %d", &n, &m);
	for(i=1; i<=n-1+m; i++){
		scanf("%d %d", &u, &v);
		deg[v]++;
		addedge(u, v);
	}

	ql=1;
	qr=0;
	for(i=1; i<=n; i++) if(!deg[i]) q[++qr]=i;
	while(ql<=qr){
		u=q[ql++];
		for(i=head[u]; i; i=pre[i]){
			deg[v=to[i]]--;
			far[v]=u;
			if(!deg[v]){
				q[++qr]=v;
			}
		}
	}

	for(i=1; i<=n; i++) printf("%d\n", far[i]);
	return 0;
}

