struct Object {
    // 任意の構造体
    ll x;
    ll depth;
};

queue<Object> q;
vector<vec> v;
int N, M;
vec p, d;
vec memo;
void bfs() {
    while (!q.empty()) {
        // キューの先頭の要素を取り出す dequeue(pop)
        Object now = q.front(); q.pop();

        // 停止条件
        // if (now.hoge == target) return ~;  // 探索対象
        // if (now.x == gx && now.y == gy) return now.depth;

        // BFS
        rep(i, v[now.x].size()){
            ll next_x = v[now.x][i];
            Object next = {next_x, now.depth+1};  // 深さ（ステップ数）を一つ足す
            if(d[next_x] < next.depth){
                d[next_x] = next.depth;
                // p[next_x] = now.x+1;
            }
            if(memo[next_x] == 0) continue;
            memo[next_x]--;
            q.push(next);
        }
    }
}

void solve() {
    cin >> N >> M;
    p.resize(N, 0); v.resize(N); d.resize(N, 0);
    memo.resize(N, 0);
    auto vv = v;
    rep(i, N-1+M){
        int a, b; cin >> a >> b;
        a--; b--;
        memo[b]++;
        p[b] = a+1;
        v[a].push_back(b);
        vv[b].push_back(a);
    }
    auto mt = memo;
    int pa;
    rep(i, N) if(memo[i] == 0) pa = i;
    q.push({pa, 0});
    bfs();
    rep(i, N){
        if(mt[i] > 1){
            int tmp = 0;
            rep(j, mt[i]){
                if(tmp < d[vv[i][j]]){
                    tmp = d[vv[i][j]];
                    p[i] = vv[i][j]+1;
                }
            }
        }
    }
    rep(i, N){
        cout << p[i] << endl;
    }
}

