void add(int u,int v){
    e[cnt].v = v, e[cnt].next = head[u], head[u] = cnt ++;
}
void init(){
    memset(head,-1,sizeof head); cnt = 0;
    memset(du, 0, sizeof du);
    memset(vis, 0, sizeof du);
    memset(fa, 0, sizeof du);
