struct DirectedGraph
{
    int V; // 頂点数
    vector<vector<int> > to;
    vector<vector<int> > from;

    vector<bool> used;
    vector<int> vs;

    void dfs(int v)
    {
        used[v] = true;
        for (auto t : to[v]) if (!used[t]) dfs(t);
        vs.push_back(v);
    }
    void rdfs(int v, int k)
    {
        used[v] = true;
        cmp[v] = k;
        for (auto t : from[v]) if (!used[t]) rdfs(t, k);
    }

    vector<int> cmp;
    DirectedGraph(int V) : V(V),
                           to(vector<vector<int> >(V)), 
                           from(vector<vector<int> >(V)),
                           cmp(vector<int>(V))
                           {}
    void add_edge(int from_, int to_)
    {
        to[from_].push_back(to_);
        from[to_].push_back(from_);
    }

    int scc_num = -1;
    int scc()
    {
        used = vector<bool>(V, false);
        vs.clear();
        for (int v = 0; v < V; v++) if (!used[v]) dfs(v);

        used = vector<bool>(V, false);
        scc_num = 0;
        for (int i = vs.size() - 1; i >= 0; i--) if (!used[vs[i]]) rdfs(vs[i], scc_num++);
        return scc_num; // 強連結成分の個数を返却
    }

};

int main()
{
    int N, M;
    cin >> N >> M;
    DirectedGraph g(N + 1);
    REP(_, N - 1 + M)
    {
        int A, B;
        cin >> A >> B;
        g.add_edge(A, B);
    }
    g.scc();
    vector<int> vec = g.vs;
    reverse(vec.begin(), vec.end());
    vec.pop_back();

    set<int> used;
    vector<int> ans(N + 1);
    for (auto now : vec)
    {
        for (auto nxt : g.to[now])
        {
            ans[nxt] = now;
        }
    }
    FOR(i, 1, N + 1) printf("%d\n", ans[i]);
}

