struct node{
	int depth;
	int parent;
	std::vector<int> parent_candidates;

	node(): depth(-1), parent(-1)
	{}
};

int set_node(
	int depth,
	std::vector<node>& tree,
	node& node
){
	if(node.depth >= 0){
		return node.depth + 1;
	}else{
		if(node.parent_candidates.size() == 0){ // root
			node.depth = 0;
			return 1;
		}else{
			int max = 0;
			for(int i : node.parent_candidates){
				int tmp_dpth = set_node(depth, tree, tree[i]);
				if(max < tmp_dpth){
					max = tmp_dpth;
					node.parent = i;
				}
			}
			node.depth = max;
			return node.depth + 1;
		}
	}
}

int main(){
	int N, M;
	std::cin >> N >> M;

	std::vector<node> tree(N);

	for(int i = 0; i < N+M - 1; i++){
		int u, v;
		std::cin >> u >> v;
		tree[v - 1].parent_candidates.push_back(u - 1);
	}

	for(int i = 0; i < N; i++){
		set_node(0, tree, tree[i]);
		std::cout << tree[i].parent + 1 << std::endl;
	}
}

