bool leaf[MAX_N];
int level[MAX_N];
bool used[MAX_N];

void solve(int pos, int l)
{
  level[pos] = max(level[pos], l);
  l = max(l, level[pos]);
  // cerr << pos+1 << " * " << l << endl;
  // cerr << level[pos] << endl;

  if(Edge[pos].size() == 0) {
    leaf[pos] = true;
    return;
  }

  for(int next : Edge[pos]) {
    if(inCnt[next]==1) {
      solve(next, l+1);
    } else {
      inCnt[next]--;
      level[next] = max(level[next], l+1);
    }
  }
}

vector<int> newEdge[MAX_N];
int ansList[MAX_N];

void solve2(int pos)
{
  for(int next : Edge[pos]) {
    if(level[pos]+1 == level[next]) {
      newEdge[pos].push_back(next);
      ansList[next] = pos+1;
    }
    solve2(next);
  }
}

