vector<int> V[100000];

int findRoot( vector<int>& B, int N, int M ){
    vector<bool> isAppeared(N, false);  // B に現れてないのが root
    for( int i = 0; i < N-1+M; ++i ) isAppeared[B[i]] = true;
    for( int i = 0; i < N; ++i ){
        if( !isAppeared[i] ) return i;
    }
    return -1;
}


int main()
{
    int N, M;
    cin >> N >> M;
    vector<int> A(N-1+M), B(N-1+M);
    for( int i = 0; i < N+M-1; ++i ){
        cin >> A[i] >> B[i];
        --A[i], --B[i];
        V[A[i]].push_back( B[i] );
    }


    int root = findRoot(B, N, M);

    vector<int> dist(N), parent(N);
    queue<int> s;
    s.push( root );
    while( !s.empty() )
    {
        int tmp = s.front();
        s.pop();
        for( auto edge: V[tmp] ){
            if( dist[edge] < dist[tmp]+1 ){
                dist[edge] = dist[tmp]+1; 
                parent[edge] = tmp+1;
            }
            s.push( edge );
        }
    }

    for( int i = 0; i < N; ++i ) cout << parent[i] << endl;

    return 0;
}

