typedef long long ll;
ll n, m, root, edge[100008][2], parent[100008][2];//parent depth
bool isroot[100008];
list<ll> edgelist[100008];

int ganbaru(ll now, ll depth){
	while(!edgelist[now].empty()){
		ll buf = edgelist[now].back(); edgelist[now].pop_back();
		if(parent[buf][0] == -1){// || parent[buf][1] < depth+1){
			parent[buf][0] = now;
			parent[buf][1] = depth+1;
			ganbaru(buf, depth+1);
		}
		else{
			ll olddepth = parent[buf][1]; ll at = buf;
			while(olddepth == parent[at][1]){
				olddepth--;
				at = parent[at][0];
				if(at == root){olddepth = parent[buf][1]; break;}
				if(olddepth != parent[at][1]){olddepth = parent[at][1] + (parent[buf][1]-olddepth); break;}
			}

			if(olddepth < depth+1){
				parent[buf][0] = now;
				parent[buf][1] = depth+1;
				ganbaru(buf, depth+1);
			}
		}
	}
	return 0;
}

