void solve(int pos, int l)
{
  level[pos] = max(level[pos], l);
  l = max(l, level[pos]);

  if(Edge[pos].size() == 0) {
    leaf[pos] = true;
    return;
  }

  for(int next : Edge[pos]) {
    if(inCnt[next]==1) {
      solve(next, l+1);
    } else {
      inCnt[next]--;
      level[next] = max(level[next], l+1);
    }
  }
}

