void solve2(int pos)
{
  used[pos] = true;
  for(int next : Edge[pos]) {
    if(level[pos]+1 == level[next]) {
      newEdge[pos].push_back(next);
      ansList[next] = pos+1;
    }
    if(!used[next])
      solve2(next);
  }
}

