bool ispar(int v, int u){
	return (st[v] <= st[u] && ft[u] <= ft[v]);
}

void DFS(int v, int p = 0){
	st[v] = ++Time;
	par[v] = p;
	M[v] = 1;
	//cout << v << ' ' << p << '\n';
	for (auto u:G[v]){
		if (!M[u.F]){
			DFS(u.F, v);
		}else{
			//cout << v << ' ' << u.F << '\n';
			if (st[v] < st[u.F]){
				mark[u.S] = 1;
			}else{
				if (ispar(par[v], u.F)) mark[u.S] = 1;
			}
		}
	}  	
	ft[v] = Time;
}

void DFS2(int v, int p = 0){
	par[v] = p;
	for (auto u:g[v]){
		if (p != u) DFS2(u, v);
	}
}

