int main(){
    ll N,M;
    cin >> N >> M;

    ll A[N-1+M], B[N-1+M];
    for(int i=0; i<N-1+M; i++){
        cin >> A[i] >> B[i];
        A[i]--;
        B[i]--;
    }

    ll num_p[N];
    for(int i=0; i<N; i++){
        num_p[i]=0;
    }
    for(int i=0; i<N-1+M; i++){
        num_p[B[i]]++;
    }

    ll root;
    for(int i=0; i<N; i++){
        if(num_p[i]==0){
            root=i;
            break;
        }
    }

    queue<ll> node;
    node.push(root);

    vector<ll> son[N];
    for(int i=0; i<N-1+M; i++){
        son[A[i]].push_back(B[i]);
    }

    ll p[N];
    for(int i=0; i<N; i++){
        p[i]=root;
    }
    ll depth[N];
    for(int i=0; i<N; i++){
        depth[i]=0;
    }
    p[root]=-1;
    depth[root]=0;


    while(!node.empty()){
        ll temp_p=node.front();

        for(int i=0; i<son[temp_p].size(); i++){
            ll temp_s=son[temp_p][i];

            if(depth[temp_s]<depth[temp_p]+1){
                depth[temp_s]=depth[temp_p]+1;
                p[temp_s]=temp_p;


                node.push(temp_s);
            }
        }


        node.pop();
    }


    for(int i=0; i<N; i++){
        cout << p[i]+1 << endl;
    }
    return 0;
}

