int dfs(const vector< vector<int> > &G, vector<int> &d, int v){
  if(d[v] >= 0) return d[v];
  for(size_t i = 0; i < G[v].size(); ++i){
    int t_ = dfs(G,d,G[v][i]);
    d[v] = max(d[v],t_+1);
  }
  return d[v];
}

