		for (int i = 0; i < graph.at(now).size(); i++)
		{
			int dst = graph.at(now).at(i).dst;

			if (srcnum[dst] <= 1)
				continue;

			// 複数あるならtansakuzumiの指されている奴は消す.
			for (int j = 0; j < graph.at(dst).size(); j++)
			{
				if (tansazumi[graph.at(dst).at(j).src] == true)
				{
					// 削除だといろいろめんどいので.
					graph.at(dst).at(j).src = -1;
					graph.at(now).at(i).dst = -1;
					srcnum[dst]--;
				}
			}
		}

		for (int i = 0; i < graph.at(now).size(); i++)
		{
			if (graph.at(now).at(i).src == now && graph.at(now).at(i).dst != -1)
			{
				tansazumi[graph.at(now).at(i).dst] = true;
				que.push(graph.at(now).at(i).dst);
			}
		}
	}
	for (int i = 0; i < N; i++)
	{
		for (int j = 0; j < graph.at(i).size(); j++)
		{
			if (i == root)
			{
				cout << 0 << endl;
				break;
			}
			else if (graph.at(i).at(j).src != -1 && graph.at(i).at(j).src != i)
			{
				cout << graph.at(i).at(j).src + 1<< endl;
				break;
			}
		}

	}


	return 0;
}

