		G.edges.push_back({ s, t });
		lst[s].push_back(t);
	}
	Topological_Sort ts(G);
	vi v = ts.get_result();
	vi ans(n);
	Foreach(a, v) {
		Foreach(b, lst[a]) {
			ans[b] = a + 1;
		}
	}
	Loop(i, n) {
		cout << ans[i] << endl;
	}
}

