//ここから
ll N, M;
vector<ll> E[100010];
vector<ll> d(100010, -1);

ll findParent(){
  vector<bool> J(N, 1);
  rep(i, N){
    for(ll to : E[i]){
      J[to] = 0;
    }
  }
  rep(i, N){
    if(J[i] == 1) return i;
  }
  return -1;
}

void dfs(ll start){
  d[start] = 0;
  priority_queue<pair<ll, ll>> pque;
  pque.push({0, start});
  while(!pque.empty()){
    pair<ll, ll> p = pque.top();
    pque.pop();
    if(d[p.s] > p.f) continue;
    for(ll to : E[p.s]){
      if(d[to] < p.f + 1){
        d[to] = p.f + 1;
        pque.push({d[to], to});
      }
    }
  }
}

vector<ll> par(100010);
void dfs2(ll now){
  for(ll to : E[now]){
    if(to == -1) continue;
    par[to] = now;
    dfs2(to);
  }
}

int main(void){
  cin >> N >> M;
  rep(i, N+M-1){
    ll A, B;
    cin >> A >> B;
    A--, B--;
    E[A].pb(B);
  }
  //親を見つける
  ll parent = findParent();

  //最長経路
  dfs(parent);

  //辺の削除
  rep(i, N){
    rep(j, E[i].size()){
      if(d[i] + 1 != d[E[i][j]]) E[i][j] = -1;
    }
  }
  par[parent] = -1;
  dfs2(parent);
  rep(i, N){
    cout << par[i] + 1 << endl;
  }
}

