template <class Weight>
struct Edge {
  size_t src, dst;
  Weight cost;

  Edge(size_t src, size_t dst, Weight cost=1):
    src(src), dst(dst), cost(cost)
  {}

  bool operator <(const Edge<Weight> &rhs) const {
    if (cost != rhs.cost) return cost < rhs.cost;
    if (src != rhs.src) return src < rhs.src;
    return dst < rhs.dst;
  }
};

template <class Weight>
struct Graph: public std::vector<std::vector<Edge<Weight>>> {
  Graph(size_t n): std::vector<std::vector<Edge<Weight>>>(n) {}

  void connect_with(size_t src, size_t dst, Weight cost=1) {
    (*this)[src].emplace_back(src, dst, cost);
    (*this)[dst].emplace_back(dst, src, cost);
  }

  void connect_to(size_t src, size_t dst, Weight cost=1) {
    (*this)[src].emplace_back(src, dst, cost);
  }

  std::vector<size_t> sccomp(size_t &num) const {
    const size_t V=this->size();
    Graph rev(V);
    for (const auto &v: *this)
      for (const auto &e: v)
        rev.connect_to(e.dst, e.src, e.cost);

    std::vector<bool> used(V);
    std::vector<size_t> vs;
    std::function<void (size_t)> dfs=[&](size_t v) {
      used[v] = true;
      for (size_t i=0; i<(*this)[v].size(); ++i)
        if (!used[(*this)[v][i].dst]) dfs((*this)[v][i].dst);

      vs.push_back(v);
    };

    for (size_t v=0; v<V; ++v)
      if (!used[v]) dfs(v);

    used.assign(V, false);
    std::vector<size_t> cmp(V);
    num = 0;
    std::function<void (size_t)> rdfs=[&](size_t v) {
      used[v] = true;
      cmp[v] = num;
      for (size_t i=0; i<rev[v].size(); ++i)
        if (!used[rev[v][i].dst]) rdfs(rev[v][i].dst);
    };

    for (size_t i=vs.size(); i--;)
      if (!used[vs[i]]) {
        rdfs(vs[i]);
        ++num;
      }

    return cmp;
  }

  std::vector<size_t> sccomp() const {
    size_t tmp;
    return sccomp(tmp);
  }
};


int main() {
  size_t N, M;
  scanf("%zu %zu", &N, &M);

  Graph<int> g(N);
  for (size_t i = 1; i < N+M; ++i) {
    size_t A, B;
    scanf("%zu %zu", &A, &B);
    --A;
    --B;
    g.connect_to(A, B, 1);
  }

  std::vector<size_t> indeg(N);
  for (size_t i = 0; i < N; ++i)
    for (const auto& e: g[i])
      ++indeg[e.dst];

  std::queue<std::pair<size_t, size_t>> q;  // <id, depth>
  for (size_t i = 0; i < N; ++i)
    if (indeg[i] == 0)
      q.emplace(i, 0);

  assert(!q.empty());
  std::vector<size_t> depth(N);
  std::vector<size_t> par(N, -1);
  while (!q.empty()) {
    size_t v, d;
    std::tie(v, d) = q.front();
    q.pop();

    for (auto& e: g[v]) {
      if (depth[e.dst] >= depth[v] + 1) continue;
      // fprintf(stderr, "[%zu] <- %zu\n", e.dst, depth[v]+1);
      depth[e.dst] = depth[v] + 1;
      q.emplace(e.dst, depth[e.dst]);
      par[e.dst] = v;
    }
  }

  for (size_t i = 0; i < N; ++i)
    printf("%zu\n", par[i]+1);
}

