    cin >> a >> b;
    a--;
    b--;
    G[a].pb(b);
    G2[b].pb(a);
  }

  vector<bool> seen(N, 0);
  vll order;
  rep(i, N) {
    if (seen[i]) continue;
    rec(i, G, seen, order);
  }
  REVERSE(order);

  vll order2(N);
  rep(i, N) order2[order[i]] = i;

  rep(i, N) {
    ll max_index = -1;
    ll ma = -1;
    for (auto gg : G2[i])
      if (ma < order2[gg]) {
        max_index = gg;
        ma = order2[gg];
      }

    COUT(max_index + 1);
  }

  return 0;
}

