	ll upd=0;
	if(0<=pidx && cost[idx] < cost[pidx]+1) {
		cost[idx] = cost[pidx]+1;
		parent[idx] = pidx;
		upd=1;
	}
	if(0<=pidx && !upd) return;
	REP(i, g[idx].size()) {
		ll nidx = g[idx][i];
		dfs(idx, nidx, g);
	}
}


