void calc_ind(vector<vector<int>> &graph, vector<int> &ind, vector<bool> &flag, int start)
{
  //入次数を求めるためにDFS
  stack<int> s;
  s.push(start);
  flag[start] = true;
  while(!s.empty()){
    int current = s.top();
    s.pop();
    for(int i = 0; i < graph[current].size(); i++)
    {
      int next = graph[current][i];
      ind[next]++;
      if(!flag[next])
      {
        s.push(next);
        flag[next] = true;
      }
    }
  }
}

void calc_parent(vector<vector<int>> &graph, vector<int> &parent, vector<int> &flag, int root)
{
  //親を見つけるためにBFS
  //あとのラウンドで見つかった方を親に設定
  stack<int> q;
  q.push(root);
  flag[root] = 1;
  while(!q.empty())
  {
    int current = q.top();
    bool ok = true;
    for(int i = 0; i < graph[current].size(); i++)
    {
      int next = graph[current][i];
      if(flag[next] == 0)
      {
        q.push(next);
        flag[next] = true;
        ok = false;
        parent[next] = current;
      }else if(flag[next] == 1)
      {
        parent[next] = current;
      }
    }
    if(ok){
      q.pop();
      flag[current] = 2;
    }
  }
}

int main()
{
  int n, m;
  cin >> n >> m;
  vector<vector<int>> graph(n, vector<int>());
  for(int i = 0; i < n + m - 1; i++)
  {
    int a, b;
    cin >> a >> b;
    graph[a - 1].push_back(b - 1);
  }
  vector<int> ind(n, 0);
  vector<int> parent(n , -1);
  vector<bool> flag(n, false);
  for(int i = 0; i < n; i++)
  {
    if(flag[i]) continue;
    calc_ind(graph, ind, flag, i); 
  }
  int root = 0;
  for(int i = 0; i < ind.size(); i++)
  {
    if(ind[i] == 0)
    {
      root = i;
      break;
    }
  }
  //rootからBFS
  vector<int> flag2(n, 0);
  calc_parent(graph, parent, flag2, root);
  for(auto e : parent){
    cout << e + 1 << endl;
  }
}

