void solve() {
    i64 N; RD(N);
    i64 M; RD(M);

    vector<vector<i64>> G(N);
    vector<i64> deg_in(N, 0);
    REP(_, N-1+M) {
        i64 from,to; RD1(from); RD1(to);
        G[from].emplace_back(to);
        ++deg_in[to];
    }
    DBG(G);
    DBG(deg_in);

    i64 root = arg_find(0, N, [&deg_in](i64 v) { return deg_in[v] == 0; });

    queue<i64> que;
    vector<i64> parent(N, -1);
    que.emplace(root);
    while(!que.empty()) {
        i64 v = POP(que);
