        dest[b[i] - 1] = dest[a[i] - 1] + 1;
      }
    }
  }
  }
  for (int i = 0; i < n; i++) {
    if (dest[i] == 0) cout << 0 << endl;
    else cout << parents[i] + 1 << endl;
  }
  return 0;
}

