#include <bits/stdc++.h>

struct edge_t {
  int from;
  int to;
  int distance;
};

using namespace std;

static int n, m;
static std::vector<edge_t> es{};
static std::vector<std::vector<int>> sources{};
static std::vector<std::vector<int>> dests{};

std::vector<int> solve(int root) {
  std::vector<int> idxes{root};
  int distance = 1;
  while (true) {
    std::vector<int> next_idxes{};
    for (auto const idx : idxes) {
      for (auto const fromIdx : sources[idx]) {
        auto& e = es[fromIdx];
        e.distance = distance;
        next_idxes.push_back(e.to);
      }
    }
    if (next_idxes.empty()) {
      break;
    }
    idxes = next_idxes;
    distance++;
  }

  std::vector<int> ret(n);
  for (int i = 0; i < n; ++i) {
    int from = 0;
    int distance = -1;
    for (auto const toIdx : dests[i]) {
      const auto& e = es[toIdx];
      if (e.distance <= distance) {
        continue;
      }
      distance = e.distance;
      from = e.from;
    }
    if (distance < 0) {
      ret[i] = 0;
    } else {
      ret[i] = from + 1;
    }
  }
  return ret;
}

int main() {
  std::cin.tie(nullptr);
  std::ios::sync_with_stdio(false);
  std::cin >> n >> m;
  es.resize(n - 1 + m);
  dests.resize(n, std::vector<int>(0));
  sources.resize(n, std::vector<int>(0));
  std::vector<bool> rootish(n, true);
  for (int i = 0; i < n - 1 + m; ++i) {
    auto& e = es[i];
    std::cin >> e.from;
    std::cin >> e.to;
    e.from--;
    e.to--;
    e.distance = -1;
    sources[e.from].push_back(i);
    dests[e.to].push_back(i);
    rootish[e.to] = false;
  }
  int root;
  for (root = 0; root < n; ++root) {
    if (rootish[root]) {
      break;
    }
  }
  auto ret = solve(root);
  for (auto node : ret) {
    std::cout << node << std::endl;
  }
  return 0;
}

