    Graph(int n, int m) : z(n), y(n), r(n), v(n, { -1, 0 }), e(m), n(n), m(0), l(0) {}
    void add_edge(int i, int j) {
        e[m] = { j, v[i].n };
        v[i].n = m;
        m++;
    }
    void dfs(int i) {
        v[i].f = 1;
        for (int j = v[i].n; j >= 0; j = e[j].n) {
            Edge& o = e[j];
            if (v[o.i].f) continue;
            dfs(o.i);
        }
        y[i] = l;
        z[l] = i;
        l++;
    }
    void solve(Graph f) {
        for (int i1 = 0; i1 < n; i1++) {
            int i = z[i1];
            int i0 = -1, m = n;
            for (int j = f.v[i].n; j >= 0; j = f.e[j].n) {
                Edge& o = f.e[j];
                if (y[o.i] < m) {
                    m = y[o.i];
                    i0 = o.i;
                }
            }
            r[i] = i0;
        }
        for (int i = 0; i < n; i++) {
            cout << r[i] + 1 << '\n';
        }
        cout << flush;
    }
    int l;
    vector<int> z, y, r;
    vector<Vertex> v;
    vector<Edge> e;
    int n, m;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, m;
    cin >> n >> m;
    int k = n - 1 + m;

    vector<int> c(n);
    Graph g(n, k), f(n, k);
    for (int i = 0; i < k; i++) {
        int a, b;
        cin >> a >> b;
        a--; b--;

        g.add_edge(a, b);
        f.add_edge(b, a);
        c[b] = 1;
    }

    int i0;
    for (int i = 0; i < k; i++) {
        if (c[i] == 0) i0 = i;
    }

    g.dfs(i0);
    g.solve(f);
    //bに現れないのが根
    //根からDFSして深さを浅いほうへ更新したら要らない辺 深いほうへ更新したら要るかも
    //一度訪れた頂点は適切に更新したら即return でないと経路数は爆発する
    //訪れるたびに親を更新
    //半順序が入るのでは？移動元のうち最も近いもの

    return 0;
}

