int in[100005];
int out[100005];
int dp[100005];
int par[100005];
using graph = VVI;

int main() {
	int n, m;
	scanf("%d%d", &n, &m);
	graph g(n);
	REP(i, n+m-1) {
		int x, y;
		scanf("%d%d", &x, &y);
		x--, y--;
		g[x].PB(y);
		out[x]++;
		in[y]++;
	}
	stack<int> st;
	VI nodes;
	REP(i, n) {
		if (!in[i]) {
			st.push(i);
		}
	}
	while (!st.empty()) {
		auto i = st.top();
		nodes.PB(i);
		st.pop();
		for (auto j : g[i]) {
			in[j]--;
			if (!in[j])st.push(j);
		}
	}
	int ret = 0;
	par[nodes[0]] = -1;
	for (auto i : nodes) {
		for (auto j : g[i]) {
			if (dp[j] < dp[i] + 1) {
				par[j] = i;
				dp[j] = dp[i] + 1;
			}
		}
	}
	REP(i,n)printf("%d\n", par[i]+1);
	return 0;
}

