void dfs(vector<vector<int>> &vec, vector<vector<int>> &road, int node, int dp){

    for(int i=0; i<road[node].size(); i++){
        int next = road[node][i];
        int next_p= vec[next][0];
        //if(next_p==node)continue;
        if(vec[next][1]<dp+1){
            vec[next][0]=node;
            vec[next][1]=dp+1;
        }
        if(next_p==-1){
            dfs(vec, road, next,dp+1);
        }
    }
}

int rootSearch(vector<vector<int>> &inv_road, int node){
    if(inv_road[node].size()==0){
        return node;
    }else{
        return rootSearch(inv_road, inv_road[node][0]);
    }
}

