	}
	nodes.resize(N);
	for (auto& e : E) {
		nodes[e.first].children.push_back(e.second);
		++(nodes[e.second].nparents);
	}
	for (int i = 0; i < N; ++i) {
		if (nodes[i].nparents == 0) {
			nodes[i].parent = -1;
			subroots.push_back(i);
		}
	}

	while (!subroots.empty()) {
		auto subroot = std::move(subroots.back());
		subroots.pop_back();
		for (auto child : nodes[subroot].children) {
			if (--nodes[child].nparents == 0) {
				nodes[child].parent = subroot;
				subroots.push_back(child);
			}
		}
	}

	for (int i = 0; i < N; ++i) {
		std::cout << (nodes[i].parent+1) << "\n";
	}
}

