	for(int i=0;i<n;++i){
		if(!r.count(i))root=i;
	}
	par[root]=root;
	queue<int>q;
	q.push(root);
	while(!q.empty()){//dfsだと子孫の計算が終わっていない状態で探索を開始するとやり直しになり、TLEになる。
		int v=q.front();
		q.pop();
		for(int x:g[v]){
			if(chmax(cost[x],cost[v]+1))par[x]=v+1;
			q.push(x);
		}
	}
	for(int i=0;i<n;++i){
		if(i==root)cout<<0<<"\n";
		else cout<<par[i]<<"\n";
	}
}

