void dfs(int n) {
	if (chi[n].size() == 0)return;
	//葉に達したら探索を終える
	int nChi = chi[n].size();
	//頂点nの子の根からの距離を求める
	for (int i = 0; i < nChi; ++i) {
		int nxt = chi[n][i];
		nPar[nxt]--;
		if (dist[nxt] < dist[n] + 1) {
			//距離が更新される時に親を更新する
			dist[nxt] = dist[n] + 1;
			ans[nxt] = n;
		}
		//頂点nxtへのnPar[nxt]回目の参照の時以降の探索を行う
		if (nPar[nxt] == 0)dfs(nxt);
	}
}
