void input() {
    cin >> N >> M;
    paths.resize(N + 1);
    for (ll i = 0; i < N - 1 + M; i++) {
        ll a, b;
        cin >> a >> b;
        paths[a].push_back(b);
    }
}

vector<ll> find_roots() {
    vector<bool> visited(N + 1);
    for (auto& targets : paths) {
        for (auto target : targets) {
            visited[target] = true;
        }
    }
    vector<ll> roots;
    for (ll i = 1; i < N + 1; i++) {
        if (not visited[i])
            roots.push_back(i);
    }
    return roots;
}

void solve() {
    vector<ll> pars(N + 1, 0);

    queue<ll> qs;
    auto roots = find_roots();
    for (auto root : roots)
        qs.push(root);
    vector<bool> visited(N + 1, false);
    while(not qs.empty()) {
        auto q = qs.front(); qs.pop();
        if (visited[q])
            continue;
        visited[q] = true;
        auto& targets = paths[q];
        for (auto target : targets) {
            pars[target] = q;
            qs.push(target);
        }
    }
    for (ll i = 1; i < N + 1; i++) {
        cout << pars[i] << endl;
    }
}


