const int MAX_V = (int)1e5 + 5;
const int MAX_E = (int)1e5 + 5;

vector<int> G[MAX_V];
bool used[MAX_V];
int parent[MAX_V];
int maxDepth;
int candV;
vector<int> g[MAX_V];

void dfs(int curr, int prev, int depth){
	used[curr] |= true;
	int cnt = 0;

	if (depth > maxDepth){
		candV = curr;
		maxDepth = depth;
	} // end if

	rep (i, (int)G[curr].size()){
		int next = G[curr][i];
		if (prev != -1){
			if (!used[next] && cnt == 0){
				dfs(next, curr, depth + 1);
				g[curr].push_back(next);
				g[next].push_back(curr);
				++cnt;
			} // end if
		}else{
			if (!used[next] && cnt <= 1){
				dfs(next, curr, depth + 1);
				g[curr].push_back(next);
				g[next].push_back(curr);
				++cnt;
			} // end if
		} // end if
	} // end rep
}

void dfs2(int curr, int prev){
	parent[curr] = prev;
	used[curr] |= true;
	int cnt = 0;
	rep (i, (int)g[curr].size()){
		int next = g[curr][i];
		if (!used[next] && cnt == 0){
			dfs2(next, curr);
			++cnt;
		} // end if
	} // end rep
}

