		--A[i], --B[i];
		G[A[i]].push_back(B[i]);
		G[B[i]].push_back(A[i]);
	} // end rep

	maxDepth = 0;
	candV = -1;
	memset(used, false, sizeof(used));
	dfs(0,-1,0);

//	cerr << "candV: " << candV << endl;

	memset(parent, -1, sizeof(parent));
	memset(used, false, sizeof(used));
	dfs2(candV, -1);

	rep (i, N){
		cout << parent[i] + 1 << endl;
	} // end rep

	return 0;
}

