vector<int> solve(int n, int m, vector<vector<int> > const & g, vector<vector<int> > const & g_rev) {
    queue<int> que;
    vector<int> outdegree(n);
    REP (i, n) {
        outdegree[i] = g[i].size();
        if (outdegree[i] == 0) {
            que.push(i);
//cerr << "push* " << i+1 << endl;
        }
    }
    vector<int> parent(n, -1);
    while (not que.empty()) {
        int i = que.front();
        que.pop();
//cerr << "pop " << i+1 << endl;
        for (int j : g[i]) {
            if (parent[j] == -1) {
                parent[j] = i;
            }
        }
        for (int j : g_rev[i]) {
            -- outdegree[j];
            if (outdegree[j] == 0) {
//cerr << "push " << j+1 << endl;
                que.push(j);
            }
        }
    }
    return parent;
}

