//ここから編集する
class Dijkstra {
public:
    using T = long long int;
    typedef pair<T, int> P; //firstは最短距離、secondは頂点の番号
    const T inf = (T) 5e15;
    struct edge {
        int to;
        T cost;
    };


    int V;                  //超点数
    vector<vector<edge>> G; //グラフ,G[i]はiから出る辺の集合,G[i][j]はiから出る辺のj番目の辺
    vector<T> d;           //最短距離
    vector<int> prev;

    //0origin
    Dijkstra(int N) {
        V = N;
        G = vector<vector<edge >>(N);
        d = vector<T>(N);
        prev = vector<int>(N, -1);
    };

    void dijkstra(int s) {
        priority_queue<P, vector<P>, greater<P>> que;
        fill(d.begin(), d.end(), inf);
        d[s] = 0;
        que.push(P(0, s));

        while (!que.empty()) {
            P p = que.top();
            que.pop();
            int v = p.second;
            if (d[v] < p.first)
                continue;
            for (int i = 0; i < G[v].size(); i++) {
                edge e = G[v][i];
                if (d[e.to] > d[v] + e.cost && !(d[e.to] == inf && d[v] == inf)) {
                    d[e.to] = d[v] + e.cost;
                    que.push(P(d[e.to], e.to));
                    prev[e.to] = v;
                }
            }
        }
    }

    /* 頂点fromに頂点toに達するコストcostの辺を貼る */
    void addEdge(int from, int to, T cost) {
        edge e;
        e.to = to;
        e.cost = cost;
        G[from].push_back(e);
    }

    T getDist(int v) {
        return d[v];
    }
};

class Solve {
public:
    int N, M;
    vector<vector<int>> G;
    vector<vector<int>> rG;
    int root = -1;

    void input() {
        cin >> N >> M;
        G.resize(N);
        rG.resize(N);
        rep(i, 0, N + M - 1) {
            int a, b;
            cin >> a >> b;
            a--, b--;
            G[a].push_back(b);
            rG[b].push_back(a);
        }


        for (int i = 0; i < N; ++i) {
            if (rG[i].size() == 0) root = i;
        }
    }


    void solve() {
        input();
        vector<int> tree(N, -1);
        set<int> searched;

        priority_queue<pair<int, int>> que;

        Dijkstra dij(N);
        for (int i = 0; i < N; ++i) {
            for (auto c : G[i]) {
                dij.addEdge(i, c, -1);
            }
        }

        dij.dijkstra(root);
        for (int i = 0; i < N; ++i) {
            tree[i] = dij.prev[i];
        }


        for (int i = 0; i < N; ++i) {
            cout << tree[i] + 1 << endl;
        }

    }
};


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);

    Solve().solve();


    return 0;
}

