  void add_edge(int x, int y)
  {
    gg[x].push_back(y);
    rg[y].push_back(x);
    edges.emplace_back(x, y);
  }

  int operator[](int k)
  {
    return (comp[k]);
  }

  void dfs(int idx)
  {
    if(used[idx]) return;
    used[idx] = true;
    for(int to : gg[idx]) dfs(to);
    order.push_back(idx);
  }

  void rdfs(int idx, int cnt)
  {
    if(comp[idx] != -1) return;
    comp[idx] = cnt;
    for(int to : rg[idx]) rdfs(to, cnt);
  }

  void build(vector< vector< int > > &t)
  {
    for(int i = 0; i < gg.size(); i++) dfs(i);
    reverse(begin(order), end(order));
    int ptr = 0;
    for(int i : order) if(comp[i] == -1) rdfs(i, ptr), ptr++;

    t.resize(ptr);
    set< pair< int, int > > connect;
    for(auto &e : edges) {
      int x = comp[e.first], y = comp[e.second];
      if(x == y) continue;
      if(connect.count({x, y})) continue;
      t[x].push_back(y);
      connect.emplace(x, y);
    }
  }
};


int main() {
	int n, m; scanf("%d%d", &n, &m); m += n - 1;
	std::vector<std::vector<int>> g(n), G(n);
	StronglyConnectedComponents scc(n);
	for(int i = 0; i < m; i++) {
		int a, b; scanf("%d%d", &a, &b);
		g[a - 1].push_back(b - 1);
		scc.add_edge(a - 1, b - 1);
	}
	std::vector<std::vector<int>> t, T(n);
	scc.build(t);

	std::vector<int> ans(n, -1);
	std::vector<int> latte(t.size(), -1);
	for(int i = 0; i < n; i++) latte[scc[i]] = i;
	std::vector<int> h(t.size(), 0), hh(t.size(), 0);
	for(int i = 0; i < n; i++) {
		for(auto v : t[i]) {
			h[v]++;
			T[v].push_back(i);
		}
		hh[i] = t[i].size();
	}
	for(int i = 0; i < n; i++) {
		if(!h[i]) {
			std::vector<bool> used(n, false); used[latte[i]] = true;
			std::queue<int> qu; qu.push(latte[i]);
			while(!qu.empty()) {
				int p = qu.front(); qu.pop();

				for(auto e : g[p]) {
					if(used[e]) continue; used[e] = true;
					ans[e] = p;
					qu.push(e);
				}
			}
			for(auto v : ans) printf("%d\n", v + 1);
			return 0;
		} else if(!hh[i]) {
			int root = -1;
			std::vector<bool> used(n, false); used[i] = true;
			std::queue<int> qu; qu.push(i);
			while(!qu.empty()) {
				auto p = qu.front(); qu.pop();

				bool f = true;
				for(auto e : T[p]) {
					if(used[e]) continue; used[e] = true;
					qu.push(e); f = false;
				}
				if(f) {
					root = latte[p];
					while(!qu.empty()) qu.pop();
					break;
				}
			}
			assert(root != -1);
			used = std::vector<bool>(n, false); used[root] = true;
			qu.push(root);
			while(!qu.empty()) {
				int p = qu.front(); qu.pop();
				for(auto e : g[p]) {
					if(used[e]) continue; used[e] = true;
					ans[e] = p;
					qu.push(e);
				}
			}
			for(auto v : ans) printf("%d\n", v + 1);
			return 0;
		}
	}
	return 0;
}

