vector<long long>tsort(long long n) {
	vector<long long>mon(n + 1), ans;
	stack<long long>s;
	for (long long i = 1; i <= n; ++i) {
		for (auto j : v[i]) { ++mon[j]; }
	}
	for (long long i = 1; i <= n; ++i) {
		if (mon[i] == 0) { s.push(i); }
