void dfs(int d, int parent,int now)
{
  if(nodes[now].depth<d){
    nodes[now].parent = parent;
    nodes[now].depth = d;
  }
  REP(i,0,nodes[now].childsize){
    dfs(d + 1, now, nodes[now].childs[i]);
  }
}

