//閉路がない有向グラフの各有向辺が順方向になるように頂点をソートする
//閉路が検出された場合、空のvectorを返す
vector<ll> topological_sort(vector<vector<ll>> &g){
	ll gsize=g.size();
	//各頂点の入次数を記録
	vector<ll> indegree(gsize, 0);
	for(ll from=0; from<gsize; from++){
		for(ll to : g[from]){
			indegree[to]++;
		}
	}

	//入次数が0の頂点であればqueueに追加
	queue<ll> que;
	for(ll i=0; i<gsize; i++){
		if(indegree[i]==0)que.push(i);
	}

	//入次数が0の頂点から順にansへ格納
	vector<ll> ans;
	while(!que.empty()){
		ll v=que.front();
		que.pop();
		ans.push_back(v);
		for(ll nextv : g[v]){
			indegree[nextv]--;
			if(indegree[nextv]==0)que.push(nextv);
		}
	}

	//ansへ格納されていない頂点がある＝閉路が存在する
	return (ll)ans.size()==gsize ? ans : vector<ll>();
}

//トポロジカルソートの最大パスを返す
vector<ll> longest_path(vector<vector<ll>> &g, vector<ll> &topological){
	ll gsize=g.size();
	vector<ll> dp(gsize, 0);
	vector<ll> nextv(gsize, -1);
	ll maxval = -1;
	ll startv = -1;
	for(auto it = topological.rbegin(); it != topological.rend(); ++it){
		for(ll u : g[*it]){
			if(chmax(dp[*it], dp[u] + 1)) nextv[*it] = u;
		}
		if(chmax(maxval, dp[*it])) startv = *it;
	}

	ll v=startv;
	vector<ll> longest_path;
	while(1){
		longest_path.push_back(v);
		if(nextv[v]==-1)break;
		v=nextv[v];
	}
	return longest_path;
}

