  scanf("%d %d", &n, &m);
  for (int i = 0; i < m + n - 1; i++) {
    scanf("%d %d", &as[i], &bs[i]);
    as[i]--;  // NOTE : modified input
    bs[i]--;  // NOTE : modified input
  }

  // create graph and determine root
  int root = -1;
  vector<int> cnts(n, 0);
  vector<vector<int>> adj_lists(n, vector<int>());
  for (int i = 0; i < m + n - 1; i++) {
    adj_lists[as[i]].push_back(bs[i]);
    cnts[bs[i]]++;
  }
  for (int i = 0; i < n; i++) {
    if (cnts[i] == 0) {
      root = i;
      break;
    }
  }
  // printf("root = %d\n", root);

  // erase links
  vector<int>ds(n, 0);
  queue<int> que[2];
  int d = 0;
  que[d % 2].push(root);
  while (!que[d % 2].empty()) {
    while (!que[d % 2].empty()) {
      const int v = que[d % 2].front();
      que[d % 2].pop();
      // erase all links starting from v
      for (int u : adj_lists[v]) {
        cnts[u]--;
        // if there are no more links to u, u's depth is d + 1
        if (cnts[u] == 0) {
          que[(d + 1) % 2].push(u);
          ds[u] = d + 1;
        }
      }
    }
    d++;
  }
  // for (int i = 0; i < n; i++) {
