  for (int i = 0; i < m + n - 1; i++) {
    if (ds[as[i]] + 1 == ds[bs[i]]) {
      ps[bs[i]] = as[i];
    }
  }
  for (int i = 0; i < n; i++) {
    printf("%d\n", ps[i] + 1);
  }

  return 0;
}

