tuple<bool,vector<i64>> graph_tsort(const vector<vector<i64>>& g) {
    i64 n = SIZE(g);
    vector<i64> res;
    res.reserve(n);

    vector<i64> deg_in(n, 0);
    for(const auto& tos : g)
        for(auto to : tos)
            ++deg_in[to];

    queue<i64> que;
    REP(v, n) {
        if(deg_in[v] == 0)
            que.emplace(v);
    }

    while(!que.empty()) {
        i64 v = que.front(); que.pop();

        res.emplace_back(v);

        for(auto to : g[v]) {
            if(--deg_in[to] > 0) continue;
            que.emplace(to);
        }
    }

    bool ok = SIZE(res) == n;
    return make_tuple(ok, res);
}

void solve() {
    i64 N; RD(N);
    i64 M; RD(M);

    vector<vector<i64>> G(N);
    REP(_, N-1+M) {
        i64 from,to; RD1(from); RD1(to);
        G[from].emplace_back(to);
    }
    DBG(G);

    bool ok;
    vector<i64> t;
    tie(ok,t) = graph_tsort(G);
    assert(ok);

    vector<i64> t_idx(N);
    REP(i, N) {
        i64 v = t[i];
        t_idx[v] = i;
    }

    vector<i64> parent(N, -1);
    REP(from, N) {
        for(auto to : G[from]) {
            chmax(parent[to], from, LT_ON([&t_idx](i64 v) { return v == -1 ? -1 : t_idx[v]; }));
        }
    }

    for(auto p : parent) {
        PRINTLN(p+1);  // 1-based
    }

