class Solver {
  public:
    bool solve() {
        int N, M; cin >> N >> M;
        vector<vector<int>> E(N);
        vector<vector<int>> rE(N);
        rep(i, N - 1 + M) {
            int a, b; cin >> a >> b;
            a--; b--;
            E[a].push_back(b);
            rE[b].push_back(a);
        }
        int root = -1;
        {
            rep(i, N) if(rE[i].size() == 0) {
                assert(root == -1);
                root = i;
            }
        }
        vector<int> parent(N, -2);
        vector<int> depth(N, -1);

        function<void(int, int, int)> dfs = [&] (int now, int prev, int d) {
            if(d > depth[now] and parent[now] != prev)
                parent[now] = prev;
            else
                return;
            depth[now] = d;
            for(int nxt : E[now]) {
                dfs(nxt, now, d + 1);
            }
        };
        dfs(root, -1, 0);
        rep(i, N) {
            cout << parent[i] + 1 << endl;
        }

        return 0;
    }
};

