void exec(){
  int n, m, u, v;
  int from_num[MAX_N];
  VI to[MAX_N];
  int parent[MAX_N];
  cin >> n >> m;

  for (int i = 0; i < n; i++){
    from_num[i] = 0;
    parent[i] = -1;
  }

  for (int i = 0; i < n - 1 + m; i++){
    scanf("%d %d", &u, &v);
    u--;
    v--;
    to[u].push_back(v);
    from_num[v]++;
  }

  int root = -1;
  for (int i = 0; i < n; i++){
    if (from_num[i] == 0){
      root = i;
      break;
    }
  }

  priority_queue<ituple, vector<ituple>, greater<ituple> > pq;

  pq.push(ituple(0, root, -1));

  while (!pq.empty()){
    ituple e = pq.top();
    pq.pop();
    int depth = get<0>(e);
    int v = get<1>(e);
    int from = get<2>(e);
    from_num[v]--;

    if (from_num[v] > 0){
      continue;
    }

    parent[v] = from + 1;

    for (int i = 0; i < to[v].size(); i++){
      pq.push(ituple(depth + 1, to[v][i], v));
    }
  }

  for (int i = 0; i < n; i++){
    printf("%d\n", parent[i]);
  }

}

void solve(){
  int t = 1;
  // scanf("%d", &t);
  for (int i = 0; i < t; i++){
    exec();
  }
}

int main(){
  solve();
  return 0;
}

