// bfs
void bfs(int root) {
    queue<int> que;
    que.push(root);
    while(!que.empty()) {
        int v = que.front();
        que.pop();
        for(int next : edge[v]) {
            if(dist[next] != -1) {
                continue;
            } else {
                dist[next] = dist[v] + 1;
                par[next] = v;
                que.push(next);
            }
        }
    }
}
// dfs
void dfs(int root) {
    for(int next : edge[root]) {
        if(dist[next] == -1) {
            par[next] = root;
            dist[next] = dist[root] + 1;
            dfs(next);
        }
    }
}
