void DFS(int V,int P,vector<vector<int> > &GRAPH, vector<int> & Parent,vector<int>& DIST,vector<int> & used)
{
  if(Parent[V] != P)return;
  if(P != -1)
  if(DIST[P] + 1 != DIST[V])return;
  for (auto &&nV : GRAPH[V])
  {
    if(DIST[V] >= DIST[nV])
    {
      Parent[nV] = V;
      DIST[nV] = DIST[V]+1;
      DFS(nV,V,GRAPH,Parent,DIST,used);
    }

  }
  return;
}
