vector<int> topo_sort(const graph& G) {
	int V = G.size();
	vector<int> ide(V);
	for (int i = 0; i < V; i++) {
		for (auto to : G[i]) {
			ide[to]++;
		}
	}
	vector<int> res;
	vector<int> used(V);
	for (int i = V - 1; i >= 0; i--) {
		if (ide[i] == 0) {
			dfs(i, G, res, used);
		}
	}
	reverse(res.begin(), res.end());
	return res;
}


