void DFS_topo(int u) {
    Used[u] = 1;
    L[u] = ++order;
    for (int v : Adj[u]) {
        if (Used[v] == 1) {
            if (Used[u] == 2) continue;
            if (L[u] <= L[v] && L[v] <= R[u]) continue;
            parent[v] = u;
            Used[v] = 2;
