using namespace std;

int N, M;
vector<vector<int>> E, ansE;
int cntin[100000 + 100], cntout[100000 + 100];
int d[100000 + 100];
int Log[100000 + 100];

void bfs(int s) {
	d[s] = 0;
	queue<pair<int, int>> q;
	q.push(make_pair(0, s));
	while (q.size()) {
		auto now = q.front(); q.pop();
		int pos = now.second;
		if (d[pos] > now.first)continue;

		for (int i = 0; i < E[pos].size(); i++) {
			int nxt = E[pos][i];
			if (d[nxt] < d[pos] + 1) {
				d[nxt] = d[pos] + 1;
				q.push(make_pair(d[nxt], nxt));
				Log[nxt] = pos;
			}
		}
	}
}

int main() {
	cin >> N >> M;
	E.resize(N), ansE.resize(N);
	for (int i = 0; i < N + M - 1; i++) {
		int a, b;
		cin >> a >> b;
		a--, b--;
		E[a].push_back(b);
		cntout[a]++;
		cntin[b]++;
	}

	//根から最大距離を求めるBFSをする。
	int root;
	for (int i = 0; i < N; i++)
		if (cntin[i] == 0) {
			root = i;
			break;
		}

	bfs(root);

	//葉から根に最大距離の経路をたどっていく。
	for (int i = 0; i < N; i++) {
		if (cntout[i] == 0) {
			//葉である
			int idx = i;
			while (idx != root) {
				ansE[Log[idx]].push_back(idx);
				idx = Log[idx];
			}
		}
	}

	vector<vector<int>> revansE(N);
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < ansE[i].size(); j++) {
			revansE[ansE[i][j]].push_back(i);
		}
	}
	for (int i = 0; i < N; i++) {
		if (revansE[i].size() == 0)cout << 0 << endl;
		else cout << revansE[i][0] + 1 << endl;
	}
	return 0;
}

