void dfs(int x){
	vis[x]=1;
	for (int i=0;i<g[x].size();i++)
		if (!vis[g[x][i]]) dfs(g[x][i]);
	v.push_back(x); 
}
int parents[100003];
void dfs1(int x){
	for (int i=0;i<g[x].size();i++)
		if (!vis[g[x][i]]){
			vis[g[x][i]]=1;
			parents[g[x][i]]=x;
			dfs1(g[x][i]);
		}
}
int main(){
