struct bellmanford {
	ll N;//頂点数(1-index)
	vector<vector<edge>> g;//有向グラフ
	ll s;


	vector<edge> e;
	vector<ll> ans;//頂点sからiまでの距離(負閉路がない場合)
	ll minuscycle;//sから到達可能な負閉路があるか

	bellmanford(ll N0, ll s0, vector<vector<edge>> g0) {
		N = N0;
		s = s0;
		g = g0;

		ans.assign(N + 1, INF);
		ans[s] = 0;

		repn(i, N) {
			for (edge ed : g[i]) {
				e.push_back(ed);
			}
		}

		minuscycle = 0;

		repn(i, N) {
			for (edge ed : e) {
				if (ans[ed.fr] != INF && ans[ed.fr] + ed.d < ans[ed.to]) {
					ans[ed.to] = ans[ed.fr] + ed.d;
					if (i == N) { minuscycle = 1; }
				}
			}
		}

	}
};


int main() {
