	}

	ll rt = 0;
	repn(i, N) {
		if (root[i]) { rt = i; }
	}

	bellmanford dij(N, rt, g);


	vector<ll> ans(N + 1, 0);
	repn(v, N) {
		for (edge e : g[v]) {
			ll w = e.to;
			if (dij.ans[w] == dij.ans[v] - 1) { ans[w] = v; }
		}
	}

	repn(i, N) {
		cout << ans[i] << endl;
	}











	system("PAUSE");

}

