void bfs(ll p, ll node, ll depth, vint &ans, vint &depth_arr, const vvint &g){
  if(depth_arr[node] >= depth) return;

  depth_arr[node] = depth;
  ans[node] = p+1;

  for(auto e:g[node]){
    bfs(node, e, depth+1, ans, depth_arr, g);
  }

  return;
}




