vector<int> t_sort(){
  stack<int> st;
  REP(i, v) if(h[i] == 0) st.push(i);
  vector<int> res;
  while(st.size()) {
    int i = st.top(); st.pop();
    res.push_back(i);
    for(auto& j: g[i]) {
      h[j]--;
      if(h[j] == 0) st.push(j);
    }
  }
  return res;
}
