using Edge = pair<int, int>;

int getRoot(const int n, const vector<Edge>& edges) {
  set<int> rootie;
  for (int i = 0; i < n; ++i)
    rootie.insert(i);
  for (auto& e : edges)
    rootie.erase(e.second);
  return *rootie.begin();
}

int main() {
  int n, m;
  cin >> n >> m;
  vector<Edge> edges;
  for (int i = 0; i < n + m; ++i) {
    int u, v;
    cin >> u >> v;
    edges.emplace_back(u - 1, v - 1);
  }
  const int root = getRoot(n, edges);

  vector<vector<int>> children(n);
  for (auto& e : edges) {
    children[e.first].push_back(e.second);
  }

  vector<int> rank(n, -1);
  vector<int> parent(n, -1);
  queue<int> q;
  q.push(root);
  rank[root] = 0;
  parent[root] = -1;
  while (!q.empty()) {
    int p = q.front();
    int r = rank[p] + 1;
    for (int c : children[p]) {
      if (rank[c] < r) {
        int pre = parent[c];
        rank[c] = r;
        parent[c] = p;
        if (pre < 0)
          q.push(c);
        continue;
      }
    }
    q.pop();
  }

  for (int p : parent)
    cout << (p + 1) << "\n";

  return 0;
}

