const int N = 2e5 + 10;
vector<int>g[N];
vector<pair<int, pair<int, int>>> gg[N];
int n, m, cnt;
bool bz[N];
int stack[N], dfn[N], low[N], belong[N];
bool instack[N];
int in[N], fa[N];
void dfs(int x)
{
    static int calc = 0;
    dfn[x] = low[x]  = ++ calc, stack[++ stack[0]] = x, instack[x] = 1;
    for (auto u:g[x])
        if (!dfn[u])
        {
            dfs(u);
            low[x] = min(low[x], low[u]);
        } else
            if (instack[u])
                low[x] = min(low[x], dfn[u]);
    if (low[x] == dfn[x])
    {
        ++cnt;
        do{
            int u;
            instack[u = stack[stack[0]]] = 0;
            belong[u] = cnt;
            stack[0] --;
        }while (stack[stack[0] + 1] != x);
    }
}
void dfs1(int x)
{
    for (auto u:gg[x]) {
        fa[u.second.second] = u.second.first;
        dfs1(u.first);
    }
}
void dfs2(int x)
{
    for (auto u:g[x])
        if (belong[u] == belong[x] && !fa[u])
        {
            fa[u] = x;
            dfs2(u);
        }
}
void dfs3(int x)
{
    for (auto u:g[x])
        if (u != 1  && !fa[u])
        {
            fa[u] = x;
            dfs3(u);
        }
}
int main()
{
    scanf("%d %d", &n, &m);
    for (int i = 1 ; i < n + m ; i ++)
    {
        int x ,y;
        scanf("%d %d", &x, &y);
        g[x].push_back(y);
    }
    for (int i = 1; i <= n ; i ++)
        if (!dfn[i])
            dfs(i);
    for (int i = 1; i <= n ; i ++)
        for (auto u:g[i])
            if (belong[u] != belong[i])
            {
                gg[belong[i]].push_back(make_pair(belong[u], make_pair(i, u)));
                in[belong[u]] += 1;
            }
    if (cnt == 1)
    {
        dfs3(1);
    } else {
        for (int i = 1; i <= cnt; i++)
            if (!in[i]) {
                dfs1(i);
                break;
            }
        for (int i = 1; i <= n; i++)
            if (fa[i])
                dfs2(i);
    }
    for (int i = 1; i <= n ;  i++)
        printf("%d\n", fa[i]);
    return 0;
}

