// 隣接リスト
vector<vector<int> > G;

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    // input
    ll N, M;
    cin >> N >> M;

    vector<Edge> E;
    ll edge_num = N-1+M;
    E.reserve(edge_num);
    FOR(i, 0, edge_num){
        ll a, b;
        cin >> a >> b;
        E.push_back(Edge(a,b));
    }

    // search root

    bool visited[N+1];
    FOR(i, 0, N+1){
        visited[i] = false;
    }
    for(auto edge : E){
        visited[edge.to] = true;
    }
    ll root;
    FOR(i, 1, N+1){
        if(!visited[i]){
            root = i;
            break;
        }
    }

    // 隣接リスト
    G.resize(N+1);
    for(auto edge : E){
        G[edge.from].push_back(edge.to);
    }

    // Eはもう使わない
    E.clear();

    // 距離
    int d[N+1];
    FOR(i, 0, N+1){
        d[i] = -1;
    }
    d[root] = 0;

    // 親
    ll parent[N+1];
    parent[root] = 0;

    stack<int> sta;
    sta.push(root);

    FOR(i, 0, N+1){
        visited[i] = false;
    }

    while(!sta.empty()){
        int id = sta.top();
        sta.pop();
        visited[id] = true;

        int dist = d[id];

        auto list = G[id];
        for(auto to : list){
            if(d[to] < dist+1){
                parent[to] = id;
                d[to] = dist+1;

                if(!visited[to]){
                    sta.push(to);
                }
            }

        }
    }

    FOR(i, 1, N+1){
        p(parent[i]);
    }

    return 0;
}

