template <typename KeyType, typename ValueType>
std::pair<KeyType, ValueType> get_max(const std::map<KeyType, ValueType> &x) {
    using pairtype = std::pair<KeyType, ValueType>;
    return *std::max_element(x.begin(), x.end(),
                             [](const pairtype &p1, const pairtype &p2) {
                                 return p1.second < p2.second;
                             });
}
vector<int> A;
vector<int> B;
vector<int> dist;
vector<int> par;
queue<int> que;
vector<vector<int>> edge;

// bfs
void bfs(int root) {
    queue<int> que;
    que.push(root);
    while(!que.empty()) {
        int v = que.front();
        que.pop();
        for(int next : edge[v]) {
            if(dist[next] != -1) {
                continue;
            } else {
                dist[next] = dist[v] + 1;
                par[next] = v;
                que.push(next);
            }
        }
    }
}
// dfs
void dfs(int root) {
    for(int next : edge[root]) {
        if(dist[root] + 1 >= dist[next]) {
            par[next] = root;
            dist[next] = dist[root] + 1;
            dfs(next);
        }
    }
}
int main() {
    int N, M;
    // N頂点, M本の有向辺
    cin >> N >> M;
    dist.resize(N);
    par.resize(N);
    REP(i, N) {
        dist[i] = -1;
        par[i] = 0;
    }
    A.resize(N - 1 + M);
    B.resize(N - 1 + M);
    map<int, int> cnt;
    edge.resize(N);
    REP(i, N) { cnt[i] = 0; } // return 0;
    REP(i, N - 1 + M) {
        cin >> A[i] >> B[i];
        A[i]--;
        B[i]--;
        cnt[B[i]]--;
        edge[A[i]].push_back(B[i]);
    }
    auto max = get_max(cnt);
    int root = max.first;
    // return 0;
    //幅優先
    dist[root] = 0;
    dfs(root);
    REP(i, N) { par[i]++; }
    par[root] = 0;
    REP(i, N) { cout << par[i] << endl; }
    // REP(i, N) { cout << dist[i] << endl; }
    return 0;
}

