vector<int> tpl_sort(vector<vector<int>>& r){
	int n= r.size();
	vector<int> rt(n), cnt(n); rt.reserve(n+2);
	for(auto& xl: r) for(auto x: xl) cnt[x]++;
	queue<int> qu;
	for(int i=0; i<n; i++) if(cnt[i]==0){ qu.emplace(i); rt[i] = 0;}
	while(!qu.empty()){
		auto cr = qu.front(); qu.pop();
		//rt.emplace_back(cr);
		for(auto x: r[cr]) if(--cnt[x] == 0){ qu.emplace(x); rt[x] = cr+1;}
	}
	return rt;
}



