    for (int i = 0; i < n - 1 + m; i++) {
        int a, b;
        cin >> a >> b; a--; b--;
        g[a].push_back({b});
    }
    auto scc = get_scc(g);
    V<int> res(n, -1);
    for (int i = 0; i < n; i++) {
        for (auto e: g[i]) {
            int j = e.to;
            if (res[j] == -1 || scc.id[res[j]] < scc.id[i]) res[j] = i;
        }
    }

    for (int d: res) cout << d + 1 << endl;
    return 0;
}

