        }
    }
    queue<ll> q;
    q.push(root);
    while(!q.empty()){
        ll cur=q.front();q.pop();
        for(auto c:child[cur]){
            true_parent[c]=cur;
            if(used[c]==false){
                q.push(c);
                used[c]=true;
            }
        }
    }
    REP(N){
        cout<<true_parent[i+1]<<endl;
    }
}

