//トポロジカルソート(1 orig)
vector<int> kahn(const Graph& g)
{
	const int V = g.size();
	vector<int> indeg(V, 0);	//indeg[i] : 頂点iに入ってくる辺の数
	stack<int> S;				//indeg[i] == 0 なるiの集合

	//隣接リストは辺の集合g[i]でノード一つを表す
	//各ノードについて入ってくる辺の数を計算
	for (Edges node : g) {
		for (Edge e : node) {
			indeg[e.dst]++;
		}
	}
	// 1 orig なのでVはノード数+1であることに注意
	for (int i = 1; i < V; i++) {
		if (indeg[i] == 0) S.push(i);
	}

	vector<int> ans;

	while (S.size() > 0) {
		int n = S.top();
		S.pop();

		ans.push_back(n);

		//入る辺のないノードを削除し、そのノードから出ているエッジのdstの参照カウンタを減らす
		for (Edge e : g[n]) {
			indeg[e.dst]--;
			if (indeg[e.dst] == 0) S.push(e.dst);
		}
	}
	return ans;

}

