// メイン
int main()
{
	int N, M;
	static vector<int> G[N_MAX + 1];
	static int jigen[N_MAX + 1];

	// 入力
	cin >> N >> M;
	REP(i, N + M - 1) {
		int a, b;
		cin >> a >> b;
		a--; b--;
		G[a].push_back(b);
		jigen[b]++;
	}

	// 親探し
	int root = 0;
	REP(i, N + M - 1) {
		if (jigen[i] == 0) {
			root = i;
			break;
		}
	}

	// トポロジカルソート
	queue<int> que;
	static int parentList[N_MAX + 1];
	que.push(root);
	parentList[root] = 0;
	while (!que.empty()) {
		int parent = que.front();
		que.pop();

		for (auto gOne : G[parent]) {
			jigen[gOne]--;
			if (jigen[gOne] == 0) {
				que.push(gOne);
				parentList[gOne] = parent + 1;
			}
		}

	}

	// リスト表示
	REP(i, N) {
		cout << parentList[i] << endl;
	}
	cout << endl;
	return 0;
}

