	//
	reg(i,1,n)dp[i]=-1;
	//
	reg(i,1,n){
		if(rev[i].size()==0){
			root=i;
			break;
		}
	}
	f(root);
	//
	queue<ll> Q;
	reg(i,1,n){
		if(v[i].size()==0)Q.push(i);
	}
	while(!Q.empty()){
		ll p = Q.front();Q.pop();
		if(p==root)continue;
		if(par[p]!=0)continue;
		ll max_id=0;
		rep(i,rev[p].size()){
