	if (N < 2)			 return false;
	else if (N == 2)	 return true;
	else if (N % 2 == 0) return false;
	for (ll i = 3; i <= sqrt(N); i += 2) { if (N % i == 0)	return false; }
	return true;
}

//---------------------------------------------------------------
