// 整数をビットのリストに変換する ll->vbool
//---------------------------------------------------------------
vbool to_bitlist(ll bit, ll fixed_size = 1) {
	if (bit == 0) return vbool(fixed_size, 0);
	vbool list;
	while (bit > 0) { list.emplace_back(bit & 1);	bit /= 2; }
	while (list.size() < fixed_size) { list.emplace_back(0); }
	return list;
}

