vector<int> tsort(int n, vector<int> *e) {
	stack<int> st;
	int ny[n] = {};
	for (int i=0; i<n; ++i) for (auto j:e[i]) ny[j]++;
	for (int i=0; i<n; ++i) if (ny[i]==0) st.push(i);
	vector<int> res;
	while (!st.empty()) {
		int ne = st.top(); st.pop();
		res.push_back(ne);
		for (auto i:e[ne]) if (--ny[i]==0) st.push(i);
	}
	return res;
}

