		return a.second > b.second;
	});

	VL ans(n);
	REPC(p, depth) {
		ll i = p.first;
		ll dep = p.second;
		if (v[i] == 0) {
			ans[i] = 0;
		} else if (v[i] == 1) {
			ans[i] = *parent[i].begin() + 1;
		} else {
			ll max = 0;
			ll tmp;
			REPC(x, parent[i]) {
				if (max < depth_old[x].second) {
					max = depth_old[x].second;
					tmp = x;
				}
			}
			ans[i] = tmp + 1;
		}
	}

	REPC(x, ans) {
		cout << x << " ";
	}
	cout << endl;
}

