int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    ll N,M;
    cin>>N>>M;
    vll A(N-1+M),B(N-1+M);
    vvll next(N);
    for(ll i=0;i<N-1+M;i++){
        cin>>A[i]>>B[i];
        A[i]--;B[i]--;
        next[A[i]].push_back(B[i]);
    }

    vector<bool> root_condidate(N,true);

    for(ll i=0;i<N-1+M;i++){
        root_condidate[B[i]]=false;
    }

    ll r=-1;
    for(ll i=0;i<N;i++){
        if(root_condidate[i])r=i;
    }

    vll ans(N,-1);
    ans[r]=0;
    vll open;
    open.push_back(r);

    while(open.size()>0){
        ll node=open[0];
        //printf("node=%d\n",node);
        open.erase(open.begin());

        for(ll i=0;i<next[node].size();i++){
            //printf("%d\n",next[node][i]);
            if(ans[next[node][i]]==-1)open.push_back(next[node][i]);
            ans[next[node][i]]=node+1;
        }
    }
    for(ll i=0;i<N;i++){
        printf("%lld\n",ans[i]);
    }

    return 0;
}

