int main() {
  int n, m;
  scan(n, m);
  vvi ab(n-1+m, vi(2));
  vector<set<int>> children(n);
  vector<set<int>> parents(n);
  rep (i, n-1+m) {
    int a, b;
    scan(a, b);
    a -= 1; b -= 1;
    children[a].insert(b);
    parents[b].insert(a);
  }
  int root = -1;
  rep (i, n) {
    if (parents[i].size() == 0) {
      root = i;
    }
  }
  assert(root != -1);

  vector<set<int>> true_children(n);
  deque<int> q = {root};
  while (!q.empty()) {
    int u = q.front();
    q.pop_front();
    for (int v : children[u]) {
      parents[v].erase(u);
