        input();
        vector<int> tree(N, -1);

        queue<int> que;

        que.push(root);
        while (!que.empty()) {
            int top = que.front();
            que.pop();

            int v = top;

            for (auto nv : G[v]) {
//                que.push(nv);
//                tree[nv] = v;
                if (rG[nv].size() == 1) {
                    que.push(nv);
                    tree[nv] = v;
                } else if (rG[nv].size() == 0) {
                    tree[nv] = v;
                } else {
                    rG[nv].erase(v);
                }
            }
        }


        for (int i = 0; i < N; ++i) {
            cout << tree[i] + 1 << endl;
        }

    }
};


