      scanf("%d %d", &n1, &n2);
      edges[n1].push_back(n2);
      rev[n2].push_back(n1);
   }//for
   for (int i = 1; i <= N; i++) {
      if (rev[i].empty())
         Q.push(i), depths[0].push_back(i);
       rem[i] = (int)rev[i].size();
   }//if
   while (!Q.empty()) {
      int curr = Q.front();
      Q.pop();
      for (auto& e : edges[curr]) {
         if (!--rem[e]) {
            Q.push(e);
            dist[e] = dist[curr] + 1;
            depths[dist[e]].push_back(e);
         }//if
      }//for
   }//while
   for (int i = N; i >= 0; i--) {
      for (auto& curr : depths[i]) {
         for (auto& e : edges[curr]) {
            if (!seen[e]) {
               seen[e] = 1;
               parent[e] = curr;
            }//if
         }//for
      }//for
   }//while
   for (int i = 1; i <= N; i++)
      printf("%d\n", parent[i]);
