int main(int argc, char const *argv[])
{
  int N, M;
  cin >> N >> M;
  vector<vector<bool>> edges(N + 1, vector<bool>(N + 1));
  vector<vector<bool>> edges_rev(N + 1, vector<bool>(N + 1, false));
  for (int i = 0, l = N + M - 1; i < l; ++i)
  {
    int fr, to;
    cin >> fr >> to;
    edges[fr][to] = true;
    edges_rev[to][fr] = true;
  }

  int root;
  for (int to = 1; to <= N; ++to)
  {
    auto &fr = edges_rev[to];
    if (none_of(fr.begin(), fr.end(), [](bool b) { return b; }))
    {
      root = to;
      break;
    }
  }

  vector<int> answer;
  answer.reserve(N);

  stack<int> st;
  st.push(root);
  while (!st.empty())
  {
    int current = st.top();
    answer.push_back(current);
    st.pop();

    for (int to = 1; to <= N; ++to)
    {
      if (edges[current][to])
      {

        edges[current][to] = false;
        edges_rev[to][current] = false;
        auto &fr = edges_rev[to];
        if (none_of(fr.begin(), fr.end(), [](bool b) { return b; }))
        {
          st.push(to);
        }
      }
    }
  }

  for (auto &i : answer)
  {
    cout << i << '\n';
  }
  cout.flush();
}

