int dfs(const vvi& qs,int u,vi& deps,vi& ps)
{
	if(deps[u]==-1){
		int d=-1,p=-1;
		for(int v:qs[u]){
			int t=dfs(qs,v,deps,ps);
			if(d<t)
				d=t,p=v;
		}
		deps[u]=d+1;
		ps[u]=p;
	}
	return deps[u];
}

