//Graph in adjcency list
class Graph{
public:
    int N;
    vector<vector<int>> adjlist;
    vector<int> tsort;

    Graph(int n) : N(n), adjlist(n+1){}

    void setEdge(int a, int b){
        adjlist[a].push_back(b);
    }

    void topologicalSort(){
        vector<int> deg(N);
        for(auto i : adjlist){
            for(auto j : i){
                deg[j]++;
            }
        }

        deque<int> deq;
        REP(i, N){
            if(deg[i] == 0){
                deq.push_back(i);
            }
        }

        while(!deq.empty()){
            int v = deq.front();
            deq.pop_front();
            tsort.push_back(v);
            for(auto i : adjlist[v]){
                deg[i]--;
                if(deg[i] == 0){
                    deq.push_back(i);
                }
            }
        }
    }

    void solve(){
        topologicalSort();
        vector<int> f(N);
        REP(i, N){
            f[tsort[i]] = i;
        }
        vector<vector<int>> in(N);
        REP(i, N){
            for(auto j : adjlist[i]){
                in[j].push_back(i);
            }
        }
        for(auto i : in){
            int m = -1;
            for(auto j : i){
                if(f[j] > m){
                    m = f[j];
                }
            }
            cout << (m == -1 ? 0 : tsort[m] + 1) << endl;
        }
    }
};

