        this->used.assign(num_node, false);
    }

    // 自分から自分にエッジを張る場合に注意(graph[0] = {0, 1, 2, ..}みたいなの)
    bool sort() {
        for (int u = 0; u < N; ++u) {
            for (int v : graph[u]) {
                indeg[v]++;
            }
        }

        for (int u = 0; u < N; ++u) {
            if (indeg[u] == 0 and not used[u]) {
                bfs(u);
            }
        }

        return this->result.size() == N;
    }

private:
    void bfs(int s) {
        std::queue<int> que;
        que.push(s);
        used[s] = true;
        while (not que.empty()) {
            int u = que.front();
            que.pop();
            result.emplace_back(u);

            for (int v : graph[u]) {
                indeg[v]--;
                if (indeg[v] == 0 and not used[v]) {
                    used[v] = true;
                    que.push(v);
                }
            }
        }
    }
};


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N, M;
    cin >> N >> M;

    auto graph = make_v<int>(N, 0);
    auto graph2 = make_v<int>(N, 0);
    unordered_map<int, int> ingree, degree;
    FOR(i, 0, N - 1 + M) {
        int A, B;
        cin >> A >> B;
        A--; B--;
        graph[A].emplace_back(B);
        graph2[B].emplace_back(A);
        ingree[A]++;
        degree[B]++;
    }

    TopologicalSort ts(N, graph);
    ts.sort();

    auto pos = make_v<int>(N);
    FOR(i, 0, N) {
        pos[ts.result[i]] = i;
    }

    int root = -1;
    FOR(i, 0, N) {
        if (degree[i] == 0) {
            root = i;
            break;
        }
    }

    queue<int> que;
    FOR(i, 0, N) {
        if (ingree[i] == 0) {
            que.emplace(i);
        }
    }
    auto parent = make_v<int>(N);
    fill_v(parent, -1);

    while (not que.empty()) {
        const int u = que.front(); que.pop();
        if (u == root) {
            continue;
        }

        int p = -1;
        int dist = -1;
        FOE(v, graph2[u]) {
