        in[t].push_back(s);
        out[s].push_back(t);
    }

    int root;
    for (int i = 0; i < N; i++) {
        if (in[i].size() == 0) {
            root = i;
            break;
        }
    }

    auto p = ts.build();

    for (int node : p) {
        for (int i = 0; i < out[node].size(); i++) {
            parent[out[node][i]] = node + 1;
        }
    }

    for (int i = 0; i < N; i++) {
        cout << parent[i] << "\n";
    }

    return 0;
}

