void dfs(ll now_parent, ll now_height){
	now_height++;
	for (ll z=0;z<node[now_parent].size();z++){
		ll now = node[now_parent][z];
		if (height[now] == 0) {
			height[now] = now_height; 
			parent[now] = now_parent;
			dfs(now,now_height);
		}
		else if (now_height > height[now]) parent[now] = now_parent;
	}
}

