{
	vec p(n, 0);
	rep(i, n)
	{
		rep(j, gr[i].size())
		{
			p[gr[i][j]]++;
		}
	}

	vec ans;
	queue<lint> q;
	rep(i, n)
	{
		if (p[i] == 0)
			q.push(i);
	}

	while (!q.empty())
	{
		lint next = q.front();
		q.pop();
		rep(i, gr[next].size())
		{
			p[gr[next][i]]--;
			if (p[gr[next][i]] == 0)
				q.push(gr[next][i]);
		}
		ans.push_back(next);
	}
	return ans;
}

