bool used[MAX]={};
int ind[MAX];
vector<int> dist(MAX,0);

void bfs(int s){
    queue<int> q;
    q.push(s);
    used[s]=true;
    dist[s]=0;
    while(!q.empty()){
        int u=q.front(); q.pop();
        out.push_back(u);
        for(auto it=g[u].begin();it!=g[u].end();it++){
            int v=*it;
            ind[v]--;
            dist[v]=max(dist[u]+1,dist[v]);
            if(ind[v]==0&&used[v]==false){ //入次数が0になったら追加
                used[v]=true; //再訪しない
                q.push(v);
            }
        }
    }
}

void tsort(){
    for(int i=0;i<N;i++){
        ind[i]=0;
    }
    for(int u=0;u<N;u++){
        for(auto it=g[u].begin();it!=g[u].end();it++){
            int v=*it;
            ind[v]++; //各頂点の次数を計算
        }
    }
    for(int u=0;u<N;u++){
        if(ind[u]==0&&used[u]==false) bfs(u);
    }
    //for(int i=0;i<out.size();i++){
        //cout << out[i] << endl;
    //}
}

