int ganbaru(ll now, ll depth){
	while(!edgelist[now].empty()){
		ll buf = edgelist[now].back(); edgelist[now].pop_back();
		if(parent[buf][0] == -1 || parent[buf][1] < depth+1){
			parent[buf][0] = now;
			parent[buf][1] = depth+1;
			ganbaru(buf, depth+1);
		}
	}
	return 0;
}

