void toposort(int u) {
	seen[u] = true;
	for (auto &v : g[u]) {
		if (!seen[v]) {
			toposort(v);
		}
	}
	sorted_vertices.pb(u);
}

void recover(int u) {
	seen[u] = true;
	vector<pii> children;
	for (auto &v : g[u]) {
		children.pb({idx[v], v});
	}
	sort(children.begin(), children.end());
	for (auto &p : children) {
		if (!seen[p.second]) {
			parent[p.second] = u;
			recover(p.second);
