    vector<T> Dijkstra(int s) {
        const T INF = numeric_limits<T>::max() / 5;
        using P = pair<T, int>;
        int N = (*this).size();
        vector<T> dist(N, INF);
        //vector<int> bef(N, -1);
        priority_queue<P, vector<P>, greater<P>> que;
        dist[s] = 0;
        que.emplace(dist[s], s);
        while (!que.empty()) {
            P p = que.top();
            que.pop();
            int now = p.second;
            if (dist[now] < p.first)
                continue;
            for (auto& p : (*this)[now]) {
                int nxt = p.to;
                T cost = p.cost;
                if (dist[nxt] > dist[now] + cost) {
                    dist[nxt] = dist[now] + cost;
                    //bef[nxt] = now;
                    que.emplace(dist[nxt], nxt);
                }
            }
        }
        return dist;
        //return make_pair(dist, bef);
    }
