    vector<vector<T>> WarshallFloyd() {
        int N = (*this).size();
        const T INF = numeric_limits<T>::max() / 3;
        vector<vector<T>> ret(N, vector<T>(N, INF));
        for (int i = 0; i < N; i++) {
            ret[i][i] = 0;
            for (auto& e : (*this)[i]) {
                ret[i][e.to] = e.cost;
            }
        }
        for (int k = 0; k < N; k++) {
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    if (ret[i][j] > ret[i][k] + ret[k][j])
                        ret[i][j] = ret[i][k] + ret[k][j];
                }
            }
        }
        return ret;
    }
