    //--------Kruskal--------
    //verified
private:
    vector<int> Kruskal_data;
    bool Kruskal_unite(int x, int y) {
        x = Kruskal_root(x), y = Kruskal_root(y);
        if (x == y)
            return (false);
        if (Kruskal_data[x] > Kruskal_data[y])
            swap(x, y);
        Kruskal_data[x] += Kruskal_data[y];
        Kruskal_data[y] = x;
        return (true);
    }
    int Kruskal_root(int k) {
        if (Kruskal_data[k] < 0)
            return (k);
        return (Kruskal_data[k] = Kruskal_root(Kruskal_data[k]));
    }
    bool Kruskal_same(int x, int y) {
        return Kruskal_root(x) == Kruskal_root(y);
    }
    int Kruskal_size(int k) {
        return (-Kruskal_data[Kruskal_root(k)]);
    }
    //
public:
    template <class Compare = less<T>>
    pair<T, vector<bool>> Kruskal(bool flag = false) {
        struct edge2 {
            int from, to;
            T cost;
            bool used;
            int id;
            edge2(int from, int to, T cost, int id) : from(from), to(to), cost(cost), used(false), id(id) {}
        };
        vector<edge2> edges;
        int N = (*this).size();
        Kruskal_data.assign(N, -1);
        for (int i = 0; i < (int)(*this).size(); i++) {
            auto& V = (*this)[i];
            for (auto& e : V) {
                edges.emplace_back(i, e.to, e.cost, e.id);
            }
        }
        sort(edges.begin(), edges.end(), [](const edge2& a, const edge2& b) {
            return Compare()(a.cost, b.cost);
        });
        T ret = 0;
        vector<bool> V;
        if (flag)
            V.resize(M, false);
        for (auto& e : edges) {
            if (Kruskal_unite(e.from, e.to)) {
                ret += e.cost;
                e.used = true;
            }
        }
        if (flag)
            for (auto& e : edges) {
                assert(e.id >= 0 && e.id < M);
                if (e.used)
                    V[e.id] = true;
            }
        if (N == Kruskal_size(0))
            return make_pair(ret, V);
        else
            return make_pair(-1, V);
    }
