    //--------TopologicalSort--------
    //unverified
public:
    vector<int> TopologicalSort() {
        assert(!undirected);
        int N = (*this).size();
        vector<int> deg(N);
        for (auto& V : (*this))
            for (auto& e : V)
                deg[e.to]++;
        stack<int> st;
        for (int i = 0; i < N; i++)
            if (deg[i] == 0)
                st.emplace(i);
        vector<int> ret;
        ret.reserve(N);
        while (!st.empty()) {
            auto x = st.top();
            st.pop();
            ret.emplace_back(x);
            for (auto& e : (*this)[x])
                if (--deg[e.to] == 0) {
                    st.emplace(e.to);
                    ans[e.to] = x + 1;
                }
        }
        return ret;
    }
    //
