const int maxn=30;

int head[maxn],ip,indegree[maxn];
int n,m,seq[maxn];
int fa[maxn];
struct note
{
    int v,next;
};
std::vector<int> edge[maxn];
void addedge(int u,int v)
{
    edge[u].push_back(v);
}

int topo()///拓扑，可做模板
{
    queue<int>q;
    for(int i=0; i<n; i++)
    {
        //indeg[i]=indegree[i];
        if(indegree[i]==0){
            fa[i] = 0;
            q.push(i);
        //    std::cout << i<<"!" << std::endl;
        }
    }
    int k=0;
    bool res=false;
    while(!q.empty())
    {
        if(q.size()!=1)res=true;
        int u=q.front();
        q.pop();
        seq[k++]=u;
        for(auto &it : edge[u])
        {
            int v=it;
            indegree[v]--;
            if(indegree[v]==0){
                fa[v] = u;
                q.push(v);
            }
        }
    }
    if(k<n)return -1;///存在有向环，总之不能进行拓扑排序
    if(res)return 0;///可以进行拓扑排序，并且只有唯一一种方式，seq数组即是排序完好的序列
    return 1;///可以进行拓扑排序，有多种情况，seq数组是其中一种序列
}

int main(){
  //  int n,m;
    std::cin >> n >> m;
    for(int i = 1; i <= n + m - 1; i++){
        int u,v;
        std::cin >> u >> v;
        addedge(u,v);
        indegree[v] ++;
      //  std::cout << u << v <<indegree[v] << '!' << std::endl;
    }
    topo();
    for(int i = 1; i <= n; i++){
        std::cout << fa[i] << std::endl;
    }
}

