void solve() {
    int n, m;
    cin >> n >> m;
    Graph forw(n), rev(n);
    for (int i=0; i<n+m-1; i++) {
        int a, b;
        cin >> a >> b;
        forw.at(a-1).push_back(b-1);
        rev.at(b-1).push_back(a-1);
    }

    vector<int> res(n, -1);
    int root = -1;
    for (int i=0; i<n; i++) {
        if (rev.at(i).empty()) {
            res.at(i) = 0;
            root = i;
            break;
        }
    }
    queue<int> que;
    que.push(root);
    while (!que.empty()) {
        int cur = que.front(); que.pop();
        for (int next : forw.at(cur)) {
            if (res.at(next) != cur + 1) {
                res.at(next) = cur + 1;
                que.push(next);
            }
        }
    }

    for (int i=0; i<n; i++) {
        cout << res.at(i) << '\n';
    }
}

