int main() {
    cin.sync_with_stdio(false);
    cin.tie(0);

    int N, M;
    cin >> N >> M;
    vector<int> A(N - 1 + M, 0);
    vector<int> B(N - 1 + M, 0);
    vector<int> is_root(N, 1);
    vector<vector<int> > children(N);
    for (int i = 0; i < N - 1 + M; ++i) {
        int a1, b1;
        cin >> a1 >> b1;
        A[i] = a1 - 1;
        B[i] = b1 - 1;
        children[A[i]].push_back(B[i]);
        is_root[B[i]] = 0;
    }
    const int root = distance(is_root.begin(), find(all(is_root), 1));

    vector<int> dist(N, -1);
    vector<int> real_parent(N, -1);
    struct Item { int node, parent, dist; };
    deque<Item> que;
    que.push_back(Item {root, -1, 0});
    while (!que.empty()) {
        auto i = que.front(); que.pop_front();
        if (dist[i.node] < i.dist) {
            dist[i.node] = i.dist;
            real_parent[i.node] = i.parent;
            for (auto c : children[i.node]) {
                que.push_back(Item {c, i.node, i.dist + 1});
            }
        }
    }

    for (auto p : real_parent) {
        cout << p + 1 << endl;
    }

    return 0;
}

