#include <bits/stdc++.h>
using namespace std;
const int N = 1e5 + 10;
int n, m, dis[N], dg[N], par[N];
bool mark[N];
vector<int> gr[N], rg[N];
void dfs(int v, int prn = -1) {
	mark[v] = 1;
	for (auto u : gr[v])
		if (!mark[u])
			dis[u] = dis[v] + 1, dfs(u, v);
}
void getPar() {
	memset(mark, 0, sizeof(mark));
	queue<int> q;
	for (int i = 0; i < n; i++) 
		if (!(int) gr[i].size())
			q.push(i);
	while (!q.empty()) {
		int v = q.front();
		q.pop();
		pair<int, int> mx = {-1, -1};
		for (auto u : rg[v])
			mx = max(mx, {dis[u], u});
		par[v] = mx.second;;
		if (mx.second > -1 && !mark[mx.second])
			q.push(mx.second);
	}
	return;
}
int main() {
	cin >> n >> m;
	for (int i = 1; i < n + m; i++) {
		int x, y;
		cin >> x >> y;
		x--, y--;
		gr[x].push_back(y);
		rg[y].push_back(x);
		dg[y]++;
	}
	for (int i = 0; i < n; i++)
		if (dg[i] == 0)
			dfs(i);
	getPar();
	for (int i = 0; i < n; i++) 
		cout << par[i] + 1 << "\n";
	return 0;
}

