void dfs2(int idx, int p) {
  if(used[idx]) return;
  used[idx] = true;
  par[idx] = p;
  vector< pair< int, int > > reach;
  for(auto to : g[idx]) {
    reach.emplace_back(pos[to], to);
  }
  sort(begin(reach), end(reach));
  for(auto q : reach) {
    dfs2(q.second, idx);
  }
}


