        H[b].push_back(a);
    }
    ll root=-1;
    REP(i, N) if(H[i].size()==0) root = i;
    topologicalSort(root, 0);
    vector<ll> res(N);
    REP(i, N){
        if((int)H[i].size()==1) res[i] = H[i][0]+1;
        else if(H[i].size()==0) res[i] = 0;
        else{
            ll pid = -1;
            for(ll j=0; j<H[i].size(); j++){
                if(pid< topo[H[i][j]]){
                    pid = topo[H[i][j]];
                    res[i] = H[i][j]+1;
                } 
            }
        }
    }
    REP(i, N) cout << res[i] << endl;
    return 0;
}

