typedef pair<int, int> P; // min distance, vertex index

class DirectedGraph {
    struct edge {
        int to;
        int cost;
    };

public:
    int V;
    vector<vector<edge> > G;

    DirectedGraph(int v) : G(v), V(v) {}

    void add_edge(int u, int v, int cost) {
        edge add_e = {v,cost};
        G[u].push_back(add_e);
    }

    // O(E * logV)
    vector<int> dijkstra(int s) {
        vector<int> d(V, 0);
        d[s] = 0;

        priority_queue<P, vector<P>, less<P> > que;
        que.push(make_pair(0,s));
        while (!que.empty()) {
            P  p = que.top(); que.pop();
            int v = p.second;
            if (d[v] > p.first) continue;
            for (edge e : G.at(v)) {
                if (d[e.to] < d[v] + e.cost) {
                    d[e.to] = d[v] + e.cost;
                    que.push(make_pair(d[e.to], e.to));
                }
            }
        }

        return move(d);
    }
};

bool _mysort(pair<int, int> a, pair<int, int> b) {
    if (a.first != b.first)
        return a.first < b.first;
    else {
        return a.second < b.second;
    }
}

