  while(!q.empty()) {
    int c = q.front(); q.pop();
    auto it = edge.find(c);
    if(it != edge.end()) {
      for(const auto& x : it->second) {
        parent[x-1] = c;
        q.push(x);
      }
    }
  }
  for(int i=0; i<N; ++i)
    cout << parent[i] << endl;
}

