int dfs(vector< vector< int > > &G, vector< int > &level, int x) {
	if (level[x] != -1)
		return level[x];
	int ret = -1;
	rep(i, G[x].size()) {
		int j = G[x][i];
		chmax(ret, dfs(G, level, j));
	}
	return level[x] = ret + 1;
}

