int n, m;
vector<int> edg[100003];
vector<int> ok[100003];
int cnt[100003];
int ans[100003];

int main() {
	cin >> n >> m;
	for (int i = 0; i < n - 1 + m; i++) {
		int a, b; cin >> a >> b;
		edg[a].push_back(b);
		ok[a].push_back(1);
		cnt[b]++;
	}
	int rt;
	for (int i = 1; i <= n; i++) if (cnt[i] == 0) rt = i;
	deque<pair<int, int>> que;
	que.push_back({ rt, 0 });
	ans[rt] = -1;
	while (!que.empty()) {
		int idx = que.front().first, par = que.front().second;
		que.pop_front();
		if (ans[idx] == par) continue;
		ans[idx] = par;
		for (int i = 0; i < (int)edg[idx].size(); i++) {
			if (ok[idx][i] != 1) continue;
			ok[idx][i] = 0;
			int to = edg[idx][i];
			que.push_back({ to, idx });
		}
	}
	for (int i = 1; i <= n; i++) cout << ans[i] << endl;;
	return 0;
}

