int parentNode[100000];
int main() {
    int N, M;

    cin >> N >> M;
    for (int i=0; i<N-1+M; i++) {
        int a, b;
        cin >> a >> b;
        inedge[b-1].push_back(a-1);
        canMoveTo[a-1].push_back(b-1);
    }
    int rootNode = -1;
    for (int i=0; i<N; i++) {
        if (inedge[i].size() == 0) rootNode = i;
    }
    if (rootNode == -1) return -1;
    //bfs
    queue<int> q;
    q.push(rootNode);
    step[rootNode] = 0;
    parentNode[rootNode] = 0;
    while (!q.empty()) {
        int node = q.front();
        q.pop();
        for (auto child : canMoveTo[node]) {
            int putting = step[node] + 1;
            step[child] = putting;
            parentNode[child] = node+1;
            q.push(child);
        }
    }
    //cerr << "bfs end" << endl;

    for (int i=0; i<N; i++) {
        cout << parentNode[i] << endl;
    }
    return 0;
}

