vector<int> topological_sort(const vector<vector<int>> &G) {
    int V = G.size();
    vector<int> L;        // トポロジカルソートされたリスト
    queue<int> S;         // 入力辺がないノードたち
    vector<int> Sink(V);  // 入力の個数

    for (int i = 0; i < V; i++)
        for (auto to : G[i]) Sink[to]++;

    for (int i = 0; i < V; i++)
        if (Sink[i] == 0) S.push(i);

    while (!S.empty()) {
        int from = S.front();
        L.push_back(from);
        S.pop();
        for (auto to : G[from]) {
            Sink[to]--;
            if (Sink[to] == 0) S.push(to);
        }
    }
    return L;
}

