vector<int> sccd(vector<vector<int>>& g) {
  int n = g.size();
  vector<vector<int>> rG(n);
  for(int i = 0;i < n;i++) {
    for(auto& e : g[i]) rG[e].push_back(i);
  }

  vector<bool> vis(n,false);
  vector<int> vs;
  vector<int> res(n,-1);
  function<void(int)> dfs = [&](int v) {
    vis[v] = true;
    for(auto& e : g[v]) {
      if(!vis[e]) dfs(e);
    }
    vs.push_back(v);
  };

  function<void(int,int)> rdfs = [&](int v,int k) {
    vis[v] = true;
    res[v] = k;
    for(int to : rG[v]) {
      if(!vis[to]) rdfs(to,k);
    }
  };

  for(int i = 0;i < n;i++) {
    if(!vis[i]) dfs(i);
  }

  vis.assign(n,false);
  int k = 0;
  for(int i = n - 1;i >= 0;i--) {
    if(!vis[vs[i]]) rdfs(vs[i] , k++);
  }
  return res;
}



