using namespace std;
const int N = 100005;
int n, m, f[N], visit[N];
vector <int> v[N], to[N], p;
void dfs (int x) {
	//cout << x << endl;
	visit[x] = 1;
	for (int i = 0; i < v[x].size(); i ++) {
		int y = v[x][i];
		for (int j = 0; j < to[y].size(); j ++)
			if (to[y][j] != x && visit[to[y][j]] == 1) {
				to[y].erase(to[y].begin() + j);
				j --;
			}
	}
	for (int i = 0; i < v[x].size(); i ++)
		dfs (v[x][i]);
	visit[x] = 0;
	return ;
}
int main() {
	cin >> n >> m;
	for (int i = 1; i < n + m; i ++) {
		int x, y;
		cin >> x >> y;
		v[x].push_back(y);
		to[y].push_back(x);
	}
	for (int i = 1; i <= n; i ++)
		if (to[i].size() == 0)
			dfs (i);
	for (int i = 1; i <= n; i ++)
		if (to[i].size() == 0)
			cout << 0 << endl;
		else
			cout << to[i][0] << endl;
	return 0;
}

