void dfs(int node, int par, int dis){
   //cout << node << ", "<< par <<", "<< dis << endl;
   if(dist[node] < dis){
      dist[node]=dis;
      parent[node]=par;
   }
   for(int ei = 0; ei < (int)edge[node].size(); ei++){
      int nxt = edge[node][ei];
      dfs(nxt, node, dis+1);
   }
   return;
}

