#define P pair<ll, ll>
const int N_MAX = 100010;
vector<vector<int>> adj(N_MAX), radj(N_MAX);
double d[N_MAX], par[N_MAX];
ll N, M;

void dijkstra(ll s) {
  priority_queue<P, vector<P>, greater<P>> q;
  fill_n(par, N, 0); par[s] = -1;
  fill_n(d, N, 0); q.push(P(0, s));
  while (!q.empty()) {
    P p = q.top(); q.pop();
    ll v = p.second;
    for (auto e: adj[v]) {
      if (d[e] <= d[v]) {
        d[e] = d[v]+1;
        par[e] = v;
        q.push(P(d[e], e));
      }
    }
  }
}

int main() {
  cin >> N >> M;
  // adj.resize(N); radj.resize(N);
  rep(i,N-1+M) {
    int A, B; cin >> A >> B; A--; B--;
    adj[A].push_back(B);
    radj[B].push_back(A);
  }
  int root = 0;
  rep(i,N) if (radj[i].empty()) root = i;
  dijkstra(root);
  // rep(i,N) cout << d[i] << " "; cout << endl;
  rep(i,N) cout << par[i]+1 << " "; cout << endl;
  return 0;
}

#include<bits/stdc++.h>

using namespace std;

void restore(int root, vector<vector<int>> &graph, vector<int> &tree){
  queue<int> q;
  q.push(root);

  while(!q.empty()){
    int node = q.front();
    q.pop();
    for(int child : graph[node]){
      tree[child]++;
      if(!tree[child]){
        tree[child] = node + 1;
        q.push(child);
      }
    }
  }
}

int main(){
  int N, M;
  cin >> N >> M;

  vector<int> tree(N, 0);
  vector<vector<int>> graph(N);

  for(int j = 0; j < N - 1 + M; j++){
    int A, B;
    cin >> A >> B;
    A--;
    B--;

    graph[A].push_back(B);
    tree[B]--;
  }

  int root;
  for(int i = 0; i < N; i++){
    if(!tree[i]){
      root = i;
      break;
    }
  }

  restore(root, graph, tree);

  for(int i = 0; i < N; i++){
    cout << tree[i] << endl;
  }

  return 0;
}

