void input(){
	cin>>n>>m;
	for(int i=1;i<=n+m-1;i++){
		cin>>a[i]>>b[i];
		f[b[i]]++;
		mp[P(b[i],a[i])]=i;
		v[a[i]].eb(b[i]);
		r[b[i]].eb(a[i]);
	}
	return;
}

void solve(){
	for(int i=1;i<=n;i++){
		if(!f[i]){
			root=i;
			break;
		}
	}
	if(root){
		int nex=v[root][0];
		fl[nex]=true;
		ans[nex]=root;
		ans[root]=0;
		for(int i=1;i<=n;i++){
			if(i==nex||i==root)continue;
			ans[i]=r[i][0];
		}
	}
	else{
		int w=0;
		for(int i=1;i<=n;i++){
			w+=f[i]-1;
		}
		for(int i=1;i<=n;i++){
			if(!v[i].size())continue;
			root=i;
			break;
		}
		int nex=v[root][0];
		fl[nex]=true;
		ans[nex]=root;
		ans[root]=0;
		for(int i=1;i<=n;i++){
			if(i==nex||i==root)continue;
			ans[i]=r[i][0];
		}
	}
	for(int i=1;i<=n;i++){
		cout<<ans[i]<<endl;
	}
	return;
}

int main(){
	input();
	solve();
	return 0;
}

