vvll a(0, vll(0));
vpl b(0);
vll k(0);

void solve(ll t, ll d) {
	vll l(0);
	FOR(i, 0, (ll)a[t].sz - 1) {
		if (k[a[t][i]] > 1) {
			l.pb(a[t][i]);
		}
		else if (b[a[t][i]].se < d) {
			b[a[t][i]].fi = t;
			b[a[t][i]].se = d;
			if (a[a[t][i]].sz > 0) solve(a[t][i], d + 1);
		}
	}
	FOR(i, 0, (ll)l.sz - 1) {
		if (b[l[i]].se < d) {
			b[l[i]].fi = t;
			b[l[i]].se = d;
			if (a[l[i]].sz > 0) solve(l[i], d + 1);
		}
	}
	return;
}

