	li(n, m);
	a.assign(n + 1, vll(0));
	b.assign(n + 1, mp(0, 0));
	k.assign(n + 1, 0);
	ll p;
	ll q;
	FOR(i, 0, n + m - 2) {
		cin >> p;
		cin >> q;
		a[p].pb(q);
		k[q]++;
	}
	ll s = 0;
	FOR(i, 1, n) {
		if (k[i] == 0) s = i;
	}
	solve(s, 1);
	FOR(i, 1, n) {
		sal(b[i].fi);
	}

}

