void bfs(int root, V<int> &dist, const V<V<int>> &to) {
  queue<int> q;
  q.push(root);
  while(sz(q)) {
    int v = q.front(); q.pop();
    for(int nv : to[v]) {
      chmax(dist[nv], dist[v] + 1);
      q.push(nv);
    }
  }
}

