struct edge{int to,dir;};


struct graph{
	int n;
	vector<vector<int>>g;
	vector<bool>used;	
	vector<int>ts;	
	vector<int>pr;

	graph(int _n){
		n=_n;
		g.resize(n);
		used.resize(n,false);
		pr.resize(n,-1);
	};

	void add_edge(int a,int b){
		g[a].push_back(b);
	}

	void traverse(int i){
		if(used[i])return;
		used[i]=true;
		for(auto&& w:g[i]){
			traverse(w);
		}
		ts.push_back(i);
	}
	void tsort(){
		for(int i=0;i<n;i++){
			traverse(i);
		}
		reverse(begin(ts),end(ts));
	}

	int get_pr(int i){
		if(i==ts[0])return 0;
		int x=find(begin(ts),end(ts),i)-begin(ts);
		for(int j=x-1;j>=0;j--){
			if(count(begin(g[ts[j]]),end(g[ts[j]]),i)>0)return ts[j];
		}
	}




	void set_pr(){
		tsort();
		pr[ts[0]]=0;
		for(int i=0;i<n;i++){
			pr[i]=get_pr(i);
		}
	}

};


int main(){
	int n,m;cin>>n>>m;
	graph gr(n);
	for(int i=0;i<n+m-1;i++){
	   int x,y;cin>>x>>y;x--;y--;
		gr.add_edge(x,y);
	}
	 gr.set_pr();
	for(auto&& w:gr.pr)cout<<w<<endl;


}

