  vector<int> res;
  queue<int> que;
  que.push(root);

  while (que.size()) {
    int p = que.front();
    que.pop();
    res.push_back(p);
    for (auto&& i : ga[p]) {
      gb[i].erase(p);
      if (gb[i].size() == 0) {
        que.push(i);
      }
    }
  }

  return res;
