		for(int i=t[v].size()-1;i!=-1;--i) if(maxn<dep[t[v][i]]) {maxn=dep[t[v][i]];k=t[v][i];}
		ans[v]=k;dep[v]=dep[k]+1;
	}
	for(int i=head[v];i;i=seg[i].next) dfs(seg[i].to);
}
int main()
{
	scanf("%d%d",&n,&m);
	for(int i=1;i<n+m;++i) {
		scanf("%d%d",&A,&B);check[B]=true;
		addseg(A,B);t[B].push_back(A);
	}
	for(int i=1;i<=n;++i) if(!check[i]) {dfs(i);break;}
	for(int i=1;i<=n;++i) printf("%d\n",ans[i]);
	return 0;
}

#include <iostream>
#include <vector>
#include <list>
using namespace std;
typedef struct edge
{
    int out;    //出力端のノード
    int in;     //入力端のノード
    int status; //枝の有効無効(0:有効 1:無効)(初期値:0)
} edge;
typedef struct node
{
    int input;  //ノードの入力端の数
    int parent; //親ノード
    int num;    //ノード自身の番号
} node;
typedef struct nodes
{
    vector<node> nodeList;    //ノードを格納したベクター
    list<int> noInputNodeQue; //入力端を持たないノードのキュー
    int root;                 //根のノード
    //初期化処理
    //引数 : 要素数 int
    void nodesInitializ(int N)
    {
        this->root = -1;
        vector<node> list(N);
        for (int i = 0; i < N; i++)
        {
            list[i].num = i;
            list[i].input = 0;
            list[i].parent = -1;
        }
        this->nodeList = list;
    }
} nodes;
typedef struct edgeList
{
    vector<edge> edgeList; //エッジのリスト
    int edgeNum;           //エッジの個数
    //エッジの入力処理
    //引数：ノード(nodes)
    void inputEdge(nodes &nodes)
    {
        vector<edge> tmp(this->edgeNum);
        this->edgeList = tmp;
        for (int i = 0; i < this->edgeNum; i++)
        {
            cin >> this->edgeList[i].out >> this->edgeList[i].in; //入力
            this->edgeList[i].out--;
            this->edgeList[i].in--;
            this->edgeList[i].status = 0;                 //状態の初期化
            nodes.nodeList[this->edgeList[i].in].input++; //入力端の数を増やす
        }
        cout << "入力完了" << endl;
    }
} edges;
//終了していれば0,終了していなければ1を返す
int isDone(const vector<edge> &edList)
{
    for (auto ed : edList)
    {
        if (ed.status == 0)
        {
            return 1;
        }
    }
    return 0;
}
int main()
{
    int N, M;
    cin >> N >> M;
    cout << "エッジ入力開始" << endl;
    //ノードの初期化
    nodes nodes;
    nodes.nodesInitializ(N);
    //枝の入力
    edgeList edges;
    edges.edgeNum = N + M - 1;
    edges.inputEdge(nodes);
    /*ソート*/
    while (isDone(edges.edgeList) == 1)
    {
        nodes.noInputNodeQue.clear();
        //入力端のないノードのリストを作る
        for (int i = 0; i < N; i++)
        {
            if (nodes.nodeList[i].input == 0)
            {
                nodes.nodeList[i].input = -1;
                nodes.noInputNodeQue.push_back(i);
            }
        }
        //枝の処理
        //node:処理中の頂点
        for (auto &node : nodes.noInputNodeQue)
        {
            for (auto &ed : edges.edgeList)
            {
                if (ed.status == 0 && ed.out == node)
                {
                    ed.status = 1;
                    nodes.nodeList[ed.in].input--;
                    if (nodes.nodeList[ed.in].input == 0)
                    {
                        if (nodes.root == 0)
                        {
                            nodes.root = ed.out;
                        }
                        nodes.nodeList[ed.in].parent = ed.out;
                    }
                }
            }
        }
    }
    for (int i = 0; i < N; i++)
    {
        if (i == nodes.root)
        {
            cout << "0" << endl;
        }
        else
        {
            cout << nodes.nodeList[i].parent + 1 << endl;
        }
    }
    return 0;
}

