			root = i;
			break;
		}
	}

	std::queue<LL>queue;
	std::vector<LL>depth(N + 1, -1);
	depth[root] = 0;
	queue.push(root);
	while (!queue.empty())
	{
		LL v = queue.front(); queue.pop();
		for (auto u : G[v])
		{
			if (depth[u] == -1) queue.push(u);
			depth[u] = std::max(depth[u], depth[v] + 1);
		}
	}

	std::vector<LL>ans(N + 1, -1);
	ans[root] = 0;
	queue.push(root);
	while (!queue.empty())
	{
		LL v = queue.front(); queue.pop();
		for (auto u : G[v])
		{
			if (ans[u] == -1)
			{
				if (depth[u] == depth[v] + 1) ans[u] = v;
				queue.push(u);
			}
		}
	}

	rep(i, N) out << ans[i + 1] << std::endl;
}

