	flag[v] = 1;
	sibl[v].set(v, 1);
	for (int i = 0; i < (int)e[v].size(); i++)
		if (!flag[e[v][i]]) {
			dfs_sibl(e[v][i]);
			sibl[v] |= sibl[e[v][i]];
		}
}


void dfs(int v) {
	nnew[v] = 1;
	for (int i = 0; i < (int)e[v].size(); i++)
		if (!nnew[e[v][i]]) {
			int Ok = 1;
			for (int j = 0; j < (int)e_back[e[v][i]].size(); j++)
				if (sibl[v].test(e_back[e[v][i]][j])) {
					Ok = 0;
					break;
				}
			if (Ok)
				for (int j = 0; j < (int)e[e[v][i]].size(); j++)
					if (nnew[e[e[v][i]][j]]) {
						Ok = 0;
						break;
					}
			//if ((sibl[v] & bts[e[v][i]]).count() == 0) {
			if (Ok) {
				ans[e[v][i]] = v;
				dfs(e[v][i]);
			}
		}
}


