vi d;
int bellmanford(v(ed) &ES,int V,int E,int s) {
  // ES[i] = ed(c,P(f,t)) means that from `f` to `t` 's cost is `c`
  // returns meaning
  // 0 -> no negative cycle, 
  // -1 -> has negative cycle
  d = vi(V,INF);
  d[s] = 0;
  int cnt = 0;
  while(true) {
    bool update = false;
    rep(i,E) {
      ed e = ES[i];
      if(d[e.second.first] != INF && d[e.second.second] > d[e.second.first] + e.first) {
        d[e.second.second] = d[e.second.first] + e.first;
        update = true;
      }
    }
    if(!update) break;
    cnt++;
    if(cnt >= V) {
      return -1;
    }
  }
  return 0;
}

