vector<int> topological_sort(vector<vector<int>> Edges, int root){
	stack<int> st;
	st.push(root);

	vector<int> ans;

	vector<int> h(Edges.size(), 0);

	for (vector<int> E: Edges){
		for (int e: E){
			h[e]++; 
		}
	}

	while(st.size()){
		int i = st.top(); st.pop();
		ans.push_back(i);

		for (const auto& e : Edges[i-1]){
			h[e]--;
			if (h[e] == 0) st.push(e+1);
		}
	}
  	return ans;
}

