			fa[ver[i]] = x, d[ver[i]] = d[x] + 1;
	}
}
void spfa(int root)
{
	queue<int> q;
	q.push(root);
	vis[root] = 1;
	while (!q.empty())
	{
		int x = q.front();
		q.pop();
		for (int i = first[x]; i; i = nxt[i])
		{
			int  y = ver[i];
			if (d[y] < d[x] + 1)
			{
				d[y] = d[x] + 1;
				fa[y] = x;
				if (!vis[y])
				{
					vis[y] = 1;
					q.push(y);
				}
			}
		}
