void Main()
{
	int N, M;
	std::cin >> N >> M;;
	std::vector<std::set<int>> childs(N);
	std::vector<std::set<int>> parents(N);
	for (int i : boost::irange(0, N + M - 1))
	{
		int a, b;
		std::cin >> a >> b;
		--a; --b;
		childs[a].emplace(b);
		parents[b].emplace(a);
	}
	std::vector<int> roots(N);
	std::set<int> rest;
	int root = 0;
	for (int i : boost::irange(0, N))
	{
		if (parents[i].size() != 0)
		{
			rest.emplace(i);
		}
		else
		{
			root = i;
		}
	}
	std::set<int> check = { root };
	while (check.size())
	{
		std::set<int> next;
		for (int i : check)
		{
			for (auto c : childs[i])
			{
				next.emplace(c);
				roots[c] = i + 1;
			}
		}
		std::swap(next, check);
	}
	for (auto const& v : roots)
	{
		out::write_line(v);
	}
}

