void dijkstra(int s){
  priority_queue<P, vector<P>, greater<P>> que;
  rep(i,n) d[i] = -INF;
  d[s] = 0;
  que.push(P(0,s));
  while(!que.empty()){
    P p = que.top();
    que.pop();
    int v = p.second;
    if(d[v] > p.first) continue;
    rep(i, g[v].size()){
      edge e = g[v][i];
      if(d[e.to] < d[v] + e.cost){
        d[e.to] = d[v] + e.cost;
        que.push(P(d[e.to], e.to));
      }
    }
  }
}

