using Edge = pair<int, int>;

int getRoot(const int n, const vector<Edge>& edges) {
  set<int> rootie;
  for (int i = 0; i < n; ++i)
    rootie.insert(i);
  for (auto& e : edges)
    rootie.erase(e.second);
  return *rootie.begin();
}

int main() {
  int n, m;
  cin >> n >> m;
  vector<Edge> edges;
  for (int i = 0; i < n + m - 1; ++i) {
    int u, v;
    cin >> u >> v;
    edges.emplace_back(u - 1, v - 1);
  }
  const int root = getRoot(n, edges);

  vector<vector<int>> children(n);
  vector<set<int>> parents(n);
  for (auto& e : edges) {
    children[e.first].push_back(e.second);
    parents[e.second].insert(e.first);
  }

  vector<int> parent(n, -2);
  queue<int> q;
  q.push(root);
  parent[root] = -1;
  while (!q.empty()) {
    int p = q.front();
    for (int c : children[p]) {
      if (parents[c].size() == 1) {
        parent[c] = p;
        q.push(c);
      } else {
        parents[c].erase(p);
      }
    }
    children[p].clear();
    q.pop();
  }

  for (int p : parent)
    cout << (p + 1) << "\n";

  return 0;
}

