    //cout << k << endl;
    //REP(i, N) cout << cmp[i] << endl;
    REP(i, N){
        int ans = -1, mm = -1;
        for(int c: cand[i]){
            if(cmp[c] > mm){
                mm = cmp[c];
                ans = c;
            }
        }
        cout << ans + 1 << endl;
    }

    return 0;
}

