        adj[u].push_back({v, i});
    }
    for (int i = 1; i <= n; i++) {
        if (number[i] == 0) DFS_SCC(i);
    }
    cout << SLTPLTM;
}

int parent[maxN], L[maxN], R[maxN], child[maxN], D[maxN];
int cost[maxM];
long long res = 0;

void DFS_tree(int u) {
    L[u] = ++order;
    child[u] = 1;
    for (i2 x : adj[u]) {
        int id = x.second;
        int v = x.first;
        if (v == parent[u]) continue;
        parent[v] = u;
        D[v] = D[u] + cost[id];
        DFS_tree(v);
        child[u] += child[v];
        res += 1LL * cost[id] * child[v] * (n - child[v]);
        //cout << child[v] << " " << v << " ";
    }
    R[u] = order;
}

void NTTREE() { /// https://vn.spoj.com/problems/NTTREE/
    cin >> n;
    for (int i = 1; i < n; i++) {
        int u, v; cin >> u >> v >> cost[i];
        u++; v++;
        adj[u].push_back({v, i});
        adj[v].push_back({u, i});
    }
    DFS_tree(1);
    cout << res;
}

vector<int> Adj[2 * maxN];
int val[2 * maxN];

void DFS_counter(int u) {
    for (int v : Adj[u]) {
        if (v == parent[u]) continue;
        parent[v] = u;
        val[v] += val[u];
        DFS_counter(v);
    }
}

void solveD_Ki() { /// https://atcoder.jp/contests/abc138/tasks/abc138_d
    int q; cin >> n >> q;
    for (int i = 1; i < n; i++) {
        int u, v; cin >> u >> v;
        Adj[u].push_back(v);
        Adj[v].push_back(u);
    }
    while (q--) {
        int p, x; cin >> p >> x;
        val[p] += x;
    }
    DFS_counter(1);
    for (int i = 1; i <= n; i++) cout << val[i] << " ";
}

int Used[maxN], inD[maxN];

void DFS_topo(int u) {
    Used[u]++;
    L[u] = ++order;
    for (int v : Adj[u]) {
        if (Used[v] == 1) {
            //if (Used[u] != 1) continue;
            if (L[parent[v]] <= L[u] && L[u] <= R[parent[v]]) {
                parent[v] = u;
                DFS_topo(v);
            }
            continue;
            //parent[v] = u;
        }
        //D[v] = D[u] + 1;
        parent[v] = u;
        DFS_topo(v);
    }
    R[u] = order;
}

void solveD_RestoreTheTree() { ///https://atcoder.jp/contests/nikkei2019-qual/tasks/nikkei2019_qual_d
    cin >> n >> m;
    for (int i = 1; i < n + m; i++) {
        int u, v; cin >> u >> v;
        Adj[u].push_back(v);
        inD[v]++;
    }
    int root = 0;
    for (int i = 1; i <= n; i++) {
        if (inD[i] == 0) {
            root = i;
            break;
        }
    }
    for (int i = 1; i <= n; i++) R[i] = 1e9;
    DFS_topo(root);
    for (int i = 1; i <= n; i++) cout << parent[i] << "\n";
}

