struct Edge {
    ll to, rev;
    long double cap;
    Edge(ll _to, long double _cap, ll _rev) {
        to = _to;
        cap = _cap;
        rev = _rev;
    }
};
using Edges = vector<Edge>;
using Graph = vector<Edges>;

void add_edge(Graph &G, ll from, ll to, long double cap, bool revFlag,
              long double revCap) {
    G[from].push_back(Edge(to, cap, (ll)G[to].size()));
    if(revFlag)
        G[to].push_back(Edge(from, revCap, (ll)G[from].size() - 1));
}

void solve() {
    ll n, m;
    cin >> n >> m;
    Graph g(n);
    REP(i, n - 1 + m) {
        ll a, b;
        cin >> a >> b;
        add_edge(g, --b, --a, 1, false, 1);
    }

    Array dp(n, -1);
    Array depth(n, -1);
    auto dfs = [&](auto &&self, int v) {
        if(dp[v] != -1)
            return dp[v];
        dp[v] = 0;
        depth[v] = 0;
        for(auto e : g[v]) {
            self(self, e.to);
            if(chmax(depth[v], depth[e.to] + 1)) {
                dp[v] = e.to + 1;
            }
        }
    };
    REP(i, n) {
        dfs(dfs, i);
        cout << dp[i] << en;
    }
}

