void solve(long long N, long long M, std::vector<long long> A,
           std::vector<long long> B) {
  vector<int> cnt(N, 0);
  vector<vector<int>> G(N);
  int m = N - 1 + M;
  for (int i = 0; i < m; i++) {
    A[i]--;
    B[i]--;
    G[A[i]].push_back(B[i]);
    // Graph[A[i]].push_back(B[i]);
  }

  for (int i = 0; i < m; i++) cnt[B[i]]++;
  int root = 0;
  for (int i = 0; i < N; i++) {
    if (cnt[i] == 0) root = i;
  }
  /*
    for (int i = 0; i < N; i++)
      if (!used[i]) dfs(i);
    for (int i = 0; i < N; i++) cout << topologicalOrder[i] << " ";
    cout << endl;
  */
  queue<int> data;
  data.push(root);
  vector<int> parent(N, 0);
  vector<int> tmp(N, 0);
  while (!data.empty()) {
    int cur = data.front();
    data.pop();
    for (auto u : G[cur]) {
      tmp[u]++;
      if (tmp[u] < cnt[u]) continue;
      // used[u] = true;
      data.push(u);
      parent[u] = cur + 1;
    }
  }
  for (int i = 0; i < N; i++) cout << parent[i] << endl;
}

