                parent[now_u] = ans[i];
                is_ok[now_u] = true;
            }
        }
    }
    parent[ans[ans.size() - 1]] = -1;
    for (int i = 0; i < N; i++) {
        cout << parent[i] + 1 << endl;
    }
    return 0;
}

