int num[MAX_N];
bool used2[MAX_N];
int cou;

void dfs2(int v,int depth,int p) {
  used2[v] = true;


  rep(i,(int)g[v].size() ){
    int vnext = g[v][i];
    if (!used2[vnext] ) {
      dfs2(vnext,depth+1,v);
    }
  }
  num[v] = cou;
  cou++;
}

void tsort() {
  for(int i=0; i<v; ++i) dfs(i);
  reverse(ans.begin(), ans.end());
}

