	q.push(Pll(0,top));

	while(q.size() != 0) {
		Pll buf = q.top();
		q.pop();
		if (root[buf.S] < buf.F) {
			root[buf.S] = buf.F;
			buf.F++;
			rep(i,0,down[buf.S].size()) {
				q.push(Pll(buf.F,down[buf.S][i]));
			}
		}
