	rep(i,0,N) {
		rep(j,0,up[i].size()) {
			if (root[up[i][j]]+1 == root[i]) {
				ans[i] = up[i][j];
			}
		}
	}
	ans[top] = -1;
	rep(i,0,N) {
		put(ans[i]+1);
	}
	return 0;
