bool eq(edge a, edge b){
	return a.from==b.from&&a.to==b.to;
}
bool comp(edge a, edge b){
	if(a.from<b.from)return true;
	if(a.from==b.from)return a.to<b.to;
	return false;
}
bool exist(int x, int y){
	edge sf;
	sf.from=x;
	sf.to=y;
	int po=(edgeList.size()+1)>>1, mo=(po+1)>>1;
	for(int i = 1;i <= 4*edgeList.size();i <<= 1){
		if(eq(edgeList[po],sf))return true;
		if(!comp(edgeList[po],sf)){
			po-=mo;
			if(po<0)po=0;
		}else{
			po+=mo;
			if(po>=edgeList.size())po=edgeList.size()-1;
		}
		mo=(mo+1)/2;
	}
	return false;
}
