template<class Type>
Type solve(Type res = Type()){
    int N,M; cin >> N >> M;
    vector<vector<int>> G(N+1);
    vector<vector<int>> rG(N+1);
    for(int i = 0; i < N-1+M;i++){
        int A,B; cin >> A >> B;

        A--; B--;
        G[A].push_back(B);
        rG[B].push_back(A);
    }

    // 逆辺グラフからrootを探索する
    int root = 0;
    while(!rG[root].empty()) root = rG[root].front();

    // 順辺グラフを用いて各頂点の到達優先度を数える (昇順)
    vector<ll> visit_priority(N);

    visit_priority[root] = 1;
    queue<int> q; q.push(root);
    while(q.size()){
        int n = q.front(); q.pop();
        for(auto next:G[n]){
            visit_priority[next] = max(visit_priority[next],visit_priority[n] + 1); //親と子の関係は必ず優先度が降下 ;
            q.push(next);
        }
    }

    // 逆順グラフで親の中から最も優先度が低いものが真の親
    for(int i = 0; i < N;i++){
        int ans = 0;
        ll min_priority = 0;
        for(auto next:rG[i]){
            if(min_priority < visit_priority[next]){
                min_priority = visit_priority[next];
                ans = next + 1;
            }
        }

        cout << ans << endl;
    }
    return res;
}
int main(void) {
    cin.tie(0); ios_base::sync_with_stdio(false);
    solve(0);
    // cout << fixed << setprecision(15) << solve<ll>() << endl;
    return 0;
}

