void solve() {
  int N, M;
  cin >> N >> M;

  vector<vector<int>> v(N+1);
  vector<vector<int>> w(N+1);

  for (int i = 0; i < N-1+M; i++) {
    int a, b;
    cin >> a >> b;
    v[b].push_back(a);
    w[a].push_back(b);
  }

  int root = 1;
  while (!v[root].empty()) {
    root++;
  }

  vector<int> parent(N+1);
  vector<bool> visited(N+1);
  parent[root] = 0;
  visited[root] = true;

  queue<int> que;
  queue<int> depth;

  que.push(root);
  depth.push(1);

  while(!que.empty()) {
    int p = que.front(); que.pop();
    int d = depth.front(); depth.pop();

    for (int x:w[p]) {
      parent[x] = p;
      if (v[p].size() <= d) {
        que.push(x);
        depth.push(d+1);
      }

      // if (!visited[x]) {
