using namespace std;

vector<int> tsort(int v, vector<int> g[], bool zero_index = false) {
  vector<int> ret;

  int start = zero_index ? 0 : 1;
  int end = zero_index ? v : v + 1;
  int degree[end];
  memset(degree, 0, sizeof(degree));

  for (int from = start; from < end; from++) {
    for (int i = 0; i < g[from].size(); i++) {
      int to = g[from][i];
      degree[to]++;
    }
  }

  stack<int> root;

  for (int i = start; i < end; i++) {
    if (degree[i] == 0) {
      root.push(i);
    }
  }

  while (!root.empty()) {
    int from = root.top();
    root.pop();

    ret.push_back(from);

    for (int i = 0; i < g[from].size(); i++) {
      int to = g[from][i];
      degree[to]--;

      if (degree[to] == 0) {
        root.push(to);
      }
    }
  }

  return ret;
}

int main() {
  int n, m;
  cin >> n >> m;

  vector<int> g[n + 1];

  int a, b;
  for (int i = 0; i < n - 1 + m; i++) {
    cin >> a >> b;

    g[a].push_back(b);
  }

  vector<int> order = tsort(n, g);

  int ans[n + 1];
  memset(ans, -1, sizeof(ans));

  ans[order[0]] = 0;

  for (int i = 0; i < order.size(); i++) {
    int from = order[i];

    for (int j = 0; j < g[from].size(); j++) {
      int to = g[from][j];
      ans[to] = from;
    }
  }

  for (int i = 1; i <= n; i++) {
    cout << ans[i] << endl;
  }

  return 0;
}

