struct segtree {
	int N, dat[2 * 300000];
	segtree() {}
	segtree(int n) {
		N = 1;
		while (N < n) N *= 2;
		for (int i = 0; i < 2 * N - 1; i++)
			dat[i] = INF;
	}
	// update k th element
	void update(int k, int a) {
		k += N - 1; // leaf
		dat[k] = a;
		while (k > 0) {
			k = (k - 1) / 2;
			dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
		}
	}
	// min [a, b)
	int query(int a, int b) { return query(a, b, 0, 0, N); }
	int query(int a, int b, int k, int l, int r) {
		if (r <= a || b <= l) return INF;
		if (a <= l && r <= b) return dat[k];
		int m = (l + r) / 2;
		return min(query(a, b, k * 2 + 1, l, m), query(a, b, k * 2 + 2, m, r));
	}
};

struct Edge {
	int src,dst,weight;
};

typedef vector<vector<Edge>> Graph;

bool visit(const Graph &g, int v, vector<int> &order, vector<int> &color) {
	color[v] = 1;
	for(auto e : g[v]) {
		if (color[e.dst] == 2) continue;
		if (color[e.dst] == 1) return false;
		if (!visit(g, e.dst, order, color)) return false;
	}
	order.push_back(v); color[v] = 2;
	return true;
}
bool topologicalSort(const Graph &g, vector<int> &order) {
	int n = g.size();
	vector<int> color(n);
	REP(u, n) if (!color[u] && !visit(g, u, order, color))
		return false;
	reverse(ALL(order));
	return true;
}

signed main(void) {
	int n, m;

	cin >> n >> m;
	Graph g(n);
	vector<int> inc(n);
	REP(i, n + m-1) {
		int a, b;
		scanf("%d %d", &a, &b);
		a--, b--;
		g[a].push_back(Edge{a,b,1});
		inc[b] ++;
	}
	int root = -1;
	REP(i, n) {
		if (inc[i] == 0) {
			root = i;
		}
	}

	if (root == -1) {
		return -1;
	}
	vector<int> order(n),prev(n), dist(n);
	topologicalSort(g, order);

	REP(i, n) {
		int ind = order[i];
		for (auto itr : g[ind]) {
			if (dist[itr.dst] < dist[ind] + 1) {
				prev[itr.dst] = ind;
				dist[itr.dst] = dist[ind] + 1;
			}
		}
	}

	prev[root] = -1;
	REP(i, n) {
		printf("%d\n", prev[i] + 1);
	}

	return 0;
}

