void DFS(int V,int P,vector<vector<int> > &GRAPH, vector<int> & Parent,vector<int>& DIST,vector<int> & used,map<pair<int,int>,int> & mp)
{
  if(Parent[V] != P)return;
  if(P != -1)
  if(DIST[P] + 1 != DIST[V])return;
  for (auto &&nV : GRAPH[V])
  {
    int INDEX = mp[make_pair(V,nV)];
    if(used[INDEX] == 1)continue;
    if(DIST[V] +1 >= DIST[nV])
    {
      Parent[nV] = V;
      DIST[nV] = DIST[V]+1;
      used[INDEX] = 1;
      DFS(nV,V,GRAPH,Parent,DIST,used,mp);
    }

  }
  return;
}
