  for (int i = 0; i < n+m-1; ++i) {
    scanf("%d%d", a+i, b+i); a[i]--; b[i]--;
    edges[a[i]].push_back(b[i]);
    redges[b[i]].push_back(a[i]);
  }
  int root;
  for (int i = 0; i < n; ++i) {
    if (redges[i].size() == 0) root = i;
  }
  vector<int> ans(n);
  vector<int> cnt(n);
  queue<pii> q;
  q.push(make_pair(root, -1));
  while(q.size()) {
    int node = q.front().first;
    int prev = q.front().second;
    q.pop();
    cnt[node]++;
    //printf("node:%d cnt:%d/%lu prev:%d\n", node, cnt[node], redges[node].size(), prev);
    if (cnt[node] == redges[node].size() || node == root) {
      ans[node] = prev;
    } else {
      continue;
    }
    for (int i = 0; i < edges[node].size(); ++i) {
      int next = edges[node][i];
      q.push(make_pair(next, node));
    }
  }
  for (int i = 0; i < n; ++i) {
    if (i == root) printf("%d\n", 0);
    else {
      printf("%d\n", ans[i] + 1);
    }
  }
