using namespace std;

void BFS(vector<vector<int> > & adj, vector<int> & parent, int start){
  queue<int> q;
  q.push(start);
  vector<bool> visited(adj.size(), false);

  while(!q.empty()){
  	int here = q.front();
    q.pop();

    for(auto desc : adj[here]){
      parent[desc] = here;
      if(!visited[desc]){
        visited[desc] = true;
        q.push(desc);
      }
    }  
  }
}

