vector<int> tsort_Kahn(const vector<vector<int>>& g){
  const int V = g.size();
  vector<int> indeg(V, 0);
  stack<int> S;

  for(auto& u_out_edges : g){
    for(auto& v : u_out_edges){
      indeg[v]++;
    }
  }

  REP(i, V) if(indeg[i] == 0) S.push(i);

  vector<int> ans;
  while(S.size()){
    int u = S.top(); S.pop();
    ans.emplace_back(u);
    for(auto& v : g[u]){
      indeg[v]--;
      if(indeg[v] == 0) S.push(v);
    }
  }
  return ans;
}

