using namespace std;

int depth[10005];
int par[100005];
vector<vector<int> > es;
vector<vector<int> > rev_es;

int GetRoot(int i) {
  if (rev_es[i].empty())
    return i;
  return GetRoot(rev_es[i][0]);
}

void SetDepth(int u, int d) {
  if (depth[u] >= d) {
    return;
  }
  depth[u] = d;
  for(auto v : es[u]) {
    SetDepth(v, d + 1);
  }
}

void SetParent(int u_par, int u, int d) {
  if (depth[u] > d) {
    return;
  }
  par[u] = u_par;
  for(auto v : es[u]){
    SetParent(u, v, d + 1);
  }
}

int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  int N, M;
  cin >> N >> M;
  es.resize(N, vector<int>(0));
  rev_es.resize(N, vector<int>(0));
  REP(i, N + M - 1){
    int a, b;
    cin >> a >> b;
    a--;
    b--;
    es[a].push_back(b);
    rev_es[b].push_back(a);
  }
  cerr << "START" << endl;
  int root = GetRoot(0);
  cerr << "OK ROOT" << endl;
  SetDepth(root, 1);
  cerr << "OK DEPTH" << endl;
  SetParent(-1, root, 1);
  REP(i,N){
    cout << par[i] + 1 << endl;
  }
  return 0;
}

