void solve() {
  int N, M; cin >> N >> M;
  Graph Tree(N);
  vector<set<int>> Parent(N);
  rep(i,N-1+M) {
    int a, b; cin >> a >> b; --a; --b;
    Tree[a].push_back(b);
    Parent[b].insert(a);
  }
  queue<int> q;
  rep(i,N) {
    if (Parent[i].empty()) {
      Parent[i].insert(-1);
      q.push(i);
      continue;
    }
  }
  while (!q.empty()) {
    int p = q.front(); q.pop();
    for (auto v : Tree[p]) {
      q.push(v);
      if (Parent[v].size() > 1) {
        Parent[v].erase(p);
      }
    }
  }
  rep(i,N) cout << *begin(Parent[i]) + 1 << endl;
}


