void dfs(int v, int p, int d) {
	if(ans[v].second<d){
		int k=ans[v].first;
		ans[v].first=p+1;
		ans[v].second=d;
		if(k!=-1) return;
	}
	for (auto to : edge[v]) {
		if (to != p) dfs(to, v, d+1);
	}
}

