//Graph in adjcency list
class Graph{
public:
    int N;
    vector<vector<int>> adjlist;
    vector<ll> depth;
    vector<int> root;

    Graph(int n) : N(n), adjlist(n+1), depth(n+1, -1), root(n+1, -1){}

    void setEdge(int a, int b){
        adjlist[a].push_back(b);
    }

    void dfs(int p, int v, ll d){
        static vector<bool> check(N+1, false);
        if(d > depth[v]){
            depth[v] = d;
            root[v] = p;
            for(auto i : adjlist[v]){
                depth[i] = d + 1;
                root[i] = v;
            }
        }
        if(check[v]){
            return;
        }else{
            check[v] = true;
        }
        for(auto i : adjlist[v]){
            dfs(v, i, d+1);
        }
    }
};

