inline void dfs(li now, li now_depth) {
    depth[now] = now_depth;
    for (auto && next : edges[now]) {
        if (depth[next] == -1) {
            depth[next] = now_depth + 1;
            parent[next] = now;
            dfs(next, now_depth + 1);
        } else if (depth[next] <= now_depth + 1) {
            // nextのparentを書き換え
            depth[next] = now_depth + 1;
            parent[next] = now;
            dfs(next, now_depth + 1);
        } else {
            // 今見ている辺はショートカット辺なのでスルー
        }
    }
}

