        edges[a].pb(b);
        root[b] = false;
    }
    rin{
        if (!root[i])continue;
        // dfs from root
        dfs(i, 0);
    }

    rin{
        if (root[i])cout << "0" << endl;
        else cout << parent[i] + 1 << endl;
    }

    return 0;
}

