	vector<int>visited(N);
	prev[root] = -1;
	function<void(int,int)>f = [&](int v, int p) {
		prev[v] = p;
		visited[v] = 1;
		for (auto u : g.G[v]) {
			if (u == p or visited[u])continue;
			f(u, v);
		}
	};
