int n,m,a[100004],b[100004];
vector<int> road[100004],topo;
bool chi[100004],went[100004],went2[100004],did[100004];
itn ans[100004];
void dfs(int x){
    went[x]=1;
    for(auto&i:road[x]){
        if (went[i]) {
            continue;
        }
        dfs(i);
    }
    topo.emplace_back(x);
}
signed main() {
    ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    cin>>n>>m;

    rep(i,n+m-1){
        cin>>a[i]>>b[i];
        road[a[i]].emplace_back(b[i]);
        chi[b[i]]=1;
    }
    REP(i,n){
        if (!chi[i]) {
            dfs(i);
            reverse(ALL(topo));
            break;
        }
    }
    for(int i=n-1;i>=0;i--){
        for(auto&j:road[topo[i]]){
            if (!did[j]) {
                ans[j]=topo[i];
                did[j]=1;
            }
        }
    }
    REP(i,n){
        cout<<ans[i]<<endl;
    }
}

