int dfs(int v){
    if(D[v] >= 0) return D[v];
    int d = -1;
    int idx = 0;
    for(int i = 0; i < L[v].size(); i++){
        int next = L[v][i];
        int x = dfs(next);
        if(d < x){
            d = x;
            idx = next;
        }
    }
    D[v] = d+1;
    P[v] = idx+1;
    return D[v];
}


