    }

    int root = -1;
    FOR(i, 0, N) {
        if (degree[i] == 0) {
            root = i;
            break;
        }
    }

    queue<int> que;
    que.emplace(root);
    auto parent = make_v<int>(N);
    fill_v(parent, -1);

    while (not que.empty()) {
        const int u = que.front(); que.pop();
        FOE(v, graph[u]) {
            if (parent[v] == -1) {
                que.emplace(v);
            }
            parent[v] = u;
        }
    }

    FOR(i, 0, parent.size()) {
        print(parent[i] + 1);
    }


    return 0;
}

