struct DAG {
private:
    struct Edge {
        int to;
    };
    std::vector<std::vector<Edge>> graph;
    bool is_dag = false;
    std::vector<int> sorted; // トポロジカルソート
    int V; // 頂点数
public:

    DAG(int v) {
        assert(v > 0);
        V = v;
        graph.resize(v);
    }

    // from から to への有向辺を張る
    void add_edge(int from, int to) {
        graph[from].push_back({to});
    }

    // トポロジカルソート O(V + E)
    // DAG じゃないなら size 0 の vectorを返す
    std::vector<int> topological_sort() {
        std::stack<int> sta;
        //std::vector<int> dist(V, 0);//その頂点までの最長路
        std::vector<int> in(V, 0);// 入次数
        int used_cnt = 0;//使用した頂点の数
        for (int i = 0; i < V; i++) {
            for (Edge e : graph[i]) {
                in[e.to]++;
            }
        }
        for (int i = 0; i < V; i++) if (in[i] == 0) {
            sta.push(i);
            used_cnt++;
        }
        while (!sta.empty()) {
            int p = sta.top(); sta.pop();
            sorted.push_back(p);
            for (Edge e : graph[p]) {
                int v = e.to;
                in[v]--;
                //dist[v] = std::max(dist[v], dist[p] + 1);
                if (in[v] == 0) {
                    sta.push(v);
                    used_cnt++;
                }
            }
        }
        if (used_cnt == V) {
            return sorted;
        }
        else {
            return std::vector<int>(0);
        }
    }

    vector<Edge>& operator[](int x) {
        return graph[x];
    }
};

int main() {
    int n, m; scanf("%d %d", &n, &m);
    m += n - 1;
    DAG dag(n);
    vector<vector<int>> g(n);
    REP(i, m) {
        int a, b; scanf("%d %d", &a, &b);
        a--; b--;
        dag.add_edge(a, b);
        g[b].push_back(a);
    }
    auto vec = dag.topological_sort();
    vector<int> rvec(n); // 頂点iは何番目
    REP(i, n) rvec[vec[i]] = i;
    vector<int> ans(n);
    REP(i, vec.size()) {
        int par = -1;
        REP(j, g[vec[i]].size()) {
            par = max(par, rvec[g[vec[i]][j]]);
        }
        ans[vec[i]] = par < 0 ? -1 : vec[par];
    }
    REP(i, n) {
        printf("%d\n", ans[i] + 1);
    }
    return 0;
}

