template <typename T1, typename T2>
void func(T1& to, T2& rank, int v, vector<bool>& ch) {
	if (ch[v]) { return ; }
	for (int i = 0; i < to[v].size(); ++i) {
		if ((rank[to[v][i]] > rank[v])) { continue; }
		rank[to[v][i]] = rank[v] + 1;
		func(to, rank, to[v][i], ch);
	}
	ch[v] = true;
}

