template <typename T>
class dijkstra
{
private:
    using P = pair<T, T>;
    struct edge{
        ll to;
        T cost;
    };
    ll vertex;   // 頂点数
    vector<vector<edge>> list;  //隣接リスト
    vector<T> distance;    // 距離
public:
    dijkstra(ll n, T infinity = 1e16);  // nは頂点の数、infinityは初期化に使う値
    void add_edge(ll v1, ll v2, T cost);    // 頂点v1から頂点v2に辺を張る
    void run(ll s);        // sは開始地点。
    T get_distance(ll v);    // 頂点vへの距離を返す
};

template <typename T>
dijkstra<T>::dijkstra(ll n, T infinity){
    vertex = n;
    list.resize(n);
    distance = vector<T>(vertex, -infinity);
}

template <typename T>
void dijkstra<T>::add_edge(ll v1, ll v2, T cost){
    list[v1].push_back({ v2, cost });
}

template <typename T>
void dijkstra<T>::run(ll s){
    priority_queue<P> que;

    distance[s] = 0;    // 開始点の距離は0
    que.push(P(0, s));

    while(!que.empty()){
        P p = que.top(); que.pop();
        T v = p.second;
        if(distance[v] > p.first) continue;
        for(auto e : list[v]){
            if(distance[e.to] < distance[v] + e.cost){
                distance[e.to] = distance[v] + e.cost;
                que.push(P(distance[e.to], e.to));
            }
        }
    }
}

template <typename T>
T dijkstra<T>::get_distance(ll v){
    return distance[v];
}



int main() {
    ll n, m;
    cin >> n >> m;
    dijkstra<ll> dik(n);
    vector<vector<ll>> g(n);
    vector<ll> cnt(n);
    REP(i, n - 1 + m){
        ll a, b;
        cin >> a >> b;
        a--; b--;
        dik.add_edge(a, b, 1);
        g[a].push_back(b);
        cnt[b]++;
    }
    ll root = -1;
    REP(i, n){
        if(cnt[i] == 0){
            root = i;
        }
    }

    dik.run(root);

    vector<ll> par(n);
    REP(i, n){
        ll d = dik.get_distance(i);
        for(auto &child : g[i]){
            if(d + 1 == dik.get_distance(child)){
                par[child] = i + 1;
            }
        }
    }

    REP(i, n){
        cout << par[i] << endl;
    }
}

