void bfs(int root){
    using P = pair<int,int>;
    priority_queue<P,vector<P>,greater<P>> qu;
    qu.push({0,root});
    while(qu.size()){
        P cur = qu.top(); qu.pop();
        int v = cur.second;
        if(depth[v] > cur.first) continue;
        for(int c : ch[v]){
            if( depth[c] < depth[v]+1){
                depth[c] = depth[v]+1;
                qu.push({depth[c], c});
            }
        }
    }
}

