    io.read(a, b);
    G[a - 1].push_back(b - 1);
    came[b - 1] = 1;
  }
  int root = -1;
  REP(i, N) if (came[i] == 0) root = i;
  vector<int> ans(N, -1), depth(N, 0);
  function<void(int)> dfs = [&](int u) {
    for (auto v : G[u]) {
      if (ans[v] == -1 || depth[v] < depth[u] + 1) {
        depth[v] = depth[u] + 1;
        ans[v] = u;
        if (ans[v] == u) dfs(v);
      }
    }
  };
  dfs(root);
  REP(i, N) {
    io.write(ans[i] + 1);
    io.write("\n");
  }
