int main(int argc, char const *argv[])
{
  int N, M;
  cin >> N >> M;
  vector<vector<bool>> edges(N + 1, vector<bool>(N + 1));
  vector<vector<bool>> edges_rev(N + 1, vector<bool>(N + 1, false));
  for (int i = 0, l = N + M - 1; i < l; ++i)
  {
    int fr, to;
    cin >> fr >> to;
    edges[fr][to] = true;
    edges_rev[to][fr] = true;
  }

  int root;
  for (int to = 1; to <= N; ++to)
  {
    auto &fr = edges_rev[to];
    if (none_of(fr.begin(), fr.end(), [](bool b) { return b; }))
    {
      root = to;
      break;
    }
  }

  vector<int> parent(N + 1, -1), length(N + 1, -1);
  parent[root] = 0;
  length[root] = 0;

  stack<int> st;
  st.push(root);
  while (!st.empty())
  {
    int fr = st.top();
    st.pop();

    for (int to = 1; to <= N; ++to)
    {
      if (edges[fr][to])
      {
        if (length[to] < length[fr] + 1)
        {
          length[to] = length[fr] + 1;
          parent[to] = fr;
          st.push(to);
        }
      }
    }
  }

  for (int i = 1; i <= N; ++i)
  {
    cout << parent[i] << '\n';
  }
  cout.flush();
}

