    for(int i=0;i<N-1+M;i++){
        cin >> Ai >> Bi;
        if(graph.count(Ai)==0) graph[Ai] = array<set<ll>,2>();
        if(graph.count(Bi)==0) graph[Bi] = array<set<ll>,2>();
        graph[Bi][0].insert(Ai);
        graph[Ai][1].insert(Bi);
    }

    queue<ll> root;
    for(auto m : graph){
        if(m.second[0].size()==0){
            root.push(m.first);
            solution[m.first] = 0;
        }
    }
    while(!root.empty()){
        auto r = root.front(); root.pop();
        auto out = graph[r][1];
        for(auto s : out){
            if(graph[s][0].size()==1){
                root.push(s);
                solution[s] = r;
            }
            graph[s][0].erase(r);
        }
    }
    for(auto s : solution){
        cout<<s.second<<endl;
    }

    return 0;
}

