void bfs(int st) {
	queue<int> q;
	q.push(st);
	mark[st] = 1;
	while (!q.empty()) {
		int v = q.front();
		q.pop();
		for (auto u : gr[v])
			if (!mark[u])
				q.push(u), dis[u] = dis[v] + 1, mark[u] = 1;
	}
	return;
