int dfs(vi &dp, vvi &g, vi &p, int v) {
	if (dp[v] != -1)return dp[v];
	int ret = 0;
	REP(i, g[v].size()) {
		if (chmax(ret, dfs(dp, g, p, g[v][i])+1)) {
			p[v] = g[v][i];
		}
	}
	return dp[v] = ret;
}
