template <typename T>
void printv(const vector<T> &v)
{
    int sz = v.size();
    for (int i = 0; i < sz; i++)
    {
        cout << v[i] << " \n"[i == sz - 1];
    }
}

using Graph = vector<vector<int>>;

void dfs(int v, const Graph &G, vector<int> &res, vector<int> &used)
{
    used[v] = 1;
    for (auto to : G[v])
        if (used[to] == 0)
        {
            dfs(to, G, res, used);
        }
    res.push_back(v);
}

vector<int> topo_sort(const Graph &G)
{
    int V = G.size();
    vector<int> ide(V);
    for (int i = 0; i < V; i++)
    {
        for (auto to : G[i])
        {
            ide[to]++;
        }
    }
    vector<int> res;
    vector<int> used(V);
    for (int i = V - 1; i >= 0; i--)
    {
        if (ide[i] == 0)
        {
            dfs(i, G, res, used);
        }
    }
    if (res.size() == 0)
        res = {-1};
    reverse(res.begin(), res.end());
    return res;
}

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n, m;
    cin >> n >> m;
    Graph g(n), rev(n);
    for (int i = 0; i < n - 1 + m; i++)
    {
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        g[a].push_back(b);
        rev[b].push_back(a);
    }
    vector<int> ts = topo_sort(g);
    vector<int> res(n, -1), pri(n);
    for (int i = 0; i < n; i++)
        pri[ts[i]] = i;
    res[ts[0]] = 0;
    for (int i = n - 1; i > 0; i--)
    {
        int v = ts[i];
        int ma = -1, idx = -1;
        for (auto u : rev[v])
        {
            if (pri[u] > ma)
            {
                ma = pri[u];
                idx = u;
            }
        }
        res[v] = idx;
    }
    for (int i = 0; i < n; i++)
    {
        if (res[i] == -1)
            cout << 0 << endl;
        else
            cout << res[i] + 1 << endl;
    }
}

