struct edge{int to, cost;};

class Graph
{
public:
    int V;
    vector<vector<edge>> G;

    Graph(int V): V(V){
        G = vector<vector<edge>>(V, vector<edge>(0));
    }

    void add_edge(int from, int to, int cost){
        G[from].push_back(edge({to, cost}));
    }

    void add_edge2(int v1, int v2, int cost){
        add_edge(v1, v2, cost);
        add_edge(v2, v1, cost);
    }

    //SCC decomposition
    void dfs(int v, vector<bool> &used, vec &vs){
        used[v] = true;
        REP(i, G[v].size()){
            if(!used[G[v][i].to]) dfs(G[v][i].to, used, vs);
        }
        vs.push_back(v);
    }
    void rdfs(int v, int k, vector<bool> &used, vec &cmp){
        used[v] = true;
        cmp[v] = k;
        REP(i, G[v].size()){
            if(!used[G[v][i].to]) rdfs(G[v][i].to, k, used, cmp);
        }
    }
    vec scc(int &k){
        vector<bool> used(V, false);
        vec vs(0), cmp(V);
        REP(i, V){
            if(!used[i]) dfs(i, used, vs); 
        }
        //reverse graph
        Graph rG(V);
        REP(v, V) REP(i, G[v].size()) rG.add_edge(G[v][i].to, v, G[v][i].cost);

        fill(used.begin(), used.end(), false);
        k = 0;
        IREP(i, vs.size()){
            if(!used[vs[i]]) rG.rdfs(vs[i], k++, used, cmp);
        }
        return cmp;
    }

};

signed main(){

    int N, M; cin >> N >> M;
    Graph G(N);
    int A, B;
    mat cand(N, vec(0));

    REP(i, N + M - 1){
        cin >> A >> B;
        G.add_edge(A - 1, B - 1, 0);
        cand[B - 1].push_back(A - 1);
    }
    int k;
    vec cmp = G.scc(k);
    //cout << k << endl;
    //REP(i, N) cout << cmp[i] << endl;
    REP(i, N){
        int ans = -1, mm = -1;
        for(int c: cand[i]){
            if(cmp[c] > mm){
                mm = cmp[c];
                ans = c;
            }
        }
        cout << ans + 1 << endl;
    }

    return 0;
}

