void solve(int v)
{
  if (parent[v] != -2)
  {
    return;
  }
  for (auto x : W[v])
  {
    solve(x);
  }
  int maxi = -1;
  int ind = -1;
  for (auto x : W[v])
  {
    if (maxi < depth[x])
    {
      ind = x;
      maxi = depth[x];
    }
  }
  parent[v] = ind;
  depth[v] = maxi + 1;
  // cerr << "parent[" << v << "] = " << parent[v] << endl;
  // cerr << "depth[" << v << "] = " << depth[v] << endl;
}

