void md(int index, vector<vector<int>> &child, vector<int> &height, vector<int> &r){
    for(int i = 0; i < child[index].size(); i++){
        if(height[child[index][i]] < height[index] + 1){
            height[child[index][i]] = height[index] + 1;
            r[child[index][i]]--;
            if(r[child[index][i]] == 0) md(child[index][i], child, height, r);
        }
    }
}



