namespace adaptor = boost::adaptors;
using index_t = std::size_t;		

boost::optional<std::vector<index_t>> topological_sort(std::vector<std::set<index_t>>const& edge)
{
	auto const N = edge.size();
	std::vector<index_t> ret(N);
	index_t now = N;
	enum mark
	{
		none,
		temp,
		conf
	};
	std::vector<mark> vec(N);
	std::function<bool(index_t)> visit = [&](index_t i)
	{
		if (vec[i] == temp)
		{
			return false;
		}
		else if (vec[i] == none)
		{
			vec[i] = temp;
			for (auto&& n : edge[i])
			{
				if (!visit(n))
				{
					return false;
				}
			}
			vec[i] = conf;
			ret[--now] = i;
		}
		return true;
	};
	for (auto i : boost::irange(index_t(), N))
	{
		if (vec[i] != none)
		{
			continue;
		}
		if (!visit(i))
		{
			return boost::none;
		}
	}
	return ret;
}

void Main()
{
	std::size_t N, M;
	std::cin >> N >> M;
	std::vector<std::set<index_t>> edge(N);
	std::vector<index_t> count(N);
	for (auto i : boost::irange<index_t>(1, N + M))
	{
		index_t a, b;
		std::cin >> a >> b;
		--a; --b;
		edge[a].emplace(b);
		++count[b];
	}
	auto sorted = topological_sort(edge);
	for (auto i : *sorted)
	{
		std::set<index_t> erase;
		for (auto n : edge[i])
		{
			if (count[n] != 1)
			{
				erase.emplace(n);
				--count[n];
			}
		}
		for (auto n : erase)
		{
			edge[i].erase(n);
		}
	}
	std::vector<boost::optional<index_t>> prev(N);
	std::stack<std::pair<boost::optional<index_t>, index_t>> stack;
	stack.emplace(boost::none, sorted->at(0));
	while (stack.size())
	{
		auto p = stack.top();
		stack.pop();
		prev[p.second] = p.first;
		for (auto n : edge[p.second])
		{
			stack.emplace(p.second, n);
		}
	}
	for (auto p : prev)
	{
		if (!p)
		{
			std::cout << 0 << std::endl;
		}
		else
		{
			std::cout << *p + 1 << std::endl;
		}
	}
}

