using namespace std;

struct node
{
	vector<int> p,c;
	int deep;
	int par;
};
vector<node> nodes(100005);

int dfs(int id,int parent,int deep)
{
	if(nodes[id].deep>deep+1)
		return 0;
	else
	{
		nodes[id].deep=deep+1;
		nodes[id].par=parent;
		for(int i=0;i<nodes[id].c.size();i++)
			dfs(nodes[id].c[i],id,nodes[id].deep);
	}
	return 0;
}
int rdfs(int id,int count)
{
	if(nodes[id].p.size()>=2)
	{
		int tmpcount=0;
		int nowcount;
		int parid;
		for(int j=0;j<nodes[id].p.size();j++)
		{
			nowcount=rdfs(nodes[id].p[j],0);
			if(tmpcount<nowcount)
			{
				tmpcount=nowcount;
				parid=j;
			}
		}
		nodes[id].par=nodes[id].p[parid];
		nodes[id].p.clear();
		return tmpcount+count+1;
	}

	if(nodes[id].par==-1)
		return count+1;

	return rdfs(nodes[id].p[0],count+1);
}

