    a--, b--;

    edges[a].push_back(b);
    ts.add(a, b);
  }

  ts.sort();

  VL parents(N, -1);

  for (ll u : ts.sorted) {
    for (ll v : edges[u]) parents[v] = u;
  }

  rep(i, N) cout << (i == ts.sorted[0] ? 0 : parents[i] + 1) << endl;
}

