using namespace std;

int N, M;
vector<int> length, parent;

int calcLength(const vector<vector<int>> &edges_rev, int current)
{
  if (length[current] != -1)
    return length[current];
  int longest = -1;
  for (const int &fr : edges_rev[current])
  {
    int len = calcLength(edges_rev, fr) + 1;
    if (longest < len)
    {
      longest = len;
      parent[current] = fr;
      length[current] = longest;
    }
  }
  return longest;
}

int main(int argc, char const *argv[])
{
  cin >> N >> M;
  parent.resize(N + 1, -1);
  length.resize(N + 1, -1);
  vector<vector<int>> edges(N + 1);
  vector<vector<int>> edges_rev(N + 1);
  for (int i = 0, l = N + M - 1; i < l; ++i)
  {
    int fr, to;
    cin >> fr >> to;
    edges[fr].push_back(to);
    edges_rev[to].push_back(fr);
  }

  int root;
  for (int to = 1; to <= N; ++to)
  {
    auto &fr = edges_rev[to];
    if (fr.size() == 0)
    {
      root = to;
      break;
    }
  }

  parent[root] = 0;
  length[root] = 0;
  for (int i = 1; i <= N; ++i)
  {
    calcLength(edges_rev, i);
  }

  for (int i = 1; i <= N; ++i)
  {
    cout << parent[i] << '\n';
  }
  cout.flush();
}

