    for (auto i = vi -> begin(); i != vi -> end(); ++i) {
      cerr << *i << " ";
    }
    cerr << "\n";
  }
  cerr << "}\n";
}


int N, M;
int Root;
vector<USI> node_parents, node_children;
USI leaves, visited;


void find_leaf(int v)
{
  if (visited.find(v) != visited.end()) return;
  visited.insert(v);
  auto &vc = node_children[v];
  if (vc.size() == 0) leaves.insert(v);
  else {
    for (auto ci = vc.begin(); ci != vc.end(); ++ci) {
      find_leaf(*ci);
    }
  }
}


VVI find_root_path(int v)
{
  if (v == Root) return VVI(1, VI(1, v));
  VVI path = VVI(0);
  for (auto pvi = node_parents[v].begin(); pvi != node_parents[v].end(); ++pvi) {
    VVI ppath = find_root_path(*pvi);
    if (ppath.size() > 0) {
      path.insert(path.end(), ppath.begin(), ppath.end());
    }
  }

  if (path.size() == 0) {
    return VVI(0);
  }
  for (auto p = path.begin(); p != path.end(); ++p) {
    p -> push_back(v);
  }
  return path;
}


VI find_longest_path(const VVI &paths) {
  size_t l = 0;
  auto ipl = paths.begin();
  for (auto ip = paths.begin(); ip != paths.end(); ++ip) {
    if (l < ip -> size()) {
      l = ip -> size();
      ipl = ip;
    }
  }
  return *ipl;
}


int main(void)
{
  cin.tie(0);
  ios::sync_with_stdio(false);

  cin >> N >> M;
  node_parents = vector<unordered_set<int>>(N);
  node_children = vector<unordered_set<int>>(N);

  int a, b;
  REP(i, N - 1 + M) {
    cin >> a >> b;
    node_parents[b-1].insert(a-1);
    node_children[a-1].insert(b-1);
  }

  REP(i, N) {
    if (node_parents[i].empty()) {
      Root = i;
      break;
    }
  }

  find_leaf(Root);
  for (auto li = leaves.begin(); li != leaves.end(); ++li) {
    VVI paths = find_root_path(*li);
    // cerr << *li << " ";
    // print_vvi(paths);
    VI long_path = find_longest_path(paths);
    unordered_set<ll> lp_edges;

    for (auto lpi = long_path.begin() + 1; lpi != long_path.end(); ++lpi) {
      lp_edges.insert(*(lpi-1) * N + *lpi);
    }
    for (auto pi = paths.begin(); pi != paths.end(); ++pi) {
      for (auto vi = pi -> begin() + 1; vi != pi -> end(); ++vi) {
	ll edge = *(vi-1) * N + *vi;
      	if (lp_edges.find(edge) == lp_edges.end()) {
	  int e0 = edge / N;
	  int e1 = edge % N;
	  if (node_parents[e1].find(e0) != node_parents[e1].end()) {
	    node_parents[e1].erase(e0);
	  }
      	}
      }
    }
  }

  REP(i, N) {
    if (i == Root)
      cout << 0 << "\n";
    else {
      cout << *(node_parents[i].begin()) + 1 << "\n";
    }
  }


  return 0;
}

