    out = vector<vector<LL>>(N+1);
    in = vector<vector<LL>>(N+1);
    for(int i=0;i<N+M-1;i++){
    	LL u,v;cin >> u >> v;
    	out[u].push_back(v);
        in[v].push_back(u);
    }

    solve();

    for(int i=1;i<=N;i++)cout << ans[i] << endl;
    return 0;
}

