int N, M;
vector<int> adj[100000];
vector<int> adj_rev[100000];

int find_root(){
  for(int i = 0; i < N; i++){
    if(adj_rev[i].size() == 0){
      return i;
    }
  }
}

int main(){
  cin >> N >> M;
  for(int i = 0; i < N - 1 + M; i++){
    int a, b;
    cin >> a >> b;
    adj[a - 1].push_back(b - 1);
    adj_rev[b - 1].push_back(a - 1);
  }
  int root = find_root();

  priority_queue<pair<int, int> > depth_idx;
  depth_idx.push(make_pair(0, root));
  int depth[100000] = {};

  while(!depth_idx.empty()){
    pair<int, int> item = depth_idx.top(); depth_idx.pop();
    int dpt = item.first;
    int now = item.second;
    if(dpt < depth[now]){
      continue;
    }

    for(int i = 0; i < adj[now].size(); i++){
      int next = adj[now][i];
      if(dpt + 1 > depth[next]){
	depth_idx.push(make_pair(dpt + 1, next));
	depth[next] = dpt + 1;
      }
    }
  }

  for(int i = 0; i < N; i++){
    if(i == root){
      cout << 0 << endl;
    }else{
      for(int j = 0; j < adj_rev[i].size(); j++){
	if(depth[i] == depth[adj_rev[i][j]] + 1){
	  cout << adj_rev[i][j] + 1 << endl;
	}
      }
    }
  }
}

