const int MAX_N=1e6+1;
VI G[MAX_N];
int N,M;

int D[MAX_N];
int res[MAX_N];
void solve() {
  REP(u,N) FORR(v,G[u]) {
    D[v]++;
  }

  MINUS(res);
  queue<int> Q;
  REP(u,N) if(D[u]==0) Q.emplace(u);
  assert(SZ(Q)==1);
  while(SZ(Q)) {
    int u=Q.front(); Q.pop();
    FORR(v,G[u]) {
      D[v]--;
      if(D[v]==0) res[v]=u,Q.emplace(v);
    }
  }
  REP(u,N) cout<<res[u]+1<<endl;
}

