void depth_serch(ll now, ll de)
{
    if (vi[now])
    {
        depth[now] = max(depth[now], de);
        rep(i,Size(revg[now])){
            if(depth[now]-1!=depth[revg[now][i]]){
                out[{revg[now][i],now}]=1;
            }
        }
        return;
    }
    vi[now] = true;
    rep(i, Size(g[now]))
    {
        depth[g[now][i]] = max(depth[g[now][i]], de + 1);
        depth_serch(g[now][i], de + 1);
    }
    return;
}

void depth_serch2(ll now, ll de)
{
    if (vi3[now])
    {
        return;
    }
    vi3[now] = true;
    rep(i, Size(g[now]))
    {
        if(out[{now,g[now][i]}]==1)continue;
        depth[g[now][i]] = max(depth[g[now][i]], de + 1);
        depth_serch(g[now][i], de + 1);
    }
    return;
}

void dfs(ll now)
{
    if (vi2[now])
        return;
    vi2[now] = true;
    rep(i, Size(g[now]))
    {
        if (depth[now] + 1 == depth[g[now][i]])
        {
            ans[g[now][i]] = now + 1;
            dfs(g[now][i]);
        }
    }
    return;
}

