    // トポロジカルに処理
    // 入次数が０になったものから処理
    // DAGの最長経路問題
    queue<int> que;
    que.push(root);
    while(que.size()){
        int i = que.front();
        que.pop();
        for(int j : from[i]){
            if(dist[j] + 1 > dist[i]){
                par[i] = j;
                dist[i] = dist[j] + 1;
            }
        }
        // 対象からの辺を削り、入次数が0になったものが次の処理対象
        for(int j : edges[i]){
            indeg[j]--;
            if(indeg[j] == 0) que.push(j);
        }    
    }
    REP(i, N) cout << par[i] + 1 << endl;
    return 0;
}

