#include <bits/stdc++.h>
#define REP(i, n) for (int i = 0; (i) < (int)(n); ++ (i))
using namespace std;

vector<int> solve(int n, int m, vector<vector<int> > const & g, vector<vector<int> > const & g_rev) {
    queue<int> que;
    vector<int> outdegree(n);
    REP (i, n) {
        outdegree[i] = g[i].size();
        if (outdegree[i] == 0) {
            que.push(i);
        }
    }
    vector<int> parent(n, -1);
    while (not que.empty()) {
        int i = que.front();
        que.pop();
        for (int j : g[i]) {
            if (parent[j] == -1) {
                parent[j] = i;
            }
        }
        for (int j : g_rev[i]) {
            -- outdegree[j];
            if (outdegree[j] == 0) {
                que.push(j);
            }
        }
    }
    return parent;
}

int main() {
    int n, m; cin >> n >> m;
    vector<vector<int> > g(n), g_rev(n);
    REP (i, n - 1 + m) {
        int a, b; cin >> a >> b;
        -- a;
        -- b;
        g[a].push_back(b);
        g_rev[b].push_back(a);
    }
    auto parent = solve(n, m, g, g_rev);
    REP (i, n) {
        cout << parent[i] + 1 << endl;
    }
    return 0;
}

