ll N, M;
vector<vector<ll>> paths;
vector<ll> parent_count;

void input() {
    cin >> N >> M;
    paths.resize(N + 1);
    parent_count.resize(N + 1);
    for (ll i = 0; i < N - 1 + M; i++) {
        ll a, b;
        cin >> a >> b;
        paths[a].push_back(b);
        parent_count[b]++;
    }
}

void solve() {
    vector<ll> pars(N + 1, 0);

    vector<bool> visited(N + 1);
    for (auto& targets : paths) {
        for (auto target : targets) {
            visited[target] = true;
        }
    }
    queue<ll> qs;
    for (ll i = 1; i < N + 1; i++) {
        if (not visited[i])
            qs.push(i);
    }

    while(not qs.empty()) {
        auto q = qs.front(); qs.pop();
        auto& targets = paths[q];
        for (auto target : targets) {
            parent_count[target]--;
            if (parent_count[target] == 0) {
                pars[target] = q;
                qs.push(target);
            }
        }
    }
    for (ll i = 1; i < N + 1; i++) {
        cout << pars[i] << endl;
    }
}


int main() {
    input();
    //    cout << solve() << endl;
