vector<int> toposort(vector<vector<int>> &g, vector<int> &h) {
    int n = g.size();
    stack<int> st;
    for(int i = 0; i < n; i++) {
        if(h[i] == 0) {
            st.push(i);
        }
    }
    vector<int> toposorted;
    while(st.size()) {
        int u = st.top();
        st.pop();
        toposorted.emplace_back(u);
        for(auto v : g[u]) {
            h[v]--;
            if(h[v] == 0) {
                st.push(v);
            }
        }
    }
    return toposorted;
}

