void solve() {
    int N, M;
    cin >> N >> M;
    vector<int> D(N);
    vector<vector<int>> G(N);
    for (int i = 0; i < N - 1 + M; i++) {
        int a, b;
        cin >> a >> b;
        a--, b--;
        D[b]++;
        G[a].push_back(b);
    }

    vector<pll> P(N);
    for (int i = 0; i < N; i++) {
        P[i] = {-1, 0};
    }

    int par = 0;
    for(int i = 0; i < N; i++) {
        if (D[i] == 0) {
            par = i;
            break;
        }
    }

    priority_queue<V> Q;
    Q.push({0, -1, par});
    while(!Q.empty()) {
        V p = Q.top(); Q.pop();
        if (P[p.v].first >= p.d) continue;
        P[p.v].first = p.d;
        P[p.v].second = p.par;
        for(int i = 0; i < G[p.v].size(); i++) {
            if (p.d + 1 <= P[G[p.v][i]].first) continue;
            Q.push({p.d + 1, p.v, G[p.v][i]});
        }
    }

    for (int i = 0; i < N; i++) {
        cout << P[i].second + 1 << endl;
    }
}

