void topological(int p,std::vector<std::vector<int>> &g,std::vector<int> &ans){
    ans.pb(p);
    al.erase(p);
    erep(i,g[p]){
         c[i]--;
         if(c[i]==0){
             topological(i,g,ans);
         }
    }
    //return;
}
std::vector<int> topo(std::vector<std::vector<int>> &g){
    std::vector<int> ans;
    rep(i,g.size())al.insert(i);
    c.resize(g.size());
    rep(i,g.size()){
        erep(j,g[i]){
            c[j]++;
        }
    }
    rep(i,g.size()){
        if(c[i]==0&&al.find(i)!=al.end()){
            topological(i,g,ans);
        }
    }
    return ans;
}


