const int N=1e5+2;
const int inf=1e9+1;
vector<int> adj[N],topoo;
unordered_set<int> back[N];
bool used[N];
int head[N],pos[N];
void build_topo(int x){
	for(int i=0;i<adj[x].size();i++){
		if(!used[adj[x][i]]){
			used[adj[x][i]]=true;
			build_topo(adj[x][i]);
		}
	}
	pos[x]=topoo.size();
	topoo.push_back(x);
}
int main(){
	ios::sync_with_stdio(0);
	cin.tie(0);
	unordered_set<int>::iterator ite;
	int i,j,k,n,m,root;
	cin>>n>>m;
	for(i=1;i<=n-1+m;i++){
		cin>>j>>k;
		adj[j].push_back(k);
		back[k].insert(j);
	}
	for(i=1;i<=n;i++){
		if(back[i].size()==0){
			root=i;
			break;
		}
	}
	used[root]=true;;
	build_topo(root);
	for(i=0;i<topoo.size()-1;i++){
		if(back[topoo[i]].find(topoo[i+1])!=back[topoo[i]].end()){
			head[topoo[i]]=topoo[i+1];
		}
		else{
			root=inf;
			for(ite=back[topoo[i]].begin();ite!=back[topoo[i]].end();ite++){
				if(pos[*ite]<root){
					root=pos[*ite];
					head[topoo[i]]=*ite;
				}
			}
		}
	}
	for(i=1;i<=n;i++){
		cout<<head[i]<<endl;
	}
}

