class Searcher;

class Node {
public:
    Node(int id) noexcept
        : id(id)
    {
    }
    int getId(void) const noexcept
    {
        return id;
    }
    std::list<std::shared_ptr<Node>> getPrevs() const noexcept
    {
        return prevs;
    }
    std::list<std::shared_ptr<Node>> getNexts() const noexcept
    {
        return nexts;
    }
    void addPrev(const std::shared_ptr<Node>& node) noexcept
    {
        prevs.push_back(node);
    }
    void addNext(const std::shared_ptr<Node>& node) noexcept
    {
        nexts.push_back(node);
    }

    std::shared_ptr<Searcher> getSearcher() const noexcept
    {
        return searcher;
    }

    void searchedBy(std::shared_ptr<Searcher> searcher) noexcept;

private:
    std::list<std::shared_ptr<Node>> prevs;
    std::list<std::shared_ptr<Node>> nexts;
    std::shared_ptr<Searcher> searcher;
    int id;
};

class Searcher {
public:
    Searcher(std::shared_ptr<Node> prev, std::shared_ptr<Node> current) noexcept
        : prev(prev)
        , current(current)
        , alive(true)
    {
    }
    std::shared_ptr<Node> getCurrent() const noexcept { return current; }
    std::shared_ptr<Node> getPrev() const noexcept { return prev; }
    std::shared_ptr<Searcher> search(std::shared_ptr<Node> next) noexcept
    {
        auto child = std::make_shared<Searcher>(current, next);
        children.push_back(child);
        next->searchedBy(child);
        return child;
    }
    bool isAlive() const noexcept { return alive; }
    void kill() noexcept
    {
        alive = false;
        for (auto child : children) {
            child->kill();
        }
    }

private:
    std::shared_ptr<Node> prev;
    std::shared_ptr<Node> current;
    std::list<std::shared_ptr<Searcher>> children;
    bool alive;
};

void Node::searchedBy(std::shared_ptr<Searcher> searcher) noexcept
{
    if (this->searcher != nullptr) {
        this->searcher->kill();
    }
    this->searcher = searcher;
}

int main(void)
{
    int N, M;

    // get input
    std::cin >> N >> M;
    std::vector<std::shared_ptr<Node>> nodes;
    for (int i = 0; i < N; i++) {
        nodes.emplace_back(std::make_shared<Node>(i + 1));
    }

    // make graph
    for (int i = 0; i < N - 1 + M; i++) {
        int src, dest;
        std::cin >> src >> dest;
        nodes.at(src - 1)->addNext(nodes.at(dest - 1));
        nodes.at(dest - 1)->addPrev(nodes.at(src - 1));
    }

    // search root
    std::shared_ptr<Node> root = *(nodes.begin());
    while (root->getPrevs().size() > 0) {
        root = *(root->getPrevs().begin());
    }

    std::queue<std::shared_ptr<Searcher>> searcherQueue;
    searcherQueue.push(std::make_shared<Searcher>(nullptr, root));
    root->searchedBy(searcherQueue.front());

    while (!searcherQueue.empty()) {
        auto searcher = searcherQueue.front();
        searcherQueue.pop();
        auto current = searcher->getCurrent();
        for (auto next : current->getNexts()) {
            auto nextSearcher = searcher->search(next);
            searcherQueue.push(nextSearcher);
        }
    }

    for (auto node : nodes) {
        auto searcher = node->getSearcher();
        auto prev = searcher->getPrev();
        if (prev) {
            std::cout << prev->getId() << std::endl;
        } else {
            std::cout << 0 << std::endl;
        }
    }

    return 0;
}

