#include<bits/stdc++.h>
using namespace std;

vector<int> tsort(const vector<vector<int>> &g){
  int N = (int)g.size();
  vector<int> ret;
  vector<bool> is_temp(N, false);
  vector<bool> is_perm(N, false);
  function<void(int)> visit = [&](int n){
    if(is_temp[n])
      assert(false);
    else if(!is_perm[n]){
      for(int to:g[n]){
        visit(to); 
      }
      is_perm[n] = true;
      is_temp[n] = false;
      ret.emplace_back(n);
    }
  };
  for(int i=0;i<N;i++){
    if(!is_perm[i]&&!is_temp[i]){
      visit(i);
      // assert(t != 1);
    }
  }
  reverse(ret.begin(), ret.end());
  return ret;
}

int main(){
  int N, M;
  cin >> N >> M;
  vector<vector<int>> g(N);
  for(int i=0;i<N+M-1;i++){
    int a,b;
    cin >> a >> b;
    a--;b--;
    g[a].emplace_back(b);
  }
  vector<int> tsorted = tsort(g);
  vector<int> ans(N, -1);
  for(auto&& u:tsorted)
    for(auto&& v:g[u])
      ans[v] = u; 
  for(auto&& x:ans)cout << x+1 << endl;
}

