	parent[start] = 0;
	queue<ll> qu;
	qu.push(start);
	while (!qu.empty()) {
		ll cur = qu.front();
		qu.pop();
		for (auto next : G[cur]) {
			node[next]--;
			if (node[next] == 0) {
				parent[next] = cur;
				qu.push(next);
			}
		}
	}
}

