#include<iostream>
#include<map>
#include<stack>
#include<vector>
#include<set>
using namespace std;

int main(){
    int n, m;
    scanf("%d %d", &n, &m);

    map<int,set<int>> v;
    vector<pair<int,int>> edge;

    int a, b;
    for(int i = 0; i < n+m-1; i++){
        scanf("%d %d", &a, &b);
        v[a].insert(b);
        edge.push_back({a,b});
    }

    // TLE不可避
    for(int i = 0; i < n+m-1; i++){
        pair<int,int> e = edge[i];
        stack<int> s;
        int from = e.first, to = e.second;
        vector<bool> visit(n, 0);

        for(auto p : v[from]){
            if(p == to) continue;
            s.push(p);
        }
        bool judge = false;
        while(!s.empty()){
            int n = s.top();    s.pop();
            if(n == to){
                judge = true;
                break;
            }
            if(visit[n])    continue;
            visit[n] = true;

            for(auto p : v[n]){
                int next = p;
                if(!visit[next])    s.push(next);
            }
        }

        if(judge){
            v[from].erase(to);
        }
    }

    vector<int> ans(n+1, 0);
    for(auto p : v){
        for(auto q : p.second){
            ans[q] = p.first;
        }
    }

    for(int i = 1; i <= n; i++) printf("%d\n", ans[i]);

    return 0;
}

