int main(){
  int n, m;

  scanf("%d%d", &n, &m);

  for(int i=0;i<n+m-1;i++){
    int u, v;
    scanf("%d%d", &u, &v);
    u--; v--;

    dag[u].push_back(v);
    inedge[v]++;
  }

  int root = 0;

  for(int i=0;i<n;i++){
    if(inedge[i] == 0) root = i;
  }

  queue<int> que;

  que.push(root);

  while(que.size()){
    int p = que.front();
    que.pop();

    for(int i=0;i<dag[p].size();i++){
      int to = dag[p][i];
      inedge[to]--;

      if(inedge[to] == 0){
        que.push(to);
      } else {
        added.insert({p, to});
      }
    }
  }

  int parent[SIZE] = {};

  for(int i=0;i<n;i++){
    for(int j=0;j<dag[i].size();j++){
      int p = i, q = dag[i][j];
      if(added.find({p, q}) == added.end()){
        parent[q] = p;
      }
    }
  }

  parent[root] = -1;

  for(int i=0;i<n;i++){
    printf("%d\n", parent[i]+1);
  }

  return 0;
}

