long long int parent = 0;
long long int recursive(vector<long long int>&len, long long int idx, vector<vector<long long int>>&E){
	if( len[idx] || idx == parent ){
		return len[idx];
	}
	for( auto e : E[idx] ){
		len[idx] = max(len[idx], recursive(len, e, E) + 1);
	}
	return len[idx];
}

int main(){
	long long int N, M;
	cin >> N >> M;
	vector<vector<long long int>>D(N), E(N);
	vector<long long int>count(N), count2(N);
	for( size_t i = 0; i < N + M - 1; i++ ){
		long long int a, b;
		cin >> a >> b;
		a--; b--;
		D[a].push_back(b);
		E[b].push_back(a);

		count[b]++;
		count2[a]++;
	}
	for( size_t i = 0; i < N; i++ ){
		if( count[i] == 0 ){
			parent = i;
			break;
		}
	}
	vector<long long int>len(N, 0);
	for( size_t i = 0; i < N; i++ ){
		recursive(len, i, E);
	}

	vector<long long int>parentid(N, 0);

	len[parent] = 0;
	queue<pair<long long int, long long int>>que;
	que.push(make_pair(parent, 0));
	while( que.size() ){
		auto now = que.front(); que.pop();
		if( len[now.first] != now.second ){
			continue;
		}

		for( auto d : D[now.first] ){
			if( len[d] == now.second + 1 ){
				parentid[d] = now.first + 1;

				que.push(make_pair(d, now.second + 1));
			}
		}
	}

	for( size_t i = 0; i < N; i++ ){
		cout << parentid[i] << endl;
	}
}

