vector<int> TopologicalSort(set<pair<int,int>> edges,int n){
  //nは頂点数
  //0_index
  vector<int> results;
  set<int> notins;//入力辺を持たない辺の集合
  vector<set<int>> ins(n);//入力辺集合
  //notinsを構築する
  for(auto i:edges){
    ins[i.second].insert(i.first);
  }
  for(int i=0;i<n;i++){
    if(ins[i].size()==0){
      notins.insert(i);
    }
  }
  //notins構築完了
  vector<set<int>> nexts(n);//各頂点に対する辺情報
  for(auto i:edges){
    nexts[i.first].insert(i.second);
  }
  //辺入力完了
  //本計算

  while(notins.size()>0){
    int nownode=*notins.begin();
    notins.erase(nownode);
    results.push_back(nownode);
    set<int>tmp=nexts[nownode];
    for(auto i:tmp){
      int nownext=i;
      nexts[nownode].erase(nownext);
      edges.erase({nownode,nownext});
      ins[nownext].erase(nownode);
      if(ins[nownext].size()==0){
        notins.insert(nownext);
      }
    }
  }
  if(edges.size()>0){
    //NOT DAG
    ;
  }
  return results;
}
