using ll = long long;
class Node{
 public:
  vector<ll> children;
  ll parent;
  ll depth;
};
void defdepth(vector<Node*>& node,ll i,ll de,ll pa){
    if(de>node[i]->depth){
      node[i]->depth=de;
      node[i]->parent=pa;
    }else{return;}
  if(node[i]->children.size()==0){
    return;
  }
  for(int ii=0;ii<node[i]->children.size();++ii){
    defdepth(node,node[i]->children[ii],node[i]->depth+1,i);
  }
  return;
}
ll sarchroot(vector<Node*>& node){
  vector<int> n(node.size(),0);
  for(int i=1;i<node.size();++i){
  	for(int ii=0;ii<node[i]->children.size();++ii){
      n[node[i]->children[ii]]=1;
  	}
  }
  for(int i=1;i<node.size();++i){if(n[i]==0)return i;}
}
int main(){
  ll N,M;
  cin>>N>>M;
  vector<Node*> node;
  node.push_back(new Node());
  for(ll i=0;i<N;++i){node.push_back(new Node());}
  for(ll i=0;i<N+1;++i){node[i]->depth=0;}
  for(ll i=0;i<N+M-1;++i){
    ll a,b;
    cin>>a>>b;
    node[a]->children.push_back(b);
    //node[b]->parent.push_back(a);
  }
  for(ll i=1;i<=N;++i){
    ll root = sarchroot(node);
    defdepth(node,root,1,0);
  }
  for(ll i=1;i<=N;++i){
      cout<<node[i]->parent<<endl;

  }
  return 0;
}

