class Node{
 public:
  vector<ll> children;
  vector<ll> parent;
};
ll lenNode(vector<Node*>& node,ll i){
  if(node[i]->parent.size()==0)return 0;
  ll maxlen=0;
  ll maxii=0;
  for(int ii=0;ii<node[i]->parent.size();++ii){
   		ll tmp = lenNode(node,node[i]->parent[ii]);
        if(tmp>maxlen){
          maxlen=tmp;
          maxii=ii;
        }
  }
  return lenNode(node,node[i]->parent[maxii])+1;
}
