      ll maxlen=-1;
      for(int ii=0;ii<node[i]->parent.size();++ii){
        ll tmp = lenNode(node,node[i]->parent[ii]);
        if(tmp>maxlen){
          maxlen=tmp;
          maxparent=node[i]->parent[ii];
