// ---
const int AnLim = POW_10_5;
int N, M, A[AnLim], B[AnLim];
vector<int> P[AnLim];
int root, dist[AnLim];

void Sub(int i) {
  if (dist[i] != INF) { return; }
  if (P[i].size() == 1) {
    Sub(P[i][0]);
    dist[i] = dist[P[i][0]] + 1;
    return;
  }
  REP(j, P[i].size()) { Sub(P[i][j]); }
  int aj = 0;
  FOR(j, 1, P[i].size() - 1) {
    if (dist[P[i][j]] > dist[P[i][aj]]) { aj = j; }
  }
  dist[i] = dist[P[i][aj]] + 1;
  P[i] = {P[i][aj]};
  return;
}

void Ans() {
  REP(i, N-1+M) {
    P[B[i]].push_back(A[i]);
  }

  REP(i, N) {
    if (P[i].size() == 0) {
      P[i].push_back(-1);
      root = i;
      break;
    }
  }

  REP(i, N) { dist[i] = INF; }
  dist[root] = 0;
  REP(i, N) { Sub(i); }

  REP(i, N) {
    P[i][0]++;
  }

  return;
}

signed main() {
  cin >> N >> M;
  REP(i, N-1+M) { cin >> A[i] >> B[i]; }
  REP(i, N-1+M) { A[i]--; B[i]--; }

  Ans();

  REP(i, N) {
    cout << P[i][0] << endl;
  }
  return 0;
}

