	for(int i=0;i<adj[x].size();i++){
		if(!used[adj[x][i]]){
			level[adj[x][i]]=level[x]+1;
			head[adj[x][i]]=x;
			used[adj[x][i]]=1;
			build_topo(adj[x][i]);
			used[adj[x][i]]=2;
		}
		else{
			if(used[adj[x][i]]==2&&level[head[adj[x][i]]]<=level[x]){
				head[adj[x][i]]=x;
			}
		}
	}
}
