typedef struct edge_t
{
    int level;
    int n_child;
    int parent;
    int *child;
} edge;

typedef struct input_t
{
    int a;
    int b;
} input;

int qsort_input(const void *a, const void *b)
{
    return ((*(input *)a).a) - ((*(input *)b).a);
}

void set_level(edge ed[], int p, int level)
{
    int i;

    p--;

    if (ed[p].level < level) {
        ed[p].level = level;

        for (i = 0; i < ed[p].n_child; i++) {
            set_level(ed, ed[p].child[i], level + 1);
        }
    }

    return;
}

int main(int argc, char *argv[])
{
    int n, m;
    input in[100000];
    edge ed[100000];
    int child_pool[100000];
    int child_ptr;
    char is_root[100000];
    int root;
    int i, j, k;
    int child;

    scanf("%d %d", &n, &m);

    for (i = 1; i <= n; i++) {
        is_root[i] = 1;
    }
    for (i = 0; i < n - 1 + m; i++) {
        scanf("%d %d", &in[i].a, &in[i].b);
        is_root[in[i].b] = 0;
    }
    for (i = 1; i <= n; i++) {
        if (is_root[i] == 1) {
            root = i;
        }
    }

    qsort(in, n - 1 + m, sizeof(input), qsort_input);

    // グラフ構造体の作成
    child_ptr = 0;
    j = 0;
    for (i = 0; i < n; i++) {
        ed[i].level = -1;
        ed[i].child = child_pool + child_ptr;
        ed[i].n_child = 0;
        ed[i].parent = 0;
        k = 0;
        while(j < n - 1 + m) {
            if (in[j].a != i + 1) {break;}
            ed[i].child[k] = in[j].b;
            k++;
            j++;
            child_ptr++;
            ed[i].n_child++;
        }
    }

    // レベル付け
    set_level(ed, root, 0);

    // 親の登録
    for (i = 0; i < n; i++) {
        for (j = 0; j < ed[i].n_child; j++) {
            child = ed[i].child[j];
            if (ed[child - 1].level - ed[i].level == 1) {
                ed[child - 1].parent = i + 1;
            }
        }
    }

    for (i = 0; i < n; i++) {
        printf("%d\n", ed[i].parent);
    }

    return 0;
}

