#include<stdio.h>
#include<stdlib.h>

typedef struct directedGraph{
  int *vertex;
  int *next;
  int *start;
  int v,e;
  int pointer;
} graph;

graph* newGraph(const int v,const int e){
  graph *g=(graph *)malloc(sizeof(graph));
  g->vertex=(int *)calloc(e,sizeof(int));
  g->next=(int *)calloc(e,sizeof(int));
  g->start=(int *)calloc(v,sizeof(int));
  for(int i=0;i<v;i++) g->start[i]=-1;
  g->v=v;
  g->e=e;
  g->pointer=0;
  return g;
}

void freeGraph(graph *g){
  free(g->vertex);
  free(g->next);
  free(g->start);
  free(g);
  return;
}

void addEdge(graph *g,const int from,const int to){
  const int p=g->pointer;
  g->vertex[p]=to;
  g->next[p]=g->start[from];
  g->start[from]=p;
  g->pointer++;
  return;
}

void run(void){
  int n,m;
  scanf("%d%d",&n,&m);
  graph *g=newGraph(n,n-1+m);
  int i;
  for(i=0;i<n-1+m;i++){
    int a,b;
    scanf("%d%d",&a,&b);
    a--;
    b--;
    addEdge(g,a,b);
  }
  int *parent=(int *)calloc(n,sizeof(int));
  int *cnt=(int *)calloc(n,sizeof(int));
  int *q=(int *)calloc(n,sizeof(int));
  for(i=0;i<n;i++){
    for(int p=g->start[i];p!=-1;p=g->next[p]){
      int u=g->vertex[p];
      cnt[u]++;
    }
  }
  int front=0;
  int last=0;
  for(i=0;i<n;i++) if(cnt[i]==0) q[last++]=i;
  parent[q[0]]=-1;
  while(last<n){
    int v=q[front++];
    for(int p=g->start[v];p!=-1;p=g->next[p]){
      int u=g->vertex[p];
      cnt[u]--;
      if(cnt[u]==0){
	parent[u]=v;
	q[last++]=u;
      }
    }
  }
  for(i=0;i<n;i++) printf("%d\n",parent[i]+1);
}

int main(void){
  run();
  return 0;
}

