struct edge_t {
    int from;
    int to;
};
struct node_t {
    int parent;
    int depth;
    node_t():parent(-2),depth(-1){
    }
};

node_t parentFind(
    int i,
    int n,
    vector<vector<edge_t> > &abs,
    vector<node_t> &node
    ){
  if (node[i].parent!=-2) {
      return node[i];
  }
  if (abs[i].size()==0){
      node[i].parent = -1;
      node[i].depth = 0;
      return node[i];
  }
  vector<edge_t> &es(abs[i]);
  int m = es.size();
  for (int j=0;j<m;j++) {
    node_t p = parentFind(es[j].from,n,abs,node);
    if (node[i].depth < p.depth + 1) {
        node[i].depth = p.depth + 1;
        node[i].parent = es[j].from;
    }
  }
  return node[i];
}

int main() {
  int n, m, t;

  while (cin>>n>>m) {
    t = n - 1 + m;
    vector<vector<edge_t> > abs(n);
    vector<node_t> node(n);
    edge_t e;
    for (int i=0;i<t;i++) {
      cin >> e.from >> e.to;
      e.from--;
      e.to--;
      abs[e.to].push_back(e);
    }
    for (int i=0;i<n;i++) {
      cout << parentFind(i,n,abs,node).parent+1 << endl;
    }
  }
  return 0;
}

