void makemkj(rs g[],mkj x[],long long n){
    long long i,ms=0,nst=g[0].st;
    for(i=1;i<n;i++){
        if(g[i].st!=g[i-1].st){
            x[nst].kz=i-ms;
            x[nst].st=ms;
            nst=g[i].st;ms=i;
        }
    }
    x[nst].kz=n-ms;
    x[nst].st=ms;
}

//topological-sort(vertex:1-indexed)
long long topological_sort(long long n,long long m,rs g[],mkj x[],long long res[]){
  long long cnt[524288]={0},c=0,i,j,w;
  for(i=0;i<m;i++){
    cnt[g[i].fi]++;
  }
  for(i=1;i<=n;i++){
    if(cnt[i]==0){
      res[c]=i;
      c++;
    }
  }
  i=0;
  while(i<c){
    w=res[i];
    for(j=x[w].st;j<x[w].st+x[w].kz;j++){
      cnt[g[j].fi]--;
      if(cnt[g[j].fi]==0){
        res[c]=g[j].fi;
        c++;
      }
    }
    i++;
  }
  if(c==n){return 0;}
  else{return -1;}
}

