		siRes = -1;
	}
#else
	printf("%s", pcpLine);
#endif

	return 0;
}

// 辺 - 追加
int
fAddEdge(
	int piVFNo					// <I> 頂点 - 元
	, int piVTNo				// <I> 頂点 - 先
)
{
	sz1Edge[siECnt].miVNo = piVTNo;
	sz1Edge[siECnt].mzpNext = sz1Vtx[piVFNo].mzpEdge;
	sz1Vtx[piVFNo].mzpEdge = &sz1Edge[siECnt];
	sz1Vtx[piVTNo].miFCnt++;
	siECnt++;

	return 0;
}

// 根からの距離 - セット
int
fSetLen(
	int piVNo					// <I> 頂点
	, int piLen					// <I> 距離
)
{
	// 根からの距離 - 更新
	if (sz1Vtx[piVNo].miLen < piLen) {
		sz1Vtx[piVNo].miLen = piLen;
	}

	// 接続元頂点数
	sz1Vtx[piVNo].miFCnt--;
	if (sz1Vtx[piVNo].miFCnt > 0) {
		return 0;
	}

	// 辺でループ
	Edge *lzpEdge = sz1Vtx[piVNo].mzpEdge;
	while (lzpEdge != NULL) {

		// 下位へ
		fSetLen(lzpEdge->miVNo, piLen + 1);

		// 次の辺へ
		lzpEdge = lzpEdge->mzpNext;
	}

	return 0;
}

// 接続元頂点 - セット
int
fSetVFNo(
	int piVFNo					// <I> 頂点 - 元
	, int piVTNo				// <I> 頂点 - 先
)
{
	// 処理済フラグ
	if (sz1Vtx[piVTNo].mcDone != D_OFF) {
		return 0;
	}
	sz1Vtx[piVTNo].mcDone = D_ON;

	// 接続元頂点 - セット
	sz1Vtx[piVTNo].miVFNo = piVFNo;

	// 辺でループ
	Edge *lzpEdge = sz1Vtx[piVTNo].mzpEdge;
	while (lzpEdge != NULL) {

		// 根からの距離
		int liLen = sz1Vtx[lzpEdge->miVNo].miLen - sz1Vtx[piVTNo].miLen;
		if (liLen == 1) {
			fSetVFNo(piVTNo, lzpEdge->miVNo);
		}

		// 次の辺へ
		lzpEdge = lzpEdge->mzpNext;
	}

	return 0;
}

// 実行メイン
int
fMain(
)
{
	int i;
	char lc1Buf[1024];

	// データ - 初期化
	memset(sz1Vtx, 0, sizeof(sz1Vtx));
	siECnt = 0;

	// 頂点数・追加数 - 取得
	int liACnt;
	fgets(lc1Buf, sizeof(lc1Buf), szpFpI);
	sscanf(lc1Buf, "%d%d", &siVCnt, &liACnt);

	// 辺 - 取得
	for (i = 0; i < siVCnt - 1 + liACnt; i++) {
		int liVNo1, liVNo2;
		fgets(lc1Buf, sizeof(lc1Buf), szpFpI);
		sscanf(lc1Buf, "%d%d", &liVNo1, &liVNo2);

		// 辺 - 追加
		fAddEdge(liVNo1, liVNo2);
	}

	// 根 - 取得
	int liVNo;
	for (i = 1; i <= siVCnt; i++) {
		if (sz1Vtx[i].miFCnt == 0) {
			liVNo = i;
			break;
		}
	}

	// 根からの距離 - セット
	fSetLen(liVNo, 0);

	// 接続元頂点 - セット
	fSetVFNo(0, liVNo);

	// 出力
	for (i = 1; i <= siVCnt; i++) {
		sprintf(lc1Buf, "%d\n", sz1Vtx[i].miVFNo);
		fOutLine(lc1Buf);
	}

	return 0;
}

