fun main(args: Array<String>) {
    val (N, M) = readInputLine().split(" ").map { it.toInt() }

    val edges = Array(N) { mutableSetOf<Int>() }
    val revEdges = Array(N) { mutableSetOf<Int>()}

    repeat(N + M - 1) {
        val (A, B) = readInputLine().split(" ").map { it.toInt() - 1 }
        edges[A].add(B)
        revEdges[B].add(A)
    }

    val topologicalSorted = IntArray(N) { -1 }
    val searched = mutableSetOf<Int>()
    var current = N - 1

    fun topologicalSort(node: Int) {
        for (c in edges[node]) {
            if (topologicalSorted[c] != -1) {
                continue
            }
            topologicalSort(c)
        }
        topologicalSorted[node] = current
        current--
        searched.add(node)
    }

    repeat(N) {
        if (topologicalSorted[it] == -1) {
            topologicalSort(it)
        }
    }

    repeat(N) {
        if (revEdges[it].isEmpty()) {
            println(0)
        } else {
            var minNode = -1
            var minOrder = -1
            for (r in revEdges[it]) {
                if (topologicalSorted[r] > minOrder) {
                    minOrder = topologicalSorted[r]
                    minNode = r
                }
            }
            println(minNode + 1)
        }
    }
}

