import java.io.*;
import java.util.*;

class Solver {
  final int n, m;
  final int[] as, bs;
  List<List<Integer>> parentCandidateMatrix;
  int[] depth;

  Solver(int n, int m, int[] as, int[] bs) {
    this.n = n;
    this.m = m;
    this.as = as;
    this.bs = bs;
  }

  private int calculateDepth(int index) {
    if (depth[index] >= 0) {
      return depth[index];
    }

    depth[index] = 0;
    for (int parentCandidate: parentCandidateMatrix.get(index)) {
      depth[index] = Math.max(depth[index], calculateDepth(parentCandidate) + 1);
    }
    return depth[index];
  }

  public int[] solve() {
    parentCandidateMatrix = new ArrayList<>();
    for (int i = 0; i <= n; i++) {
      parentCandidateMatrix.add(new ArrayList<>());
    }

    for (int i = 0; i < n + m - 1; i++) {
      parentCandidateMatrix.get(bs[i]).add(as[i]);
    }

    depth = new int[n + 1];
    Arrays.fill(depth, -1);
    for (int i = 1; i <= n; i++) {
      calculateDepth(i);
    }

    int[] answers = new int[n];
    for (int i = 1; i <= n; i++) {
      for (int parentCandidate: parentCandidateMatrix.get(i)) {
        if (depth[i] == depth[parentCandidate] + 1) {
          answers[i - 1] = parentCandidate;
          break;
        }
      }
    }
    return answers;
  }
}

public class Main {
  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int m = reader.nextInt();
    int[] as = new int[n + m - 1];
    int[] bs = new int[n + m - 1];
    for (int i = 0; i < n + m - 1; i++) {
      as[i] = reader.nextInt();
      bs[i] = reader.nextInt();
    }
    for (int answer : new Solver(n, m, as, bs).solve()) {
      out.println(answer);
    }
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

class ContestReader {
  private BufferedReader reader;
  private StringTokenizer tokenizer;

  ContestReader(InputStream in) {
    reader = new BufferedReader(new InputStreamReader(in));
  }

  public String next() {
    while (tokenizer == null || !tokenizer.hasMoreTokens()) {
      try {
        tokenizer = new java.util.StringTokenizer(reader.readLine());
      } catch (Exception e) {
        throw new RuntimeException(e);
      }
    }
    return tokenizer.nextToken();
  }

  public int nextInt() {
    return Integer.parseInt(next());
  }

  public long nextLong() {
    return Long.parseLong(next());
  }

  public double nextDouble() {
