class ModCalculator {
  private final long mod;

  ModCalculator(long mod) {
    this.mod = mod;
  }

  public long add(long a, long b) {
    return (a + b) % mod;
  }

  public long sub(long a, long b) {
    return (a - b + mod) % mod;
  }

  public long mul(long a, long b) {
    return (a * b) % mod;
  }

  public long pow(long a, long b) {
    if (b == 0) {
      return 1;
    }
    long v = pow(mul(a, a), b / 2);
    if (b % 2 == 1) {
      return mul(v, a);
    } else {
      return v;
    }
  }

  public long inverse(long a) {
    return pow(a, mod - 2);
  }

  public long div(long a, long b) {
    return mul(a, inverse(b));
  }
}

class ModCombinationCache {
  private final ModCalculator modCalculator;
  private final List<Long> factorialCache;
  private final List<Long> factorialInverseCache;

  public ModCombinationCache(ModCalculator modCalculator) {
    this.modCalculator = modCalculator;
    factorialCache = new ArrayList<>();
    factorialCache.add(1L);
    factorialInverseCache = new ArrayList<>();
    factorialInverseCache.add(1L);
  }

  private void resize(int n) {
    for (int i = factorialCache.size() - 1; i < n; i++) {
      long v = modCalculator.mul(factorialCache.get(i), i + 1);
      factorialCache.add(v);
      factorialInverseCache.add(modCalculator.inverse(v));
    }
  }

  public long getP(int n) {
    resize(n);
    return factorialCache.get(n);
  }

  public long getC(int n, int k) {
    resize(n);
    return modCalculator.mul(factorialCache.get(n), modCalculator.mul(factorialInverseCache.get(k), factorialInverseCache.get(n-k)));
  }
}

class Algorithm {
  private static void swap(Object[] list, int a, int b) {
    Object tmp = list[a];
    list[a] = list[b];
    list[b] = tmp;
  }

  public static <T extends Comparable<? super T>> boolean nextPermutation(T[] ts) {
    int rightMostAscendingOrderIndex = ts.length - 2;
    while (rightMostAscendingOrderIndex >= 0 &&
        ts[rightMostAscendingOrderIndex].compareTo(ts[rightMostAscendingOrderIndex + 1]) >= 0) {
      rightMostAscendingOrderIndex--;
    }
    if (rightMostAscendingOrderIndex < 0) {
      return false;
    }

    int rightMostGreatorIndex = ts.length - 1;
    while (ts[rightMostAscendingOrderIndex].compareTo(ts[rightMostGreatorIndex]) >= 0) {
      rightMostGreatorIndex--;
    }

    swap(ts, rightMostAscendingOrderIndex, rightMostGreatorIndex);
    for (int i = 0; i < (ts.length - rightMostAscendingOrderIndex - 1) / 2; i++) {
      swap(ts, rightMostAscendingOrderIndex + 1 + i, ts.length - 1 - i);
    }
    return true;
  }

  public static void shuffle(int[] array) {
    Random random = new Random();
    int n = array.length;
    for (int i = 0; i < n; i++) {
      int randomIndex = i + random.nextInt(n - i);

      int temp = array[i];
      array[i] = array[randomIndex];
      array[randomIndex] = temp;
    }
  }

  public static void shuffle(long[] array) {
    Random random = new Random();
    int n = array.length;
    for (int i = 0; i < n; i++) {
      int randomIndex = i + random.nextInt(n - i);

      long temp = array[i];
      array[i] = array[randomIndex];
      array[randomIndex] = temp;
    }
  }

  public static void sort(int[] array) {
    shuffle(array);
    Arrays.sort(array);
  }

  public static void sort(long[] array) {
    shuffle(array);
    Arrays.sort(array);
  }
}

class UnionFind {
  int[] parents;
  int[] ranks;

  UnionFind(int n) {
    parents = new int[n];
    ranks = new int[n];

    for (int i = 0; i < n; i++) {
      parents[i] = i;
    }
  }

  public int getRoot(int index) {
    if (parents[index] == index) {
      return index;
    } else {
      parents[index] = getRoot(parents[index]);
      return parents[index];
    }
  }

  public boolean sameGroup(int a, int b) {
    return getRoot(a) == getRoot(b);
  }

  public void merge(int a, int b) {
    int rootA = getRoot(a);
    int rootB = getRoot(b);
    if (rootA == rootB) {
      return;
    }
    if (ranks[rootA] < ranks[rootB]) {
      parents[rootA] = rootB;
    } else if (ranks[rootB] < ranks[rootA]) {
      parents[rootB] = rootA;
    } else {
      parents[rootA] = rootB;
      ranks[rootB]++;
    }
  }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
	private class Node {
		public List<Integer> parents = null;
		public List<Integer> children = null;
		public List<Integer> depths = null;

		public int setParents = 0;
		public int trueParent = -1;
		public int trueDepth = -1;

		public Node() {
			parents = new ArrayList<Integer>();
			children = new ArrayList<Integer>();
			depths = new ArrayList<Integer>();
		}

		public void addParent(int p) {
			parents.add(p);
			depths.add(-1);
		}

		public void setDepth(int parent, int depth) {
			for (int i=0; i<parents.size(); i++) {
				if (parents.get(i) == parent) {
					depths.set(i, depth);
				}
			}
			setParents++;

			if (setParents >= parents.size()) {
				for (int i=0; i<depths.size(); i++) {
					if (trueDepth < depths.get(i)) {
						trueDepth = depths.get(i);
						trueParent = parents.get(i);
					}
				}
			}
		}

		public int getDepth() {
			if (parents.size() == 0) {
				return 0;
			}
			return trueDepth;
		}

		public int getTrueParent() {
			if (parents.size() == 0) {
				return 0;
			}
			return trueParent;
		}

		public boolean isRoot() {
			if (parents.size() == 0) {
				return true;
			} else {
				return false;
			}
		}
	}

	private int getRoot(Node[] nodes) {
		int root = 0;
		for (root=1; root<nodes.length; root++) {
			if (nodes[root].isRoot()) {
				break;
			}
		}

		return root;
	}

	public void solve() {
		Scanner in = new Scanner(System.in);
		int N = in.nextInt();
		int M = in.nextInt();

		Node[] nodes = new Node[N+1];
		for (int i=0; i<N+1; i++) {
			nodes[i] = new Node();
		}

		for (int i=0; i<N+M-1; i++) {
			int a = in.nextInt();
			int b = in.nextInt();

			nodes[a].children.add(b);
			nodes[b].addParent(a);
		}

		in.close();

		int root = getRoot(nodes);

		ArrayList<Integer> queue = new ArrayList<Integer>();
		queue.add(root);

		while (queue.size() > 0) {
			int target = queue.remove(0);
			int depth = nodes[target].getDepth();
			if (depth == -1) {
				// 別の親から入ってくるのを待つ
				continue;
			}

			for (Integer x : nodes[target].children) {
				nodes[x].setDepth(target, depth+1);
				queue.add(x);
			}
		}

		for (int i=1; i<N+1; i++) {
			System.out.println(nodes[i].getTrueParent());
		}
	}

	public static void main(String[] args) {
		Main main = new Main();
		main.solve();
	}
}

