final class Solver {
	static final Solver INSTANCE = new Solver();

	void solve(Supplier<String> sc) {
		int N = Integer.parseInt(sc.get());
		int M = Integer.parseInt(sc.get());
		BitSet[] graph = new BitSet[N];
		BitSet[] reversed = new BitSet[N];
		int root;
		{
			BitSet child = new BitSet(N);
			Arrays.setAll(graph, $ -> new BitSet());
			Arrays.setAll(reversed, $ -> new BitSet());
			for (int i = 0; i < N - 1 + M; i++) {
				int A = Integer.parseInt(sc.get()) - 1;
				int B = Integer.parseInt(sc.get()) - 1;

				graph[A].set(B);
				reversed[B].set(A);

				child.set(B);
			}
			root = child.nextClearBit(0);
		}

		Queue<Integer> queue = new ArrayDeque<>();
		queue.add(root);
		int[] parent = new int[N];
		while (!queue.isEmpty()) {
			int remove = queue.remove();
			PrimitiveIterator.OfInt iterator = graph[remove].stream().iterator();
			while (iterator.hasNext()) {
				int next = iterator.next();
				reversed[next].flip(remove);
				if (!reversed[next].isEmpty()) continue;
				parent[next] = remove;
				queue.add(next);
			}
		}
		parent[root] = -1;
		for (int i : parent) {
			System.out.println(i + 1);
		}
	}
}

