    while(!q.isEmpty())
    {
      int proc = q.pop();
      if(schd[proc] == 0 || g.get(proc).size() > 1)
        for(Integer e : g.get(proc))
        {
          prof[e] = proc;
          q.add(e);
        }
      schd[proc] = 1;
    }

    for(int i = 1; i <= n; i++)
    {
      System.out.println(prof[i]);
    }
  }


