import java.util.*;
public class Main {
	static Scanner s =new Scanner(System.in);
	public static void main(String[] $){
		int N=s.nextInt(), M=s.nextInt(); //N:頂点数、　M:追加の辺の数
		int[] in=new int[N]; //各頂点の入次数
		int[] ret=new int[N]; // 返却用の配列
		HashMap<Integer, ArrayList<Integer>> lis = new HashMap<Integer,ArrayList<Integer>>(); //各頂点についてその行き先を保持
		for(int i=0;i<N-1+M;i++){
			int from =s.nextInt()-1, to=s.nextInt()-1; //それぞれの頂点番号 1~N を 0~N-1
			in[to]++;
			if (lis.containsKey(from)) lis.get(from).add(to);
			else {
				ArrayList<Integer> al = new ArrayList<Integer>();
				al.add(to);
				lis.put(from, al);
			}
		}
		// 根は入次数が０のはず。もともと根付き木であるからちょうど1つ存在。
		int root=0;
		for(int i=0;i<N;i++)
			if(in[i]==0) root=i;
		//
		ArrayDeque<Integer> q=new ArrayDeque<>(); //両端キュー
		q.add(root);
		while(!q.isEmpty()){
			int p=q.poll(); //先頭要素を取得し削除
			if (!lis.containsKey(p)) continue;
			for(int o:lis.get(p)){ //pの各々の子らに対し、
				if(--in[o]==0){ // p以外に親がいない、pを親のノードのリストから消す
					ret[o]=p+1; //pの番号を代入
					q.add(o); 
				}
			}
		}
		// for回さずに表示できる
		Arrays.stream(ret).forEach(System.out::println);
	}
}

import java.util.Scanner;
import java.util.Stack;

public class Main {

	private static int max = 0;
	private static int count = 0;
	static Stack<Integer> list = new Stack<Integer>();

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		Scanner scan = new Scanner(System.in);
		int n = scan.nextInt();
		int m = scan.nextInt();
		int[][] arr01 = new int[n + 1][n + 1];
		for (int i = 1; i <= n + m - 1; i++) {
			arr01[scan.nextInt()][scan.nextInt()] = 1;
		}
		int[][] ans = new int[n + 1][n + 1];
		for (int i = 1; i <= n; i++) {
			for (int j = 1; j <= n; j++) {
				if (arr01[j][i] != 0) {
					ans[j][i] = max(arr01, i, j);
					max = 0;
					count = 0;
				}
			}
		}
		for (int i = 1; i <= n; i++) {
			System.out.println(maxPath(ans, i));
		}
		scan.close();
	}

	private static int max(int[][] arr01, int col, int row) {

		count++;
		list.add(row);
		for (int i = 1; i < arr01.length; i++) {
			if (arr01[i][row] != 0) {
				max(arr01, row, i);
			}
		}

		if (count > max) {
			max = count;
		}
		count--;
		list.pop();

		return max;

	}

	private static int maxPath(int ans[][], int col) {
		int max = 0;
		int ret = 0;
		for (int i = 1; i < ans.length; i++) {
			if (ans[i][col] > max) {
				max = ans[i][col];
				ret = i;
			}
		}
		return ret;
	}
}

