import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

class Node {
	int num;
	int parent = 0;
	int level = 0;
	List<Integer> childList = new ArrayList<Integer>();
}
public class Main {
	static List<Node> list = new ArrayList<Node>();

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		String line = in.nextLine();
		String[] split = line.trim().split("\\s+");
		int n = Integer.parseInt(split[0]);
		int m = Integer.parseInt(split[1]);
		for (int i = 1 ; i <= n ; i++) {
			Node node = new Node();
			node.num = i;
			list.add(node);
		}
		for (int i = 0 ; i < (n + m - 1) ; i++) {
			line = in.nextLine();
			split = line.trim().split("\\s+");
			int p = Integer.parseInt(split[0]);
			int c = Integer.parseInt(split[1]);
			list.get(p-1).childList.add(c);
			list.get(c-1).parent = -1;
		}
		in.close();

		Node rootNode = list.get(0);
		for (Node node : list) {
			if (node.parent == 0) {
				rootNode = node;
				break;
			}
		}

		retrieve(rootNode, 1);

		for (Node node : list) {
			System.out.println(node.parent);
		}
	}

	private static void retrieve(Node node, int level) {
		for (int i : node.childList) {
			Node child = list.get(i-1);
			if (child.level <= level) {
				child.parent = node.num;
				child.level = level;
			}
			retrieve(child, level + 1);
		}
	}
}

import java.util.*;

public class Main {

	private static int max = 0;
	private static int count = 0;

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		Scanner scan = new Scanner(System.in);
		int n = scan.nextInt();
		int m = scan.nextInt();
		boolean[][] arr01 = new boolean[n + 1][n + 1];
		for (int i = 0; i < n + m - 1; i++) {
			arr01[scan.nextInt()][scan.nextInt()] = true;
		}
		int[][] ans = new int[n + 1][n + 1];
		for (int i = 1; i < arr01[0].length; i++) {
			for (int j = 1; j < arr01.length; j++) {
				if (arr01[j][i]) {
					ans[j][i] = max(arr01, i, j);
					max = 0;
					count = 0;
				}
			}
			System.out.println(maxPath(ans, i));
		}
		scan.close();
	}

	private static int max(boolean[][] arr01, int col, int row) {
		count++;
		for (int i = 1; i < arr01.length; i++) {
			if (arr01[i][col]) {
				max(arr01, row, i);
			}
		}
		if (count > max) {
			max = count;
		}
		count--;
		return max;
	}

	private static int maxPath(int ans[][], int col) {
		int receiver = 0;
		for (int i = 1; i < ans.length; i++) {
			if (ans[i][col] > ans[receiver][col]) {
				receiver = i;
			}
		}
		return receiver;
	}
}

