public void solve() {
	int numNode = ni();
	int numEdge = ni() + numNode - 1;
	Graph g = new Graph(numNode, numEdge, true);
	for(int i = 0; i < numEdge; i ++) {
		int source = ni() - 1;
		int target = ni() - 1;
		long cost = 1;
		g.add(new Edge(source, target, cost));
	}
	prtlns(topologicalSort(g.nodes, g.edges));
}

int[] topologicalSort(Node[] nodes, Set<Edge> edges) { // O(E+V) V=numNode, E=numEdge
	int numNode = nodes.length;
	Deque<Integer> dq = new ArrayDeque<>();
	int deg[] = new int[numNode];
	fill(deg, 0);
	for(Edge e : edges) deg[e.target] ++;
	int ans[] = new int[numNode];
	for(int i = 0; i < numNode; i ++) if(deg[i] == 0) dq.addLast(i);
	int idx = 0;
	while(!dq.isEmpty()){
		int crt = dq.removeFirst();
		// ans[idx ++] = crt;
		for(Edge e : nodes[crt]) if(-- deg[e.target] == 0) { dq.addLast(e.target); ans[e.target] = e.source + 1; }
	}
	return max(deg) == 0 ? ans : null;
}

	}
}

import java.io.*;
import java.util.*;
import java.util.Map.Entry;

@SuppressWarnings("unused")
public class Main {
    FastScanner in = new FastScanner(System.in);
    PrintWriter out = new PrintWriter(System.out);
    final int MOD = (int)1e9+7;
    void printlnYN(boolean b){out.println((b ? "Yes" : "No"));}

    void solve() throws Exception{
        int N = in.nextInt(), M = in.nextInt();
        ArrayList<ArrayList<Integer>> G = new ArrayList<>();
        for(int i = 0; i < N; i++) G.add(new ArrayList<>());
        int[] numPar = new int[N];
        for(int i = 0; i < N-1+M; i++){
            int a = in.nextInt()-1;
            int b = in.nextInt()-1;
            G.get(a).add(b);
            numPar[b]++;
        }

        int root = -1;
        for(int i = 0; i < N; i++) if(numPar[i] == 0) root = i;

        int[] par = new int[N];
        ArrayDeque<Integer> queue = new ArrayDeque<Integer>();
        queue.addLast(root);
        while(!queue.isEmpty()){
            int v = queue.removeFirst();
            for(int next : G.get(v)){
                numPar[next]--;
                if(numPar[next] == 0){
                    par[next] = v+1;
                    queue.addLast(next);
                }
            }
        }
        for(int e : par) out.println(e);
    }

    public static void main(String[] args) throws Exception {
        new Main().m();
    }

    void m() throws Exception {
        solve();
        out.flush();
    }

    static class FastScanner {
        Reader input;

        FastScanner() {this(System.in);}
        FastScanner(InputStream stream) {this.input = new BufferedReader(new InputStreamReader(stream));}

        int nextInt() {return (int) nextLong();}

        long nextLong() {
            try {
                int sign = 1;
                int b = input.read();
                while ((b < '0' || '9' < b) && b != '-' && b != '+') {
                    b = input.read();
                }
                if (b == '-') {
                    sign = -1;
                    b = input.read();
                } else if (b == '+') {
                    b = input.read();
                }
                long ret = b - '0';
                while (true) {
                    b = input.read();
                    if (b < '0' || '9' < b) return ret * sign;
                    ret *= 10;
                    ret += b - '0';
                }
            } catch (IOException e) {
                e.printStackTrace();
                return -1;
            }
        }

        double nextDouble() {
            try {
                double sign = 1;
                int b = input.read();
                while ((b < '0' || '9' < b) && b != '-' && b != '+') {
                    b = input.read();
                }
                if (b == '-') {
                    sign = -1;
                    b = input.read();
                } else if (b == '+') {
                    b = input.read();
                }
                double ret = b - '0';
                while (true) {
                    b = input.read();
                    if (b < '0' || '9' < b) break;
                    ret *= 10;
                    ret += b - '0';
                }
                if (b != '.') return sign * ret;
                double div = 1;
                b = input.read();
                while ('0' <= b && b <= '9') {
                    ret *= 10;
                    ret += b - '0';
                    div *= 10;
                    b = input.read();
                }
                return sign * ret / div;
            } catch (IOException e) {
                e.printStackTrace();
                return Double.NaN;
            }
        }

        char nextChar() {
            try {
                int b = input.read();
                while (Character.isWhitespace(b)) {
                    b = input.read();
                }
                return (char) b;
            } catch (IOException e) {
                e.printStackTrace();
                return 0;
            }
        }

        String nextStr() {
            try {
                StringBuilder sb = new StringBuilder();
                int b = input.read();
                while (Character.isWhitespace(b)) {
                    b = input.read();
                }
                while (b != -1 && !Character.isWhitespace(b)) {
                    sb.append((char) b);
                    b = input.read();
                }
                return sb.toString();
            } catch (IOException e) {
                e.printStackTrace();
                return "";
            }
        }

        public int[] nextIntArray(int n) {
            int[] res = new int[n];
            for (int i = 0; i < n; i++) {
                res[i] = nextInt();
            }
            return res;
        }

        public int[] nextIntArrayDec(int n) {
            int[] res = new int[n];
            for (int i = 0; i < n; i++) {
                res[i] = nextInt() - 1;
            }
            return res;
        }

