	static void solve() {
		n = ni(); m = ni();
		g = new ArrayList[n];
		for(int i=0;i<n;i++)g[i] = new ArrayList<>();
		List<Integer> ps[] = new ArrayList[n];
		for(int i=0;i<n;i++)ps[i] = new ArrayList<>();
		for(int i=0;i<n+m-1;i++) {
			int a = ni()-1, b = ni()-1;
			g[a].add(b);
			ps[b].add(a);
		}
		used = new boolean[n];
		for(int i=0;i<n;i++) {
			if(!used[i])dfs(i);
		}
		int num[] = new int[n];
		int cnt = 0;
		while(!topo.isEmpty()) {
			num[topo.poll()] = cnt++;
		}
		for(int i=0;i<n;i++) {
			if(ps[i].isEmpty()) {
				out.println(0);
				continue;
			}
			int p = ps[i].get(0);
			for(int t:ps[i]) {
				if(num[p]<num[t]) p = t;
			}
			out.println(p+1);
		}


	}

