        int n=sc.nextInt();
        int m=sc.nextInt()+n-1;
        int ts[]=new int[n];
        int dg[]=new int[n];
        int dg2[]=new int[n];
        ArrayList<Integer> lis[]=new ArrayList[n];
        for (int i = 0; i < lis.length; i++) {
            lis[i] = new ArrayList<Integer>();
        }

        for (int i = 0; i < m; i++) {
            int from=sc.nextInt()-1, to=sc.nextInt()-1;
            lis[from].add(to);
            dg[to]++;
            dg2[to]++;
        }
        int c=0;
        for (int i = 0; i < n; i++) {
            if(dg[i]==0)ts[c++]=i;
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0,to; j < lis[ts[i]].size(); j++) {
                to = lis[ts[i]].get(j);
                if(--dg[to]==0) ts[c++]=to;
            }
        }

        for (int i = 0; i < ts.length; i++) {
            for (int j = 0,to; j < lis[ts[i]].size(); j++) {
                to = lis[ts[i]].get(j);
                if(dg2[to]-->=2) {lis[ts[i]].remove(j);}
            }			
		}
        int ans[]=new int[n];
        for (int i = 0; i < ts.length; i++) {
            for (int j = 0,to; j < lis[ts[i]].size(); j++) {
                to = lis[ts[i]].get(j);
                ans[to]=ts[i]+1;
            }
		}
        for (int i = 0; i < ans.length; i++) {
            out.println(ans[i]);
		}
//        out.println();
        out.flush();
    }


