        numc++;
        chi.add(to);
    }

    public void added(){
        nump++;
    }

    public void calcLen(int from, int len, Node[] tree){
        this.len.add(new Integer[]{from, len});
        if(len > maxlen){
            maxlen = len;
            par = from;
            for(int i=0; i<numc; i++){
                tree[chi.get(i)].calcLen(id, maxlen+1, tree);
            }
        }
    }
}

