    private static void solve() throws IOException {
        int n = nextInt();
        int m = nextInt();
        Set<Integer>[] in = new Set[n + 1];
        Set<Integer>[] out = new Set[n + 1];
        for (int i = 0; i < n; i++) {
            in[i + 1] = new HashSet<>();
            out[i + 1] = new HashSet<>();
        }
        for (int i = 0; i < n + m - 1; i++) {
            int f = nextInt();
            int t = nextInt();
            in[t].add(f);
            out[f].add(t);
        }
        int root = 0;
        for (int i = 1; i <= n; i++) {
            if (in[i].size() == 0) {
                root = i;
                break;
            }
        }
        boolean vis[] = new boolean[n + 1];
        vis[root] = true;
        Queue<Integer> queue = new LinkedList<>();
        queue.offer(root);
        while (!queue.isEmpty()) {
            int x = queue.size();
            while (x-- > 0) {
                int q = queue.poll();
                Set<Integer> edges = out[q];
                for (int t : edges) {
                    if (vis[t]) {
                        continue;
                    }
                    if (in[t].size() > 1) {
                        in[t].remove(q);
                    } else {
                        queue.offer(t);
                        vis[t] = true;
                    }
                }
            }
        }
