public class Main {

	static TreeMap<Integer, We> w = new TreeMap<>();
	static TreeMap<Integer, List<Integer>> idx = new TreeMap<>();

	public static void main(String[] args) throws IOException {
		Scanner in = new Scanner(System.in);
		int n = in.nextInt();
		int m = in.nextInt();
		Set<Integer> from = new TreeSet<>();
		Set<Integer> to = new TreeSet<>();
		for (int i = 0; i < n - 1 + m; i++) {
			int a = in.nextInt();
			int b = in.nextInt();

			from.add(a);
			to.add(b);

			List<Integer> list = idx.get(a);
			if (list == null) {
				list = new ArrayList<>();
				idx.put(a, list);
			}
			list.add(b);
		}

		from.removeAll(to);
		Integer root = from.iterator().next();
		hoge(root, 0, 0);

		BufferedOutputStream out = new BufferedOutputStream(System.out);
		OutputStreamWriter wri = new OutputStreamWriter(out);

		for (Map.Entry<Integer, We> e : w.entrySet()) {
			wri.write(String.valueOf(e.getValue().val) + "\n");
		}

		in.close();
	}

	public static void hoge(int root, int parent, int level) {
		w.merge(root, new We(level, parent), (old, v) -> {
			if (v.level > old.level) {
				return v;
			} else {
				return old;
			}
		});
		level++;
		List<Integer> list = idx.get(root);
		if (list != null) {
			for (Integer i : list) {
				hoge(i, root, level);
			}
		}
	}

}

class We {
	int level;
	int val;
	public We(int level, int val) {
		this.level = level;
		this.val = val;
	}
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
	private class Node {
		public List<Integer> parents = null;
		public List<Integer> children = null;
		public int trueParent = 0;
		public int depth = 0;

		public Node() {
			parents = new ArrayList<Integer>();
			children = new ArrayList<Integer>();
		}

		public boolean isRoot() {
			if (parents.size() == 0) {
				return true;
			} else {
				return false;
			}
		}
	}

	private int getRoot(Node[] nodes) {
		int root = 0;
		for (root=1; root<nodes.length; root++) {
			if (nodes[root].isRoot()) {
				break;
			}
		}

		return root;
	}

	public void solve() {
		Scanner in = new Scanner(System.in);
		int N = in.nextInt();
		int M = in.nextInt();

		Node[] nodes = new Node[N+1];
		for (int i=0; i<N+1; i++) {
			nodes[i] = new Node();
		}

		for (int i=0; i<N+M-1; i++) {
			int a = in.nextInt();
			int b = in.nextInt();

			nodes[a].children.add(b);
			nodes[b].parents.add(a);
		}

		in.close();

		int root = getRoot(nodes);

		ArrayList<Integer> stack = new ArrayList<Integer>();
		stack.add(root);

		while (stack.size() > 0) {
			int target = stack.remove(stack.size()-1);
			int depth = nodes[target].depth + 1;

			for (Integer x : nodes[target].children) {
				if (nodes[x].depth < depth) {
					nodes[x].trueParent = target;
					stack.add(x);
				}
			}
		}

		for (int i=1; i<N+1; i++) {
			System.out.println(nodes[i].trueParent);
		}
	}

	public static void main(String[] args) {
		Main main = new Main();
		main.solve();
	}
}

