import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.Queue;
import java.util.Scanner;

public class Main {
	static int N;
	static int M;
	static Node[] nodeArray;
	static Node root;

	public static void main(String[] args) {
		readInput();

		solve();
	}

	static void solve() {
		boolean[] isSearched = new boolean[N+1];
		int[] distance = new int[N+1];

		recursiveSearch(root.id, isSearched, distance, 1);

		for(int i = 1; i<=N; i++) {
			System.out.println(nodeArray[i].parentId);
		}
	}

	static void recursiveSearch(int nodeId, boolean[] isSearched, int[] distance, int depth) {
		if(isSearched[nodeId]) {
			return;
		}
		isSearched[nodeId] = true;

		for(int childId : nodeArray[nodeId].children) {
			recursiveSearch(childId, isSearched, distance, depth + 1);
			Node child = nodeArray[childId];
			if(child.distance < depth) {
				child.parentId = nodeId;
				child.distance = depth;
			}
		}
	}

	static void readInput() {
		try (Scanner sc = new Scanner(System.in)) {
			N = sc.nextInt();
			M = sc.nextInt();

			nodeArray = new Node[N+1];

			for(int i = 0; i<nodeArray.length; i++) {
				nodeArray[i] = new Node(i);
			}

			// 根（親のいないノード）の検索用
			boolean[] hasParent = new boolean[N+1];

			// 辺の情報を読み込む
			for(int i = 0; i<(N - 1 + M); i++) {
				int s = sc.nextInt();
				int d = sc.nextInt();

				nodeArray[s].children.add(d);
				hasParent[d] = true;
			}

			// 根を探す
			for(int i = 1; i<=N; i++) {
				if(!hasParent[i]) {
					root = nodeArray[i];
				}
			}
		}
	}

	static class Node{
		public int id;
		public int parentId;
		public int distance;
		public ArrayList<Integer> children;

		public Node(int id) {
			parentId = 0;
			this.id = id;
			children = new ArrayList<>();
		}
	}
}

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        int M = sc.nextInt();

        ArrayList<ArrayList<Integer>> edges = new ArrayList<>(N+1);
        ArrayList<ArrayList<Integer>> parents = new ArrayList<>(N+1);
        for(int i = 0; i < N+1; i++) {
            edges.add(new ArrayList<Integer>());
            parents.add(new ArrayList<Integer>());
        }

        int[] incounts = new int[N+1];
        for(int i = 0; i < N - 1 + M; i++) {
            int A = sc.nextInt();
            int B = sc.nextInt();

            edges.get(A).add(B);
            incounts[B]++;

            parents.get(B).add(A);
        }

        LinkedList<Integer> queue = new LinkedList<>();
        for(int i = 1; i < N+1; i++) {
            if (incounts[i] == 0) {
                queue.add(i);
            }
        }

        int[] vertexes = new int[N+1];
        int n = 0;
        while(!queue.isEmpty()) {
            int v = queue.removeFirst();
            vertexes[v] = n;
            n++;
            for(int w: edges.get(v)) {
                incounts[w]--;
                if (incounts[w] == 0) {
                    queue.add(w);
                }
            }
        }

        for(int i = 1; i < N+1; i++) {
            if (vertexes[i] == 0) {
                System.out.println(0);
            } else {
                int parent = -1;
                for(int w: parents.get(i)) {
                    if(parent < 0 || vertexes[w] > vertexes[parent]) {
                        parent = w;
                    }
                }
                System.out.println(parent);
            }
        }
    }
}

