    static class TaskD {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            Vertex[] vertices = new Vertex[n + 1];
            Map<Vertex, Integer> vn = new HashMap<>();
            Set<Vertex> root = new HashSet<>();
            for (int i = 1; i <= n; i++) {
                vertices[i] = new Vertex();
                vn.put(vertices[i], i);
                root.add(vertices[i]);
            }

            for (int i = 0; i < n + m - 1; i++) {
                Vertex from = vertices[in.nextInt()];
                Vertex to = vertices[in.nextInt()];
                from.setEdge(to);
                root.remove(to);
            }

            Vertex r = null;
            for (Vertex cv : root)
                r = cv;

            List<Vertex> sorted = Sort.topologicalSort(r);
            int[] ans = new int[n + 1];

            for (Vertex cv : sorted) {
                int cn = vn.get(cv);
                for (Edge ce : cv.getEdges())
                    ans[vn.get(ce.getTo())] = cn;
            }

            for (int i = 1; i <= n; i++)
                out.println(ans[i]);
        }

    }

    static class Edge {
        private Vertex from;
        private Vertex to;
        private long cost;

        public Edge() {
        }

        public Edge(Vertex to) {
            this.to = to;
        }

        public Edge(Vertex to, long c) {
