		Set<Integer> from = new TreeSet<>();
		Set<Integer> to = new TreeSet<>();
		for (int i = 0; i < n - 1 + m; i++) {
			int a = in.nextInt();
			int b = in.nextInt();

			from.add(a);
			to.add(b);

			List<Integer> list = idx.get(a);
			if (list == null) {
				list = new ArrayList<>();
				idx.put(a, list);
			}
			list.add(b);
		}

		from.removeAll(to);
		Integer root = from.iterator().next();
		hoge(root, 0, 0);
//
