        depth = new int[n];
        parent = new int[n];
        e = new Edge[n];
        canUse = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(canUse[i], true);
        }
        boolean[] isParent = new boolean[n];
        Arrays.fill(isParent,true);
        for (int i = 0; i < n; i++) e[i] = new Edge();
        for (int i = 0; i < n + m - 1; i++) {
            int from = in.ni()-1, to = in.ni()-1;
            e[from].add(to);
            isParent[to] = false;
        }
        for (int i = 0; i < n; i++) {
            if(isParent[i]){
                dfs(-1, i);
                parent[i] = -1;
            }
        }
        StringBuilder sb = new StringBuilder();
        for(int x: parent) sb.append(x+1).append("\n");
        out.print(sb);
    }
    public static void dfs(int from, int to){
        if(from!=-1){
            if(depth[to]>=depth[from]+1){
                canUse[from][to] = false;
                return;
            }
            parent[to] = from;
            depth[to] = depth[from]+1;
        }
        for(Integer x: e[to])if(canUse[to][x]) dfs(to,x);
    }
