    void solve() {
        int n = in.nextInt();
        int m = in.nextInt();
        int[] inc = new int[n];
        List<List<Integer>> edges = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            edges.add(new ArrayList<>());
        }
        for (int i = 0; i < n + m - 1; i++) {
            int a = in.nextInt() - 1;
            int b = in.nextInt() - 1;
            inc[b]++;
            edges.get(a).add(b);
        }
        int root = -1;
        for (int i = 0; i < n; i++) {
            if (inc[i] == 0) {
                root = i;
            }
        }
        int[] parent = new int[n];
        Arrays.fill(parent, -1);
        Deque<Integer> deque = new ArrayDeque<>();
        deque.addLast(root);
        while (!deque.isEmpty()) {
            Integer v = deque.pollFirst();
            for (Integer u : edges.get(v)) {
                if (parent[u] == -1) {
                    deque.addLast(u);
                }
                parent[u] = v;
            }
        }
        for (int i = 0; i < n; i++) {
