		ArrayList<Integer>[] adj = new ArrayList[n];

		for(int i = 0; i < n; i++)
			adj[i] = new ArrayList<Integer>();

		int[] in = new int[n];

		for(int i = 0; i < n - 1 + m; i++) {
			int u = s.nextInt() - 1, v = s.nextInt() - 1;
			adj[u].add(v);
			in[v]++;
		}	

		Queue<Integer> q = new LinkedList<Integer>();

		for(int i = 0; i < n; i++)
			if(in[i] == 0)
				q.add(i);

		int[] order = new int[n];
		int c = 0;

		while(!q.isEmpty()) {

			int x = q.poll();
			order[x] = c++;

			for(int y : adj[x]) {
				in[y]--;
				if(in[y] == 0)
					q.add(y);
			}
		}

		int[] res = new int[n];
		Arrays.fill(res, -1);

		int[] val = new int[n];
		Arrays.fill(val, -1);

		for(int i = 0; i < n; i++) {

			for(int j : adj[i]) {

				if(val[j] < order[i]) {
					res[j] = i; val[j] = order[i];
				}
			}
		}

