    void solve() {
        int n = ni(), m = ni(), nm = n + m;
        List<Integer> edge[] = new List[n];
        List<Integer> rev[] = new List[n];
        for (int i = 0; i < n; ++i) {
            edge[i] = new ArrayList<>();
            rev[i] = new ArrayList<>();
        }
        for (int i = 0; i < nm - 1; ++i) {
            int a = ni() - 1;
            int b = ni() - 1;
            edge[a].add(b);
            rev[b].add(a);
        }
        int p = -1;
        for (int i = 0; i < n; ++i) {
            if (rev[i].isEmpty()) {
                p = i;
                break;
            }
        }
        int prev[] = new int[n];
        int count[] = new int[n];
        int dist[] = new int[n];
        Queue<Integer> queue = new ArrayDeque<>();
        queue.add(p);
        while (queue.size() > 0) {
            int s = queue.poll();
            for (Integer t : edge[s]) {
                count[t]++;
                if (count[t] == rev[t].size()) queue.add(t);
                int d = dist[s] + 1;
                if (dist[t] < d) {
                    dist[t] = d;
                    prev[t] = s;
                }
            }
        }
        for (int i = 0; i < n; ++i) {
            out.println(p == i ? 0 : prev[i] + 1);
        }
    }

