    public static void main(String[] args) {
        FastScanner fsc=new FastScanner();
        int n=fsc.nextInt();
        int m=fsc.nextInt();
        ArrayList<Integer>[] edges=new ArrayList[n];
        int[] in=new int[n];
        for(int i=0;i<n;i++){
            edges[i]=new ArrayList<>();
        }
        for(int i=0;i<n+m-1;i++){
            int a=fsc.nextInt()-1;
            int b=fsc.nextInt()-1;
            edges[a].add(b);
            in[b]++;
        }
        fsc.close();
        int root=-1;
        for(int i=0;i<n;i++){
            if(in[i]==0){
                root=i;
                break;
            }
        }
        int[] d=new int[n];
        fill(d, -1);
        ArrayDeque<Integer> dq=new ArrayDeque<>();
        d[root]=0;
        dq.add(root);
        while(dq.size()>0){
            int now=dq.pollFirst();
            for(int next:edges[now]){
                if(--in[next]==0){
                    dq.add(next);
                    d[next]=d[now]+1;
                }
            }
        }
        int[] parent=new int[n];
        parent[root]=-1;
        dq.add(root);
        while(dq.size()>0){
            int now=dq.pollFirst();
            for(int next:edges[now]){
                if(d[next]==d[now]+1){
                    parent[next]=now;
                    dq.add(next);
                }
            }
        }
        StringBuilder sb=new StringBuilder();
        for(int p:parent){
            sb.append(p+1).append('\n');
        }
        System.out.print(sb);
    }

    static class IntUtil {
        public static int min(int a, int... b) {
            int ret = a;
            for (int c : b) {
                ret = Math.min(ret, c);
            }
            return ret;
        }

        public static int max(int a, int... b) {
            int ret = a;
            for (int c : b) {
                ret = Math.max(ret, c);
            }
            return ret;
        }

        /**
         * Caluculate the ceil of a/b. Returns the smallest integer greater than or
         * equal to a/b while 'a/b' rounds fractional parts to ZERO.
         * 
         * @param a
         * @param b
         * @return the smallest integer greater than or equal to a/b
         */
        public static int ceilDiv(int a, int b) {
            if ((a > 0 && b > 0) || (a < 0 && b < 0)) {
                if (b > 0) {
                    return (a + b - 1) / b;
                } else {
                    return (a + b + 1) / b;
                }
            } else {
                return a / b;
            }
        }

        /**
         * Caluculate the floor of a/b. Returns the largest integer less than or equal
         * to a/b while 'a/b' rounds fractional parts to ZERO.
         * 
         * @param a
         * @param b
         * @return the largest integer less than or equal to a/b
         */
        public static int floorDiv(int a, int b) {
            if ((a > 0 && b > 0) || (a < 0 && b < 0)) {
                return a / b;
            } else {
                if (b > 0) {
                    return (a - b + 1) / b;
                } else {
                    return (a - b - 1) / b;
                }
            }
        }

        public static int fold(IntBinaryOperator func, int a, int... b) {
            int ret = a;
            for (int c : b) {
                ret = func.applyAsInt(ret, c);
            }
            return ret;
        }
    }

