        for(int i = 0; i < n; i++){
            edge[i] = new ArrayList<>();
        }
        int[] input = new int[n];
        for(int i = 0; i < n+m-1; i++){
            int s = ni()-1;
            int t = ni()-1;
            edge[s].add(t);
