        }
        int source = -1;
        for(int i = 0; i < n; i++){
            if(input[i]==0){
                source = i;
                break;
            }
        }
        Queue<Integer> q = new ArrayDeque<>();
        int[] p = new int[n];
        Arrays.fill(p, -1);
        for(int t : edge[source]){
            q.add(t);
            p[t] = source;
        }
        boolean[] seen = new boolean[n];
        while(!q.isEmpty()){
            int r = q.poll();
            if(seen[r]) continue;m
            for(int d : edge[r]){
