class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] nm = scanner.nextLine().split(" ", 2);
        int n = Integer.parseInt(nm[0]);
        int m = Integer.parseInt(nm[1]);

        Map<Integer, Integer> inputMap = new HashMap<>();
        Map<Integer, Set<Integer>> parentsMap = new HashMap<>();
        for (int i = 0; i < n - 1 + m; i++) {
            String[] ab = scanner.nextLine().split(" ", 2);
            int a = Integer.parseInt(ab[0]);
            int b = Integer.parseInt(ab[1]);
            inputMap.put(a, b);

            Set<Integer> parents = parentsMap.get(b);
            if (parents == null) {
                parents = new HashSet<>();
                parentsMap.put(b, parents);
            }
            parents.add(a);
        }

        //int root = 0;
        //for (int i = 1; i <= n; i++) {
        //    if (!parentsMap.containsKey(i)) {
        //        root = i;
        //        break;
        //    }
        //}

        // prepare indirect parents
        Map<Integer, Set<Integer>> indirectParentsMap = new HashMap<>();
        for (Map.Entry<Integer, Set<Integer>> entry : parentsMap.entrySet()) {
            Integer child = entry.getKey();
            for (Integer parent : entry.getValue()) {
                addParentParents(indirectParentsMap, parentsMap, child, parent);
            }
        }

        // detect unnecessary vector
        Map<Integer, Integer> parentMap = new HashMap<>();
        for (Map.Entry<Integer, Set<Integer>> entry : parentsMap.entrySet()) {
            Integer child = entry.getKey();
            Set<Integer> parents = entry.getValue();
            if (parents.size() == 1) {
                for (Integer parent : parents) {
                    parentMap.put(child, parent);
                }
                continue;
            }

            Set<Integer> indirectParents = indirectParentsMap.get(child);
            for (Integer parent : parents) {
                if (indirectParents.contains(parent)) {
                    // remove this path
                } else {
                    parentMap.put(child, parent);
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            if (parentMap.containsKey(i)) {
                System.out.println(parentMap.get(i));
            } else {
                System.out.println(0);
            }
        }
    }

    private static void addParentParents(Map<Integer, Set<Integer>> indirectParentsMap,
            Map<Integer, Set<Integer>> parentsMap, Integer child, Integer parent) {
        Set<Integer> parentParents = parentsMap.get(parent);
        if (parentParents == null) {
            return;
        }

        Set<Integer> indirectParents = indirectParentsMap.get(child);
        if (indirectParents == null) {
            indirectParents = new HashSet<>();
            indirectParentsMap.put(child, indirectParents);
        }

        for (Integer parentParent : parentParents) {
            indirectParents.add(parentParent);
            addParentParents(indirectParentsMap, parentsMap, child, parentParent);
        }
    }
}

import java.util.*;
import java.util.concurrent.LinkedBlockingDeque;

public class Main {
    public static class Node {
        int current;
        int father;
        public Node(int current, int father) {
            this.current = current;
            this.father = father;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;

            Node node = (Node) o;

            if (current != node.current) return false;
            return father == node.father;

        }

        @Override
        public int hashCode() {
            int result = current;
            result = 31 * result + father;
            return result;
        }
    }
    public static void main(String [] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        Map<Integer, Set<Integer>> graph = new HashMap<>();
        Map<Integer, Integer> fathers = new HashMap<>();
        Set<Integer> roots = new HashSet<>();
        for (int i = 1; i <= n; ++i) {
            roots.add(i);
        }
        for (int i = 0; i < n + m - 1; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            Set<Integer> descendants = graph.getOrDefault(u, new HashSet<>());
            descendants.add(v);
            graph.put(u, descendants);
            roots.remove(v);
        }
        int root = -1;
        for (final int r : roots) {
            root = r;
        }
        Queue<Node> travel = new LinkedBlockingDeque<>();
        travel.add(new Node(root, 0));
        while (!travel.isEmpty()) {
            Node currentNode = travel.poll();
         //   System.out.println("#current: " + currentNode.current + " father: " + currentNode.father);

            if (!graph.containsKey(currentNode.current)) {
                fathers.put(currentNode.current,  currentNode.father);
                continue;
            }
            for (int son : graph.get(currentNode.current)) {
                if (!fathers.containsKey(son)) {
                    travel.add(new Node(son, currentNode.current));
         //           System.out.println("push: " + son + " father: "+ currentNode.current);
                }
          //      System.out.println("current: " + son + " father: " + currentNode.current);

                fathers.put(son, currentNode.current);

            }
        }
        fathers.put(root, 0);
        for (int i = 1; i <= n; ++i) {
            System.out.println(fathers.get(i));
        }

    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Queue;
import java.util.Scanner;
import java.util.Stack;

public class Main {

	private static int max = 0;
	private static int count = 0;
	static Stack<Integer> list = new Stack<Integer>();

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		Scanner scan = new Scanner(System.in);
		int n = scan.nextInt();
		int m = scan.nextInt();
		int[][] arr01 = new int[n + 2][n + 2];
		for (int i = 1; i <= n + m - 1; i++) {
			arr01[scan.nextInt()][scan.nextInt()] = 1;
		}
		int[][] ans = new int[n + 2][n + 2];
		for (int i = 1; i <= n; i++) {
			for (int j = 1; j <= n; j++) {
				if (arr01[j][i] != 0) {
					ans[j][i] = max(arr01, i, j);
					max = 0;
					count = 0;
				}
			}
		}
		for (int i = 1; i <= n; i++) {
			System.out.println(maxPath(ans, i));
		}
		scan.close();
	}

	private static int max(int[][] arr01, int col, int row) {

		count++;
		list.add(row);
		for (int i = 1; i < arr01.length; i++) {
			if (arr01[i][row] != 0) {
				max(arr01, row, i);
			}
		}

		if (count > max) {
			max = count;
		}
		count--;
		list.pop();

		return max;

	}

	private static int maxPath(int ans[][], int col) {
		int max = 0;
		int ret = 0;
		for (int i = 1; i < ans.length; i++) {
			if (ans[i][col] > max) {
				max = ans[i][col];
				ret = i;
			}
		}
		return ret;
	}
}

