class Main {

    static PrintWriter out;
    static InputReader sc;

    public static void main(String[] args) {
        sc = new InputReader(System.in);
        out = new PrintWriter(System.out);
        solve();
        out.flush();
    }

    static void solve() {
        int N = sc.nextInt();
        int M = sc.nextInt();
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            graph.add(new ArrayList<Integer>());
        }
        for (int i = 0; i < N - 1 + M; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            graph.get(a).add(b);
        }
        int[] sorted = topologicalSort(graph);
        int[] ans = new int[N];
        int[] lank = new int[N];
        for (int i = 0; i < N; i++) {
            lank[sorted[i]] = i;
        }
        List<List<Integer>> graph2 = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            graph2.add(new ArrayList<Integer>());
        }
        for (int s = 0; s < N; s++) {
            for (int t : graph.get(s)) {
                graph2.get(t).add(s);
            }
        }
        for (int i = 0; i < N; i++) {
            int max = -1;
            int idx = -1;
            for (int u : graph2.get(i)) {
                if (max < lank[u]) {
                    max = lank[u];
                    idx = u;
                }
            }
            ans[i] = idx;
        }
        for (int i = 0; i < N; i++) {
            out.println(ans[i] + 1);
        }
    }

    /**
     * C++のPairと同じ
     */
    public static class Pair implements Comparable<Pair> {
        int first;
        int second;

        public Pair(int first, int second) {
            this.first = first;
            this.second = second;
        }

        @Override
        public int hashCode() {
            return Integer.valueOf(this.first + this.second).hashCode();
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) {
                return true;
            }
            if (!(obj instanceof Pair)) {
                return false;
            }
            Pair pair = (Pair) obj;
            return this.first == pair.first && this.second == pair.second;
        }

        @Override
        public int compareTo(Pair o) {
            return Integer.compare(this.first, o.first);
        }

        @Override
        public String toString() {
            return String.format("{%d,%d}", this.first, this.second);
        }

    }

    public static int[] topologicalSort(List<List<Integer>> graph) {
        int V = graph.size();
        int[] indegree = new int[V];
        for (int i = 0; i < V; i++) {
            for (int node : graph.get(i)) {
                indegree[node]++;
            }
        }
        ArrayDeque<Integer> que = new ArrayDeque<>();
        for (int i = 0; i < V; i++) {
            if (indegree[i] == 0) {
                que.add(i);
            }
        }
        int cnt = 0;
        int[] res = new int[V];

        while (!que.isEmpty()) {
            int u = que.poll();
            res[cnt++] = u;
            for (int node : graph.get(u)) {
                indegree[node]--;
                if (indegree[node] == 0) {
                    que.add(node);
                }
            }
        }
        return res;
    }

