import java.io.*;
import java.util.*;

public class Main {
    public static final long mod = (long)1e9+7;
    public static final long INF = Long.MAX_VALUE/2;
    public static final int inf = Integer.MAX_VALUE/2;

    public static int n, m;
    public static int[] depth, parent;
    public static Edge[] e;
    public static boolean[] canUse;
    public static HashMap<Long, Integer> map;
    static void solve(InputReader in, PrintWriter out){
        n = in.ni();
        m = in.ni();
        depth = new int[n];
        parent = new int[n];
        e = new Edge[n];
        canUse = new boolean[n+m-1];
        map = new HashMap<>();
        Arrays.fill(canUse,true);
        boolean[] isParent = new boolean[n];
        Arrays.fill(isParent,true);
        for (int i = 0; i < n; i++) e[i] = new Edge();
        for (int i = 0; i < n + m - 1; i++) {
            int from = in.ni()-1, to = in.ni()-1;
            e[from].add(to);
            isParent[to] = false;
            map.put((long)n*(long)from+to, i);
        }
        for (int i = 0; i < n; i++) {
            if(isParent[i]){
                depth[i] = -1;
                dfs(i, i);
                parent[i] = -1;
            }
        }
        StringBuilder sb = new StringBuilder();
        for(int x: parent) sb.append(x+1).append("\n");
        out.print(sb);
    }
    public static void dfs(int from, int to){
        if(depth[to]>=depth[from]+1){
            canUse[map.get((long)n*(long)from+to)] = false;
            return;
        }
        parent[to] = from;
        depth[to] = depth[from]+1;
        for(Integer x: e[to]) if(canUse[map.get((long)n*(long)to + x)]) dfs(to,x);
    }
    public static class Edge extends ArrayList<Integer>{}
    public static void main(String[] args){
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        solve(in, out);
        out.close();
    }
    public static class InputReader{
        private BufferedReader br;
        private StringTokenizer st;
        public InputReader(InputStream is){
            br = new BufferedReader(new InputStreamReader(is));
            st = null;
        }
        public String ns(){
            if(st == null || !st.hasMoreTokens()){
                try{
                    st = new StringTokenizer(br.readLine());
                }catch (Exception e){
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }
        public int ni(){
            return Integer.parseInt(ns());
        }
        public long nl(){
            return Long.parseLong(ns());
        }
        public double nd(){
            return Double.parseDouble(ns());
        }
        public char nc(){
            return ns().toCharArray()[0];
        }
        public int[] ni(int n){
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = ni();
            }
            return a;
        }
        public long[] nl(int n){
            long[] a = new long[n];
            for (int i = 0; i < n; i++) {
                a[i] = nl();
            }
            return a;
        }
        public double[] nd(int n){
            double[] a = new double[n];
            for (int i = 0; i < n; i++) {
                a[i] = nd();
            }
