        }

        public int nextInt() {
            long n = nextLong();

            if (n < Integer.MIN_VALUE || n > Integer.MAX_VALUE)
                throw new NumberFormatException();

            return (int) n;
        }

    }

    static class Sort {
        public static int[] topologicalSort(int[][] g) {
            int n = g.length;
            int[] inDegreeCount = new int[n];
            for (int[] f : g)
                for (int t : f)
                    inDegreeCount[t]++;

            int[] sorted = new int[n];
            int p = 0;
            for (int i = 0; i < n; i++)
                if (inDegreeCount[i] == 0)
                    sorted[p++] = i;

            for (int i = 0; i < p; i++) {
                int cv = sorted[i];
                for (int t : g[cv])
                    if (--inDegreeCount[t] == 0)
                        sorted[p++] = t;
            }
            return sorted;
        }

    }
}

