import java.util.*;
import java.util.concurrent.LinkedBlockingDeque;

public class Main {
    public static class Node {
        int current;
        int father;
        public Node(int current, int father) {
            this.current = current;
            this.father = father;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;

            Node node = (Node) o;

            if (current != node.current) return false;
            return father == node.father;

        }

        @Override
        public int hashCode() {
            int result = current;
            result = 31 * result + father;
            return result;
        }
    }
    public static void main(String [] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        Map<Integer, Set<Integer>> graph = new HashMap<>();
        Map<Integer, Integer> fathers = new HashMap<>();
        Set<Integer> roots = new HashSet<>();
        for (int i = 1; i <= n; ++i) {
            roots.add(i);
        }
        for (int i = 0; i < n + m - 1; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            Set<Integer> descendants = graph.getOrDefault(u, new HashSet<>());
            descendants.add(v);
            graph.put(u, descendants);
            roots.remove(v);
        }
        int root = -1;
        for (final int r : roots) {
            root = r;
        }
        Set<Node> addedNode = new HashSet<>();
        Queue<Node> travel = new LinkedBlockingDeque<>();
        travel.add(new Node(root, 0));
        while (!travel.isEmpty()) {
            Node currentNode = travel.poll();
         //   System.out.println("current: " + currentNode.current);
            if (!graph.containsKey(currentNode.current)) {
                continue;
            }
            if (addedNode.contains(currentNode)) {
                continue;
            }

            for (int son : graph.get(currentNode.current)) {
                if (fathers.containsKey(son) && fathers.get(son) != currentNode.current) {
                    addedNode.add(new Node(son, fathers.get(son)));
            //        System.out.println("addNode: " + son + " father: " + fathers.get(son));
                }
                travel.add(new Node(son, currentNode.current));
                fathers.put(son, currentNode.current);
         //       System.out.println("son: " + son + " father: " + currentNode.current);
            }
        }
        fathers.put(root, 0);
        for (int i = 1; i <= n; ++i) {
            System.out.println(fathers.get(i));
        }

    }
}

import java.util.LinkedList;
import java.util.List;
import java.util.Scanner;

public class Main {
	private class Node {
		public int parentsCount = 0;
		public List<Integer> children = null;

		public int setParents = 0;
		public int trueParent = 0;
		public int trueDepth = 0;

		public Node() {
			children = new LinkedList<Integer>();
		}

		public void setDepth(int parent, int depth) {
			if (trueDepth < depth) {
				trueDepth = depth;
				trueParent = parent;
			}
			setParents++;
		}

		public int getDepth() {
			if (parentsCount > setParents) {
				return -1;
			}
			return trueDepth;
		}

		public int getTrueParent() {
			if (parentsCount > setParents) {
				return -1;
			}
			return trueParent;
		}

		public boolean isRoot() {
			if (parentsCount == 0) {
				return true;
			} else {
				return false;
			}
		}
	}

	private int getRoot(Node[] nodes) {
		int root = 0;
		for (root=1; root<nodes.length; root++) {
			if (nodes[root].isRoot()) {
				break;
			}
		}

		return root;
	}

	public void solve() {
		Scanner in = new Scanner(System.in);
		int N = in.nextInt();
		int M = in.nextInt();

		Node[] nodes = new Node[N+1];
		for (int i=0; i<N+1; i++) {
			nodes[i] = new Node();
		}

		for (int i=0; i<N+M-1; i++) {
			int a = in.nextInt();
			int b = in.nextInt();

			nodes[a].children.add(b);
			nodes[b].parentsCount++;
		}

		in.close();

		int root = getRoot(nodes);

		LinkedList<Integer> list = new LinkedList<Integer>();
		list.addFirst(root);

		while (list.size() > 0) {
			int target = list.removeFirst();
			int depth = nodes[target].getDepth();
			if (depth == -1) {
				// 別の親から入ってくるのを待つ
				continue;
			}

			for (Integer x : nodes[target].children) {
				nodes[x].setDepth(target, depth+1);
				list.addFirst(x);
			}
		}

		for (int i=1; i<N+1; i++) {
			System.out.println(nodes[i].getTrueParent());
		}
	}

	public static void main(String[] args) {
		Main main = new Main();
		main.solve();
	}
}

