public class Main {
	private class Node {
		public HashMap<Integer, Integer> parents = null;
		public List<Integer> children = null;

		public int setParents = 0;
		public int trueParent = -1;
		public int trueDepth = -1;

		public Node() {
			parents = new HashMap<Integer, Integer>();
			children = new ArrayList<Integer>();
		}

		public void addParent(int p) {
			parents.put(p, -1);
		}

		public void setDepth(int parent, int depth) {
			parents.put(parent, depth);
			setParents++;

			if (setParents >= parents.size()) {
				for (int p : parents.keySet()) {
					int d = parents.get(p);
					if (trueDepth < d) {
						trueDepth = d;
						trueParent = p;
					}
				}
			}
		}

		public int getDepth() {
			if (parents.size() == 0) {
				return 0;
			}
			return trueDepth;
		}

		public int getTrueParent() {
			if (parents.size() == 0) {
				return 0;
			}
			return trueParent;
		}

		public boolean isRoot() {
			if (parents.size() == 0) {
				return true;
			} else {
				return false;
			}
		}
	}

	private int getRoot(Node[] nodes) {
		int root = 0;
		for (root=1; root<nodes.length; root++) {
			if (nodes[root].isRoot()) {
				break;
			}
		}

		return root;
	}

	public void solve() {
		Scanner in = new Scanner(System.in);
		int N = in.nextInt();
		int M = in.nextInt();

		Node[] nodes = new Node[N+1];
		for (int i=0; i<N+1; i++) {
			nodes[i] = new Node();
		}

		for (int i=0; i<N+M-1; i++) {
			int a = in.nextInt();
			int b = in.nextInt();

			nodes[a].children.add(b);
			nodes[b].addParent(a);
		}

		in.close();

		int root = getRoot(nodes);

		ArrayList<Integer> queue = new ArrayList<Integer>();
		queue.add(root);

		while (queue.size() > 0) {
			int target = queue.remove(0);
			int depth = nodes[target].getDepth();
			if (depth == -1) {
				// 別の親から入ってくるのを待つ
				continue;
			}

			for (Integer x : nodes[target].children) {
				nodes[x].setDepth(target, depth+1);
				queue.add(x);
			}
		}

		for (int i=1; i<N+1; i++) {
			System.out.println(nodes[i].getTrueParent());
		}
	}

	public static void main(String[] args) {
		Main main = new Main();
		main.solve();
	}
