public class Main {


  private static void solve() {
    int n = ni();
    int m = ni();
    int[] from = new int[n + m - 1];
    int[] to = new int[n + m - 1];

    int[] cnt = new int[n];
    for (int i = 0; i < n + m - 1; i ++) {
      from[i] = ni() - 1;
      to[i] = ni() - 1;

      cnt[to[i]] ++;
    }


    int[][] g = packD(n, to, from);
    int[] a = sortTopologically(g);
    int[] dp = new int[n];
    for (int i = 0; i < n; i ++) {
      int v = a[i];

      for (int u : g[v]) {
        dp[u] = Math.max(dp[u], dp[v] + 1);
      }
    }

    int[] ret = new int[n];
    Arrays.fill(ret, -1);
    for (int i = 0; i < n; i ++) {
      int v = a[i];
      for (int u : g[v]) {
        if (dp[u] == dp[v] + 1) {
          ret[v] = u;
          break;
        }
      }
    }

    for (int i = 0; i < n; i ++) {
      out.println(ret[i] + 1);
    }
  }

  public static int[] sortTopologically(int[][] g)
  {
      int n = g.length;
      int[] ec = new int[n];
      for(int i = 0;i < n;i++){
          for(int to : g[i])ec[to]++;
      }
      int[] ret = new int[n];
      int q = 0;

      // sources
      for(int i = 0;i < n;i++){
          if(ec[i] == 0)ret[q++] = i;
      }

      for(int p = 0;p < q;p++){
          for(int to : g[ret[p]]){
              if(--ec[to] == 0)ret[q++] = to;
          }
      }
      // loop
      for(int i = 0;i < n;i++){
          if(ec[i] > 0)return null;
      }
      return ret;
  }



  public static int[][] packD(int n, int[] from, int[] to){ return packD(n, from, to, from.length);}
  public static int[][] packD(int n, int[] from, int[] to, int sup)
  {
      int[][] g = new int[n][];
      int[] p = new int[n];
      for(int i = 0;i < sup;i++)p[from[i]]++;
      for(int i = 0;i < n;i++)g[i] = new int[p[i]];
      for(int i = 0;i < sup;i++){
          g[from[i]][--p[from[i]]] = to[i];
      }
      return g;
  }

