class Node{
    public int id;
    public int numc;
    public int nump;
    public ArrayList<Integer> chi;
    public ArrayList<Integer> pars;
    public int maxlen;
    public ArrayList<Integer[]> len;
    public int par;
    public Node(int id){
        this.id = id;
        numc = 0;
        nump = 0;
        chi = new ArrayList<Integer>();
        pars = new ArrayList<Integer>();
        maxlen = -1;
        len = new ArrayList<Integer[]>();
        par = -1;
    }

    public void add(int to){
        numc++;
        chi.add(to);
    }

    public void added(int from){
        nump++;
        pars.add(from);
    }

    public void calcLen(int from, int len, Node[] tree){
        this.len.add(new Integer[]{from, len});
        if(len > maxlen){
            maxlen = len;
            par = from;
            for(int i=0; i<numc; i++){
                tree[chi.get(i)].calcLen(id, maxlen+1, tree);
            }
        }
    }

    public void calcLen2(int from, int len, Node[] tree, ArrayDeque<Integer> que, int[] clen, int[] dlen, int[] ff){
        this.len.add(new Integer[]{from, len});
        if(len > maxlen){
            maxlen = len;
            par = from;
            dlen[id] = maxlen;
            for(int i=0; i<numc; i++){
                int next = chi.get(i);
                if(clen[next] < maxlen+1){
                    clen[next] = maxlen+1;
                    ff[next] = id;
                    que.add(next);
                }
            }
        }
    }

    public void searchPar(Node[] tree){
        int mpar = -1;
        int min = 1000000;
        for(int i=0; i<nump; i++){
            if(tree[pars.get(i)].numc < min){
                min = tree[pars.get(i)].numc;
                mpar = pars.get(i); 
            }
        }
        par = mpar;
    }
}

import java.util.*;

import static java.lang.System.*;

// https://ja.wikipedia.org/wiki/%E3%83%88%E3%83%9D%E3%83%AD%E3%82%B8%E3%82%AB%E3%83%AB%E3%82%BD%E3%83%BC%E3%83%88
// O(N+M)
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();

        Map<Integer, List<Integer>> nodeToNodes = new HashMap<Integer, List<Integer>>();  //ノードから伸びるノードリスト
        for (int i = 0; i < N - 1 + M; i++) {
            int a = sc.nextInt();
            int b = sc.nextInt();

            List<Integer> toNodes = new ArrayList<Integer>();
            if (nodeToNodes.containsKey(a)) {
                toNodes = nodeToNodes.get(a);
            }
            toNodes.add(b);
            nodeToNodes.put(a, toNodes);
        }

        // トポロジカルソートの準備
        Map<Integer, List<Integer>> nodesParents = new HashMap<Integer, List<Integer>>();  //ノードの親
        for(Map.Entry<Integer, List<Integer>> nodeToNode: nodeToNodes.entrySet()){
            int parent = nodeToNode.getKey();
            List<Integer> kids = nodeToNode.getValue();

            for(int k: kids){
                List<Integer> toParents = new ArrayList<Integer>();
                if (nodesParents.containsKey(k)) {
                    toParents = nodesParents.get(k);
                }
                toParents.add(parent);
                nodesParents.put(k, toParents);
            }
        }

        //for(Map.Entry<Integer, List<Integer>> nodeParents: nodesParents.entrySet()){
        //    int node = nodeParents.getKey();
        //    List<Integer> parents = nodeParents.getValue();

        //    out.println(node+"=>");
        //    for(int n: parents){
        //        out.print(n+",");
        //    }
        //    out.println();
        //}

        // 親がいない
        Queue<Integer> noParents  = new ArrayDeque<Integer>();
        for(int n = 1; n < N; n++){
            if (!nodesParents.containsKey(n)){
                noParents.add(n);
            }
        }

        // トポロジカルソート
        Queue<Integer> sortedTree = new ArrayDeque<Integer>();
        while(!noParents.isEmpty()){
            int p = noParents.poll();
            sortedTree.add(p);

            //out.println(p);

            // 親から削除する
            if(nodeToNodes.containsKey(p)) {
                List<Integer> toNodes = nodeToNodes.get(p);
                for (int toNode : toNodes) {
                    List<Integer> parents = nodesParents.get(toNode);
                    parents.remove(parents.indexOf(p));

                    // もし親がいないならキューに追加
                    if (parents.size() == 0) {
                        noParents.add(toNode);
                        nodesParents.remove(nodesParents.remove(toNode));
                    } else {
                        nodesParents.put(toNode, parents);
                    }
                }
            }
        }

        int[] parents = new int[N+1];
        Arrays.fill(parents, -1);
        int parent = 0;
        parents[((ArrayDeque<Integer>) sortedTree).getFirst()] = parent;

        while(!sortedTree.isEmpty()){
            int node = sortedTree.poll();
            parent = node;

            //out.println(node+","+Arrays.toString(parents));

            // 子供の親を更新
            if(nodeToNodes.containsKey(node)) {
                List<Integer> kids = nodeToNodes.get(node);
                for (int kid : kids) {
                    if (parents[kid] == -1) {
                        parents[kid] = parent;
                    }
                }
            }
        }

        for(int n = 1; n <= N; n++) {
            out.println(parents[n]);
        }
    }
}

