import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Scanner;

class D {
    static class Node extends ArrayList<Node> {
        final int id;
        int depth = -1;
        boolean visited = false;
        int parent = -1;

        public Node(int id) {
            this.id = id;
        }
    }

    public static void main(String... args) {
        final Scanner sc = new Scanner(System.in);
        final int N = sc.nextInt();
        final int M = sc.nextInt();
        final Node[] ns = new Node[N];
        for (int i = 0; i < N; i++)
            ns[i] = new Node(i);
        for (int i = 0; i < N + M - 1; i++) {
            final int A = sc.nextInt() - 1;
            final int B = sc.nextInt() - 1;
            ns[A].add(ns[B]);
        }
        final ArrayDeque<Node> topological = new ArrayDeque<>();
        final ArrayDeque<Node> stack = new ArrayDeque<>();
        for (int i = 0; i < N; i++)
            if (!ns[i].visited) {
                stack.offerFirst(ns[i]);
                while (!stack.isEmpty()) {
                    final Node n = stack.pollFirst();
                    if (n.visited) {
                        topological.offerFirst(n);
                    } else {
                        n.visited = true;
                        stack.offerFirst(n);
                        for (final Node child : n)
                            stack.offerFirst(child);
                    }
                }
            }
        topological.peekFirst().depth = 0;
        while(!topological.isEmpty()) {
            final Node n = topological.pollFirst();
            for(final Node child : n)
                if(child.depth < n.depth + 1) {
                    child.depth = n.depth + 1;
                    child.parent = n.id;
                }
        }
        final PrintWriter pw = new PrintWriter(System.out, false);
        for (int i = 0; i < N; i++)
            pw.println(ns[i].parent + 1);
        pw.flush();
    }
}
public class Main {
    public static void main(String... args) {
        D.main();
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Queue;
import java.util.Scanner;

public class Main {
	public static final int MAX_HIGHT = 100;

	static int N;
	static int M;
	static Node[] nodeArray;
	static Node root;

	public static void main(String[] args) {
		readInput();

		solve();
	}

	public static void solve() {
		// 幅優先探索で距離が長いパスがもともとのパス
		Queue<Node> queue = new ArrayDeque<>();
		queue.add(root);

		int[] distanceList = new int[N+1];

		while(!queue.isEmpty()) {
			Node node = queue.poll();

			int newdistance = distanceList[node.id] + 1;

			for(Node child : node.children) {
				if(distanceList[child.id] < newdistance) {
					child.parentId = node.id;
					distanceList[child.id] = newdistance;
					queue.add(child);
				}
			}
		}

		for(int i = 1; i<=N; i++) {
			System.out.println(nodeArray[i].parentId);
		}
	}

	public static void readInput() {
		try (Scanner sc = new Scanner(System.in)) {
			N = sc.nextInt();
			M = sc.nextInt();

			nodeArray = new Node[N+1];

			for(int i = 1; i<nodeArray.length; i++) {
				nodeArray[i] = new Node(i);
			}

			// 根（親のいないノード）の検索用
			boolean[] hasParent = new boolean[N+1];

			// 辺の情報を読み込む
			for(int i = 0; i<(N - 1 + M); i++) {
				int s = sc.nextInt();
				int d = sc.nextInt();

				nodeArray[s].children.add(nodeArray[d]);
				hasParent[d] = true;
			}

			// 根を探す
			for(int i = 1; i<=N; i++) {
				if(!hasParent[i]) {
					root = nodeArray[i];
				}
			}
		}
	}

	public static class Node{
		public int id;
		public int parentId;
		public ArrayList<Node> children;

		public Node(int id) {
			parentId = 0;
			this.id = id;
			children = new ArrayList<Node>();
		}
	}
}

import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Scanner;

public class Main {
	static Scanner sc = new Scanner(System.in);

	public static void main(String[] args) {
		int N = sc.nextInt();
		int M = sc.nextInt();
		SCC scc = new SCC();
		ArrayList<ArrayList<Integer>> parents = new ArrayList<>();
		for (int i = 0; i < N; i++) {
			parents.add(new ArrayList<>());
		}
		for (int i = 0; i < N - 1 + M; i++) {
			int A = Integer.parseInt(sc.next()) - 1;
			int B = Integer.parseInt(sc.next()) - 1;
			scc.addEdge(A, B);
			parents.get(B).add(A);
		}
		scc.calc();
		PrintWriter writer = new PrintWriter(System.out);
		for (int i = 0; i < N; i++) {
			int parent = -1;
			int min = Integer.MAX_VALUE;
			for (int p : parents.get(i)) {
				if (scc.idx[p] < min) {
					min = scc.idx[p];
					parent = p;
				}
			}
			writer.println(parent + 1);
		}
		writer.flush();
	}

	static class SCC {

		int N;
		ArrayList<ArrayList<Integer>> child = new ArrayList<>();
		ArrayList<ArrayList<Integer>> parent = new ArrayList<>();
		int[] idx;

		void addEdge(int from, int to) {
			while (child.size() <= from) {
				child.add(new ArrayList<>());
			}
			while (parent.size() <= to) {
				parent.add(new ArrayList<>());
			}
			child.get(from).add(to);
			parent.get(to).add(from);
		}

		void calc() {
			while (child.size() < parent.size()) {
				child.add(new ArrayList<>());
			}
			while (parent.size() < child.size()) {
				parent.add(new ArrayList<>());
			}
			N = child.size();
			dfs();
		}

		void dfs() {
			idx = new int[N];
			boolean[] used = new boolean[N];
			int pos = 0;
			for (int i = 0; i < N; ++i) {
				if (used[i]) continue;
				used[i] = true;
				ArrayDeque<Integer> q = new ArrayDeque<>();
				q.addAll(child.get(i));
				q.add(-i - 1);
				while (!q.isEmpty()) {
					int cur = q.pollFirst();
					if (cur < 0) {
						idx[-cur - 1] = pos++;
						continue;
					}
					if (used[cur]) continue;
					used[cur] = true;
					q.addFirst(-cur - 1);
					for (int c : child.get(cur)) {
						q.addFirst(c);
					}
				}
			}
		}
	}
}

