import java.util.*;

class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] nm = scanner.nextLine().split(" ", 2);
        int n = Integer.parseInt(nm[0]);
        int m = Integer.parseInt(nm[1]);

        Map<Integer, Integer> inputMap = new HashMap<>();
        Map<Integer, Set<Integer>> parentsMap = new HashMap<>();
        for (int i = 0; i < n - 1 + m; i++) {
            String[] ab = scanner.nextLine().split(" ", 2);
            int a = Integer.parseInt(ab[0]);
            int b = Integer.parseInt(ab[1]);
            inputMap.put(a, b);

            Set<Integer> parents = parentsMap.get(b);
            if (parents == null) {
                parents = new HashSet<>();
                parentsMap.put(b, parents);
            }
            parents.add(a);
        }

        // remove indirect parents from parents
        for (Map.Entry<Integer, Set<Integer>> entry : parentsMap.entrySet()) {
            Integer child = entry.getKey();
            Set<Integer> parents = entry.getValue();
            if (parents.size() == 1) continue;

            Integer[] parentsArray = parents.toArray(new Integer[parents.size()]);
            for (Integer parent : parentsArray) {
                if (removeParents(parentsMap, parents, child, parent)) {
                    break;
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            if (parentsMap.containsKey(i)) {
                for (Integer parent : parentsMap.get(i)) {
                    System.out.println(parent);
                    break;
                }
            } else {
                System.out.println(0);
            }
        }
    }

    private static boolean removeParents(Map<Integer, Set<Integer>> parentsMap, Set<Integer> parentsSet, Integer child, Integer parent) {
        Set<Integer> parentParents = parentsMap.get(parent);
        if (parentParents == null) {
            return false;
        }

        for (Integer parentParent : parentParents) {
            if (parentsSet.remove(parentParent) && parentsSet.size() == 1) {
                return true;
            }
            if (removeParents(parentsMap, parentsSet, child, parentParent)) {
                return true;
            }
        }
        return false;
    }
}

import java.util.*;
import java.util.concurrent.LinkedBlockingDeque;

public class Main {
    public static class Node {
        int current;
        int father;
        public Node(int current, int father) {
            this.current = current;
            this.father = father;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;

            Node node = (Node) o;

            if (current != node.current) return false;
            return father == node.father;

        }

        @Override
        public int hashCode() {
            int result = current;
            result = 31 * result + father;
            return result;
        }
    }
    public static void main(String [] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        Map<Integer, Set<Integer>> graph = new HashMap<>();
        Map<Integer, Integer> fathers = new HashMap<>();
        Set<Integer> roots = new HashSet<>();
        for (int i = 1; i <= n; ++i) {
            roots.add(i);
        }
        for (int i = 0; i < n + m - 1; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            Set<Integer> descendants = graph.getOrDefault(u, new HashSet<>());
            descendants.add(v);
            graph.put(u, descendants);
            roots.remove(v);
        }
        int root = -1;
        for (final int r : roots) {
            root = r;
        }
        Set<Node> addedNode = new HashSet<>();
        Queue<Node> travel = new LinkedBlockingDeque<>();
        travel.add(new Node(root, 0));
        while (!travel.isEmpty()) {
            Node currentNode = travel.poll();

            if (addedNode.contains(currentNode)) {
                continue;
            }

            fathers.put(currentNode.current, currentNode.father);
            if (!graph.containsKey(currentNode.current)) {
                continue;
            }
            for (int son : graph.get(currentNode.current)) {
                if (fathers.containsKey(son) && fathers.get(son) != currentNode.current) {
                    addedNode.add(new Node(son, fathers.get(son)));
                }
                travel.add(new Node(son, currentNode.current));
            }
        }
        fathers.put(root, 0);
        for (int i = 1; i <= n; ++i) {
            System.out.println(fathers.get(i));
        }

    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class Main {
    public void solve(BufferedReader stdin, PrintWriter stdout) throws NumberFormatException, IOException {
        Pattern space = Pattern.compile(" ");
        int[] first = space.splitAsStream(stdin.readLine()).mapToInt(Integer::parseInt).toArray();
        int n = first[0];
        int m = first[1];

        List<Set<Integer>> parents = IntStream.range(0, n).mapToObj(unused -> new HashSet<Integer>()).collect(Collectors.toList());
        List<Set<Integer>> children = IntStream.range(0, n).mapToObj(unused -> new HashSet<Integer>()).collect(Collectors.toList());

        for (int i = 0; i < n - 1 + m; i++) {
            int[] line = space.splitAsStream(stdin.readLine()).mapToInt(Integer::parseInt).toArray();
            int a = line[0] - 1;
            int b = line[1] - 1;
            parents.get(b).add(a);
            children.get(a).add(b);
        }

        Deque<Integer> queue = new ArrayDeque<>();
        int[] answers = new int[n];
        Integer root = IntStream.range(0, n).filter(i -> parents.get(i).isEmpty()).boxed().findAny().get();
        queue.addLast(root);
        while (!queue.isEmpty()) {
            Integer parent = queue.pollFirst();
            for (Integer child : children.get(parent)) {
                parents.get(child).remove(parent);
                if (parents.get(child).isEmpty()) {
                    answers[child.intValue()] = parent.intValue() + 1;
                    queue.add(child);
                }
            }
        }

        Arrays.stream(answers).forEach(stdout::println);
    }

    public static void main(String[] args) throws NumberFormatException, IOException {
        BufferedReader stdin = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter stdout = new PrintWriter(System.out, false);
        new Main().solve(stdin, stdout);
        stdout.flush();
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.Queue;
import java.util.Scanner;

public class Main {
	public static final int MAX_HIGHT = 100;

	static int N;
	static int M;
	static Node[] nodeArray;
	static Node root;

	public static void main(String[] args) {
		readInput();

		solve();
	}

	public static void solve() {
		// 幅優先探索で距離が長いパスがもともとのパス
		Deque<Node> queue = new ArrayDeque<>();
		queue.add(root);

		int[] distanceList = new int[N+1];

		while(!queue.isEmpty()) {
			Node node = queue.poll();

			int newdistance = distanceList[node.id] + 1;

			for(Node child : node.children) {
				if(distanceList[child.id] < newdistance) {
					child.parentId = node.id;
					queue.add(child);
				}
			}
		}

		for(int i = 1; i<=N; i++) {
			System.out.println(nodeArray[i].parentId);
		}
	}

	public static void readInput() {
		try (Scanner sc = new Scanner(System.in)) {
			N = sc.nextInt();
			M = sc.nextInt();

			nodeArray = new Node[N+1];

			for(int i = 1; i<nodeArray.length; i++) {
				nodeArray[i] = new Node(i);
			}

			// 根（親のいないノード）の検索用
			boolean[] hasParent = new boolean[N+1];

			// 辺の情報を読み込む
			for(int i = 0; i<(N - 1 + M); i++) {
				int s = sc.nextInt();
				int d = sc.nextInt();

				nodeArray[s].children.add(nodeArray[d]);
				hasParent[d] = true;
			}

			// 根を探す
			for(int i = 1; i<=N; i++) {
				if(!hasParent[i]) {
					root = nodeArray[i];
				}
			}
		}
	}

	public static class Node{
		public int id;
		public int parentId;
		public ArrayList<Node> children;

		public Node(int id) {
			parentId = 0;
			this.id = id;
			children = new ArrayList<Node>();
		}
	}
}

import java.io.*;
import java.nio.ByteBuffer;
import java.nio.channels.Channels;
import java.nio.channels.ReadableByteChannel;
import java.util.*;
import java.util.stream.Collectors;

public class Main {

    public static void main(String[] args) {

        final int n;
        final int m;
        final Map<Integer, Node> nodePool;
        final Set<Edge> givenEdges;
        final Graph givenGraph;

        n = nextInt();
        nodePool = new HashMap<>(n);
        for (int i = 1; i <= n; i++) {
            nodePool.put(i, new Node(i));
        }
        m = nextInt();
        givenEdges = new HashSet<>(n - 1 + m);
        givenGraph = new Graph(n);
        for (int i = 0; i < n - 1 + m; i++) {
            Edge e = new Edge(nodePool.get(nextInt()), nodePool.get(nextInt()));
            givenEdges.add(e);
            givenGraph.addEdge(e);
        }

        Node rootCandidate = null;
        for (int i = 1; i <= n; i++) {
            Set<Node> parents = givenGraph.getParentsOf(nodePool.get(i));
            if (parents.isEmpty()) {
                rootCandidate = nodePool.get(i);
                break;
            }
        }
        final Node root = rootCandidate;
        assert root != null;

        final Queue<Node> nonInputNode = new ArrayDeque<>();
        nonInputNode.add(root);

        final List<Node> sorted = new ArrayList<>();
        final Graph sortingGraph = givenGraph.clone();

        int level = 0;
        while (!nonInputNode.isEmpty()) {
            final Node node = nonInputNode.remove();
            if (node.getLevel() == -1) {
                node.setLevel(level);
                for (Node currentNode : nonInputNode) {
                    currentNode.setLevel(level);
                }
                level++;
            }
            sorted.add(node);
            for (final Node child : givenGraph.getChildsOf(node)) {
                sortingGraph.removeEdge(new Edge(node, child));
                if (sortingGraph.getParentsOf(child).isEmpty()) {
                    nonInputNode.add(child);
                }
            }
        }

        int[] results = new int[n];
        for (final Edge edge : givenEdges) {
            if (edge.getChild().getLevel() - edge.getParent().getLevel() == 1) {
                results[edge.getChild().getNum() - 1] = edge.getParent().getNum();
            }
        }
        try (PrintStream out = new PrintStream(new BufferedOutputStream(System.out))) {
            for (int i = 0; i < n; i++) {
                out.println(results[i]);
            }
        }

    }

    static class Edge {
        private final Node parent;
        private final Node child;

        public Edge(Node parent, Node child) {
            this.parent = parent;
            this.child = child;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Edge edge = (Edge) o;
            return Objects.equals(parent, edge.parent) &&
                    Objects.equals(child, edge.child);
        }

        @Override
        public int hashCode() {
            return Objects.hash(parent, child);
        }

        public Node getParent() {
            return parent;
        }

        public Node getChild() {
            return child;
        }

        @Override
        public String toString() {
            return "Edge{" +
                    "parent=" + parent +
                    ", child=" + child +
                    '}';
        }
    }

    static class Node {
        private final int num;
        private int level = -1;
        public Node(int num) {
            this.num = num;
        }

        @Override
        public String toString() {
            return "Node{" +
                    "num=" + num +
                    ", level=" + level +
                    '}';
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Node node = (Node) o;
            return num == node.num;
        }

        @Override
        public int hashCode() {
            return Objects.hash(num);
        }

        public int getNum() {
            return num;
        }

        public int getLevel() {
            return level;
        }

        public void setLevel(int level) {
            this.level = level;
        }
    }

    static class Graph implements Cloneable {
        private Map<Node, Set<Node>> parentMap;
        private Map<Node, Set<Node>> childMap;
        public Graph(final int initialNodeCapacity) {
            this.parentMap = new HashMap<>(initialNodeCapacity);
            this.childMap = new HashMap<>(initialNodeCapacity);
        }
        public Set<Node> getParentsOf(final Node node) {
            final Set<Node> parents = this.parentMap.get(node);
            return parents == null ? Collections.emptySet() : parents;
        }
        public Set<Node> getChildsOf(final Node node) {
            final Set<Node> childs = this.childMap.get(node);
            return childs == null ? Collections.emptySet() : childs;
        }
        public boolean addEdge(final Edge edge) {
            this.parentMap.compute(edge.getChild(), (key, existingValue) -> existingValue == null //
                    ? new HashSet<>() //
                    : existingValue).add(edge.getParent());
            return this.childMap.compute(edge.getParent(), (key, existingValue) -> existingValue == null //
                    ? new HashSet<>() //
                    : existingValue).add(edge.getChild());
        }
        public Edge removeEdge(final Edge edge) {
            this.getParentsOf(edge.getChild()).remove(edge.getParent());
            final boolean isExists = this.getChildsOf(edge.getParent()).remove(edge.getChild());
            return isExists ? edge : null;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Graph graph = (Graph) o;
            return parentMap.equals(graph.parentMap) &&
                    childMap.equals(graph.childMap);
        }

        @Override
        public int hashCode() {
            return Objects.hash(parentMap, childMap);
        }

        @Override
        public String toString() {
            return "Graph{" +
                    "parentMap=" + parentMap +
                    ", childMap=" + childMap +
                    '}';
        }
        @Override
        public Graph clone() {
            try {
                final Graph cloned = (Graph) super.clone();
                cloned.parentMap = new HashMap<>(this.parentMap.size());
                cloned.parentMap.putAll(this.parentMap.entrySet().stream() //
                        .map(entry -> new AbstractMap.SimpleEntry<>(entry.getKey(), new HashSet<>(entry.getValue()))) //
                        .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue)));
                cloned.childMap = new HashMap<>(this.childMap.size());
                cloned.childMap.putAll(this.childMap.entrySet().stream() //
                        .map(entry -> new AbstractMap.SimpleEntry<>(entry.getKey(), new HashSet<>(entry.getValue()))) //
                        .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue)));
                return cloned;
            } catch (CloneNotSupportedException e) {
                throw new InternalError("Cloneable implemented.", e);
            }
        }
    }

    private static ByteBuffer inputbuffer = ByteBuffer.allocate(1024);
    private static ReadableByteChannel inputChannel = Channels.newChannel(System.in);

    private static byte readByte() {
        while (inputbuffer.position() == inputbuffer.limit()) {
            if (Thread.interrupted()) {
                Thread.currentThread().interrupt();
                return -1;
            }
            inputbuffer.clear();
            try {
                inputChannel.read(inputbuffer);
            } catch (final IOException e) {
                throw new UncheckedIOException("IOError", e);
            }
            inputbuffer.flip();
        }
        return inputbuffer.get();
    }
    private static int nextInt() {
        int c;
        while ((c = readByte()) != -1 && ((c < '0'  || '9' < c) && c != '-')) {
            // do nothing
        }

        final boolean isMinus = (c == '-');
        if (isMinus) {
            c = readByte();
        }

        int num = 0;
        while (true) {
            if ('0' <= c && c <= '9') {
                num = num * 10 + (c - '0');
            } else {
                return isMinus ? - num : num;
            }
            c = readByte();
        }

    }

}

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

class Main{
	public static void main(String[] args) {
		Scanner sc=new Scanner(System.in);
		int N=sc.nextInt();
		int M=sc.nextInt();
		Vertex[] graph=new Vertex[N+1];
		int[] distance=new int[N+1];
		int[] to=new int[N+1];	//頂点に入っていく矢印の数
		int[] ans=new int[N+1];
		for(int i=0; i<=N; i++) {
			graph[i]=new Vertex();
			distance[i]=0;
			to[i]=0;
			ans[i]=0;
		}
		for(int i=0; i<N+M-1; i++) {
			int graph_from=sc.nextInt();
			int graph_to=sc.nextInt();
			graph[graph_from].add(graph_to,1);
			to[graph_to]++;
			if(to[graph_to]==1) {
				ans[graph_to]=graph_from;		//確定候補は確定させておく（入ってくる矢印の数が1）
			}
			else if(to[graph_to]>1) {
				ans[graph_to]=0;		//入ってくる数が2以上なら実はまだ親が確定していないので、確定しないやつは確定権利を剥奪させる
			}
		}
		Queue<Integer> q=new LinkedList<Integer>();
		for(int i=0; i<=N; i++) {
			if(to[i]==0) {
				q.add(i);		//根の頂点をキューに追加する
			}
		}
		while(!q.isEmpty()) {
			int tansaku=q.poll();	//探索する頂点
			for(int i=0; i<graph[tansaku].size(); i++) {
				int mukau=graph[tansaku].getKey(i);	//どこに向かうかの情報を取得
				to[mukau]--;	//辺を調べたので 頂点の入ってくる数を減らす
				distance[mukau]=Math.max(distance[mukau], distance[tansaku]+1);		//最長を更新できるかを確認　できたらその矢印の出た頂点が親
				if(distance[mukau]==distance[tansaku]+1) {
					ans[mukau]=tansaku;	//最長を更新したら親を更新
				}
				if(to[mukau]==0) {	//入ってくる数が0ならキューに追加
					q.add(mukau);
				}
			}
		}
		for(int i=1; i<=N; i++) {
			System.out.println(ans[i]);
		}
		sc.close();
	}
	public static final class Pair<K, V> {		//powered by mikit
		public K key;
		public V value;
		public Pair(K key, V value) {
			this.key = key;
			this.value = value;
		}
		public static int getKey(Pair<Integer,Integer> a) {
			return a.key;
		}
	}
	public static class Vertex{		//今回は2つの頂点の矢印が向いている方のリストに矢印のソースが来る
		ArrayList <Pair<Integer,Integer>> rinsetu=new ArrayList<Pair<Integer,Integer>>();
		public void add(int V,int cost) {
			rinsetu.add(new Pair<Integer, Integer>(V,cost));
		}
		public int getKey(int i) {
			return Pair.getKey(rinsetu.get(i));	//Valueを取り出す
		}
		public int size() {		//次数（無向なら）　でていく数（有向なら）を返す
			return rinsetu.size();
		}
	}
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Deque;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;

public class Main {

	static PrintWriter out;
	static InputReader ir;
	static boolean debug = true;

	static void solve() {
		int n = ir.nextInt();
		int m = ir.nextInt();
		int[][] a = new int[n + m - 1][];
		for (int i = 0; i < n + m - 1; i++)
			a[i] = ir.nextIntArray(2);
		Graph[] g = new Graph[n];
		for (int i = 0; i < n; i++)
			g[i] = new Graph();
		for (int i = 0; i < n + m - 1; i++)
			g[a[i][0] - 1].add(a[i][1] - 1);
		int[] ord = tpologicalSort(g);
		int[] dp = new int[n];
		Arrays.fill(dp, -1);
		dp[ord[0]] = 0;
		for (int i = 0; i < n; i++) {
			for (int to : g[ord[i]]) {
				dp[to] = Math.max(dp[to], dp[ord[i]] + 1);
			}
		}
		int[] par = new int[n];
		par[ord[0]] = -1;
		for (int i = 0; i < n; i++) {
			for (int to : g[ord[i]]) {
				if (dp[ord[i]] + 1 == dp[to]) {
					par[to] = ord[i];
				}
			}
		}
		for (int i = 0; i < n; i++)
			out.println(par[i] + 1);
	}

	static class Graph extends ArrayList<Integer> {
	}

	static int[] tpologicalSort(Graph[] gs) {
		int n = gs.length;
		int[] in = new int[n];
		int[] ord = new int[n];
		for (int i = 0; i < n; i++) {
			for (int to : gs[i])
				in[to]++;
		}
		Deque<Integer> s = new ArrayDeque<Integer>();
		for (int i = 0; i < n; i++) {
			if (in[i] == 0) {
				s.offerFirst(i);
			}
		}
		int p = 0;
		while (!s.isEmpty()) {
			int from = s.pollFirst();
			ord[p++] = from;
			for (int j = 0; j < gs[from].size(); j++) {
				int to = gs[from].get(j);
				in[to]--;
				if (in[to] == 0) {
					s.offerFirst(to);
				}
			}
		}
		for (int i = 0; i < n; i++)
			if (in[i] != 0)
				return null;
		return ord;
	}

	public static void main(String[] args) {
		ir = new InputReader(System.in);
		out = new PrintWriter(System.out);
		solve();
		out.flush();
	}

	static class InputReader {

		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int curbuf;
		private int lenbuf;

		public InputReader(InputStream in) {
			this.in = in;
			this.curbuf = this.lenbuf = 0;
		}

		public boolean hasNextByte() {
			if (curbuf >= lenbuf) {
				curbuf = 0;
				try {
					lenbuf = in.read(buffer);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (lenbuf <= 0)
					return false;
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[curbuf++];
			else
				return -1;
		}

		private boolean isSpaceChar(int c) {
			return !(c >= 33 && c <= 126);
		}

		private void skip() {
			while (hasNextByte() && isSpaceChar(buffer[curbuf]))
				curbuf++;
		}

		public boolean hasNext() {
			skip();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (!isSpaceChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public int nextInt() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public long nextLong() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public int[] nextIntArray(int n) {
			int[] a = new int[n];
			for (int i = 0; i < n; i++)
				a[i] = nextInt();
			return a;
		}

		public long[] nextLongArray(int n) {
			long[] a = new long[n];
			for (int i = 0; i < n; i++)
				a[i] = nextLong();
			return a;
		}

		public char[][] nextCharMap(int n, int m) {
			char[][] map = new char[n][m];
			for (int i = 0; i < n; i++)
				map[i] = next().toCharArray();
			return map;
		}
	}

	static void tr(Object... o) {
		if (debug)
			out.println(Arrays.deepToString(o));
	}
}

