import java.util.function.LongUnaryOperator;

public class Main {
    static In in = new In();
    static Out out = new Out();
    static final long inf = 0x1fffffffffffffffL;
    static final int iinf = 0x3fffffff;
    static final double eps = 1e-9;
    static long mod = 1000000007;

    void solve() {
        int n = in.nextInt();
        int m = in.nextInt();
        int[] inc = new int[n];
        List<List<Integer>> edges = new ArrayList<>();
        List<List<Integer>> rev = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            edges.add(new ArrayList<>());
            rev.add(new ArrayList<>());
        }
        for (int i = 0; i < n + m - 1; i++) {
            int a = in.nextInt() - 1;
            int b = in.nextInt() - 1;
            inc[a]++;
            edges.get(a).add(b);
            rev.get(b).add(a);
        }
        Deque<Integer> deque = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            if (inc[i] == 0) {
                deque.addLast(i);
            }
        }
        List<Integer> sorted = new ArrayList<>();
        while (!deque.isEmpty()) {
            Integer v = deque.pollFirst();
            sorted.add(v);
            for (Integer u : rev.get(v)) {
                inc[u]--;
                if (inc[u] == 0) {
                    deque.addLast(u);
                }
            }
        }
        int[] index = new int[n];
        for (int i = 0; i < sorted.size(); i++) {
            index[sorted.get(i)] = i;
        }
        int[] ans = new int[n];
        for (Integer v : sorted) {
            ans[v] = iinf;
            for (Integer u : rev.get(v)) {
                ans[v] = Math.min(ans[v], index[u]);
            }
        }
        for (int i = 0; i < n; i++) {
            out.println(ans[i] == iinf ? 0 : sorted.get(ans[i]) + 1);
        }
    }

    public static void main(String[]$) {
        new Main().solve();
        out.flush();
    }
}

class IntPair implements Comparable<IntPair> {
    int first;
    int second;

    IntPair(int first, int second) {
        this.first = first;
        this.second = second;
    }

    @Override
    public boolean equals(Object o) {
        if (!(o instanceof IntPair)) {
            return false;
        }
        IntPair that = (IntPair)o;
        return first == that.first && second == that.second;
    }

    @Override
    public int hashCode() {
        return first * 31 + second;
    }

    @Override
    public int compareTo(IntPair o) {
        return first == o.first ? Integer.compare(second, o.second) : Integer.compare(first, o.first);
    }

    @Override
    public String toString() {
        return String.format("[%s, %s]", first, second);
    }
}

