public class Main {


  private static void solve() {
    int n = ni();
    int m = ni();
    int[] from = new int[n + m - 1];
    int[] to = new int[n + m - 1];

    int[] cnt = new int[n];
    for (int i = 0; i < n + m - 1; i ++) {
      from[i] = ni() - 1;
      to[i] = ni() - 1;

      cnt[to[i]] ++;
    }

    int root = 0;
    for (int i = 0; i < n; i ++) {
      if (cnt[i] == 0) {
        root = i;
        break;
      }
    }
    int[][] g = packD(n, from, to);
    int[][] dp = new int[n][2];
    for (int[] v : dp) Arrays.fill(v, -1);
    boolean[] visited = new boolean[n];
    dfs(root, -1, g, 0, dp, visited);  

    for (int i = 0; i < n; i ++) {
      out.println(dp[i][1] + 1);
    }

  }
  static long inf = 100000000000L;
  static Map<Integer, List<int[]>> map = new HashMap<>();
  private static void dfs(int now, int pre, int[][] g, int depth, int[][] dp, boolean[] visited) {
    if (dp[now][0] < depth) {
      dp[now][1] = pre;
      dp[now][0] = depth;
    }
    if (visited[now]) {
      return;
    }
    visited[now] = true;

    for (int next : g[now]) {
      dfs(next, now, g, depth + 1, dp, visited);
    }
  }

  public static int[][] packD(int n, int[] from, int[] to){ return packD(n, from, to, from.length);}
  public static int[][] packD(int n, int[] from, int[] to, int sup)
  {
      int[][] g = new int[n][];
      int[] p = new int[n];
      for(int i = 0;i < sup;i++)p[from[i]]++;
      for(int i = 0;i < n;i++)g[i] = new int[p[i]];
      for(int i = 0;i < sup;i++){
          g[from[i]][--p[from[i]]] = to[i];
      }
      return g;
  }

