		Graph0n parent = new Graph0n(vn);

		int s1, g1;
		for(int i=1; i<(vn+en2); i++){
		    s1=sc.nexI()-1;
		    g1=sc.nexI()-1;
		    treePlus.add(s1,g1);
		    parent.add(g1,s1);
		}

		ArrayDeque<Integer> bfs = new ArrayDeque<>();
		for(int i=0; i<vn; i++){
		    if(parent.sizeOf(i)==0) bfs.add(i);
		}

		if(bfs.size()!=1) System.out.println("Error!TwoRoot");

		int[] seen = new int[vn];
		fill(seen, 0);

		while(bfs.size()>0){
		    int dw=bfs.poll();
		    for(int i: treePlus.get(dw)){
		        seen[i]++;
		        if(seen[i]>=parent.sizeOf(i)){
		            parent.get(i).clear();
		            parent.get(i).add(dw);
		            bfs.add(i);
		        }
		    }
		}

		for(int i=0; i<vn; i++){
		    if(parent.sizeOf(i)==0) out.println(0);
		    else out.println(parent.get(i,0)+1);
		}

		out.flush();
	}

	private static List<Edge> factorizationP(long n){
	    List<Edge> ans = new ArrayList<>();

	    long quotient = n;
	    long devider = 2;
	    int exponent = 0;

	    while(quotient%devider == 0){
	        quotient /= devider;
	        exponent++;
	    }
	    if(exponent>0) ans.add(new Edge(exponent, devider));

	    devider = 3;    exponent = 0;
	    while(quotient%devider == 0){
	        quotient /= devider;
	        exponent++;
	    }
	    if(exponent>0) ans.add(new Edge(exponent, devider));

	    devider=1;
	    while(devider <= Math.sqrt(n)){
	        devider+=4; exponent=0;
    	    while(quotient%devider == 0){
    	        quotient /= devider;
    	        exponent++;
    	    }
    	    if(exponent>0) ans.add(new Edge(exponent, devider));

	        devider+=2; exponent=0;
    	    while(quotient%devider == 0){
    	        quotient /= devider;
    	        exponent++;
    	    }
    	    if(exponent>0) ans.add(new Edge(exponent, devider));
	    }
	    if(quotient>1) ans.add(new Edge(1, quotient));
	    return ans;
	}

