    private byte[] inbuf = new byte[1024];
    private int lenbuf = 0, ptrbuf = 0;

    private int readByte()
    {
        if(lenbuf == -1)throw new InputMismatchException();
        if(ptrbuf >= lenbuf){
            ptrbuf = 0;
            try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
            if(lenbuf <= 0)return -1;
        }
        return inbuf[ptrbuf++];
    }

    private boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
    private int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

    private double nd() { return Double.parseDouble(ns()); }
    private char nc() { return (char)skip(); }

    private String ns()
    {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while(!(isSpaceChar(b) && b != ' ')){
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private char[] ns(int n)
    {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while(p < n && !(isSpaceChar(b))){
            buf[p++] = (char)b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private char[][] nm(int n, int m)
    {
        char[][] map = new char[n][];
        for(int i = 0;i < n;i++)map[i] = ns(m);
        return map;
    }

    private int[] na(int n)
    {
        int[] a = new int[n];
        for(int i = 0;i < n;i++)a[i] = ni();
        return a;
    }

    private int ni()
    {
        int num = 0, b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private long nl()
    {
        long num = 0;
        int b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static void tr(Object... o) { System.out.println(Arrays.deepToString(o)); }

}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Queue;
import java.util.Scanner;

public class Main {
	public static final int MAX_HIGHT = 100;

	static int N;
	static int M;
	static Node[] nodeArray;
	static Node root;

	public static void main(String[] args) {
		readInput();

		solve();
	}

	public static void solve() {
		// 幅優先探索で距離が長いパスがもともとのパス
		Queue<Node> queue = new ArrayDeque<>();
		queue.add(root);

		int[] distanceList = new int[N+1];

		while(!queue.isEmpty()) {
			Node node = queue.poll();

			int newdistance = distanceList[node.id] + 1;

			for(Node child : node.children) {
				if(distanceList[child.id] < newdistance) {
					child.parentId = node.id;
				}
				queue.add(child);
			}
		}

		for(int i = 1; i<=N; i++) {
			System.out.println(nodeArray[i].parentId);
		}
	}

	public static void readInput() {
		try (Scanner sc = new Scanner(System.in)) {
			N = sc.nextInt();
			M = sc.nextInt();

			nodeArray = new Node[N+1];

			for(int i = 1; i<nodeArray.length; i++) {
				nodeArray[i] = new Node(i);
			}

			// 根（親のいないノード）の検索用
			boolean[] hasParent = new boolean[N+1];

			// 辺の情報を読み込む
			for(int i = 0; i<(N - 1 + M); i++) {
				int s = sc.nextInt();
				int d = sc.nextInt();

				nodeArray[s].children.add(nodeArray[d]);
				hasParent[d] = true;
			}

			// 根を探す
			for(int i = 1; i<=N; i++) {
				if(!hasParent[i]) {
					root = nodeArray[i];
				}
			}
		}
	}

	public static class Node{
		public int id;
		public int parentId;
		public ArrayList<Node> children;

		public Node(int id) {
			parentId = 0;
			this.id = id;
			children = new ArrayList<Node>();
		}
	}
}

import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import java.util.Scanner;
import java.util.Set;

public class Main {

	public static void main(String[] args) {
		Main m = new Main();
		m.run();
	}

	Scanner sc = new Scanner(System.in);

	Map<Integer, Set<Integer>> map = new HashMap<Integer,Set<Integer>>();
	Map<Integer, Set<Integer>> inv = new HashMap<Integer,Set<Integer>>();

	void run() {

		int n = sc.nextInt();
		int m = sc.nextInt();
		Set<Integer> isParent = new HashSet<Integer>();
		for(int i =0 ; i < n ; i++){
			isParent.add(i+1);
		}

		for(int i = 0; i < n+m-1;i++){
			int a  =sc.nextInt();
			int b = sc.nextInt();

			map.computeIfAbsent(a, __ -> new HashSet<Integer>()).add(b);
			inv.computeIfAbsent(b, __ -> new HashSet<Integer>()).add(a);

			isParent.remove(b);
		}

		int root = isParent.toArray(new Integer[0])[0];

		int ans[] = new int[n];
		search(ans,root,0);

		for(int i =0 ; i < n ; i++){
			System.out.println(ans[i]);
		}
	}

	void search(int[] ans, int initnow, int initparent ){

		List<int[]> children = new LinkedList<int[]>();
		children.add(new int[]{initnow,initparent});


		for(;!children.isEmpty();){
			int[] n = children.remove(0);

			int now = n[0];
			int parent = n[1];

//			System.out.println(now+" "+parent);

			ans[now-1] = parent;

			for(int child : map.getOrDefault(now,new HashSet<Integer>())){
				if(inv.get(child).size() != 1){
					inv.get(child).remove(now);
//					System.out.println(" remove "+child+" : "+now);
				}else{
					children.add(new int[]{child,now});
				}			
			}

		}

		return ;

	}
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.Queue;
import java.util.Scanner;

public class Main {
	static int N;
	static int M;
	static Node[] nodeArray;
	static Node root;

	public static void main(String[] args) {
		readInput();

		solve();
	}

	static void solve() {
		boolean[] isSearched = new boolean[N+1];
		Deque<Integer> sortedNode = new ArrayDeque<>(N+1);

		for(int i = 1; i<=N; i++) {
			recursiveSearch(i, isSearched, sortedNode);
		}

		Integer[] sortedNodeArray = new Integer[sortedNode.size()];
		sortedNode.toArray(sortedNodeArray);

		int[] parentList = new int[N+1];

		for(int i = sortedNodeArray.length - 1; i>=0; i--) {
			int nodeId = sortedNodeArray[i];

			for(int j = i-1; j<=0; j--) {
				if(nodeArray[nodeId].parents.contains(sortedNodeArray[j])) {
					parentList[nodeId] = sortedNodeArray[j];
					break;
				}
			}
		}

		for(int i = 1; i<=N; i++) {
			System.out.println(parentList[i]);
		}
	}

	static void recursiveSearch(int nodeId, boolean[] isSearched, Deque<Integer> queue) {
		if(isSearched[nodeId]) {
			return;
		}

		isSearched[nodeId] = true;

		for(int childId : nodeArray[nodeId].children) {
			recursiveSearch(childId, isSearched, queue);
		}

		queue.addFirst(nodeId);
	}

	static void readInput() {
		try (Scanner sc = new Scanner(System.in)) {
			N = sc.nextInt();
			M = sc.nextInt();

			nodeArray = new Node[N+1];

			for(int i = 0; i<nodeArray.length; i++) {
				nodeArray[i] = new Node(i);
			}

			// 辺の情報を読み込む
			for(int i = 0; i<(N - 1 + M); i++) {
				int s = sc.nextInt();
				int d = sc.nextInt();

				nodeArray[d].parents.add(s);
				nodeArray[s].children.add(d);
			}
		}
	}

	static class Node{
		public int id;
		public ArrayList<Integer> parents;
		public ArrayList<Integer> children;

		public Node(int id) {
			this.id = id;
			parents = new ArrayList<>();
			children = new ArrayList<>();
		}
	}
}

