	public static long[] Dijkstra(IEnumerable<P<long,long,long>> inEdges, long V, long start, out long[] prev) {
		long[] dist = Enumerable.Repeat(0L, (int)V).ToArray();
		prev = Enumerable.Repeat(-1L, (int)V).ToArray();
		var G = new Dictionary<long,long>[V]; 
		for(int i=0;i<V;i++) G[i] = new Dictionary<long,long>();
		foreach(var e in inEdges){
			if(e.A==e.B) continue;
			if(!G[e.A].ContainsKey(e.B)||e.C<G[e.A][e.B]) G[e.A][e.B] = e.C;
			//if(!G[e.B].ContainsKey(e.A)||e.C<G[e.B][e.A]) G[e.B][e.A] = e.C;
		}

		var que = new PriorityQueue<KeyValuePair<long, long>>(V, (x,y)=>(y.Key.CompareTo(x.Key)));
		dist[start] = 0;
		que.Enqueue(new KeyValuePair<long, long>(dist[start], start));
		while(0<que.Count) {
			var q = que.Dequeue();
			if(dist[q.Value] > q.Key) continue;
			foreach(var e in G[q.Value]){
				var next_cost = q.Key + e.Value;
				if(dist[e.Key] >= next_cost) continue;
				dist[e.Key] = next_cost;
				que.Enqueue(new KeyValuePair<long, long>(dist[e.Key], e.Key));
			   	prev[e.Key] = q.Value;
			}
		}
		return dist;
	}
	public static long[] Dijkstra(IEnumerable<P<long,long,long>> inEdges, long V, long start){ long[] d; return Dijkstra(inEdges, V, start, out d); }

public class PriorityQueue<T>
{
	private readonly List<T> heap;
	private readonly Comparison<T> compare;
	private int size;
	public PriorityQueue() : this(Comparer<T>.Default) {} 
	public PriorityQueue(IComparer<T> comparer) : this(16, comparer.Compare) { }
	public PriorityQueue(Comparison<T> comparison) : this(16, comparison) { }
	public PriorityQueue(long capacity, Comparison<T> comparison)
	{
		this.heap = new List<T>((int)capacity);
		this.compare = comparison;
	}
	public void Enqueue(T item)
	{
		this.heap.Add(item);
		var i = size++;
		while (i > 0)
		{
			var p = (i - 1) >> 1;
			if (compare(this.heap[p], item) <= 0)
				break;
			this.heap[i] = heap[p];
			i = p;
		}
		this.heap[i] = item;

	}
	public T Dequeue()
	{
		var ret = this.heap[0];
		var x = this.heap[--size];
		var i = 0;
		while ((i << 1) + 1 < size)
		{
			var a = (i << 1) + 1;
			var b = (i << 1) + 2;
			if (b < size && compare(heap[b], heap[a]) < 0) a = b;
			if (compare(heap[a], x) >= 0)
				break;
			heap[i] = heap[a];
			i = a;
		}
		heap[i] = x;
		heap.RemoveAt(size);
		return ret;
	}
	public T Peek() { return heap[0]; }
	public long Count { get { return size; } }
	public bool Any() { return size > 0; }
}







