                var Outs = edges.Where(x => x.From == n).ToArray();
                //その辺が行き着くNodeについて考える。
                for (int i = 0; i < Outs.Length; i++) {
                    int to = Outs[i].To;
                    edges.Remove(Outs[i]);
                    Copy.Add(Outs[i]);
                    //もしそのNodeが他に入力辺を持たないなら、Rootに追加する。
                    if (edges.Where(x => x.To == to).Count() == 0) { Roots.Add(to); SortedEdge.Add(Outs[i]); }
