	public static long[] TopologicalSort(Dictionary<long,long>[] G) {
    	List<long> ans = new List<long>();
    	int n = (int)G.Length;
    	long[] ind = new long[n];      // ind[i]: 頂点iに入る辺の数(次数)
		for (int i = 0; i < n; i++) {  // 次数を数えておく
			foreach (var e in G[i]) ind[e.Key]++;
		}
    	Queue<long> que = new Queue<long>();
		for (int i = 0; i < n; i++) {  // 次数が0の点をキューに入れる
			if (ind[i] == 0) que.Enqueue(i);
		}
		while (0<que.Count) {  // 幅優先探索
			var now = que.Dequeue();
			ans.Add(now);
			foreach (var e in G[now]) {
				if (--ind[e.Key] == 0) que.Enqueue(e.Key);
			}
		}
		return ans.ToArray();
	}


	public static Dictionary<long,long>[] MakeGraph(IEnumerable<P<long,long>> inEdges, long N=-1, long shift=0){
		if(N==-1){
			foreach (var e in inEdges)
			{
				if(N<e.A) N = e.A;
				if(N<e.B) N = e.B;
			}
			N += shift+1;
		}
		var ret = new Dictionary<long,long>[Math.Max(N,0)];
		if (ret.Length==0) return ret;
		for (int i = 0; i < ret.Length; i++) ret[i] = new Dictionary<long,long>();
		foreach (var e in inEdges)
		{
			ret[e.A+shift][e.B+shift]=1;
