class MainClass
{
    static void Main()
    {
        var NM = Console.ReadLine().Split().Select(int.Parse).ToArray();
        int N = NM[0], M = NM[1];

        var G = new Graph(N);
        var parents = new Graph(N);
        var Degrees = new int[N];

        for (int i = 0; i < N+M-1; i++)
        {
            var r = Console.ReadLine().Split().Select(_=>int.Parse(_)-1).ToArray();
            G.Add(r[0], r[1]);
            parents.Add(r[1], r[0]);
            Degrees[r[1]]++;
        }

        var sorted = new List<int>(Topologicalsort(G, Degrees));
        var sortedpos = new int[N];
        for (int i = 0; i < N; i++)
        {
            sortedpos[sorted[i]] = i;
        }

        for (int i = 0; i < N; i++)
        {
            int parent = -1;
            int parentpos = -1;
            foreach (var j in parents[i])
            {
                if (parentpos < sortedpos[j])
                {
                    parent = j;
                    parentpos = sortedpos[j];
                }
            }
            Console.WriteLine(parent+1);
        }
    }

    static List<int> Topologicalsort(Graph G, int[] Degrees)
    {
        var que = new Queue<int>();
        for (int i = 0; i < Degrees.Length; i++)
        {
            if (Degrees[i] == 0)
                que.Enqueue(i);
        }

        var sorted = new List<int>();
        while (que.Count > 0)
        {
            var v = que.Dequeue();
            sorted.Add(v);
            foreach (var i in G[v])
            {
                Degrees[i]--;
                if (Degrees[i] == 0)
                    que.Enqueue(i);
            }
        }
        return sorted;
    }
}

