    static int[] nm;
    static int[] memo;
    static bool[] th;
    static void Solve()
    {
        nm = Input.ar;
        memo = new int[nm[0]];
        th = new bool[nm[0]];
        var ps = P.Make(nm[0], nm[0] + nm[1] - 1, false, false);
        for (var i = 0; i < nm[0]; i++)
            if (!th[i])
                dfs(ps, i);
        WriteLine(string.Join("\n", ps.Select(p => p.parent)));
    }
    static int dfs(P[] ps,int index)
    {
        if (th[index])
            return memo[index];
        th[index] = true;
        var qq = 0;
        foreach (var ad in ps[index].rev)
        {
            var calc = dfs(ps, ad) + 1;
            if (calc > qq)
            {
                ps[index].parent = ad + 1;
                qq = calc;
            }
        }
        return memo[index] = qq;
    }
}

