public class Solution
{
    public static void Main()
    {
        var vals = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
        var n = vals[0];
        var m = vals[1];
        var edges = n - 1 + m;
        var upper = Enumerable.Range(0, n + 1).Select(_ => new List<int>()).ToArray();
        var lower = Enumerable.Range(0, n + 1).Select(_ => new List<int>()).ToArray();
        var hasParent = new bool[n + 1];
        for (int i = 0; i < edges; i++)
        {
            vals = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
            var a = vals[0];
            var b = vals[1];
            upper[b].Add(a);
            lower[a].Add(b);
        }

        var root = Enumerable.Range(1, n).First(x => upper[x].Count == 0);
        var queue = new Queue<int>();
        queue.Enqueue(root);
        while (queue.Count > 0)
        {
            var p = queue.Dequeue();
            foreach (var child in lower[p])
            {
                if (upper[child].Count == 1)
                {
                    queue.Enqueue(child);
                }
                else
                {
                    upper[child].Remove(p);
                }
            }
        }

        upper[root].Add(0);
        var answer = string.Join(Environment.NewLine, upper.Skip(1).Select(u => u[0]));
        Console.WriteLine(answer);
    }
}

