using System;
using System.Collections.Generic;
using System.Linq;

static class D
{
    static void Main()
    {
        int[] nm = Console.ReadLine().Split(' ').Select(Int32.Parse).ToArray();
        int n = nm[0];
        int m = nm[1];

        var edges = Enumerable.Range(0, n).Select(_ => new List<int>()).ToList();
        var deg = Enumerable.Repeat(0, n).ToList();

        for (int i = 0; i < n - 1 + m; i++) {
            int[] ab = Console.ReadLine().Split(' ').Select(Int32.Parse).ToArray();
            int a = ab[0] - 1;
            int b = ab[1] - 1;
            edges[a].Add(b);
            ++deg[b];
        }

        var par = Enumerable.Repeat(-1, n).ToList();

        var queue = new Queue<int>();
        for (int i = 0; i < n; i++) {
            if (deg[i] == 0) {
                par[i] = 0;
                queue.Enqueue(i);
            }
        }
        while (queue.Count > 0) {
            int i = queue.Dequeue();
            foreach (int j in edges[i]) {
                if (par[j] == -1) {
                    --deg[j];
                    if (deg[j] == 0) {
                        par[j] = i + 1;
                        queue.Enqueue(j);
                    }
                }
            }
        }
        for (int i = 0; i < n; i++) {
            Console.WriteLine(par[i]);
        }
    }
}

using System;
