class Topological
{
    public List<Edge>[] Dag { get; set; }
    public int N { get; set; }
    public Topological(int n)
    {
        this.N = n;
        this.Dag = new List<Edge>[n];
        for (int i = 0; i < n; i++)
        {
            this.Dag[i] = new List<Edge>();
        }
    }
    public void Add(int a, int b, long cost)
    {
        this.Dag[a].Add(new Edge(b, cost));
    }
    public int[] Sort(int start)
    {
        // 各頂点の流入数を数え上げる
        var countIn = new int[N];
        for (int i = 0; i < N; i++)
        {
            foreach (var e in this.Dag[i])
            {
                countIn[e.To]++;
            }
        }
        // 流入数が0になった頂点から順番に並べる
        var q = new Queue<int>();
        q.Enqueue(start);
        var list = new List<int>();
        while (q.Count > 0)
        {
            var now = q.Dequeue();
            list.Add(now);
            foreach (var e in this.Dag[now])
            {
                countIn[e.To]--;
                if (countIn[e.To] == 0) q.Enqueue(e.To);
            }
        }
        return list.ToArray();
    }
    public long[] GetMinCost(int start)
    {
        var sorted = this.Sort(start);
        var dist = new long[this.N];
        for (int i = 0; i < N; i++)
        {
            dist[i] = int.MaxValue;
        }
        dist[start] = 0;
        for (int i = 0; i < N - 1; i++)
        {
            var now = sorted[i];
            foreach (var e in Dag[now])
            {
                dist[e.To] = Math.Min(dist[e.To], dist[now] + e.Cost);
            }
        }
        return dist;
    }
    public struct Edge
    {
        public int To { get; set; }
        public long Cost { get; set; }
        public Edge(int to, long cost)
        {
            this.To = to;
            this.Cost = cost;
        }
    }
}

using System;
using System.Collections.Generic;
class Program
{
	static void Main(string[] args)
	{
		// 入力フェーズ
		string[] input = Console.ReadLine().Split(' ');
        int N = int.Parse(input[0]);
        int M = int.Parse(input[1]);

        // 辺の情報を取得して配列にする
        List<List<int> > graph = createGraph(N, M);

        // 各辺について、削除できるか検証する
        // 削除可能→子ノードを0に更新
        deleteBars(ref graph, M);

        //Console.WriteLine(" AAAA");
        // graphから出力用の表記を生成する
        int[] ret = output(graph);
        //Console.WriteLine(" BBBB");
        //出力
        for (int i = 0; i < N; i++)
        {
            Console.WriteLine(ret[i]);
        }
    }

    ///Ai→Biの表記から、各頂点と子供を管理するタイプの表記にする
    /// return List<int[]> ret
    /// ret[i] は i+1のノードから伸びている子供の番号を配列にして格納する
    static private List<List<int> > createGraph(int N, int M)
    {
        List<List<int>> graph = new List<List<int> >();

        // graphをN行にする
        for (int i = 0; i < N; i++)
        {
            List<int> arr = new List<int>();
            graph.Add(arr);
        }

        for (int i = 0; i < N-1+M; i++)
        {
            string[] ab = Console.ReadLine().Split(' ');
            int a = int.Parse(ab[0]); // 親 1→0番目に格納する
            int b = int.Parse(ab[1]); // 子
            //Console.WriteLine(a + " " + b + " " + bars.GetLength(1));
            graph[a - 1].Add(b);
        }
        //Console.WriteLine(graph.Count);
        return graph;
    }

    /// たとえば1→2という有向線があったとき、この線を使わずに1から2にたどり着ければ、
    /// 1→2は削除できるので削除する
    /// というのを全ての辺、またはM本削除するまで繰り返す
    static private void deleteBars(ref List<List<int>> graph, int M)
    {
				// graphをコピーすればいいじゃん
				List<List<int>> accessibleList = new List<List<int>>(graph);

        for (int i = 0; i < graph.Count; i++)
        {
            if (M == 0)
            {
                // 検証終わり
                break;
            }
            List<int> child = graph[i];
            for (int j = 0; j < child.Count; j++)
            {
                if (M == 0)
                {
                    // 検証終わり
                    break;
                }
                // i 親ノード番号
                // child[j] 子ノード番号（今回検証する）
                //Console.WriteLine("検証 " + i + " " + child[j]);
                if(isEnableDetour(graph, i, child[j], true, accessibleList[i]))
                {
                    //Console.WriteLine("デリート " + i + " " + child[j]);
                    graph[i][j] = 0; // デリートすると順番ずれるしめんどい
                    M--;
                }
            }
        }
    }

    /// graphを使って、iからchild[j]まで、i→child[j]を使わずに迂回できたら削除できる(true)
    /// isTop = trueのときだけゴールじゃない

    static private bool isEnableDetour(List<List<int>> graph, int start, int goal, bool isTop, List<int> acList)
    {
        if (!isTop && (graph[start].Contains(goal) || acList.Contains(goal)))
        {
            // 一回目じゃないときで、startノードの子にgoalノードがあれば迂回成功
						return true;
        }
        else
        {
            List<int> child = graph[start];
            // 一回目のときは、goal以外のノードから迂回ルートを探すようにする
            for (int i = 0; i < child.Count; i++)
            {
								acList.Add(child[i]);
                if (isTop && child[i] == goal) continue;
                //Console.WriteLine("検証2 " + (child[i] - 1) + " " + goal);

                if ((child[i] - 1) >= 0 && isEnableDetour(graph, child[i] - 1, goal, false, acList)) // 親ノード番号にするときは添え字にあわせる
                {
                    return true;
                }
            }
        }
        // 葉ノードに到達しちゃったら迂回失敗を返す
        return false;
    }

    /// graph表記から、出力できる形に変形する
    static private int[] output(List<List<int>> graph)
    {
        int N = graph.Count;
        int[] ret = new int[N];

        //Console.WriteLine(N);
        for (int i = 0; i < N; i++)
        {
            //Console.WriteLine(i + " i" );
            List<int> child = graph[i];
            //Console.WriteLine(child.Count+ " c");
            for (int j = 0; j < child.Count; j++)
            {
                int node = child[j]; // 子ノード, i=親ノード番号
                //Console.WriteLine(node + " node");
                if (node == 0) continue; // 0は削除済み
                ret[node - 1] = i + 1;
            }
        }
        return ret;
    }
}

