class Program
{
    static void Main(string[] args)
    {
        var N = sc.ReadInt();
        var M = sc.ReadInt();
        var AB = sc.ReadTupArray(N + M - 1, -1);
        var g = new List<int>[N];
        for (int i = 0; i < N; i++)
        {
            g[i] = new List<int>();
        }
        var tp = new Topological(N);
        for (int i = 0; i < N + M - 1; i++)
        {
            var a = AB[i].Item1;
            var b = AB[i].Item2;
            g[a].Add(b);
            tp.Add(a, b, -1);
        }
        var root = Enumerable.Range(0, N).Except(AB.Select(ab => ab.Item2)).First();
        var dist = tp.GetMinCost(root);
        var edges = new List<Tuple<int, int>>();
        var q = new Queue<Tuple<int, int>>();
        q.Enqueue(Tuple.Create(root, 0));
        while (q.Count > 0)
        {
            var t = q.Dequeue();
            var now = t.Item1;
            var d = t.Item2;
            if (d == -dist[now])
            {
                foreach (var next in g[now])
                {
                    if (-dist[next] == d + 1)
                    {
                        edges.Add(Tuple.Create(now, next));
                        q.Enqueue(Tuple.Create(next, d + 1));
                    }
                }
            }
        }
        edges.Add(Tuple.Create(-1, root));
        foreach (var e in edges.OrderBy(e => e.Item2))
        {
            Console.WriteLine(e.Item1 + 1);
        }
    }
