            G[ab[0]].Add(ab[1]);
            Degrees[ab[1]]++;
            parents[ab[1]].Add(ab[0]);
        }

        var sorted = TopologicalSort(G, Degrees);
        var sortedpos = new int[N];
        for (int i = 0; i < N; i++)
        {
            sortedpos[sorted[i]] = i;
        }

