            foreach (var vs in parents[i])
            {
                if (parentpos < sortedpos[vs])
                {
                    parent = vs;
                    parentpos = sortedpos[vs];
                }

            }

            Console.WriteLine(parent+1);
        }
    }
    static List<int> TopologicalSort(List<int>[] G,int[] Degrees)
    {
        var que = new Queue<int>();
        for (int i = 0; i < Degrees.Length; i++)
        {
            if (Degrees[i] == 0)
                que.Enqueue(i);
        }

        List<int> sorted = new List<int>();
        while (que.Count > 0)
        {
            var t = que.Dequeue();
            sorted.Add(t);

            foreach (var i in G[t])
            {
                Degrees[i]--;
                if (Degrees[i] == 0)
                {
                    que.Enqueue(i);
                }
            }
        }

        return sorted;
    }
