using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
using System.Text;//テキストの高速出力に必要
class Program
{
	static void Main()
	{
		string[] input = Console.ReadLine().Split(' ');
		int n = int.Parse(input[0]);
		int m = int.Parse(input[1]);
    int answeredCount = 0;//解答の確定した個数
    int checkingNum = 0;
    int[] depthes = new int[n];//深さ
    for(int i = 0; i < n; i++) depthes[i] = -1;
    int[] answers = new int[n];
    List<int>[] nextList = new List<int>[n];//親の候補リスト
    for(int i = 0; i < n; i++) nextList[i] = new List<int>();//リストの宣言
    for(long i = 0; i < n-1+m; i++)
    {
      int[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),int.Parse);
      nextList[nums[1]-1].Add(nums[0]-1);
    }

    while(true)
    {
      //Console.WriteLine(checkingNum);
      //Console.WriteLine(string.Join(" ", nextList[checkingNum]));
      checkingNum++;
      if(checkingNum == n) checkingNum = 0;
      if(depthes[checkingNum] != -1) continue;

      if(nextList[checkingNum].Count() == 0)
      {
        depthes[checkingNum] = 0;
        answeredCount++;
      }else if(nextList[checkingNum].Count() == 1)
      {
        //Console.WriteLine(checkingNum+"a");
        if(depthes[nextList[checkingNum][0]] == -1) continue;//親の深さが不明
        else
        {
          depthes[checkingNum] = depthes[nextList[checkingNum][0]]+1;
          answers[checkingNum] = nextList[checkingNum][0]+1;
          answeredCount++;
        }
      }else//親の候補が複数の場合
      {
        int depthMaxMemo = -1;
        int depthMaxNum = 0;
        for(int i = 0; i < nextList[checkingNum].Count(); i++)
        {
          if(depthes[nextList[checkingNum][i]] == -1)
          {
            depthMaxMemo = -1;
            break;
          }else
          {
            if(depthMaxMemo < depthes[nextList[checkingNum][i]])
            {
              depthMaxMemo = depthes[nextList[checkingNum][i]];
              depthMaxNum = nextList[checkingNum][i];
            }
          }
        }
        if(depthMaxMemo == -1) continue;
        else
        {
          depthes[checkingNum] = depthMaxMemo + 1;
          answers[checkingNum] = depthMaxNum+1;
          answeredCount++;
        }
      }

      if(answeredCount == n) break;
    }

    var answerText = new StringBuilder();//出力
    for(long i = 0; i < answers.Length; i++)
    {
      answerText.AppendLine(answers[i].ToString());
    }
    Console.Write(answerText);
	}
}

