            que.Enqueue(root);
            var cnt = 1;
            while (que.Any())
            {
                var chk = que.Dequeue();
                foreach(var i in edgeOut[chk])
                {
                    num[i] = cnt;
                    cnt++;
                    que.Enqueue(i);
                }
            }
            var ans = new int[N + 1];
            for (int i = 1; i <= N; i++)
            {
                long max = -1;
                foreach(var j in edgeIn[i])
                {
                    if (num[j] > max)
                    {
                        max = num[j];
                        ans[i] = j;
                    }
                }
            }
            ans[root] = 0;

            for (int i = 1; i <= N; i++) Console.WriteLine(ans[i]);

            Console.WriteLine();
            Console.ReadLine();
        }

