    public long[] LongArr => StrArr.Select(long.Parse).ToArray();
    public double[] DoubleArr => StrArr.Select(double.Parse).ToArray();
    public string[] StrArr => Str.Split(new[]{' '}, StringSplitOptions.RemoveEmptyEntries);
    bool eq<T, U>() => typeof(T).Equals(typeof(U));
    T ct<T, U>(U a) => (T)Convert.ChangeType(a, typeof(T));
    T cv<T>(string s) => eq<T, int>()    ? ct<T, int>(int.Parse(s))
                       : eq<T, long>()   ? ct<T, long>(long.Parse(s))
                       : eq<T, double>() ? ct<T, double>(double.Parse(s))
                       : eq<T, char>()   ? ct<T, char>(s[0])
                                         : ct<T, string>(s);
    public void Multi<T>(out T a) => a = cv<T>(Str);
    public void Multi<T, U>(out T a, out U b)
    { var ar = StrArr; a = cv<T>(ar[0]); b = cv<U>(ar[1]); }
    public void Multi<T, U, V>(out T a, out U b, out V c)
    { var ar = StrArr; a = cv<T>(ar[0]); b = cv<U>(ar[1]); c = cv<V>(ar[2]); }
    public void Multi<T, U, V, W>(out T a, out U b, out V c, out W d)
    { var ar = StrArr; a = cv<T>(ar[0]); b = cv<U>(ar[1]); c = cv<V>(ar[2]); d = cv<W>(ar[3]); }
    public void Multi<T, U, V, W, X>(out T a, out U b, out V c, out W d, out X e)
    { var ar = StrArr; a = cv<T>(ar[0]); b = cv<U>(ar[1]); c = cv<V>(ar[2]); d = cv<W>(ar[3]); e = cv<X>(ar[4]); }
}

using System;
using System.Collections.Generic;
class Program
{
	static void Main(string[] args)
	{
		// 入力フェーズ
				string[] input = Console.ReadLine().Split(' ');
        int N = int.Parse(input[0]);
        int M = int.Parse(input[1]);

        // 辺の情報を取得して配列にする
        List<List<int> > saveGraph = new List<List<int> >();
				List<List<int> > parentGraph = new List<List<int> >();
				createGraph(N, M, ref saveGraph, ref parentGraph);// 保存用 最後に見る
				List<Tree> graph = copyGraph(saveGraph);

				// 各ノードを並び替えて順番をつける(葉ノードから番号を振る)
				int[] sortedNode = new int[N+1]; // [0]は使わない
				sortLeafToRoot(ref sortedNode, graph);

        // graphから出力用の表記を生成する
        int[] ret = output(sortedNode, parentGraph);

        //出力
        for (int i = 1; i <= N; i++)
        {
            Console.WriteLine(ret[i]);
        }
    }

		class Tree
		{
				public int nodeNo{set; get;}
				public List<int> children{set; get;}
		}

		static private List<Tree> copyGraph(List<List<int> > graph)
		{
			List<Tree> ret = new List<Tree>();
			for(int i=1; i<graph.Count; i++) // graph.Count = N+1
			{
				Tree t = new Tree();
				t.nodeNo = i;
				List<int> tt = new List<int>(graph[i]);
				t.children = tt;
				ret.Add(t);
			}

			return ret;
		}
		static private void sortLeafToRoot(ref int[] sortedNode, List<Tree> graph)
		{
			int cnt = 1;
			List<List<int> > NDelNode = new List<List<int> >(); // Nループ目で削除したノードを入れる
			for(int loop = 0; graph.Count > 0 && loop < 4; loop++)
			{
				// 前回のループで葉っぱになって削除したノードを削除する
				if(loop - 1 >= 0)
				{
					List<int> excNode = NDelNode[loop - 1];
					for(int j=0; j<graph.Count; j++)
					{
						for(int k=0; k<excNode.Count; k++)
						{
							if(graph[j].children.Contains(excNode[k]))
								graph[j].children.Remove(excNode[k]);
						}
					}
				}
				List<int> delNode = new List<int>();
				for(int i=0; i<graph.Count; i++)
				{
					//葉ノードだったらsotedNode[a(ノード番号)]に１から順番を振って番号を入れる
					if(graph[i].children.Count == 0)
					{
						int node = graph[i].nodeNo;
						sortedNode[node] = cnt++;
						delNode.Add(node);
						graph.RemoveAt(i);
					}
				}

					NDelNode.Add(delNode);
			}
		}

    ///Ai→Biの表記から、各頂点と子供を管理するタイプの表記にする
    /// return List<int[]> ret
    /// ret[i] は i+1のノードから伸びている子供の番号を配列にして格納する
    static private void createGraph(int N, int M, ref List<List<int> > graph, ref List<List<int> > Pgraph)
    {
        // graphをN+1行にする
        for (int i = 0; i <= N; i++)
        {
            List<int> arr = new List<int>();
						List<int> arr2 = new List<int>();
            graph.Add(arr);
						Pgraph.Add(arr2);
        }
        for (int i = 0; i < N-1+M; i++)
        {
            string[] ab = Console.ReadLine().Split(' ');
            int a = int.Parse(ab[0]); // 親 1→1番目に格納する
            int b = int.Parse(ab[1]); // 子
            //Console.WriteLine(a + " " + b + " " + bars.GetLength(1));
            graph[a].Add(b);
						Pgraph[b].Add(a);
        }
    }

    /// graph表記から、出力できる形に変形する
    static private int[] output(int[] sortedNode, List<List<int>> graph)
    {
			// graph[i]にはiの親ノード番号が格納されている
        int N = graph.Count;
        int[] ret = new int[N];

        //Console.WriteLine(N);
        for (int i = 1; i <= N-1; i++)
        {
            //Console.WriteLine(i + " i" );
            List<int> parent = graph[i];
						// 親ノードのうち、sortedNodeを参照して一番小さい数字が格納されているものを親とする
						int[] minP = new int[]{0, sortedNode.Length};
            for (int j = 0; j < parent.Count; j++)
            {
                int parentNode = parent[j];
								int parentRank = sortedNode[parentNode];
                //Console.WriteLine(node + " node");
                if(minP[1] > parentRank)
								{
									minP[0] = parentNode;
									minP[1] = parentRank;
								}
            }
						ret[i] = minP[0];
        }
        return ret;
    }
}

