namespace NikkeiContest.D
{
	using static Util;

	public class Solver : SolverBase
	{
		public void Run() {
			var ary = ReadIntArray();
			var N = ary[0];
			var M = ary[1];

			// [i] = 当該頂点への入次数（頂点に入ってくる数）
			int[] indegrees = new int[N+1];
			// tree[i] = 子供のList
			var tree = new List<int>[N+1];
			for (int i = 0; i < N + M - 1; i++) {
				var a = ReadIntArray();
				var p = a[0];
				var c = a[1];

				indegrees[c]++;

				var l = tree[p];
				if (l == null) tree[p] = l = new List<int>();
				l.Add(c);
			}

			// root親を探す ※入次数=0 がroot
			int root = -1;
			for (int i = 1; i <= N; i++) {
				if (indegrees[i] == 0) {
					root = i;
				}
			}

			// aryP[i] = 頂点i の 親番号
			var aryP = new int[N + 1];

			// BFSで子供をたどる
			var que = new Queue<int>();
			que.Enqueue(root);

			// BFSでトポロジカルソートしながら、親を確定していく
			while (0 < que.Count) {
				var p = que.Dequeue();
				if (tree[p] == null) continue;

				foreach (int c in tree[p]) {
					// 子でループ
					// 子の入次数をへらす
					indegrees[c]--;

					// 子の入次数が0 ＝ この時点で親が確定
					if (indegrees[c] == 0) {
						que.Enqueue(c);
						aryP[c] = p;
					}
				}
			}
			for (int i = 1; i < N + 1; i++) {
				WriteLine(aryP[i]);
			}
		}

