	public static long[] BellmanFord(IEnumerable<P<long,long,long>> inEdges, long V, long start, out long[] prev) {
		long[] dist = Enumerable.Repeat(long.MaxValue, (int)V).ToArray();
		dist[start] = 0;
		prev = Enumerable.Repeat(-1L, (int)V).ToArray();
		for(int i = 0; i < V - 1; i++) {
			foreach(var e in inEdges) {
				if(dist[e.A] == long.MaxValue) continue;
				if(dist[e.A] + e.C < dist[e.B]) {
					dist[e.B] = dist[e.A] + e.C;
				   	prev[e.B] = e.A;
				}
			}
		}

		// 負閉路検出V0
//		foreach(var e in inEdges) {
//			if(dist[e.Item1] == long.MaxValue) continue;
//			if(dist[e.Item1] + e.Item3 < dist[e.Item2]) return new long[0];
//		}
		// 負閉路検出V1
		var negative = new bool[V];
		for(int i = 0; i < V ; i++) {
			foreach(var e in inEdges) {
				if(dist[e.A] == long.MaxValue) continue;
				if(dist[e.A] + e.C < dist[e.B]) {
					dist[e.B] = dist[e.A] + e.C;
					negative[e.B] = true;
				}
				if(negative[e.A]) negative[e.B] = true;
			}
		}
		for(int i = 0; i < V ; i++) if(negative[i]) dist[i] = long.MinValue;

		return dist;
	}

public class PriorityQueue<T>
{
	private readonly List<T> heap;
	private readonly Comparison<T> compare;
	private int size;
	public PriorityQueue() : this(Comparer<T>.Default) {} 
	public PriorityQueue(IComparer<T> comparer) : this(16, comparer.Compare) { }
	public PriorityQueue(Comparison<T> comparison) : this(16, comparison) { }
	public PriorityQueue(long capacity, Comparison<T> comparison)
	{
		this.heap = new List<T>((int)capacity);
		this.compare = comparison;
	}
	public void Enqueue(T item)
	{
		this.heap.Add(item);
		var i = size++;
		while (i > 0)
		{
			var p = (i - 1) >> 1;
			if (compare(this.heap[p], item) <= 0)
				break;
			this.heap[i] = heap[p];
			i = p;
		}
		this.heap[i] = item;

	}
	public T Dequeue()
	{
		var ret = this.heap[0];
		var x = this.heap[--size];
		var i = 0;
		while ((i << 1) + 1 < size)
		{
			var a = (i << 1) + 1;
			var b = (i << 1) + 2;
			if (b < size && compare(heap[b], heap[a]) < 0) a = b;
			if (compare(heap[a], x) >= 0)
				break;
			heap[i] = heap[a];
			i = a;
		}
		heap[i] = x;
		heap.RemoveAt(size);
		return ret;
	}
	public T Peek() { return heap[0]; }
	public long Count { get { return size; } }
	public bool Any() { return size > 0; }
}







