namespace AtCoder
{
    class Program
    {
        private static string Read() { return Console.ReadLine(); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }

        static int Distance(int n, List<int>[] parents, int?[] memo)
        {
            if (!memo[n].HasValue)
            {
                memo[n] = 0;
                foreach (var parent in parents[n])
                {
                    int distance = Distance(parent, parents, memo);
                    if (distance + 1 > memo[n])
                    {
                        memo[n] = distance + 1;
                    }
                }
            }
            return memo[n].Value;
        }

        static int[] Solve(int N, int M, Tuple<int, int>[] tuples)
        {
            var parents = new List<int>[N];
            for (int i = 0; i < N; ++i)
            {
                parents[i] = new List<int>();
            }
            foreach (var tuple in tuples)
            {
                parents[tuple.Item2].Add(tuple.Item1);
            }
            var memo = new int?[N];
            var answers = Enumerable.Repeat(-1, N).ToArray();
            for (int i = 0; i < N; ++i)
            {
                int min = -1;
                foreach (var parent in parents[i])
                {
                    var distance = Distance(parent, parents, memo);
                    if (distance > min)
                    {
                        answers[i] = parent;
                        min = distance;
                    }
                }
            }
            return answers.Select(a => a + 1).ToArray();
        }

        static void Main(string[] args)
        {
            var V1 = ReadInts();
            int N = V1[0], M = V1[1];
            var tuples = new Tuple<int, int>[N + M - 1];
            for (int i = 0; i < N + M - 1; ++i)
            {
                var V2 = ReadInts();
                tuples[i] = new Tuple<int, int>(V2[0] - 1, V2[1] - 1);
            }
            foreach (var a in Solve(N, M, tuples))
            {
                Console.WriteLine(a);
            }
        }
    }
}

using System;
using System.Collections.Generic;
class Program
{
	static void Main(string[] args)
	{
		// 入力フェーズ
		string[] input = Console.ReadLine().Split(' ');
        int N = int.Parse(input[0]);
        int M = int.Parse(input[1]);

        // 辺の情報を取得して配列にする
        List<List<int> > saveGraph = new List<List<int> >();
				List<List<int> > parentGraph = new List<List<int> >();
				createGraph(N, M, ref saveGraph, ref parentGraph);// 保存用 最後に見る
				List<Tree> graph = copyGraph(saveGraph);

				// 各ノードを並び替えて順番をつける(葉ノードから番号を振る)
				int[] sortedNode = new int[N+1]; // [0]は使わない
				sortLeafToRoot(ref sortedNode, graph);

        // graphから出力用の表記を生成する
        int[] ret = output(sortedNode, parentGraph);

        //出力
        for (int i = 1; i <= N; i++)
        {
            Console.WriteLine(ret[i]);
        }
    }

		class Tree
		{
				public int nodeNo{set; get;}
				public List<int> children{set; get;}
		}

		static private List<Tree> copyGraph(List<List<int> > graph)
		{
			List<Tree> ret = new List<Tree>();
			for(int i=1; i<graph.Count; i++) // graph.Count = N+1
			{
				Tree t = new Tree();
				t.nodeNo = i;
				List<int> tt = new List<int>(graph[i]);
				t.children = tt;
				ret.Add(t);
			}

			return ret;
		}
		static private void sortLeafToRoot(ref int[] sortedNode, List<Tree> graph)
		{
			int cnt = 1;
			while(graph.Count > 0)
			{
					for(int i=0; i<graph.Count; i++)
					{
						//葉ノードだったらsotedNode[a(ノード番号)]に１から順番を振って番号を入れる
						List<int> delNode = new List<int>();
						if(graph[i].children.Count == 0)
						{
							int node = graph[i].nodeNo;
							sortedNode[node] = cnt++;
							delNode.Add(node);
							graph.RemoveAt(i);
						}

						// nodeを別の枝から削除する
						if(delNode.Count == 0) continue;
					  for(int j=0 ;j<graph.Count; j++)
						{
							for(int k=0; k<delNode.Count; k++)
							{
								if(graph[j].children.Contains(delNode[k]))
								{
									graph[j].children.Remove(delNode[k]);
								}
							}
						}
					}
			}
		}

    ///Ai→Biの表記から、各頂点と子供を管理するタイプの表記にする
    /// return List<int[]> ret
    /// ret[i] は i+1のノードから伸びている子供の番号を配列にして格納する
    static private void createGraph(int N, int M, ref List<List<int> > graph, ref List<List<int> > Pgraph)
    {
        // graphをN+1行にする
        for (int i = 0; i <= N; i++)
        {
            List<int> arr = new List<int>();
						List<int> arr2 = new List<int>();
            graph.Add(arr);
						Pgraph.Add(arr2);
        }

        for (int i = 0; i < N-1+M; i++)
        {
            string[] ab = Console.ReadLine().Split(' ');
            int a = int.Parse(ab[0]); // 親 1→1番目に格納する
            int b = int.Parse(ab[1]); // 子
            //Console.WriteLine(a + " " + b + " " + bars.GetLength(1));
            graph[a].Add(b);
						Pgraph[b].Add(a);
        }
    }

    /// graph表記から、出力できる形に変形する
    static private int[] output(int[] sortedNode, List<List<int>> graph)
    {
			// graph[i]にはiの親ノード番号が格納されている
        int N = graph.Count;
        int[] ret = new int[N];

        //Console.WriteLine(N);
        for (int i = 1; i <= N-1; i++)
        {
            //Console.WriteLine(i + " i" );
            List<int> parent = graph[i];
						// 親ノードのうち、sortedNodeを参照して一番小さい数字が格納されているものを親とする
						int[] minP = new int[]{0, sortedNode.Length};
            for (int j = 0; j < parent.Count; j++)
            {
                int parentNode = parent[j];
								int parentRank = sortedNode[parentNode];
                //Console.WriteLine(node + " node");
                if(minP[1] > parentRank)
								{
									minP[0] = parentNode;
									minP[1] = parentRank;
								}
            }
						ret[i] = minP[0];
        }
        return ret;
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

public class Solution
{
    public static void Main()
    {
        var vals = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
        var n = vals[0];
        var m = vals[1];
        var edges = n - 1 + m;
        var lower = Enumerable.Range(0, n + 1).Select(_ => new List<int>()).ToArray();
        var hasParent = new bool[n + 1];
        for (int i = 0; i < edges; i++)
        {
            vals = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
            var a = vals[0];
            var b = vals[1];
            lower[a].Add(b);
            hasParent[b] = true;
        }

        var root = Enumerable.Range(1, n).First(x => !hasParent[x]);
        var upper = new int[n + 1];
        var dist = new int[n + 1];

        var currnet = new List<int>() { root };
        int step = 0;
        while (currnet.Count > 0)
        {
            step++;
            var next = new List<int>();
            foreach (var cur in currnet)
            {
                foreach (var low in lower[cur])
                {
                    if (dist[low] < step)
                    {
                        dist[low] = step;
                        upper[low] = cur;
                        next.Add(low);
                    }
                }
                currnet = next;
            }
        }

        var answer = string.Join(Environment.NewLine, upper.Skip(1));
        Console.WriteLine(answer);
    }
}

