using System;
using System.Collections.Generic;
using System.Linq;

public class Solution
{
    static int[] Dist;
    static int Root;
    public static int GetDistance(int p, List<int>[] upper)
    {
        if (p == Root)
        {
            return 0;
        }

        if (Dist[p] == 0)
        {
            Dist[p] = upper[p].Max(u => GetDistance(u, upper)) + 1;
        }
        return Dist[p];
    }

    public static void Main()
    {
        var vals = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
        var n = vals[0];
        var m = vals[1];
        var edges = n - 1 + m;
        var upper = Enumerable.Range(0, n + 1).Select(_ => new List<int>()).ToArray();
        var hasParent = new bool[n + 1];
        for (int i = 0; i < edges; i++)
        {
            vals = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
            var a = vals[0];
            var b = vals[1];
            upper[b].Add(a);
            hasParent[b] = true;
        }

        Root = Enumerable.Range(1, n).First(x => !hasParent[x]);
        Dist = new int[n + 1];

        var parent = new int[n + 1];
        for (int i = 1; i <= n; i++)
        {
            if (i == Root)
            {
                parent[i] = 0;
            }
            else
            {
                parent[i] = upper[i].OrderByDescending(u => GetDistance(u, upper)).First();
            }
        }

