		public class ShortestPathProblem
		{
			/// <summary>
			/// 辺を隣接リストで持つ
			/// </summary>
			private Dictionary<int, int>[] edges;
			public int Size
			{
				get
				{
					return edges.Length;
				}
			}

			public int[] visited;

			public ShortestPathProblem(int n)
			{
				visited = (new int[n]).Select(x => x = -1).ToArray();
				edges = (new Dictionary<int, int>[n]).Select(e => new Dictionary<int, int>()).ToArray();
			}

			/// <summary>
			/// uからvへの重みwの有向辺を加える
			/// </summary>
			/// <param name="u"></param>
			/// <param name="v"></param>
			/// <param name="w"></param>
			public void addEdge(int u, int v, int w)
			{
				edges[u].Add(v, w);
			}

			/// <summary>
			/// uからvへの有向辺を削除する
			/// </summary>
			/// <param name="u"></param>
			/// <param name="v"></param>
			public void removeEdge(int u, int v)
			{
				edges[u].Remove(v);
			}

			/// <summary>
			/// sからtへのパスを求める
			/// </summary>
			/// <param name="s"></param>
			/// <param name="t"></param>
			/// <returns></returns>
			public void GetShortestPath(int s, int t)
			{
				var priorityQueue = new PriorityQueue<CurrentState>();
				priorityQueue.Push(new CurrentState(s, 0, s));
				while (priorityQueue.Length != 0)
				{
					var state = priorityQueue.Pop();
					visited[state.position] = state.previous;
					foreach (var e in edges[state.position])
					{
						priorityQueue.Push(new CurrentState(e.Key, state.weight + e.Value, state.position));
					}
				}
				//unsolved
				return;
			}

			public class CurrentState : IComparable
			{
				public CurrentState(int pos, int w, int pre = -1)
				{
					position = pos;
					weight = w;
					previous = pre;
				}
				public readonly int position;
				public readonly int weight;
				public readonly int previous;

				public int CompareTo(object obj)
				{
					return weight.CompareTo(((CurrentState)obj).weight);
				}
			}
		}


		public class PriorityQueue<T> where T : IComparable
		{
			#region member
			private List<T> list;
			private bool reverse;
			#endregion

			#region constructor
			/// <summary>
			/// 
			/// </summary>
			/// <param name="isReverse">定義された順序の逆で評価する</param>
			public PriorityQueue(bool isReverse = false)
			{
				list = new List<T>();
				reverse = isReverse;
			}
			#endregion

			#region private method
			private bool compare(T a, T b)
			{
				return reverse ^ a.CompareTo(b) > 0;
			}

			private void swap(int a, int b)
			{
				T tmp = list[a];
				list[a] = list[b];
				list[b] = tmp;
			}
			#endregion

			#region public method
			/// <summary>
			/// 要素を追加する
			/// </summary>
			/// <param name="item">追加する要素</param>
			public void Push(T item)
			{
				if (Length < list.Count) list[Length] = item;
				else list.Add(item);
				var pos = Length++;
				while (pos != 0)
				{
					var parent = (pos + 1) / 2 - 1;
					if (compare(list[pos], list[parent])) break;
					swap(pos, parent);
					pos = parent;
				}
			}

			/// <summary>
			/// 要素を追加する
			/// </summary>
			/// <param name="items">追加する要素の列</param>
			public void Push(IEnumerable<T> items)
			{
				foreach (var item in items)
				{
					Push(item);
				}
			}

			/// <summary>
			/// 値を確認する
			/// </summary>
			/// <returns></returns>
			public T Peek()
			{
				return list[0];
			}

			/// <summary>
			/// 値を取り出す
			/// </summary>
			/// <returns></returns>
			public T Pop()
			{
				var ret = Peek();
				var pos = 0;
				list[0] = list[--Length];
				while (2 * pos + 1 < Length)
				{
					var child = 2 * pos + 1;
					var child_other = 2 * pos + 2;
					if (child_other < Length && compare(list[child], list[child_other]))
					{
						child = child_other;
					}
					if (compare(list[child], list[pos])) break;
					swap(pos, child);
					pos = child;
				}
				return ret;
			}

			/// <summary>
			/// クリアする
			/// </summary>
			public void Clear()
			{
				list.Clear();
			}

			/// <summary>
			/// 空かを返す
			/// </summary>
			/// <returns></returns>
			public bool Empty()
			{
				return Length == 0;
			}
			#endregion

			#region property
			/// <summary>
			/// 要素の長さを取得する
			/// </summary>
			public int Length
			{
				get;
				private set;
			}
			#endregion
		}
	}
}

using System;
using System.Collections.Generic;
class Program
{
	static void Main(string[] args)
	{
		// 入力フェーズ
		string[] input = Console.ReadLine().Split(' ');
        int N = int.Parse(input[0]);
        int M = int.Parse(input[1]);

        // 辺の情報を取得して配列にする
        List<List<int> > saveGraph = new List<List<int> >();
				List<List<int> > parentGraph = new List<List<int> >();
				createGraph(N, M, ref saveGraph, ref parentGraph);// 保存用 最後に見る
				List<Tree> graph = copyGraph(saveGraph);

				// 各ノードを並び替えて順番をつける(葉ノードから番号を振る)
				int[] sortedNode = new int[N+1]; // [0]は使わない
				sortLeafToRoot(ref sortedNode, graph);

        // graphから出力用の表記を生成する
        int[] ret = output(sortedNode, parentGraph);

        //出力
        for (int i = 1; i <= N; i++)
        {
            Console.WriteLine(ret[i]);
        }
    }

		class Tree
		{
				public int nodeNo{set; get;}
				public List<int> children{set; get;}
		}

		static private List<Tree> copyGraph(List<List<int> > graph)
		{
			List<Tree> ret = new List<Tree>();
			for(int i=1; i<graph.Count; i++) // graph.Count = N+1
			{
				Tree t = new Tree();
				t.nodeNo = i;
				List<int> tt = new List<int>(graph[i]);
				t.children = tt;
				ret.Add(t);
			}

			return ret;
		}
		static private void sortLeafToRoot(ref int[] sortedNode, List<Tree> graph)
		{
			int cnt = 1;
			while(graph.Count > 0)
			{
					for(int i=0; i<graph.Count; i++)
					{
						//葉ノードだったらsotedNode[a(ノード番号)]に１から順番を振って番号を入れる
						List<int> delNode = new List<int>();
						if(graph[i].children.Count == 0)
						{
							int node = graph[i].nodeNo;
							sortedNode[node] = cnt++;
							delNode.Add(node);
							graph.RemoveAt(i);
						}

						// nodeを別の枝から削除する
						if(delNode.Count == 0) continue;
					  for(int j=0 ;j<graph.Count; j++)
						{
							for(int k=0; k<delNode.Count; k++)
							{
								if(graph[j].children.Contains(delNode[k]))
								{
									graph[j].children.Remove(delNode[k]));
								}
							}
						}
					}
			}
		}

    ///Ai→Biの表記から、各頂点と子供を管理するタイプの表記にする
    /// return List<int[]> ret
    /// ret[i] は i+1のノードから伸びている子供の番号を配列にして格納する
    static private void createGraph(int N, int M, ref List<List<int> > graph, ref List<List<int> > Pgraph)
    {
        // graphをN+1行にする
        for (int i = 0; i <= N; i++)
        {
            List<int> arr = new List<int>();
						List<int> arr2 = new List<int>();
            graph.Add(arr);
						Pgraph.Add(arr2);
        }

        for (int i = 0; i < N-1+M; i++)
        {
            string[] ab = Console.ReadLine().Split(' ');
            int a = int.Parse(ab[0]); // 親 1→1番目に格納する
            int b = int.Parse(ab[1]); // 子
            //Console.WriteLine(a + " " + b + " " + bars.GetLength(1));
            graph[a].Add(b);
						Pgraph[b].Add(a);
        }
    }

    /// graph表記から、出力できる形に変形する
    static private int[] output(int[] sortedNode, List<List<int>> graph)
    {
			// graph[i]にはiの親ノード番号が格納されている
        int N = graph.Count;
        int[] ret = new int[N];

        //Console.WriteLine(N);
        for (int i = 1; i <= N-1; i++)
        {
            //Console.WriteLine(i + " i" );
            List<int> parent = graph[i];
						// 親ノードのうち、sortedNodeを参照して一番小さい数字が格納されているものを親とする
						int[] minP = new int[]{0, sortedNode.Length};
            for (int j = 0; j < parent.Count; j++)
            {
                int parentNode = parent[j];
								int parentRank = sortedNode[parentNode];
                //Console.WriteLine(node + " node");
                if(minP[1] > parentRank)
								{
									minP[0] = parentNode;
									minP[1] = parentRank;
								}
            }
						ret[i] = minP[0];
        }
        return ret;
    }
}

