                            continue;
                        }
                        P[v] = u;
                        F[v] = F[u] + 1;

                        A.Enqueue(v);
                        B.Enqueue(u);
                    }
                }

                break;
            }
        }

        for (int i = 0; i < N; i++)
        {
            WriteLine(P[i] + 1);
        }
    }

}

