namespace AtCoder
{
    class Program
    {
        static void Main(string[] args)
        {
            new Program().Solve(new ConsoleInput(Console.In, ' '));
#if DEBUG
            ReadLine();
#endif
        }

        public class Node
        {
            public int id;
            public List<int> parents;
            public List<int> children;
            public int level;

            public Node(int id)
            {
                this.id = id;
                this.parents = new List<int>();
                this.children = new List<int>();
                this.level = -1;
            }
        }



        void Solve(ConsoleInput cin)
        {
            int n = cin.ReadInt;
            int m = cin.ReadInt;
            List<Node> graph = new List<Node>();

            for (int i = 0; i < n; i++)
            {
                graph.Add(new Node(i));
            }

            for (int i = 0; i < n - 1 + m; i++)
            {
                int a = cin.ReadInt - 1;
                int b = cin.ReadInt - 1;

                graph[a].children.Add(b);
                graph[b].parents.Add(a);
            }

            // 親を見つける
            int[] parents = new int[n];
            int idParent = 0;
            while (graph[idParent].parents.Count() > 0)
            {
                idParent = graph[idParent].parents[0];
            }

            graph[idParent].level = 0;
            Queue<int> queue = new Queue<int>();
            queue.Enqueue(idParent);

            while (queue.Count() > 0)
            {
                int id = queue.Dequeue();

                foreach (int child in graph[id].children)
                {
                    graph[child].parents.Remove(id);
                    if(graph[child].parents.Count == 0)
                    {
                        parents[child] = id + 1;
                        queue.Enqueue(child);
                    }
                }
            }

            for (int i = 0; i < n; i++)
            {
                Console.WriteLine(parents[i]);
            }
        }

        class ConsoleInput
        {
            private readonly System.IO.TextReader _stream;
            private char _separator = ' ';
            private Queue<string> inputStream;

            public ConsoleInput(System.IO.TextReader stream, char separator = ' ')
            {
                this._separator = separator;
                this._stream = stream;
                inputStream = new Queue<string>();
            }

            public string Read
            {
                get
                {
                    if (inputStream.Count != 0) return inputStream.Dequeue();
                    string[] tmp = _stream.ReadLine().Split(_separator);
                    for (int i = 0; i < tmp.Length; ++i)
                        inputStream.Enqueue(tmp[i]);
                    return inputStream.Dequeue();
                }
            }

            public string ReadLine { get { return _stream.ReadLine(); } }
            public int ReadInt { get { return int.Parse(Read); } }
            public long ReadLong { get { return long.Parse(Read); } }
            public double ReadDouble { get { return double.Parse(Read); } }
            public string[] ReadStrArray(long N) { var ret = new string[N]; for (long i = 0; i < N; ++i) ret[i] = Read; return ret; }
            public int[] ReadIntArray(long N) { var ret = new int[N]; for (long i = 0; i < N; ++i) ret[i] = ReadInt; return ret; }
            public long[] ReadLongArray(long N) { var ret = new long[N]; for (long i = 0; i < N; ++i) ret[i] = ReadLong; return ret; }
        }
    }
}

using System;
using System.Collections.Generic;
class Program
{
	static void Main(string[] args)
	{
		// 入力フェーズ
		string[] input = Console.ReadLine().Split(' ');
        int N = int.Parse(input[0]);
        int M = int.Parse(input[1]);

		// N-1+M行 辺の情報が来る
        int[,] bars = new int[2,N-1+M];
        for (int i = 0; i < N - 1 + M; i++)
        {
            string[] ab = Console.ReadLine().Split(' ');
            int a = int.Parse(ab[0]);
            int b = int.Parse(ab[1]);
            bars[0, i] = a;
            bars[1, i] = b;
        }

        //Console.WriteLine(bars[0,0] + " " + bars[1, 0]);
        // グラフを頂点の数*？の配列に直す
        List<List<int> > graph = createGraph(bars, N);

        for (int i = 0; i < graph.Count; i++)
        {
            string str = i + " 番目ノード";
            List<int> child = graph[i];
            for (int j = 0; j < child.Count; j++)
            {
                //Console.WriteLine(i + " " + j + " count " + child.Count);
                str += graph[i][j] + " ";
            }
            //Console.WriteLine(str);
        }
        // 各辺について、削除できるか検証する
        // 削除可能→子ノードを0に更新
        deleteBars(ref graph, M);

        //Console.WriteLine(" AAAA");
        // graphから出力用の表記を生成する
        int[] ret = output(graph);
        //Console.WriteLine(" BBBB");
        //出力
        for (int i = 0; i < N; i++)
        {
            Console.WriteLine(ret[i]);
        }
    }

    ///Ai→Biの表記から、各頂点と子供を管理するタイプの表記にする
    /// return List<int[]> ret
    /// ret[i] は i+1のノードから伸びている子供の番号を配列にして格納する
    static private List<List<int> > createGraph(int[,] bars, int N)
    {
        List<List<int>> graph = new List<List<int> >();

        // graphをN行にする
        //Console.WriteLine(graph.Count);
        for (int i = 0; i < N; i++)
        {
            List<int> arr = new List<int>();
            graph.Add(arr);
        }

        //Console.WriteLine(graph.Count);
        for (int i = 0; i < bars.GetLength(1); i++)
        {
            int a = bars[0, i]; // 親 1→0番目に格納する※ズレる
            int b = bars[1, i]; // 子
            //Console.WriteLine(a + " " + b + " " + bars.GetLength(1));
            graph[a-1].Add(b);
        }
        //Console.WriteLine(graph.Count);
        return graph;
    }

    /// たとえば1→2という有向線があったとき、この線を使わずに1から2にたどり着ければ、
    /// 1→2は削除できるので削除する
    /// というのを全ての辺、またはM本削除するまで繰り返す
    static private void deleteBars(ref List<List<int>> graph, int M)
    {
        for (int i = 0; i < graph.Count; i++)
        {
            if (M == 0)
            {
                // 検証終わり
                break;
            }
            List<int> child = graph[i];
            for (int j = 0; j < child.Count; j++)
            {
                if (M == 0)
                {
                    // 検証終わり
                    break;
                }
                // i 親ノード番号
                // child[j] 子ノード番号（今回検証する）
                //Console.WriteLine("検証 " + i + " " + child[j]);
                if(isEnableDetour(graph, i, child[j], true))
                {
                    //Console.WriteLine("デリート " + i + " " + child[j]);
                    graph[i][j] = 0; // デリートすると順番ずれるしめんどい
                    M--;
                }
            }
        }
    }

    /// graphを使って、iからchild[j]まで、i→child[j]を使わずに迂回できたら削除できる(true)
    /// isTop = trueのときだけゴールじゃない
    static private bool isEnableDetour(List<List<int>> graph, int start, int goal, bool isTop)
    {
        if (!isTop && graph[start].Contains(goal))
        {
            // 一回目じゃないときで、startノードの子にgoalノードがあれば迂回成功
            return true;
        }
        else
        {
            List<int> child = graph[start];
            // 一回目のときは、goal以外のノードから迂回ルートを探すようにする
            for (int i = 0; i < child.Count; i++)
            {                
                if (isTop && child[i] == goal) continue;
                //Console.WriteLine("検証2 " + (child[i] - 1) + " " + goal);
                if ((child[i] - 1) >= 0 && isEnableDetour(graph, child[i] - 1, goal, false)) // 親ノード番号にするときは添え字にあわせる
                {
                    return true;
                }
            }
        }

        // 葉ノードに到達しちゃったら迂回失敗を返す
        return false;
    }

    /// graph表記から、出力できる形に変形する
    static private int[] output(List<List<int>> graph)
    {
        int N = graph.Count;
        int[] ret = new int[N];

        //Console.WriteLine(N);
        for (int i = 0; i < N; i++)
        {
            //Console.WriteLine(i + " i" );
            List<int> child = graph[i];
            //Console.WriteLine(child.Count+ " c");
            for (int j = 0; j < child.Count; j++)
            {
                int node = child[j]; // 子ノード, i=親ノード番号
                //Console.WriteLine(node + " node");
                if (node == 0) continue; // 0は削除済み
                ret[node - 1] = i + 1;
            }
        }
        return ret;
    }
}

