            }

            foreach (Tree t in trees)
            {
                t.TreeDepth();
                Console.WriteLine(t.parent);
            }

            Console.ReadLine();
        }

        public class Tree
        {
            public static Tree[] trees;

            public int depth;
            public int index;
            public bool done;
            public int parent;
            public List<int> parentList;

            public Tree(int index)
            {
                this.index = index;
                this.parentList = new List<int>();
            }

            public int TreeDepth()
            {
                if (this.done) return this.depth;
                if (this.parentList.Count == 0) return 0;

                foreach (int t in this.parentList)
                {
                    int d = trees[t].TreeDepth() + 1;
                    if(this.depth < d)
                    {
                        this.depth = d;
                        this.parent = (t + 1);
                    }
                }

                this.done = true;

                return this.depth;
            }
        }
    }

}

