    class BellmanFord
    {
        public List<Edge> Edges { get; set; }
        public int V { get; set; }
        public long[] Distances { get; set; }
        public bool[] Negative { get; set; }
        public BellmanFord(int v)
        {
            this.V = v;
            this.Edges = new List<Edge>();
        }

        public void Add(int from, int to, int cost)
        {
            this.Edges.Add(new Edge(from, to, cost));
        }

        public void CalcDistance(int start)
        {
            this.Distances = new long[V];
            for (int i = 0; i < V; i++)
            {
                this.Distances[i] = long.MaxValue;
            }
            this.Distances[start] = 0;

            for (int i = 0; i < this.V; i++)
            {
                foreach (var e in this.Edges)
                {
                    if (this.Distances[e.From] == long.MaxValue) continue;
                    var cost = this.Distances[e.From] + e.Cost;
                    if (cost < this.Distances[e.To])
                    {
                        this.Distances[e.To] = cost;
                    }
                }
            }

            this.Negative = new bool[V];
            for (int i = 0; i < this.V; i++)
            {
                foreach (var e in this.Edges)
                {
                    if (this.Distances[e.From] == long.MaxValue) continue;
                    var cost = this.Distances[e.From] + e.Cost;
                    if (cost < this.Distances[e.To])
                    {
                        this.Distances[e.To] = cost;
                        this.Negative[e.To] = true;
                    }
                }
            }
        }
        public struct Edge
        {
            public int From { get; set; }
            public int To { get; set; }
            public int Cost { get; set; }
            public Edge(int from, int to, int cost)
            {
                this.From = from;
                this.To = to;
                this.Cost = cost;
            }
        }
    }
    class Dijkstra
    {
        public int V { get; set; }
        public int E { get; set; }
        public List<Edge>[] G { get; set; }
        public bool Directed { get; set; }
        public Dijkstra(int n, bool directed = false)
        {
            this.V = n;
            this.Directed = directed;
            this.G = new List<Edge>[V];
            for (int i = 0; i < V; i++)
            {
                this.G[i] = new List<Edge>();
            }
        }
        public void Add(int a, int b, long cost = 1)
        {
            this.G[a].Add(new Edge(b, cost));
            if (!this.Directed) this.G[b].Add(new Edge(a, cost));
            this.E++;
        }
        public long GetMinCost(int start, int goal)
        {
            var cost = new long[V];
            for (int i = 0; i < V; i++) cost[i] = long.MaxValue;
            cost[start] = 0;

            var capacity = Math.Max(1, E);
            var q = new PriorityQueue<P>(capacity, false);
            q.Enqueue(new P(start, 0));

            while (q.Count > 0)
            {
                var p = q.Dequeue();
                if (p.Cost != cost[p.A]) continue;
                foreach (var e in this.G[p.A])
                {
                    if (cost[e.To] > p.Cost + e.Cost)
                    {
                        cost[e.To] = p.Cost + e.Cost;
                        q.Enqueue(new P(e.To, cost[e.To]));
                    }
                }
            }
            return cost[goal] == long.MaxValue ? -1 : cost[goal];
        }
        public long[] Calc(int start)
        {
            var cost = new long[V];
            for (int i = 0; i < V; i++) cost[i] = long.MaxValue;
            cost[start] = 0;

            var capacity = Math.Max(1, E);
            var q = new PriorityQueue<P>(capacity, false);
            q.Enqueue(new P(start, 0));

            while (q.Count > 0)
            {
                var p = q.Dequeue();
                if (p.Cost != cost[p.A]) continue;
                foreach (var e in this.G[p.A])
                {
                    if (cost[e.To] > p.Cost + e.Cost)
                    {
                        cost[e.To] = p.Cost + e.Cost;
                        q.Enqueue(new P(e.To, cost[e.To]));
                    }
                }
            }
            return cost;
        }
        public struct Edge
        {
            public int To;
            public long Cost;
            public Edge(int to, long cost)
            {
                this.To = to;
                this.Cost = cost;
            }
        }
        public struct P : IComparable<P>
        {
            public int A;
            public long Cost;
            public P(int a, long cost)
            {
                this.A = a;
                this.Cost = cost;
            }
            public int CompareTo(P other)
            {
                return this.Cost.CompareTo(other.Cost);
            }
        }
    }
    class PriorityQueue<T>
    {
        public readonly T[] Array;
        public readonly bool Greater;
        public int Count { get; private set; } = 0;
        private IComparer<T> Cmp;
        public PriorityQueue(int capacity, bool greater = true, IComparer<T> cmp = null)
        {
            this.Cmp = cmp;
            if (cmp == null)
            {
                this.Cmp = Comparer<T>.Default;
            }
            this.Array = new T[capacity];
            this.Greater = greater;
        }
        public void Enqueue(T item)
        {
            this.Array[this.Count] = item;
            this.Count += 1;
            this.UpHeap();
        }
        public T Dequeue()
        {
            this.Swap(0, this.Count - 1);
            this.Count -= 1;
            this.DownHeap();

            return this.Array[this.Count];
        }
        public T Peek()
        {
            return this.Array[0];
        }
        private void UpHeap()
        {
            var n = this.Count - 1;
            while (n != 0)
            {
                var parent = (n - 1) / 2;

                if (this.Compare(this.Array[n], this.Array[parent]) > 0)
                {
                    this.Swap(n, parent);
                    n = parent;
                }
                else
                {
                    break;
                }
            }
        }
        private void DownHeap()
        {
            var parent = 0;
            while (true)
            {
                var child = 2 * parent + 1;
                if (child > this.Count - 1) break;

                if (child < this.Count - 1 && this.Compare(this.Array[child], this.Array[child + 1]) < 0)
                {
                    child += 1;
                }
                if (this.Compare(this.Array[parent], this.Array[child]) < 0)
                {
                    this.Swap(parent, child);
                    parent = child;
                }
                else
                {
                    break;
                }
            }
        }
        private int Compare(T a, T b)
        {
            var c = this.Cmp.Compare(a, b);
            if (!this.Greater)
            {
                c = -c;
            }
            return c;
        }
        private void Swap(int a, int b)
        {
            var tmp = this.Array[a];
            this.Array[a] = this.Array[b];
            this.Array[b] = tmp;
        }
    }
