namespace Competitive
{
    internal class Solution
    {
        public int N, _M, M;
        public Graph G;
        public void Run()
        {
            // Input
            {
                var line = Input.ReadIntArray();
                N = line[0];
                _M = line[1];
                M = N - 1 + _M;
            }

            // Graph
            G = new Graph(N);
            for (int i = 0; i < M; i++)
            {
                var line = Input.ReadIntArray();
                int u = line[0] - 1;
                int v = line[1] - 1;
                // 無向グラフ
                var e1 = new Edge(u, v, 0);
                G[u].Edges.Add(e1);
                G[v].InEdges.Add(e1);
                G[v].InCount++;
            }

            // トポロジカルソート
            Queue<int> q = new Queue<int>();
            for (int i = 0; i < N; i++)
            {
                if(G[i].InCount == 0) q.Enqueue(i);
            }

            List<int> topo = new List<int>();
            while (q.Count > 0)
            {
                int i = q.Dequeue();
                topo.Add(i);

                foreach (var e in G[i].Edges)
                {
                    G[e.To].InCount--;
                    if(G[e.To].InCount == 0) q.Enqueue(e.To);
                }
            }

            // argsort
            // argsはインデックスがトポロジカルソートの何番目かを表す
            int[] args = new int[N];
            for (int i = 0; i < N; i++)
            {
                args[topo[i]] = i;
            }

            // 2つある場合、一番下が親でいい
            for (int i = 0; i < N; i++)
            {
                var n = G[i];
                if (G[i].InEdges.Count == 0)
                {
                    Console.WriteLine(0);
                }
                else
                {
                    // argsが最も大きいfromをとる, +1する
                    int amax = -1;
                    int p = -1;
                    foreach (var e in n.InEdges)
                    {
                        int a = args[e.From];
                        if (a > amax)
                        {
                            amax = a;
                            p = e.From;
                        }
                    }
                    Console.WriteLine(p + 1);
                }
            }
        }

    }

    internal class Graph
    {
        public List<Node> Nodes;

        public Node this[int i]
        {
            set { Nodes[i] = value; }
            get { return Nodes[i]; }
        }

        public Graph(int N)
        {
            Nodes = new List<Node>();
            for (int i = 0; i < N; i++)
            {
                Nodes.Add(new Node(i));
            }
        }

    }

    internal class Node
    {
        public List<Edge> Edges;
        public List<Edge> InEdges;
        public int Dist;
        public int No;
        public int InCount = 0;

        public Node(int no)
        {
            this.No = no;
            Dist = int.MaxValue;
            Edges = new List<Edge>();
            InEdges = new List<Edge>();
            InCount = 0;
        }
    }

    internal class Edge
    {
        public int From;
        public int To;
        public int Cost;
        public Edge Rev;

        public Edge(int fr, int to, int cost = 0)
        {
            From = fr;
            To = to;
            Cost = cost;
        }

        public bool IsRev(Edge e)
        {
            return Rev != null && (e == Rev);
        }
    }


