using System;
using System.Collections.Generic;

public class Program
{
    private int N, M;
    private List<int>[] To;
    private HashSet<int>[] From;

    private int[] Ans;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        M = sc.NextInt();
        To = new List<int>[N];
        From = new HashSet<int>[N];
        for (int i = 0; i < N; i++)
        {
            To[i] = new List<int>();
            From[i] = new HashSet<int>();
        }

        for (int i = 0; i < N - 1 + M; i++)
        {
            int a = sc.NextInt() - 1;
            int b = sc.NextInt() - 1;
            To[a].Add(b);
            From[b].Add(a);
        }

        Ans = new int[N];

        int root;

        // 追加される辺は祖先->子孫
        // 元の辺も親->子
        // fromが一個も無いのが根

        for (root = 0; root < N; root++)
        {
            if (From[root].Count == 0) break;
        }

        Ans[root] = 0;

        Search(root);

        Console.WriteLine(string.Join("\n", Ans));
    }


    void Search(int n)
    {
        foreach (var i in To[n])
        {
            // 辺n->iが追加された辺?
            // iに元の辺と追加された辺が生えてる
            // from[i]が2以上ならtrue n->iを消す
            if (From[i].Count > 1)
            {
                //Console.WriteLine($"{n} {i}");
                From[i].Remove(n);
            }
        }

        foreach (int i in To[n])
        {
            if (!From[i].Contains(n))
            {
                continue;
            }

            Ans[i] = n + 1;
            Search(i);
        }
    }


    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

class Scanner
{
    public Scanner()
    {
        _pos = 0;
        _line = new string[0];
    }

    const char Separator = ' ';
    private int _pos;
    private string[] _line;

    #region スペース区切りで取得

    public string Next()
    {
        if (_pos >= _line.Length)
        {
            _line = Console.ReadLine().Split(Separator);
            _pos = 0;
        }

        return _line[_pos++];
    }

    public int NextInt()
    {
        return int.Parse(Next());
    }

    public long NextLong()
    {
        return long.Parse(Next());
    }

    public double NextDouble()
    {
        return double.Parse(Next());
    }

    #endregion

    #region 型変換

    private int[] ToIntArray(string[] array)
    {
        var result = new int[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = int.Parse(array[i]);
        }

        return result;
    }

    private long[] ToLongArray(string[] array)
    {
        var result = new long[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = long.Parse(array[i]);
        }

        return result;
    }

    private double[] ToDoubleArray(string[] array)
    {
        var result = new double[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = double.Parse(array[i]);
        }

        return result;
    }

    #endregion

    #region 配列取得

    public string[] Array()
    {
        if (_pos >= _line.Length)
            _line = Console.ReadLine().Split(Separator);

        _pos = _line.Length;
        return _line;
    }

    public int[] IntArray()
    {
        return ToIntArray(Array());
    }

    public long[] LongArray()
    {
        return ToLongArray(Array());
    }

    public double[] DoubleArray()
    {
        return ToDoubleArray(Array());
    }

    #endregion
}

