        for (int i = 0; i < n; i++)
        {
            edge[i] = new List<int>();
        }
        for (int i = 0; i < n - 1 + m; i++)
        {
            int a, b;
            sc.Multi(out a, out b);
            edge[a - 1].Add(b - 1);
            ++rc[b - 1];
