public class Solver
{
	public void Solve()
	{
		int N = GetInt();
		int M = GetInt();
		var adj = Enumerable.Range(0, N).Select(_ => new List<int>()).ToArray();
		for(int i = 0; i < N - 1 + M; i++)
		{
			int A = GetInt() - 1;
			int B = GetInt() - 1;
			adj[A].Add(B);
		}

		var tpl = tplSort(adj);
		int[] p = new int[N];
		for(int i = 0; i < N; i++)
		{
			int v = tpl[i];
			foreach(int u in adj[v])
				p[u] = v + 1;		
		}

		Console.WriteLine(string.Join("\n", p.Select(x => x.ToString()).ToArray()));
	}

	private List<int> tplSort(List<int>[] adj)
	{
		int N = adj.Length;
		int[] deg = new int[N];
		for(int v = 0; v < N; v++)
		{
			foreach(int u in adj[v])
				deg[u]++;
		}

		var res = new List<int>();
		var queue = new Queue<int>();
		for(int v = 0; v < N; v++)
			if(deg[v] == 0)
				queue.Enqueue(v);

		while(queue.Count > 0)
		{
			int v = queue.Dequeue();
			res.Add(v);
			foreach(int u in adj[v])
			{
				deg[u]--;
				if(deg[u] == 0)
					queue.Enqueue(u);
			}
		}

		return res;
	}
}


