}
public class Pq<T> where T:IComparable{
	private T[] he;
	public int count=0;
	public Pq(int max){he=new T[max];}
	public void Push(T x){
		int j=count;
		while(j!=0&&Compare(x,he[(j-1)/2])>0){he[j]=he[(j-1)/2];j=(j-1)/2;}
		he[j]=x;
		count++;
	}
	public void Pop(){
		count--;
		T r=he[count];
		int j=0;
		while(true){
			if(j*2+1<count){
				if(Compare(he[j*2+1],he[j*2+2])>0){j=j*2+1;}
				else{j=j*2+2;}
			}
			else if(j*2<count){j=j*2+1;}
			else{break;}
			if(Compare(he[j],r)<=0){j=(j-1)/2;break;}
			he[(j-1)/2]=he[j];
		}
		he[j]=r;
	}
	private int Compare(T x,T y){return y.CompareTo(x);}
	public int Count(){return count;}
	public T Top(){return he[0];}
}

