namespace AtCoder
{
    class Program
    {
        private static string Read() { return Console.ReadLine(); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }

        static int[] Solve(int N, int M, Tuple<int, int>[] tuples)
        {
            var parents = new List<int>[N];
            var children = new List<int>[N];
            for (int i = 0; i < N; ++i)
            {
                parents[i] = new List<int>();
                children[i] = new List<int>();
            }
            foreach (var tuple in tuples)
            {
                parents[tuple.Item2].Add(tuple.Item1);
                children[tuple.Item1].Add(tuple.Item2);
            }
            var root = 0;
            while (parents[root].Count > 0) { root = parents[root][0]; }
            var distances = new int[N];
            var queue = new Queue<int>();
            queue.Enqueue(root);
            while (queue.Count > 0)
            {
                var parent = queue.Dequeue();
                foreach (var child in children[parent])
                {
                    if (distances[child] < distances[parent] + 1)
                    {
                        distances[child] = distances[parent] + 1;
                        queue.Enqueue(child);
                    }
                }
            }
            var answers = Enumerable.Repeat(-1, N).ToArray();
            for (int i = 0; i < N; ++i)
            {
                int min = -1;
                foreach (var parent in parents[i])
                {
                    if (distances[parent] > min)
                    {
                        answers[i] = parent;
                        min = distances[parent];
                    }
                }
            }
            return answers.Select(a => a + 1).ToArray();
        }

        static void Main(string[] args)
        {
            var V1 = ReadInts();
            int N = V1[0], M = V1[1];
            var tuples = new Tuple<int, int>[N + M - 1];
            for (int i = 0; i < N + M - 1; ++i)
            {
                var V2 = ReadInts();
                tuples[i] = new Tuple<int, int>(V2[0] - 1, V2[1] - 1);
            }
            foreach (var a in Solve(N, M, tuples))
            {
                Console.WriteLine(a);
            }
        }
    }
}

