            {
                Console.WriteLine(t.parent);
            }

            Console.ReadLine();
        }

        public class Tree
        {
            public static Tree[] trees;

            public int depth;
            public int index;
            public bool isOrigin;
            public int parent;
            public List<int> childs;

            public Tree(int index)
            {
                this.index = index;
                this.isOrigin = true;
                this.childs = new List<int>();
            }

            public void Next()
            {
                int d = this.depth + 1;
                foreach (int i in this.childs)
                {
                    if(d > trees[i].depth)
                    {
                        trees[i].depth = d;
                        trees[i].parent = (this.index + 1);
                        trees[i].Next();
                    }
                }
            }
        }
    }

}

