class Topological
{
    public List<Edge>[] Dag { get; set; }
    public int[] CountIn { get; set; }
    public int N { get; set; }
    public Topological(int n)
    {
        this.N = n;
        this.Dag = new List<Edge>[n];
        for (int i = 0; i < n; i++)
        {
            this.Dag[i] = new List<Edge>();
        }
        this.CountIn = new int[n];
    }
    public void Add(int a, int b, long cost)
    {
        this.Dag[a].Add(new Edge(b, cost));
        this.CountIn[b]++;
    }
    public int[] Sort(int start)
    {
        int[] countIn = new int[N];
        for (int i = 0; i < N; i++) countIn[i] = this.CountIn[i];

        var q = new Queue<int>();
        q.Enqueue(start);
        var list = new List<int>();
        while (q.Count > 0)
        {
            var now = q.Dequeue();
            list.Add(now);
            foreach (var e in this.Dag[now])
            {
                countIn[e.To]--;
                if (countIn[e.To] == 0) q.Enqueue(e.To);
            }
        }
        return list.ToArray();
    }
    public long[] GetMinCost(int start)
    {
        var sorted = this.Sort(start);
        var dist = new long[this.N];
        for (int i = 0; i < N; i++)
        {
            dist[i] = int.MaxValue;
        }
        dist[start] = 0;
        for (int i = 0; i < N - 1; i++)
        {
            var now = sorted[i];
            foreach (var e in Dag[now])
            {
                dist[e.To] = Math.Min(dist[e.To], dist[now] + e.Cost);
            }
        }
        return dist;
    }
    public struct Edge
    {
        public int To { get; set; }
        public long Cost { get; set; }
        public Edge(int to, long cost)
        {
            this.To = to;
            this.Cost = cost;
        }
    }
}

