            int[] Key;
            List<Edge> edges = new List<Edge>();
            for (int i = 0; i < n; i++) {
                Key = getKeys(' ');
                edges.Add(new Edge(Key[0], Key[1]));
            }
            return edges;
        }

        static void Main() {
            var Key = getKeys(' ');
            var nodes = new int[Key[0]];
            for (int i = 0; i < nodes.Length; i++) {
                nodes[i] = i + 1;
            }
            var edges = getEdge(Key[0] + Key[1] - 1);
            var Copy = new List<Edge>();
            //答えを格納する配列と、入力辺を持たない頂点配列の2つを用意する。
            List<int> Sorted = new List<int>();
            List<Edge> SortedEdge = new List<Edge>();
            List<int> Roots = nodes.Except(edges.Select(x => x.To).Distinct()).ToList();
            while (Roots.Count > 0) {
                int n = Roots.First();
                Roots.Remove(n);
                Sorted.Add(n);
                //取り出したNode nから伸びる辺をリストアップ。
                var Outs = edges.Where(x => x.From == n).ToArray();
                //その辺が行き着くNodeについて考える。
                for (int i = 0; i < Outs.Length; i++) {
                    int to = Outs[i].To;
                    edges.Remove(Outs[i]);
                    Copy.Add(Outs[i]);
                    //もしそのNodeが他に入力辺を持たないなら、Rootに追加する。
                    if (edges.Where(x => x.To == to).Count() == 0) { Roots.Add(to); SortedEdge.Add(Outs[i]); }
                }
            }
            if (edges.Count > 0) {
                Console.WriteLine("閉路を検出しました。");
                return;
            }
//            Show(Sorted);
//            Show(SortedEdge);
            SortedEdge.Sort((x, y) => x.To - y.To);
            int[] Answer = new int[nodes.Length];
            for (int i = 0; i < SortedEdge.Count; i++) {
                Answer[SortedEdge[i].To - 1] = SortedEdge[i].From;
            }
            foreach (var item in Answer) {
                Console.WriteLine(item);
            }
        }

