using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace Atcoder
{
    class vertices
    {
        public int number;
        public List<vertices> children= null;
        public List<vertices> parents = null;
        public int depth;
        public vertices()
        {
            this.depth = 0;
            this.number = 0;
            this.children = new List<vertices>();
            this.parents = new List<vertices>();
        }

    }


    class Program
    {
        static void Main(string[] argsv)
        {
            var split = Console.ReadLine().Split();
            int N = int.Parse(split[0]);
            int M = int.Parse(split[1]);
            vertices[] vertices = new Atcoder.vertices[N];
            for (int i = 0; i < N; i++)
            {
                vertices[i] = new Atcoder.vertices();
                vertices[i].number = i+1;
            }
            int[] candidate_root = new int[N];
            for (int i = 0; i < N + M - 1; i++)
            {
                split = Console.ReadLine().Split();
                int A = int.Parse(split[0]);
                int B = int.Parse(split[1]);
                vertices[A - 1].children.Add(vertices[B - 1]);
                vertices[B - 1].parents.Add(vertices[A - 1]);
                candidate_root[B - 1] = 1;

            }
            ;
            int ignore = 0;
            for (int i = 0; i < candidate_root.Length; i++)
            {
                if (candidate_root[i] == 1) continue;

                Queue<int> queue = new Queue<int>();
                queue.Enqueue(i);

                while (queue.Count != 0)
                {
                    int task = queue.Dequeue();
                    for (int j = 0; j < vertices[task].children.Count; j++)
                    {
                        if (vertices[task].children[j].depth!= 0)
                        {
                            ignore++;
                            vertices[task].children[j].parents = vertices[task].children[j].parents.Where(x => x.number != task).ToList();
                            vertices[task].children.RemoveAt(j);
                            j--;
                            continue;
                        }
                        else
                        {
                            vertices[task].children[j].depth = vertices[task].depth + 1;
                            queue.Enqueue(vertices[task].children[j].number - 1);
                        }

                    }

                }

                int[] output = new int[N];
                if (ignore == M)
                {
                    queue.Enqueue(i);
                    while (queue.Count != 0)
                    {
                        int task = queue.Dequeue();
                        for (int j = 0; j < vertices[task].children.Count; j++)
                        {
                            if (vertices[task].children[j].depth == vertices[task].depth + 1)
                            {
                                output[vertices[task].children[j].number-1] = vertices[task].number;
                                queue.Enqueue(vertices[task].children[j].number - 1);
                            }
                        }
                    }
                }
                for (int d = 0; d < output.Length; d++)
                {
                    Console.WriteLine(output[d]);
                }
            }
        }
    }
}

