				if (l == null) tree[p] = l = new List<int>();
				l.Add(c);

				aryP[c] = p;
			}

			// root親を探す
			int root = -1;
			for (int i = 1; i <= N; i++) {
				if (aryP[i] == 0) {
					root = i;
				}
			}
			InitArray(aryP, 0);

			// BFSで子供をたどる
			var list = new List<int>();
			list.Add(root);

			// BFS
			while (0 < list.Count) {
				var nextList = new List<int>();

				foreach (var p in list) {
					if (tree[p] == null) continue;

					foreach (int c in tree[p]) {
						if (aryP[c] != p) {
							aryP[c] = p;
							nextList.Add(c);
						}
					}
				}
				list = nextList;
			}
			for (int i = 1; i < N + 1; i++) {
				WriteLine(aryP[i]);
			}
