		var ins = Enumerable.Range(0, n + 1).Select(i => map_r[i].Count()).ToArray();

		var q = new Queue<int>(Enumerable.Range(1, n).Where(i => ins[i] == 0));
		var u = new int[n + 1];
		while (q.Any())
		{
			var p = q.Dequeue();
			foreach (var np in map[p])
				if (--ins[np] == 0)
				{
					u[np] = u[p] + 1;
					q.Enqueue(np);
				}
		}
		Console.WriteLine(string.Join("\n", Enumerable.Range(1, n).Select(i => map_r[i].SingleOrDefault(x => u[i] - u[x] == 1))));
	}
}

