    class Problem 
    {
        public void solve()
        {
            Func<int[]> read = () => Console.ReadLine().Split().Select(int.Parse).ToArray();
            int[] v = read();
            int N = v[0];
            int M = v[1];
            Dictionary<int, List<int>> d = new Dictionary<int, List<int>>();
            Dictionary<int, List<int>> e = new Dictionary<int, List<int>>();
            var h = new int[N + 1];

            for (int i = 1; i <= N; i++)
            {
                d.Add(i, new List<int>());
                e.Add(i, new List<int>());
            }

            int A, B;

            for (int i = 0; i < N + M - 1; i++)
            {
                int[] b = read();
                A = b[0];
                B = b[1];
                d[A].Add(B);
                e[B].Add(A);
                h[B]++;
            }

            var tp = topologicalSort(e, d, h);
            for (int i = 1; i <= N;i++) {
                int s = 0;
                int t = 0;
                foreach(var j in e[i])
                {
                    if (s < tp[j]) {
                        s = tp[j];
                        t = j;
                    }
                }
                Console.WriteLine("{0}", t);
            }

        }

        private Dictionary<int, int> topologicalSort(Dictionary<int, List<int>> IN, Dictionary<int, List<int>> OUT, int[] h) {
            var q = new Stack<int>();
            var ans = new Dictionary<int, int>();

            foreach(var elem in IN) 
            {
                if (elem.Value.Count == 0)
                {
                    q.Push(elem.Key);
                }
            }

            int c = 0;

            while (q.Count != 0) 
            {
                var s = q.Pop();
                c++;
                ans.Add(s, c);

                foreach(var t in OUT[s])
                {
                    h[t]--;
                    if(h[t]==0)
                    {
                        q.Push(t);
                    }
                }
            }

            return ans;
        }
    }
}

