    class Program
    {
        struct PointData
        {
            public bool fixFlg;
            public int fixParnet;
            public int rootCnt;
            public List<int> rootList;

            public PointData(PointData pData)
            {
                // TODO: Complete member initialization
                this.fixFlg = pData.fixFlg;
                this.fixParnet = pData.fixParnet;
                this.rootCnt = pData.rootCnt;
                this.rootList = new List<int>(pData.rootList);
            }
        }

        struct PointMster
        {
            public List<int> parentList;
            public List<int> childList;

            public PointMster(int dummy)
            {
                // TODO: Complete member initialization
                this.parentList = new List<int>();
                this.childList = new List<int>();
            }
        }

        static PointMster[] _mstArr;
        static PointData[] _datatArr;
        static int[] _maxArr;

        static void Main(string[] args)
        {
            int[] readArr = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);
            int dataCnt = readArr[0];
            int addLineCnt = readArr[1];

            _mstArr = new PointMster[dataCnt + 1];
            _datatArr = new PointData[dataCnt + 1];
            _maxArr = new int[dataCnt + 1];

            //初期化
            for (int i = 1; i <= dataCnt; i++)
            {
                _mstArr[i].parentList = new List<int>();
                _mstArr[i].childList = new List<int>();
                _datatArr[i].rootList = new List<int>();
            }

            for (int i = 0; i < dataCnt + addLineCnt - 1; i++)
            {

                int[] tmp = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);

                _mstArr[tmp[1]].parentList.Add(tmp[0]);
                _mstArr[tmp[0]].childList.Add(tmp[1]);
            }

            for (int i = 1; i <= dataCnt; i++)
            {
                //未確定の場合
                if (!_datatArr[i].fixFlg)
                {
                    //スタート地点をセット
                    _datatArr[i].rootList.Add(i);
                    _datatArr[i].rootCnt++;
                    RootChek(_datatArr[i], i, i);

                    for (int j = 0; j < _datatArr[i].rootList.Count; j++)
                    {
                        //未確定のポイントのみ更新
                        if (!_datatArr[_datatArr[i].rootList[j]].fixFlg)
                        {
                            int nxtNo = _datatArr[i].rootList[j];
                            _datatArr[nxtNo].fixFlg = true;
                            if (j + 1 < _datatArr[i].rootList.Count)
                            {
                                _datatArr[nxtNo].fixParnet = _datatArr[i].rootList[j + 1];
                            }

                            if (0 == _mstArr[nxtNo].parentList.Count)
                            {
                                _datatArr[nxtNo].rootCnt = 0;
                            }
                            else
                            {
                                _datatArr[nxtNo].rootCnt = _datatArr[i].rootCnt - j;
                            }
                        }
                    }
                }
            }

            for (int i = 1; i <= dataCnt; i++)
            {
                Console.WriteLine(_datatArr[i].fixParnet);
            }
        }

        static void RootChek(PointData pData, int parNo, int startNo)
        {
            //根に到達した場合、もしくは確定ルートの場合
            if((0 == _mstArr[parNo].parentList.Count)||(_datatArr[parNo].fixFlg))
            {
                if (_datatArr[startNo].rootCnt <= pData.rootCnt)
                {
                    _datatArr[startNo] = pData;
                }
                return;
            }

            for(int i = 0; i < _mstArr[parNo].parentList.Count; i++)
            {
                int nextParNo = _mstArr[parNo].parentList[i];

                PointData tmpP = new PointData(pData);
                tmpP.rootList.Add(nextParNo);
                //確定ルートの場合
                if (_datatArr[nextParNo].fixFlg)
                {
                    tmpP.rootCnt += _datatArr[nextParNo].rootCnt; 
                }
                else
                {
                    tmpP.rootCnt++;
                }

                if (tmpP.rootCnt < _maxArr[nextParNo])
                {
                    break;
                }
                else
                {
                    _maxArr[nextParNo] = tmpP.rootCnt;
                    RootChek(tmpP, nextParNo, startNo);
                }
            }

        }
    }
}

