def topological_sort(node_num, edges, roots)
  ns = Array.new(node_num+1,0)
  edges.each{ |h| h.each{ |m| ns[m] += 1 } }
  nodes = roots.map{ |d| d }
  sorted = []
  while n = nodes.pop
    sorted << n
    edges[n].each{ |m|
      ns[m] -= 1
      if ns[m] == 0
        nodes << m
      end
    }
  end
  sorted
end

