func main() {
	scanner := bufio.NewScanner(os.Stdin)
	var N, M int
	scanner.Scan()
	fmt.Sscanf(scanner.Text(), "%d %d", &N, &M)

	edges = make(map[int][]int)
	redges = make(map[int][]int)
	reachables = make(map[int]map[int]struct{})

	as := make([]int, N+M-1)
	bs := make([]int, N+M-1)

	for i := 0; i < N+M-1; i++ {
		scanner.Scan()
		fmt.Sscanf(scanner.Text(), "%d %d", &as[i], &bs[i])

		cs, e := edges[as[i]]
		if !e {
			cs = make([]int, 0)
		}
		edges[as[i]] = append(cs, bs[i])

		ps, e := redges[bs[i]]
		if !e {
			ps = make([]int, 0)
		}
		redges[bs[i]] = append(ps, as[i])
	}

	root := -1
	for i := 1; i <= N; i++ {
		if _, e := redges[i]; !e {
			root = i
			break
		}
	}
	dfs(root)

}

func dfs(currentNode int) map[int]struct{} {
	if nodes, e := reachables[currentNode]; e {
		return nodes
	}
	ret := make(map[int]struct{})
	ret[currentNode] = struct{}{}
	for _, child := range edges[currentNode] {
		for n, _ := range dfs(child) {
			ret[n] = struct{}{}
		}
	}
	reachables[currentNode] = ret
	return ret
}

