func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	m := getNextInt(scanner)
	deg := make([]int, n)
	cc := make([][]int, n)

	for i := 0; i < n+m-1; i++ {
		a := getNextInt(scanner) - 1
		b := getNextInt(scanner) - 1
		cc[a] = append(cc[a], b)

		deg[b]++
	}

	q := make([]int, 0)
	for i := 0; i < n; i++ {
		if deg[i] == 0 {
			q = append(q, i)
			break
		}
	}

	ans := make([]int, n)
	for len(q) > 0 {
		p := q[0]
		q = q[1:]
		for _, to := range cc[p] {
			deg[to]--
			if deg[to] > 0 {
				continue
			}
			q = append(q, to)
			ans[to] = p + 1
		}
	}
	for i := 0; i < n; i++ {
		fmt.Fprintln(writer, ans[i])
	}
}

