type WarchalFloyd struct {
	n int
	r [][]int
}

func NewWarchalFloyd(n int) *WarchalFloyd {
	r := make([][]int, n)
	for i := range r {
		r[i] = make([]int, n)
		for j := 0; j < n; j++ {
			if i == j {
				r[i][j] = 0
			} else {
				r[i][j] = int(1e9)
			}
		}
	}
	return &WarchalFloyd{n: n, r: r}
}

func (wf *WarchalFloyd) conect(u, v, cost int) {
	wf.r[u][v] = cost
}

func (wf *WarchalFloyd) build() {
	for k := 0; k < wf.n; k++ {
		for i := 0; i < wf.n; i++ {
			for j := 0; j < wf.n; j++ {
				wf.r[i][j] = min(wf.r[i][j], wf.r[i][k]+wf.r[k][j])
			}
		}
	}
}
func (wf *WarchalFloyd) rebuild() {
	for k := 0; k < wf.n; k++ {
		for i := 0; i < wf.n; i++ {
			for j := 0; j < wf.n; j++ {
				if wf.r[i][k] < int(1e9) && wf.r[k][j] < int(1e9) {
					wf.r[i][j] = max(wf.r[i][j], wf.r[i][k]+wf.r[k][j])
				}
			}
		}
	}
}

func (wf *WarchalFloyd) cost(u, v int) int {
	return wf.r[u][v]
}

