  for i:=0;i<n-1+m;i++ {
    a[i],b[i] = input.NextInts()
    a[i],b[i] = a[i]-1,b[i]-1
    g[a[i]] = append(g[a[i]],b[i])
  }
  s := topologicalSort(g)
  r := make([]int,n)
  for i:=0;i<len(s);i++ { r[s[i]] = i }
  x := make([]int,n)
  fill(&x,s[0])
  for i:=0;i<n-1+m;i++ {
    if r[x[b[i]]] < r[a[i]] { x[b[i]] = a[i] }
  }
  x[s[0]] = -1
