  for i:=1;i<n;i++ { fmt.Println(x[i]+1) }
}
func fill(a *[]int,n int) {
  for i:=0;i<len(*a);i++ { (*a)[i] = n }
}

func topologicalSort(g [][]int) []int {
  n := len(g)
  s := []int{}
  u := make([]bool,n)
  var dfs func(int)
  dfs = func(i int) {
    if u[i] { return }
    u[i] = true
    for _,e := range g[i] { dfs(e) }
    s = append(s,i)
  }
  for i:=0;i<n;i++ { dfs(i) }
  m := len(s)
  for i:=0;i<m-1-i;i++ { s[i],s[m-1-i] = s[m-1-i],s[i] }
  return s
}

type Input struct { reader *bufio.Reader }
func(i *Input) NextLine() string {
  var buffer []byte
  for {
    line,isPrefix,err := i.reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer,line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func(i *Input) NextInts() (int,int) {
  s := strings.Fields(i.NextLine())
  x,_ := strconv.Atoi(s[0])
  y,_ := strconv.Atoi(s[1])
  return x,y
}

