			memo[b] = true
		}

	}

	queue := list.New()

	for i := 1; i < n+1; i++ {
		if !memo[i] {
			queue.PushBack(i)
		}
	}

	memo = make([]bool, n+1, n+2) //memo[:len(memo)+1]
	// memo[root] = true

	costs := make([]int, n+1, n+2)
	for {

		curT := queue.Remove(queue.Front())

