				} else if memo[val.second] {
					continue
				} else {
					ans[val.second] = val.first
					costs[val.second] = cost + 1
					memo[val.second] = true
					queue.PushBack(val.second)
				}
			}
		}

		if queue.Len() == 0 {
			break
		}
	}
	// fmt.Println(costs)

	for i := 1; i < n+1; i++ {
		fmt.Fprintln(wtr, ans[i])
