import "fmt"

func main() {
	var n, m int
	fmt.Scan(&n, &m)

	g := make([][]int, n)
	inds := make([][]int, n)
	var a, b int
	for i := 0; i < n-1+m; i++ {
		fmt.Scan(&a, &b)
		a--
		b--
		g[a] = append(g[a], b)
		inds[b] = append(inds[b], a)
	}

	gs := topologicalSort(g)
	im := make(map[int]int)
	for i, v := range gs {
		im[v] = i
	}

	for i := 0; i < n; i++ {
		mx := -1
		u := 0
		for _, v := range inds[i] {
			if mx < im[v] {
				mx = im[v]
				u = v + 1
			}
		}
		fmt.Println(u)
	}
}

func topologicalSort(g [][]int) []int {
	n := len(g)
	inds := make([]int, n)
	for i := 0; i < n; i++ {
		for _, e := range g[i] {
			inds[e]++
		}
	}

	q := make([]int, 0)
	for i := 0; i < n; i++ {
		if inds[i] == 0 {
			q = append(q, i)
		}
	}

	ans := make([]int, 0)
	for len(q) > 0 {
		u := q[0]
		q = q[1:]
		ans = append(ans, u)
		for _, v := range g[u] {
			inds[v]--
			if inds[v] == 0 {
				q = append(q, v)
			}
		}
	}
	return ans
}

