// g 隣接リスト
func topologicalSort(g [][]int) []int {
	V := len(g) // 頂点数
	ans := make([]int, 0)
	used := make([]bool, V)
	var dfs func(int)
	dfs = func(u int) {
		if used[u] {
			return
		}
		used[u] = true
		for _, v := range g[u] {
			dfs(v)
		}
		ans = append(ans, u)
	}
	for i := 0; i < V; i++ {
		dfs(i)
	}
	for i := 0; i < len(ans)/2; i++ {
		ans[i], ans[len(ans)-1-i] = ans[len(ans)-1-i], ans[i]
	}
	return ans
}

