package main

import "fmt"

type graph [][]int

func (g graph) dfs(n int, visited []bool) {
	for i := range g[n] {
		visited[g[n][i]] = true
		g.dfs(g[n][i], visited)
	}
}

func (g graph) root() int {
	roots := make([]bool, len(g))
	for i := range g {
		g.dfs(i, roots)
	}

	for i := range roots {
		if !roots[i] {
			return i
		}
	}
	return -1
}

func (g graph) depthDFS(n int, d int, depths []int) {
	if depths[n] < d {
		depths[n] = d
	}

	for i := range g[n] {
		g.depthDFS(g[n][i], d+1, depths)
	}
}

func (g graph) depth(n int) []int {
	dep := make([]int, len(g))
	dep[n] = 0
	for i := range g[n] {
		to := g[n][i]
		g.depthDFS(to, 1, dep)
	}
	return dep
}

func (g graph) parentsDFS(parent int, parents []int) {
	for i := range g[parent] {
		to := g[parent][i]
		if to != -1 {
			parents[to] = parent + 1
			g.parentsDFS(to, parents)
		}
	}
}

func (g graph) parents(root int) []int {
	parents := make([]int, len(g))
	parents[root] = 0
	g.parentsDFS(root, parents)
	return parents
}

func main() {
	var N, M int
	fmt.Scan(&N, &M)

	g := make(graph, N)
	for i := 0; i < N+M-1; i++ {
		var A, B int
		fmt.Scan(&A, &B)
		g[A-1] = append(g[A-1], B-1)
	}

	root := g.root()
	depths := g.depth(root)
	for i := range g {
		for j := range g[i] {
			if depths[i]+1 != depths[g[i][j]] {
				g[i][j] = -1
			}
		}
	}

	for _, p := range g.parents(root) {
		fmt.Println(p)
	}
}

