func main() {
  var N, M int
  fmt.Scan(&N, &M)
  C := make([][]int, N)
  P := make([]int, N)
  for i := 0; i < N; i++ {
    P[i] = 0
  }
  for i := 0; i < N - 1 + M; i++ {
    var a, b int
    fmt.Scan(&a, &b)
    C[a - 1] = append(C[a - 1], b - 1)
    P[b - 1] -= 1
  }
  Q := make([]int, N)
  for i := 0; i < N; i++ {
    if P[i] == 0 {
      Q[0] = i
      break
    }
  }
  pos := 0
  que := 1
  for ; pos < que; {
    q := Q[pos]
    pos += 1
    for _, c := range C[q] {
      P[c] += 1
      if P[c] == 0 {
        P[c] = q + 1
        Q[que] = c
        que += 1
      }
    }
  }
  for _, p := range P {
    fmt.Println(p)
  }
}

