func main() {
	N, M := ReadInt(), ReadInt()
	graph := make([][]int, N+1)
	for i := 0; i < N+M-1; i++ {
		a, b := ReadInt(), ReadInt()
		graph[a] = append(graph[a], b)
	}

	used := make(map[int]bool)
	sortedNode := []int{}
	for i := 1; i <= N; i++ {
		dfs(graph, used, i, &sortedNode)
	}
	for i, j := 0, len(sortedNode)-1; i < j; {
		sortedNode[i], sortedNode[j] = sortedNode[j], sortedNode[i]
		i++
		j--
	}
	// orderOfNode[i]: iの順番
	orderOfNode := make([]int, N+1)
	for i, n := range sortedNode {
		orderOfNode[n] = i
	}
	// parent[i]: iの親
	parent := make([]int, N+1)
	parent[sortedNode[0]] = 0
	for u, vs := range graph {
		for _, v := range vs {
			if parent[v] > 0 {
				if orderOfNode[u] > orderOfNode[parent[v]] {
					parent[v] = u
				}
			} else {
				parent[v] = u
			}
		}
	}
	for i := 1; i <= N; i++ {
		fmt.Println(parent[i])
	}
}

func dfs(graph [][]int, used map[int]bool, u int, ans *[]int) {
	if used[u] {
		return
	}
	used[u] = true
	for _, v := range graph[u] {
		dfs(graph, used, v, ans)
	}
	*ans = append(*ans, u)
}

