type graph [][]int

var sc = bufio.NewScanner(os.Stdin)

func nextInt() int {
	sc.Scan()
	i, e := strconv.Atoi(sc.Text())
	if e != nil {
		panic(e)
	}
	return i
}

func (g graph) dfs(n int, visited []bool) {
	for i := range g[n] {
		to := g[n][i]
		if !visited[to] {
			visited[to] = true
			g.dfs(to, visited)
		}
	}
}

func (g graph) root() int {
	roots := make([]bool, len(g))
	for i := range g {
		g.dfs(i, roots)
	}

	for i := range roots {
		if !roots[i] {
			return i
		}
	}
	return -1
}

func (g graph) depth(root int) []int {
	dep := make([]int, len(g))

	q := []int{root}
	for len(q) > 0 {
		r := q[0]
		q = q[1:]
		for i := range g[r] {
			to := g[r][i]
			d := dep[r] + 1
			if dep[to] < d {
				dep[to] = d
			}
			q = append(q, to)
		}
	}
	return dep
}

func (g graph) parentsDFS(parent int, parents []int) {
	for i := range g[parent] {
		to := g[parent][i]
		if to != -1 {
			parents[to] = parent + 1
			g.parentsDFS(to, parents)
		}
	}
}

func (g graph) parents(root int) []int {
	parents := make([]int, len(g))
	parents[root] = 0
	g.parentsDFS(root, parents)
	return parents
}

func main() {
	sc.Split(bufio.ScanWords)
	N, M := nextInt(), nextInt()

	g := make(graph, N)
	for i := 0; i < N+M-1; i++ {
		A, B := nextInt(), nextInt()
		g[A-1] = append(g[A-1], B-1)
	}

	root := g.root()
	depths := g.depth(root)
	for i := range g {
		for j := range g[i] {
			if depths[i]+1 != depths[g[i][j]] {
				g[i][j] = -1
			}
		}
	}

	for _, p := range g.parents(root) {
		fmt.Println(p)
	}
}

