func main() {
	scanner := bufio.NewScanner(os.Stdin)
	var N, M int
	scanner.Scan()
	fmt.Sscanf(scanner.Text(), "%d %d", &N, &M)

	edges := make(map[int][]int)
	redges := make(map[int][]int)
	inCnt := make(map[int]int)
	for i := 0; i < N-1+M; i++ {
		var from, to int
		scanner.Scan()
		fmt.Sscanf(scanner.Text(), "%d %d", &from, &to)
		edges[from] = append(edges[from], to)
		redges[to] = append(redges[to], from)
		inCnt[to]++
	}

	root := -1
	for i := 1; i <= N; i++ {
		if inCnt[i] == 0 {
			root = i
			break
		}
	}

	tpsorted := make([]int, 0)
	workList := make([]int, 0)
	left, right := 0, 0
	workList = append(workList, root)
	right++
	for left < right {
		// remove node
		node := workList[left]
		left++
		// add node
		tpsorted = append(tpsorted, node)
		for _, to := range edges[node] {
			inCnt[to]--
			if inCnt[to] == 0 {
				workList = append(workList, to)
				right++
			}
		}
	}

	node2order := make(map[int]int)
	for i, node := range tpsorted {
		node2order[node] = i
	}

	var buffer bytes.Buffer
	for i := 1; i <= N; i++ {
		if i == root {
			buffer.WriteString("0\n")
		} else if len(redges[i]) == 1 {
			buffer.WriteString(strconv.Itoa(redges[i][0]))
			buffer.WriteString("\n")
		} else {
			tmpOrder := -1
			tmpNode := -1
			for _, from := range redges[i] {
				order := node2order[from]
				if order > tmpOrder {
					tmpOrder = order
					tmpNode = from
				}
			}
			buffer.WriteString(strconv.Itoa(tmpNode))
			buffer.WriteString("\n")
		}
	}
	fmt.Println(buffer.String())
}

