var edges, redges map[int][]int
var memo map[int]int

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	var N, M int
	scanner.Scan()
	fmt.Sscanf(scanner.Text(), "%d %d", &N, &M)

	edges = make(map[int][]int)
	redges = make(map[int][]int)
	memo = make(map[int]int)

	as := make([]int, N+M-1)
	bs := make([]int, N+M-1)

	for i := 0; i < N+M-1; i++ {
		scanner.Scan()
		fmt.Sscanf(scanner.Text(), "%d %d", &as[i], &bs[i])

		cs, e := edges[as[i]]
		if !e {
			cs = make([]int, 0)
		}
		edges[as[i]] = append(cs, bs[i])

		ps, e := redges[bs[i]]
		if !e {
			ps = make([]int, 0)
		}
		redges[bs[i]] = append(ps, as[i])
	}

	root := -1
	for i := 1; i <= N; i++ {
		if _, e := redges[i]; !e {
			root = i
			break
		}
	}
	//fmt.Println(root)
	//fmt.Println(reachables)

	orgrEdge := make(map[int]int)
	for target, parents := range redges {
		if len(parents) >= 2 {
			tmpLen := math.MaxInt64
			tmpParent := -1
			for _, parent := range redges[target] {
				l := reachables(parent)
				if l < tmpLen {
					tmpLen = l
					tmpParent = parent
				}
			}
			orgrEdge[target] = tmpParent
		}
	}

	var buffer bytes.Buffer
	for i := 1; i <= N; i++ {
		if i == root {
			buffer.WriteString("0\n")
		} else if from, e := orgrEdge[i]; e {
			buffer.WriteString(strconv.Itoa(from))
			buffer.WriteString("\n")
			continue
		} else {
			froms := redges[i]
			buffer.WriteString(strconv.Itoa(froms[0]))
			buffer.WriteString("\n")
		}
	}
	fmt.Println(buffer.String())

}

func reachables(currentNode int) int {
	if nodes, e := memo[currentNode]; e {
		return nodes
	}
	ret := 0
	ret++
	for _, child := range edges[currentNode] {
		ret = ret + reachables(child)
	}
	memo[currentNode] = ret
	return ret
}

