void main()
{
	auto tokens = my_readln.split;
	auto N = tokens[0].to!long;
	auto M = tokens[1].to!long;
	auto v = new long[][](N);
	auto v2 = new long[][](N);
	foreach (i; 0..N-1+M)
	{
		auto tokens2 = my_readln.split;
		auto a = tokens2[0].to!long - 1;
		auto b = tokens2[1].to!long - 1;
		v[b] ~= a;
		v2[a] ~= b;
	}

	auto index = new ulong[](N);
	makeIndex!"a.length < b.length"(v, index);

	auto rank = new ulong[](N);

	void computeRank(ulong i, ulong r)
	{
		rank[i] = max(rank[i], r);
		foreach (e; v2[i])
		{
			computeRank(e, r+1);
		}
	}
	computeRank(index[0], 0);

	auto index2 = new ulong[](N);
	makeIndex(rank, index2);

	bool hasRoot = v[index[0]].length == 0;
	foreach (ii, i; index2)
	{
		if (!hasRoot)
		{
			v[i].length = 0;
			hasRoot = true;
		}
		else if (v[i].length > 1)
		{
			long bestI, bestR = -1;
