    auto G = new DirectedGraph(N);
    auto D = new int[](N);
    foreach (_; 0..N-1+M) {
        s = readln.split.map!(to!int);
        G.add_edge(s[0]-1, s[1]-1);
        D[s[1]-1] += 1;
    }


    int root = 0;
    foreach (i; 0..N) if (D[i] == 0) root = i;

    DList!(int) stack;
    auto P = new int[](N);

    stack.insertBack(root);
    P[root] = -1;

    while (!stack.empty) {
        int n = stack.front;
        stack.removeFront;
        foreach (m; G.adj[n]) {
            if (D[m] == 1) {
                P[m] = n;
                stack.insertBack(m);
            } else {
                D[m] -= 1;
            }
        }
    }

    P.each!(i => writeln(i+1));
}




class DirectedGraph {
    int n;
    int[][] adj;
    int[][] inv;

    this(int n) {
        this.n = n;
        adj = new int[][](n);
        inv = new int[][](n);
    }

    void add_edge(int u, int v) {
        adj[u] ~= v;
        inv[v] ~= u;
    }
}


class StronglyConnectedComponent : DirectedGraph {
    int[] index;
    int[][] scc;

    this(DirectedGraph g) {
        int cnt = 0;
        auto ord = new int[](g.n);
        auto used = new bool[](g.n);
        index = new int[](g.n);

        void dfs1(int n) {
            if (used[n]) return;
            used[n] = true;
            foreach (m; g.adj[n]) if (!used[m]) dfs1(m);
            ord[cnt++] = n;
        }

        void dfs2(int n) {
            if (used[n]) return;
            used[n] = true;
            index[n] = cnt;
            scc.back ~= n;
            foreach (m; g.inv[n]) if (!used[m]) dfs2(m);
        }

        foreach (i; 0..g.n) if (!used[i]) dfs1(i);

        cnt = 0;
        fill(used, false);

        foreach_reverse (i; 0..g.n) {
            if (used[ord[i]]) continue;
            scc.length += 1;
            dfs2(ord[i]);
            cnt += 1;
        }

        super(cnt);
        auto edge = new bool[int][](cnt);

        foreach (i; 0..g.n)
            foreach (j; g.adj[i])
                if (index[i] != index[j])
                    edge[index[i]][index[j]] = true;

        foreach (i; 0..cnt)
            foreach (j; edge[i].keys)
                add_edge(i, j);
    }
}

