auto parse( Range )( Range input )
if( isInputRange!Range && is( ElementType!Range == string ) )
{
	auto nm = input.front.split.to!( long[] );
	auto abs = new long[ 2 ][ nm[ 0 ] - 1 + nm[ 1 ] ];
	foreach( ref ab; abs )
	{
		input.popFront;
		ab = input.front.split.to!( long[] );
		ab[] -= 1;
	}
	return tuple( nm[ 0 ], abs );
}

auto solve( long n, long[ 2 ][] abs )
{
	// 辺配列から隣接リストを作成、頂点ごとに親の数をカウント
	auto nss = new long[][ n ];
	auto ps = new long[ n ];
	foreach( ab; abs )
	{
		nss[ ab[ 0 ] ] ~= ab[ 1 ];
		ps[ ab[ 1 ] ]++;
	}

	// 根を検索
	auto queue = DList!long();
	foreach( i, p; ps )
	{
		if( p == 0 )
		{
			queue.insertBack( i );
			break;
		}
	}

	// 幅優先探索で最長経路を探す
	auto anss = new long[ n ];
	while( !queue.empty )
	{
		auto f = queue.front;
		queue.removeFront();

		foreach( t; nss[ f ] )
		{
			ps[ t ]--;
			if( 0 < ps[ t ] ) continue;		// 親の探索が全部終わるまで保留
			anss[ t ] = f + 1;		// 最後に到達した辺を採用
			queue.insertBack( t );
		}
	}
	return anss.to!( string[] ).join( "\n" );
}

