  newSeqWith(n1, newSeqWith(n2, newSeq[T](n3)))

proc dfs(n: int; g: seq2[int]; v: int; dep: var seq[int]): int =
  if dep[v] != -1:
    return dep[v]

  var res = 0
  for u in g[v]:
    res = max(res, dfs(n, g, u, dep) + 1)
  dep[v] = res
  return res

