  var isRoot = newSeq[bool](n)
  isRoot.fill(true)
  for v in 0..<n:
    for u in g[v]:
      isRoot[u] = false

  var root = -1
  for v in 0..<n:
    if isRoot[v]:
      root = v
      break

  var g2 = newSeq2[int](n, 0)
  for v in 0..<n:
    for u in g[v]:
      g2[u].add(v)

  var dep = newSeq[int](n)
  dep.fill(-1)
  dep[root] = 0
  for v in 0..<n:
    dep[v] = dfs(n, g2, v, dep)

  var par = newSeq[int](n)
  for v in 0..<n:
    if g2[v].len() == 0:
      par[v] = -1
      continue

    var k = g2[v][0]
    for u in g2[v]:
      if dep[u] > dep[k]:
        k = u
    par[v] = k

  for v in 0..<n:
    echo par[v] + 1

