type
  StronglyConnectedComponents = object
    graph, rev_graph: seq[seq[int]]
    vs, comp, sorted_vs: seq[int]
    used: seq[bool]

proc initSCC(size: Natural): StronglyConnectedComponents =
  return StronglyConnectedComponents(
    graph: newSeqWith(size, newSeq[int]()),
    rev_graph: newSeqWith(size, newSeq[int]()),
    vs: newSeq[int](),
    comp: newSeq[int](size),
    sorted_vs: newSeq[int](size),
    used: newSeq[bool](size)
  )

proc add_edge(scc: var StronglyConnectedComponents, v1: int, v2: int) =
  scc.graph[v1].add(v2)
  scc.rev_graph[v2].add(v1)

proc dfs(scc: var StronglyConnectedComponents, v: int) =
  scc.used[v] = true
  for c in scc.graph[v]:
    if not scc.used[c]:
      scc.dfs(c)
  scc.vs.add(v)

proc rev_dfs(scc: var StronglyConnectedComponents, v: int, k: int) =
  scc.used[v] = true
  scc.comp[v] = k
  for c in scc.rev_graph[v]:
    if (not scc.used[c]):
      scc.rev_dfs(c, k)

proc run(scc: var StronglyConnectedComponents): int =
  scc.used.fill(false)
  for v in 0..<scc.graph.len:
    if not scc.used[v]:
      scc.dfs(v)
  scc.used.fill(false)
  var k = 0
  for v in scc.vs.reversed:
    if not scc.used[v]:
      scc.rev_dfs(v, k)
      k.inc
  for i, v in scc.comp:
    scc.sorted_vs[v] = i
  return k

when isMainModule:
  let
    (N, M) = input(int, 2)
  var scc = initSCC(N)
  var rev_edge = newSeqWith(N, newSeq[int]())
  for i in 0..<(N - 1 + M):
    let (a, b) = input(int, 2)
    rev_edge[b - 1].add(a - 1)
    scc.add_edge(a - 1, b - 1)
  discard scc.run()
  var order = newSeq[int](N)
  for i, v in scc.sorted_vs:
    order[v] = i
  for v in 0..<N:
    var
      (par, min_order) = (-1, -1)
    for p in rev_edge[v]:
      if order[p] > min_order:
        (par, min_order) = (p, order[p])
    if par == -1:
      echo(0)
    else:
      echo(par + 1)

