# proc dfs(n: int; g: seq2[int]; v, p, d: int; par, dep: var seq[int]) =
#   if d > dep[v]:
#     par[v] = p
#     dep[v] = d
# 
#   for u in g[v]:
#     dfs(n, g, u, v, d + 1, par, dep)
proc bfs(n: int; g: seq2[int]; root: int): seq[int] =
  var q = initQueue[(int, int, int)]()

  var par = newSeq[int](n)
  var dep = newSeq[int](n)
  dep.fill(-1)
  par.fill(-1)

  # v d p
  q.enqueue((root, 0, -1))
  while q.len() > 0:
    let (v, d, p) = q.dequeue()
    if d <= dep[v]:
      continue

    dep[v] = d
    par[v] = p
    for u in g[v]:
      q.enqueue((u, d + 1, v))

  return par

