def topological_sort(graph_to, graph_from):
  graph_from_cnt = [len(graph_from[i]) for i in range(N)]
  dic = DD(int)
  q = deque([i for i in range(N) if not graph_from_cnt])
  while q:
    x = q.popleft()
    dic[x] = len(dic)
    for y in graph_to[x]:
      graph_from_cnt[y] -= 1
      if not graph_from_cnt[y]:
        q.append(y)
  return dic


