def bfs(n,e,fordfs):
    P = [-1]*n
    L = [0]*n
    que = deque()
    que.append(e)
    P[e] = 0
    while que:
        now = que.popleft()
        for ne in fordfs[now]:
            if P[ne] == -1:
                L[ne] = L[now]+1
                P[ne] = now + 1
                que.append(ne)
            elif L[ne]<L[now]+1:
                L[ne] = L[now]+1
                P[ne] = now + 1
                que.append(ne)
    return P
