def solve(N, edges):
    adj = Graph(N, edges, directed=True).adj
    parent = [-1]*N

    # find root
    candidates = [True]*N
    for a,b in edges:
        candidates[b] = False

    root = next(v for v,f in enumerate(candidates) if f)

    q = [root]
    while q:
        nq = []
        for v in q:
            for u in adj[v]:
                if parent[u] != v:
                    parent[u] = v
                    nq.append(u)
        q = nq
    return (p+1 for p in parent)




