import numpy as np

class Tree(object):
    def __init__(self, edges):
        self.par = {}
        self.fix_d = {}
        for edge in edges:
            self.add(edge)

    def add(self, edge):
        r, b = edge
        if b not in self.par:
            self.par[b] = []
        self.par[b].append(r)

    def depth(self, node):
        if node in self.fix_d:
            return self.fix_d[node], False
        if node not in self.par:
            self.fix_d[node] = 0
            return 0, False
        br = len(self.par[node]) > 1
        d = None
        p = None
        for v in self.par[node]:
            dep, branched = self.depth(v)
            dep += 1
            if branched:
                d = dep
                p = v
                br = True
                break
