def solve(N, edges):
    adj = Graph(N, edges, directed=True).adj
    parent = [-1]*N

    # find root
    candidates = [True]*N
    for a,b in edges:
        candidates[b] = False

    root = next(v for v,f in enumerate(candidates) if f)

    stack = [root]
    while stack:
        v = stack.pop()
        for u in adj[v]:
            if parent[u] != v:
                parent[u] = v
                stack.append(u)

    return (p+1 for p in parent)




