def solve(N, edges):
    adj = Graph(N, edges, directed=True).adj
    parent = [-1]*N

    # find root
    candidates = [True]*N
    for a,b in edges:
        candidates[b] = False

    root = next(v for v,f in enumerate(candidates) if f)
    visited = [False]*N
    q = [root]
