from collections import deque

class Tree(object):
    def __init__(self, edges):
        self.par = {}
        self.fix_d = {}
        for edge in edges:
            self.add(edge)

    def add(self, edge):
        r, b = edge
        if b not in self.par:
            self.par[b] = []
        self.par[b].append(r)

    def remove(self, node):
        Q = deque()
        Q.append(node)
        visited = {}
        while len(Q) > 0:
            v = Q.popleft()
            if v not in self.par:
                continue
            for i in self.par[v]:
                if i in visited:
                    x = visited[i]
                    self.par[x].remove(i)
                visited[i] = v
                Q.append(i)

    def rem(self):
        for node in self.par:
            if len(self.par[node]) > 1:
                self.remove(node)

    def parent(self, node):
        if node not in self.par:
            return 0
        return self.par[node][0]


