def tsort(g):
  N = len(g)
  L = []
  temp = [False for _ in range(N)]
  perm = [False for _ in range(N)]
  def visit(n):
    if temp[n]:
      return 1
    elif not perm[n]:
      temp[n] = True
      for t in g[n]:
        visit(t)
      perm[n] = True
      temp[n] = False
      L.insert(0, n)
      return 0
  for i in range(N):
    if not perm[i] and not temp[i]:
      t = visit(i)
      if t == 1:
      	return [-1 for _ in range(N)]
  return L

