import numpy as np


def BellmanFord(edges, num_v, source):
    #グラフの初期化
    inf = float("inf")
    dist = np.zeros(num_v)
    dist[:] = np.inf
    dist[source] = 0
    parent = np.zeros(num_v, dtype=int)

    #辺の緩和
    for i in range(num_v):
        for fr, to, w in edges:
            if dist[to] > dist[fr] + w:
                dist[to] = dist[fr] + w
                parent[to] = fr
                if i == num_v-1:
                    return -1, None
    return dist, parent

def solve():
    N, M = map(int, input().split())
    TO = np.zeros(N)
    edges = []
    for _ in range(N+M-1):
        f, t = map(int, input().split())
        f -= 1
        t -= 1
        TO[t] += 1
        edges.append((f, t, -1))
    start = TO.argmin()
    _, parent = BellmanFord(edges, N, start)

    for i in range(N):
        if i==start:
            print(0)
        else:
            print(parent[i]+1)



if __name__ == "__main__":
    solve()

