def BellmanFord(edges, num_v, source):
    #グラフの初期化
    inf = float("inf")
    dist = [inf for i in range(num_v)]
    dist[source] = 0
    parent = np.zeros(num_v, dtype=int)

    #辺の緩和
    for i in range(num_v):
        for fr, to, w in edges:
            if dist[to] > dist[fr] + w:
                dist[to] = dist[fr] + w
                parent[to] = fr
                if i == num_v-1:
                    return -1, None
    return dist, parent

