def topological_sort(V, adj):
    '''
    V:N(node)
    adj:adjacency matrix
    '''

    # count num of pointed nodes for each nodes
    cnt = [0]*V
    for a in adj:
        for j in a:
            cnt[j] += 1
    "set of nodes which is not pointed from other"
    Q = []
    for i in range(V):
        if cnt[i] == 0:
            Q.append(i)

    ret = []
    while Q:
        del_node = Q.pop()
        ret.append(del_node)
        for j in adj[del_node]:
            cnt[j] -= 1
            if cnt[j] == 0:
                Q.append(j)

    #print("ret->", ','.join(map(lambda x: str(x+1), ret)))
    return ret


