def is_child(graph, start, goal):
    visited = {start}
    starts = {start}
    while True:
        nex = set()
        for s in starts:
            n = graph.get(s, set()) - visited
            if goal in n:
                return True
            nex = nex.union(n)
        if not nex:
            return False
        visited = visited.union(nex)
        starts = nex


