import numpy as np

class Tree(object):
    def __init__(self, edges):
        self.par = {}
        self.fix_d = {}
        for edge in edges:
            self.add(edge)

    def add(self, edge):
        r, b = edge
        if b not in self.par:
            self.par[b] = []
        self.par[b].append(r)

    def depth(self, node):
        if node in self.fix_d:
            return self.fix_d[node]
        if node not in self.par:
            self.fix_d[node] = 0
            return 0
        d = None
        p = None
        for v in self.par[node]:
            dep = self.depth(v) + 1
            if p == None:
                d = dep
                p = v
            elif d == dep:
                p = None
                d = None
            elif dep > d:
                d = dep
                p = v
        self.par[node] = [p]
        self.fix_d[node] = d
        return d

    def rem(self):
        for node in self.par:
            if len(self.par[node]) > 1:
                self.depth(node)

    def parent(self, node):
        if node not in self.par:
            return 0
        return self.par[node][0]


