def tpsort(es):
    n = len(es)
    indgr = [0] * n
    for e in es:
        for u in e:
            indgr[u] += 1
    st = [v for v in range(n) if indgr[v] == 0]
    parent = [0] * n
    while st:
        v = st.pop()
        for u in es[v]:
            indgr[u] -= 1
            if indgr[u] == 0:
                st.append(u)
                parent[u] = v
    return parent

