def topological_sort(V, to):
    res = []
    cnt = [0] * V
    for i in range(V):
        for j in to[i]:
            cnt[j] += 1
    Q = []
    for i in range(V):
        if cnt[i] == 0:
            Q.append(i)
    while len(Q) > 0:
        i = Q[0]
        del Q[0]
        res.append(i)
        for k in to[i]:
            cnt[k] -= 1
            if cnt[k] == 0:
                Q.append(k)
    return res


