def bfs(n,e,fordfs):
    W = [-1]*n
    W[e] = 0
    P = [-1]*n
    que = deque()
    que.append(e)
    P[e] = 0
    while que:
        now = que.popleft()
        nowW = W[now]
        for ne in fordfs[now]:
            if W[ne] == -1:
                W[ne] = nowW + 1
                que.append(ne)
                P[ne] = now + 1
            else:
                W[ne] = nowW + 1
                P[ne] = now + 1
                que.append(ne)
    return P
