def add_children(graph, children, start):
    children[start - 1] = children[start - 1].union(graph[start])
    for s in graph[start]:
        if s not in graph:
            continue
        children[start - 1] = children[start - 1].union(add_children(graph, children, s))
    return children[start - 1]


