pub struct Dikstra {
    dist: Vec<i64>,
    start: usize,
    from: Vec<usize>,
}
impl Dikstra {
    pub fn new(g: &Vec<Vec<(i64, usize)>>, start: usize) -> Self {
        let mut d = Dikstra {
            dist: vec![INF_I64; g.len()],
            start: start,
            from: vec![0; g.len()],
        };
        d.calc(g);
        return d;
    }
    fn calc(&mut self, g: &Vec<Vec<(i64, usize)>>) {
        let mut used = vec![false; g.len()];
        let mut kouho = std::collections::BinaryHeap::new();
        kouho.push((0, self.start));
        while !kouho.is_empty() {
            let (_, k) = kouho.pop().unwrap();
            used[self.start] = true;
            self.dist[self.start] = 0;
            for i in 0..g[k].len() {
                let (d, p) = g[k][i];
                if used[p] {
                    continue;
                }
                if self.dist[p] > self.dist[k] + d as i64 {
                    self.dist[p] = self.dist[k] + d as i64;
                    self.from[p] = k;
                    kouho.push((self.dist[p] * -1, p));
                }
            }
        }
    }
    pub fn dist_to(&mut self, x: usize) -> i64 {
        return self.dist[x];
    }
    pub fn from(&mut self, x: usize) -> usize {
        return self.from[x];
    }
}

fn main() {
    input! {
       N: usize,
       M:usize,
    }
    let mut map = vec![vec![]; N];
    let mut c = vec![0; N];
    for _ in 0..(N - 1 + M) {
        input! {
            a:Usize1,
            b:Usize1,
        }
        map[a].push((-1, b));
        c[b] += 1;
    }
    let mut start = c.iter().position(|&x| x == 0).unwrap();
    mydbg!(c, start);
    let mut d = Dikstra::new(&map, start);
    let mut ans = vec![0; N];
    let mut h = HashMap::new();
    for i in 0..N {
        let x = d.dist_to(i);
        let mut hp = h.entry((x * -1) as usize).or_insert(vec![]);
        hp.push(i);
    }
    for i in 0..N {
        if let Some(x) = h.get(&i) {
            for &item in x {
                ans[item] = d.from[item] + 1;
            }
        } else {
            break;
        }
    }
    ans[start] = 0;

    echo!(ans.joinToString("\n"));
}

