    for i in 0..n + m - 1 {
        t[v[i][0]].push(v[i][1]);
        rev[v[i][1]].push(v[i][0]);
    }
    let mut tab: Vec<usize> = vec![0; n];
    for i in 0..n {
        if t[i].is_empty() {
            let _ = dfs(&rev, i, &mut tab);
        }
    }
