fn dfs(t: &Vec<Vec<usize>>, v: usize, tab: &mut Vec<usize>) -> usize {
    let mut len = 0;
    for &p in t[v].iter() {
        let mut lt = dfs(t, p, tab) + 1;
        if len < lt {
            len = lt;
            tab[v] = p + 1;
        }
    }
    len
}

