macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let (n, m): (usize, usize) = parse!(it, 2);
    let mut g = vec![vec![]; n];
    for _ in 0..(n + m - 1) {
        let (a, b): (usize, usize) = parse!(it, 2);
        g[a - 1].push(b - 1);
    }
    let mut seen = vec![false; n];
    let mut parents = vec![0; n];
    for i in 0..n {
        if !seen[i] {
            dfs(&g, i, &mut parents, &mut seen);
        }
    }
    for p in parents {
        println!("{}", p);
    }
}

fn dfs(g: &Vec<Vec<usize>>, u: usize, parents: &mut Vec<usize>, seen: &mut Vec<bool>) {
    if !seen[u] {
        seen[u] = true;
        for &v in &g[u] {
            dfs(g, v, parents, seen);
        }
        for &v in &g[u] {
            if parents[v] == 0 {
                parents[v] = u + 1;
            }
        }
    }
}

