pub fn unfold<State, T, F>(init: State, f: F) -> Unfold<State, T, F> where F: FnMut(&State) -> Option<(T, State)> {
    Unfold { state: init, f: f }
}
pub struct Iterate<T, F> where F: FnMut(&T) -> T {
    state: T,
    f: F
}
impl<T, F> Iterator for Iterate<T, F> where F: FnMut(&T) -> T {
    type Item = T;
    fn next(&mut self) -> Option<T> {
        use std::mem::swap;
        let mut state = (self.f)(&self.state);
        swap(&mut state, &mut self.state);
        Some(state)
    }
}
pub fn iterate<T, F>(init: T, f: F) -> Iterate<T, F>
where
    F: FnMut(&T) -> T
{
    Iterate { state: init, f: f }
}
pub struct IterateMap<State, T, F> where F: FnMut(&State) -> (T, State) {
    state: State,
    f: F
}
impl<State, T, F> Iterator for IterateMap<State, T, F> where F: FnMut(&State) -> (T, State) {
    type Item = T;
    fn next(&mut self) -> Option<T> {
        let (value, state) = (self.f)(&self.state);
        self.state = state;
        Some(value)
    }
}
pub fn iterate_map<State, T, F>(init: State, f: F) -> IterateMap<State, T, F>
where
    F: FnMut(&State) -> (T, State)
{
    IterateMap { state: init, f }
}

