fn sort_dfs(v: usize, adj: &[Vec<usize>], visited: &mut [bool], vs: &mut Vec<usize>) {
    if visited[v] {
        return;
    }

    visited[v] = true;
    for &next in &adj[v] {
        sort_dfs(next, adj, visited, vs);
    }
    vs.push(v);
}

fn dfs(v: usize, p: Option<usize>, adj: &[Vec<usize>], orders: &[usize], parents: &mut [Option<usize>]) {
    dbg!((v, p));
    if let Some(old_p) = parents[v] {
        if orders[p.unwrap()] > orders[old_p] {
            parents[v] = p;
            // eprintln!("update {} {:?}", v, parents[v]);
        }
        return;
    }

    parents[v] = p;
    for &next in &adj[v] {
        dfs(next, Some(v), adj, orders, parents);
    }
    // eprintln!("back {} {:?}", v, parents[v]);
}

