fn main() {
    input!{
        n: usize,
        m: usize,
        v: [[usize1; 2]; n + m - 1]
    }
    let mut t: Vec<Vec<usize>> = vec![Vec::new(); n];
    let mut rev: Vec<Vec<usize>> = vec![Vec::new(); n];
    for i in 0..n + m - 1 {
        t[v[i][0]].push(v[i][1]);
        rev[v[i][1]].push(v[i][0]);
    }
    let mut tab: Vec<usize> = vec![n + 1; n];
    let mut q: VecDeque<usize> = VecDeque::new();
    for i in 0..n {
        if rev[i].is_empty() {
            q.push_back(i);
            tab[i] = 0;
            break;
        }
    }
    while !q.is_empty() {
        let s = q.pop_front().unwrap();
        for &c in t[s].iter() {
            q.push_back(c);
            tab[c] = s + 1;
        }
    }
    for i in 0..n {
        println!("{}", tab[i]);
    }
}

