fn solve() {
    let (n,m) = get!(usize, usize);
    let ab = get!(usize, usize;n-1+m);

    let mut nodes = vec![Vec::new(); n+1];

    let mut roots = (1..n+1).collect::<BTreeSet<_>>();
    for &(a,b) in &ab {
        roots.remove(&b);
        nodes[a].push(b);
    }
    let root = roots.into_iter().next().unwrap();

    let mut queue = VecDeque::new();
    let mut visited = vec![BTreeMap::new(); n+1];
    visited[root].insert(0,0);
    queue.push_back((root,0));
    while let Some((node, depth)) = queue.pop_front() {
        for &next in &nodes[node] {
            if visited[next].len() > 0 {
                visited[next].insert(depth, node);
                continue;
            }
            queue.push_back((next, depth+1));
            visited[next].insert(depth, node);
        }
    }

    for i in 1..n+1 {
        let par = visited[i].iter().rev().next().unwrap().1;
        println!("{}", par);
    }
}

