fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = CpReader::new(i);
    let (n, m) = i.read2::<usize, usize>();
    let mut bss = vec![Vec::new(); n];
    for _ in 0..n - 1 + m {
        let (a, b) = i.read2::<usize, usize>();
        bss[a - 1].push(b - 1);
    }
    let tree = solve(&bss);
    for node in tree {
        let no = if let Some(p) = node { p + 1 } else { 0 };
        writeln!(o, "{}", no).unwrap();
    }
}
fn solve(bss: &[Vec<usize>]) -> Vec<Option<usize>> {
    let n = bss.len();
    let mut is_root = vec![true; n];
    for bs in bss {
        for &b in bs {
            is_root[b] = false;
        }
    }
    let root = is_root.iter().position(|&is_root| is_root).unwrap();
    let mut ds = vec![0; n];
    let mut ps = vec![None; n];
    let mut q = vec![root];
    while let Some(a) = q.pop() {
        for &b in &bss[a] {
            let d_new = ds[a] + 1;
            if ds[b] < d_new {
                ds[b] = d_new;
                ps[b] = Some(a);
                q.push(b);
            }
        }
    }
    ps
}

