fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let (n, m): (usize, usize) = parse!(it, 2);
    let mut g = vec![vec![]; n];
    let mut unseen = std::collections::HashSet::<usize>::from_iter(0..n);
    for _ in 0..(n + m - 1) {
        let (a, b): (usize, usize) = parse!(it, 2);
        g[a - 1].push(b - 1);
        unseen.remove(&(b - 1));
    }
    let root = *unseen.iter().next().unwrap();
    let mut q = std::collections::VecDeque::new();
    q.push_back(root);
    let mut parents = vec![0; n];
    while let Some(u) = q.pop_front() {
        for &v in &g[u] {
            if parents[v] == 0 {
                q.push_back(v);
            }
            parents[v] = u + 1;
        }
    }
    for p in parents {
        println!("{}", p);
    }
}

