fn top_sort(es: &Vec<Vec<usize>>, i: usize, r_to_i: &mut Vec<usize>, i_to_r: &mut Vec<Option<usize>>) {
    if i_to_r[i].is_some() {
        return;
    }
    for &next in &es[i] {
        top_sort(es, next, r_to_i, i_to_r);
    }
    i_to_r[i] = Some(r_to_i.len());
    r_to_i.push(i);
}

