    }
    let mut rev_graph = vec![vec![]; n];
    for &(s,t) in &es {
        rev_graph[t].push(s);
    }
    let mut res = vec![0; n];
    for &i in &r_to_i {
        let mut best = None;
        for &next in &rev_graph[i] {
            if best.is_none() || i_to_r[best.unwrap()] > i_to_r[next] {
                best = Some(next);
            }
        }
        if let Some(best) = best {
            res[i] = best + 1;
        }
    }
    for &r in &res {
        println!("{}", r);
    }
}

