}

fn run() {
	let (N, M) = read!(usize, usize);
	let mut g = vec![vec![]; N];
	let mut deg = vec![0; N];
	for _ in 0..N+M-1 {
		let (a, b) = read!(usize, usize);
		g[a - 1].push(b - 1);
		deg[b - 1] += 1;
	}
	let mut parent = vec![!0; N];
	let mut stack = vec![];
	for i in 0..N {
		if deg[i] == 0 {
			stack.push(i);
			parent[i] = 0;
		}
	}
	while let Some(u) = stack.pop() {
		for &v in &g[u] {
			deg[v] -= 1;
			if deg[v] == 0 {
				parent[v] = u + 1;
				stack.push(v);
			}
		}
	}
	for i in 0..N {
		println!("{}", parent[i]);
	}
}

