struct Dag {
    g: Vec<Vec<usize>>,
    vs: Vec<usize>,
    n: usize
}

#[allow(dead_code)]
impl Dag {
    fn new(g: &Vec<Vec<usize>>) -> Dag {
        let n = g.len();
        Dag {n: n, g: g.clone(), vs: vec![]}
    }

    fn tsort(&mut self) {
        let mut h = vec![0usize;self.n];
        for i in 0..self.n {
            for &v in &self.g[i] {h[v] += 1;}
        }
        let mut stack = vec![];
        for i in 0..self.n {if h[i] == 0 {stack.push(i);}}
        while let Some(i) = stack.pop() {
            self.vs.push(i);
            for &j in &self.g[i] {
                h[j] -= 1;
                if h[j] == 0 {stack.push(j);}
            }
        }
    }

    fn is_acyclic(&self) -> bool {
        self.vs.len() == self.n
    }

    fn is_unique(&self) -> bool {
        for i in 0..self.n - 1 {
            let a = self.vs[i];
            let b = self.vs[i+1];
            let mut f = false;
            for &v in &self.g[a] {
                if v == b {
                    f = true;
                    break;
                }
            }
            if !f {return false;}
        }
        true
    }

    fn longest_path(&self) -> usize {
        let mut dp = vec![0;self.n];
        for &p in &self.vs {
            for &v in &self.g[p] {
                dp[v] = std::cmp::max(dp[v], dp[p] + 1);
            }
        }
        dp.into_iter().max().unwrap()
    }
}

