fn solve(i: usize, d: i32, j: usize, par: &mut Vec<usize>, depth: &mut Vec<i32>, graph: &Vec<Vec<usize>>, rgraph: &Vec<Vec<usize>>) {
    if depth[i] >= d {
        return;
    }
    if rgraph[i].len() > 1 {
        for k in rgraph[i].iter() {
            if *k != j && depth[*k] == -1 {
                return;
            }
        }
    }
    par[i] = j;
    depth[i] = d;
    for k in graph[i].iter() {
        solve(*k, d+1, i, par, depth, graph, rgraph);
    }
}

fn main() {
    let nm: Vec<usize> = read_line().split_whitespace().map(|s| s.parse().unwrap()).collect();
    let n = nm[0];
    let m = nm[1];

    let mut graph: Vec<Vec<usize>> = vec![Vec::new(); n];
    let mut rgraph: Vec<Vec<usize>> = vec![Vec::new(); n];
    for i in 0..n+m-1 {
        let ab: Vec<usize> = read_line().split_whitespace().map(|s| s.parse().unwrap()).collect();
        let a = ab[0];
        let b = ab[1];

        graph[a-1].push(b-1);
        rgraph[b-1].push(a-1);
    }

    let mut par: Vec<usize> = vec![n; n];
    let mut depth: Vec<i32> = vec![-1; n];
    for i in 0..n {
        if rgraph[i].len() == 0 {
            depth[i] = 0;
            for j in graph[i].iter() {
                solve(*j, 1, i, &mut par, &mut depth, &graph, &rgraph);
            }
            break;
        }
    }

    for i in 0..n {
        if depth[i]==0 {
            println!("{}", 0);
        } else {
            println!("{}", par[i] + 1);
        }
    }
}

