fn topological_sort(graph: &Graph) -> Vec<usize> {
    let mut count = vec![0; graph.len()];

    for edge in graph {
        for &to in edge {
            count[to] += 1;
        }
    }
    let mut res = vec![];
    let mut check = vec![];

    for (i, &c) in count.iter().enumerate() {
        if c == 0 {
            check.push(i);
        }
    }

    while !check.is_empty() {
        let i = check.pop().unwrap();
        for &to in &graph[i] {
            count[to] -= 1;
            if count[to] == 0 {
                check.push(to);
            }
        }
        res.push(i);
    }
    if res.len() != graph.len() {
        vec![]
    } else {
        res
    }
}

