        used[b] = true;
    }
    let mut root = 0;
    for i in 0..n + m - 1 {
        if !used[i] {
            root = i;
            break;
        }
    }

    let mut graph = vec![vec![]; n];
    let mut rev_graph = vec![vec![]; n];
    for (i, &(a, b)) in edges.iter().enumerate() {
        graph[a].push(b);
        rev_graph[b].push((a, i));
    }

    let v = topological_sort(&graph);
    let mut memo = vec![0; n];
    let mut ans = vec![];
    for i in 0..v.len() {
        memo[v[i]] = i;
        let mut root = 0;
        let mut last = 0;
        for &(p, _) in &rev_graph[v[i]] {
            if last <= memo[p] {
                root = p + 1;
                last = memo[p];
            }
        }
        ans.push((v[i], root));
    }
    ans.sort();
    for &(_, r) in &ans {
        println!("{}", r);
    }
}

