fn solve() {
    let out = stdout();
    let mut out = BufWriter::new(out.lock());
    input!{
        n:usize,m:usize,
        ab:[(usize,usize);n-1+m],
    }
    let mut g = vec![vec![];n];
    for (a,b) in ab {
        g[a-1].push(b-1);
    }
    let mut ts = TopologicalSort::new(&g);
    ts.tsort();
    let root = ts.out[0];
    let mut par = vec![0;n];
    par[root]=0;
    dfs(&g, root, &mut |conn, r| {
        if let Some((c,i)) = conn {
            par[r]=c+1;
        }
    });
    for x in par {
        writeln!(out, "{}", x);
    }
}
fn dfs<F: FnMut(Option<(usize, usize)>, usize)>(g: &[Vec<usize>], root: usize, op: &mut F) {
    let n = g.len();
    let mut stack = vec![(None, root)];
    let mut visited = vec![false; n];
    visited[root] = true;
    while !stack.is_empty() {
        let (conn, r) = stack.pop().unwrap();
        op(conn, r);
        let cs = &g[r];
        for i in 0..cs.len() {
            let c = cs[i];
            if visited[c] {
                continue;
            }
            visited[c] = true;
            stack.push((Some((r, i)), c));
        }
    }
}
struct TopologicalSort<'a> {
    g: &'a [Vec<usize>],
    colors: Vec<bool>,
    indeg: Vec<u32>,
    Q: VecDeque<usize>,
    out: Vec<usize>,
}
impl<'a> TopologicalSort<'a> {
    fn new(g: &'a [Vec<usize>]) -> Self {
        let n = g.len();
        let mut colors = vec![false; n];
        let mut indeg = vec![0; n];
        for u in 0..n {
            let conn = &g[u];
            for &next in conn {
                indeg[next] += 1;
            }
        }
        TopologicalSort {
            g: g,
            Q: VecDeque::new(),
            colors: colors,
            indeg: indeg,
            out: Vec::new(),
        }
    }
    fn bfs(&mut self, s: usize) {
        self.Q.push_back(s);
        self.colors[s] = true;
        while !self.Q.is_empty() {
            let u = self.Q.pop_front().unwrap();
            self.out.push(u);
            for &v in &self.g[u] {
                self.indeg[v] -= 1;
                if self.indeg[v] == 0 && self.colors[v] == false {
                    self.colors[v] = true;
                    self.Q.push_back(v);
                }
            }
        }
    }
    fn tsort(&mut self) {
        let n = self.g.len();
        for u in 0..n {
            if self.indeg[u] == 0 && self.colors[u] == false {
                self.bfs(u)
            }
        }
    }
}

