use std::collections::HashSet;

fn main() {
    input! {
        n: usize,
        m: usize,
        ab: [(usize1, usize1); n-1+m],
    }

    let mut g = vec![vec![]; n];
    let mut rg = vec![vec![]; n];

    for &(a, b) in ab.iter() {
        g[a].push(b);
        rg[b].push(a);
    }

    let mut root = 0;
    for i in 0..n {
        if rg[i].len() == 0 {
            root = i;
            break;
        }
    }

    let mut par = vec![None; n];
    let mut hist = HashSet::new();

    rec(root, None, &g, &mut par, &mut hist);

    for i in 0..n {
        if let Some(p) = par[i] {
            println!("{}", p + 1);
        } else {
            println!("0");
        }
    }
}

fn rec(
    cur: usize,
    prev: Option<usize>,
    g: &Vec<Vec<usize>>,
    par: &mut Vec<Option<usize>>,
    hist: &mut HashSet<usize>,
) {
    // println!("cur: {}", cur);

    hist.insert(cur);

    for &next in g[cur].iter() {
        if Some(next) == prev {
            continue;
        }

        if let Some(np) = par[next] {
            if hist.contains(&np) {
                par[next] = Some(cur);
            }
        } else {
            // println!("hoge: {} -> {}", cur, next);
            par[next] = Some(cur);
            rec(next, Some(cur), g, par, hist);
        }
    }

    hist.remove(&cur);
}

