#[derive(Debug)]
struct Rec {
    n: usize,
    graph: Vec<Vec<usize>>,
    top: Vec<usize>,
    visited: Vec<bool>,
}
impl Rec {
    fn new(n: usize) -> Rec {
        Rec {
            n: n,
            graph: vec![vec![]; n],
            top: vec![],
            visited: vec![false; n],
        }
    }
    fn add_edge(&mut self, a: usize, b: usize) {
        self.graph[a].push(b);
    }
    fn solve(&mut self) {
        self.visited = vec![false; self.n];
        for i in 0..self.n {
            if !self.visited[i] {
                self.visited[i] = true;
                self.dfs(i);
            }
        }
        let mut ans = vec![0; self.n];
        for &u in self.top.iter().rev() {
            for &v in self.graph[u].iter() {
                ans[v] = u + 1;
            }
        }
        for &u in &ans {
            println!("{}", u);
        }
    }
    fn dfs(&mut self, u: usize) {
        for i in 0..self.graph[u].len() {
            let v = self.graph[u][i];
            if !self.visited[v] {
                self.visited[v] = true;
                self.dfs(v);
            }
        }
        self.top.push(u);
    }
}
fn main() {
    input! { n, m, ab: [(usize1, usize1); n-1+m] };
    let mut rec = Rec::new(n);
    for &(a, b) in &ab {
        rec.add_edge(a, b);
    }
    rec.solve();
}

