use std::collections::VecDeque;

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    read::<String>()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}

fn main() {
    let v = read_vec::<usize>();
    let (n, m) = (v[0], v[1]);
    let mut h = vec![0; n + m - 1];
    let mut g = vec![Vec::new(); n + m - 1];
    let mut parents = vec![Vec::new(); n + m - 1];
    for _ in 0..n + m - 1 {
        let v = read_vec::<usize>();
        let (s, t) = (v[0] - 1, v[1] - 1);
        g[s].push(t);
        parents[t].push(s);
        h[t] += 1;
    }
    // println!("{:?}", parents);

    let mut st: VecDeque<usize> = VecDeque::new();

    for i in 0..n {
        if h[i] == 0 {
            st.push_back(i);
        }
    }

    let mut sorted_indexes = Vec::new();
    while !st.is_empty() {
        let i = st.pop_back().unwrap();
        sorted_indexes.push(i);
        for &j in g[i].iter() {
            h[j] -= 1;
            if h[j] == 0 {
                st.push_back(j);
            }
        }
    }
    // println!("sorted_indexes {:?}", sorted_indexes);

    let mut idx_dict = std::collections::HashMap::new();
    for (i, &idx) in sorted_indexes.iter().enumerate() {
        idx_dict.insert(idx, i);
    }

    for i in 0..n {
        if idx_dict[&i] == 0 {
            println!("0");
            continue;
        }
        let mut nearest_index = parents[i][0];
        let mut max_num = 0;
        for parent in parents[i].iter() {
            if idx_dict[parent] > max_num {
                max_num = idx_dict[parent];
                nearest_index = *parent;
            }
        }
        println!("{}", nearest_index + 1);
    }
}

