pub struct Rev<T>(pub T);
impl<T: PartialOrd> PartialOrd for Rev<T> {
    fn partial_cmp(&self, other: &Rev<T>) -> Option<Ordering> {
        other.0.partial_cmp(&self.0)
    }
}
impl<T: Ord> Ord for Rev<T> {
    fn cmp(&self, other: &Rev<T>) -> Ordering {
        other.0.cmp(&self.0)
    }
}

fn solve() {
    let (n,m) = get!(usize, usize);
    let ab = get!(usize, usize;n-1+m);

    let mut nodes = vec![Vec::new(); n+1];
    let mut rnodes = vec![Vec::new(); n+1];

    let mut roots = (1..n+1).collect::<BTreeSet<_>>();
    for &(a,b) in &ab {
        roots.remove(&b);
        nodes[a].push(b);
        rnodes[b].push(a);
    }
    let root = roots.into_iter().next().unwrap();

    let mut degrees = vec![0; n+1];
    for i in 1..n+1 {
        degrees[i] = rnodes[i].len();
    }
    let mut add = Vec::new();
    add.push(root);
    let mut topo = Vec::new();
    while let Some(node) = add.pop() {
        topo.push(node);
        for &next in &nodes[node] {
            degrees[next] -= 1;
            if degrees[next] == 0 {
                add.push(next);
            }
        }
    }

    let mut indexes = vec![0; n+1];
    let mut parents = vec![0; n+1];
    for i in 0..topo.len() {
        let mut mxp = 0;
        let mut mx = 0;
        for &par in &rnodes[topo[i]] {
            if mx <= indexes[par] {
                mx = indexes[par];
                mxp = par;
            }
        }
        indexes[topo[i]] = i;
        parents[topo[i]] = mxp;
    }
    for i in 1..n+1 {
        println!("{}", parents[i]);
    }
}

