fn main() {
    let (N, M) = read!(usize, usize);

    let mut G = vec![vec![]; N];
    // let mut H = vec![vec![]; N];
    let mut deg = vec![0; N];

    for i in 0..(N + M - 1) {
        let (A, B) = read!(usize, usize);
        G[A - 1].push((i, B - 1));
        // H[B - 1].push(i);
        deg[B - 1] += 1;
    }

    let mut root = 0;
    for i in 0..N {
        if deg[i] == 0 {
            root = i;
            break;
        }
    }
    debug!(root);

    let mut Q = VecDeque::new();
    Q.push_back(root);
    // let mut acc = vec![false; N + M - 1];
