fn main() {
    let (n, m): (usize, usize) = {
        let mut s = String::new();
        std::io::stdin().read_line(&mut s).unwrap();
        let s = s.trim_right().to_owned();
        let mut ws = s.split_whitespace();
        let a = ws.next().unwrap().parse().unwrap();
        let b = ws.next().unwrap().parse().unwrap();
        (a, b)
    };

    let mut v: Vec<(usize, usize)> = Vec::new();
    for _ in 0..(n - 1 + m) {
        let v_i = {
            let mut s = String::new();
            std::io::stdin().read_line(&mut s).unwrap();
            let s = s.trim_right().to_owned();
            let mut ws = s.split_whitespace();
            let a = ws.next().unwrap().parse().unwrap();
            let b = ws.next().unwrap().parse().unwrap();
            (a, b)
        };
        v.push(v_i)
    }

    // 0-originに変換して考える
    // 最後に1を足す！！！

    let mut graph_list: Vec<Vec<usize>> = vec![vec![]; n];
    for (a, b) in v {
        graph_list[a - 1].push(b - 1)
    }

    let sorted = topological_sort(&graph_list);
    debugln!("sorted: {:?}", sorted);
    let mut sorted_index = vec![0; n];
    for (i, vertex) in sorted.iter().enumerate() {
        sorted_index[*vertex] = i;
    }
    debugln!("sorted_index: {:?}", sorted_index);

    let ans = dfs(sorted[0], &graph_list, &sorted_index);
    for a in ans {
        // 最後に1を足す
        println!("{}", a + 1);
    }
}

fn topological_sort(graph_list: &[Vec<usize>]) -> Vec<usize> {
    let n = graph_list.len();

    let mut incoming_num = vec![0; n];
    for edges in graph_list.iter() {
        for &vertex in edges {
            incoming_num[vertex] += 1;
        }
    }

    // 入次数0の頂点集合
    let mut stack: Vec<usize> = vec![];
    for (vertex, &num) in incoming_num.iter().enumerate() {
        if num == 0 {
            stack.push(vertex);
        }
    }

    let mut ret = vec![];
    while let Some(vertex) = stack.pop() {
        ret.push(vertex);
        for &next in &graph_list[vertex] {
            incoming_num[next] -= 1;
            if incoming_num[next] == 0 {
                stack.push(next);
            }
        }
    }
    ret
}

// 深さ優先探索（再帰）
fn dfs(start: usize, graph_list: &[Vec<usize>], sorted_index: &Vec<usize>) -> Vec<isize> {
    let n = graph_list.len();
    let mut visited = vec![false; n];
    let mut ans = vec![-1; n];

    dfs_aux(start, graph_list, &mut visited, &mut ans, sorted_index);
    ans
}
// 補助関数
fn dfs_aux(start: usize, graph_list: &[Vec<usize>], visited: &mut Vec<bool>, ans: &mut Vec<isize>, sorted_index: &Vec<usize>) {
    visited[start] = true;

    debugln!("visit {}", start);

    for &next in &graph_list[start] {
        debugln!("ans[{}] = {}, sorted_index[{}] = {}", next, ans[next], start, sorted_index[start]);
        if ans[next] < 0 {
            ans[next] = start as isize;
        } else if sorted_index[ans[next] as usize] < sorted_index[start] {
            ans[next] = start as isize;
        }
        if !visited[next] {
            dfs_aux(next, &graph_list, visited, ans, sorted_index);
        }
    }
}

