fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = CpReader::new(i);
    let (n, m) = i.read2::<usize, usize>();
    let mut bss = vec![Vec::new(); n];
    for _ in 0..n - 1 + m {
        let (a, b) = i.read2::<usize, usize>();
        bss[a - 1].push(b - 1);
    }
    let tree = solve(&bss);
    for node in tree {
        let no = if let Some(p) = node { p + 1 } else { 0 };
        writeln!(o, "{}", no).unwrap();
    }
}
fn solve(bss: &[Vec<usize>]) -> Vec<Option<usize>> {
    let n = bss.len();
    let mut cs = vec![0; n];
    for bs in bss {
        for &b in bs {
            cs[b] += 1;
        }
    }
    let root = cs.iter().position(|&c| c == 0).unwrap();
    let mut a = vec![root];
    let mut a_next = Vec::new();
    let mut ps = vec![None; n];

    while !a.is_empty() {
        for &a in &a {
            for &b in &bss[a] {
                cs[b] -= 1;
                if cs[b] == 0 {
                    ps[b] = Some(a);
                    a_next.push(b);
                }
            }
        }
        a.clear();
        mem::swap(&mut a, &mut a_next);
    }
    ps
}

