const INF: i64 = 0x3f3f3f3f3f3f3f3f;
const MOD: i64 = 1000000007;
const NOTHING: usize = std::usize::MAX;
const DX: [usize; 4] = [1, 0, std::usize::MAX, 0];
const DY: [usize; 4] = [0, 1, 0, std::usize::MAX];

fn solve<R: std::io::BufRead, W: std::io::Write>(io: &mut IO<R, W>) {
    let (n, m): (usize, usize) = io.readln();
    let mut gr: Vec<Vec<usize>> = vec![vec![];n];
    let mut parent: Vec<usize> = vec![NOTHING;n];

    for _ in 0..n + m - 1 {
        let (a, b): (usize, usize) = io.readln();
        gr[a - 1].push(b - 1);
        parent[b - 1] = a - 1;
    }
    let mut root = NOTHING;
    for i in 0..n {
        if parent[i] == NOTHING {
            root = i;
            break;
        }
    }
    assert!(root != NOTHING);

    let mut q: VecDeque<usize> = VecDeque::new();
    let mut visited: Vec<bool> = vec![false;n];
    parent = vec![NOTHING;n];
    q.push_back(root);
    while let Some(v) = q.pop_front() {
        if visited[v] {
            continue;
        }
        visited[v] = true;
        for &u in &gr[v] {
            parent[u] = v;
            q.push_back(u);
        }
    }
    for i in 0..n {
        if parent[i] == NOTHING {
            io.writeln(0);
        } else {
            io.writeln(parent[i] + 1);
        }
    }

}

